EventMap::CancelEventsByGCD.body:
void EventMap::CancelEventsByGCD(uint32 gcd)
{
    gcd = (1 << (gcd + 16));

    for (auto itr = _eventMap.begin(); itr != _eventMap.end();)
    {
        if (itr->second & gcd)
        {
            _eventMap.erase(itr);
            itr = _eventMap.begin();
        }
        else
            ++itr;
    }
}

EventMap::GetNextEventTime.body:
uint32 EventMap::GetNextEventTime(uint32 eventId) const
{
    if (Empty())
        return 0;

    for (auto const& itr : _eventMap)
        if (eventId == (itr.second & 0x0000FFFF))
            return itr.first;

    return 0;
}

EventMap::GetTimeUntilEvent.body:
uint32 EventMap::GetTimeUntilEvent(uint32 eventId) const
{
    for (auto const& itr : _eventMap)
        if (eventId == (itr.second & 0x0000FFFF))
            return itr.first - _time;

    return std::numeric_limits<uint32>::max();
}

