CreatureAI::EnterEvadeMode.body:
void CreatureAI::EnterEvadeMode()
{
    if (!m_creature->IsAlive())
    {
        m_creature->CombatStop(true);
        m_creature->DeleteThreatList();
        return;
    }

    if (!m_creature->IsCharmed())
    {
        m_creature->RemoveAurasAtReset();

        // clear all movement generators except default
        m_creature->GetMotionMaster()->Clear(false);
        m_creature->GetMotionMaster()->MoveTargetedHome();
    }

    m_creature->ClearComboPointHolders();
    m_creature->DeleteThreatList();
    m_creature->CombatStop(true);
    m_creature->SetLootRecipient(nullptr);
    m_creature->CallForAllControlledUnits(EnterEvadeModeHelper(m_creature), CONTROLLED_PET | CONTROLLED_GUARDIANS | CONTROLLED_CHARM | CONTROLLED_TOTEMS);
}

CreatureAI::CanTriggerAlert.body:
bool CreatureAI::CanTriggerAlert(Unit const* who)
{
    // If this unit isn't an NPC, is already distracted, is in combat, is confused, stunned or fleeing, do nothing
    if (m_creature->GetTypeId() != TYPEID_UNIT || m_creature->IsInCombat() || m_creature->HasUnitState(UNIT_STATE_NO_FREE_MOVE))
        return false;

    // Only alert for hostiles!
    if (m_creature->IsCivilian() || m_creature->HasReactState(REACT_PASSIVE) || !m_creature->IsValidAttackTarget(who))
        return false;

    // 10 sec cooldown for stealth warning
    if (WorldTimer::getMSTimeDiffToNow(m_uLastAlertTime) < 10000)
        return false;

    // only alert if target is within line of sight
    if (!m_creature->IsWithinLOSInMap(who))
        return false;

    return true;
}

CreatureAI::TriggerAlertDirect.body:
void CreatureAI::TriggerAlertDirect(Unit const* who)
{
    // Send alert sound (if any) for this creature
    m_creature->SendAIReaction(AI_REACTION_ALERT);

    // Face the unit (stealthed player) and set distracted state for 5 seconds
    m_creature->StopMoving();
    m_creature->SetFacingTo(m_creature->GetAngle(who->GetPositionX(), who->GetPositionY()));
    m_creature->GetMotionMaster()->MoveDistract(5 * IN_MILLISECONDS);
    m_uLastAlertTime = WorldTimer::getMSTime();
}

selectAI.body:
CreatureAI* selectAI(Creature* creature)
{
    // Player mind controlling a creature.
    if (!creature->IsPet() && creature->GetCharmGuid().IsPlayer() && creature->HasUnitState(UNIT_FLAG_POSSESSED))
        return new NullCreatureAI(creature);

    // Allow scripting AI for normal creatures and not controlled pets (guardians and mini-pets)
    if ((!creature->IsPet() || !((Pet*)creature)->IsControlled()) && !creature->IsCharmed())
        if (CreatureAI* scriptedAI = sScriptMgr.GetCreatureAI(creature))
            return scriptedAI;

    CreatureAIRegistry &ai_registry(CreatureAIRepository::Instance());

    const CreatureAICreator *ai_factory = nullptr;

    std::string ainame = creature->GetAIName();

    // select by NPC flags _first_ - otherwise EventAI might be choosen for pets/totems
    // excplicit check for IsControlled() and owner type to allow guardian, mini-pets and pets controlled by NPCs to be scripted by EventAI
    Unit* owner = nullptr;
    if ((creature->IsPet() && ((Pet*)creature)->IsControlled() && creature->GetOwnerGuid().IsPlayer()) || creature->IsCharmed())
        ai_factory = ai_registry.GetRegistryItem("PetAI");
    else if (creature->IsTotem())
        ai_factory = ai_registry.GetRegistryItem("TotemAI");

    // EventAI assigned but creature is Pet.
    if (!ai_factory && !ainame.empty() && creature->IsPet() && (ainame == "EventAI"))
        ai_factory = ai_registry.GetRegistryItem("PetEventAI");

    // EventAI assigned but creature is Guard.
    if (!ai_factory && !ainame.empty() && creature->IsGuard() && (ainame == "EventAI"))
        ai_factory = ai_registry.GetRegistryItem("GuardEventAI");

    // select by script name
    if (!ai_factory && !ainame.empty())
        ai_factory = ai_registry.GetRegistryItem(ainame);

    if (!ai_factory && creature->IsGuard())
        ai_factory = ai_registry.GetRegistryItem("GuardAI");

    if (!ai_factory && creature->GetCreatureInfo()->type == CREATURE_TYPE_CRITTER)
        ai_factory = ai_registry.GetRegistryItem("CritterAI");

    // select by permit check
    if (!ai_factory)
    {
        int best_val = PERMIT_BASE_NO;
        typedef CreatureAIRegistry::RegistryMapType RMT;
        RMT const& l = ai_registry.GetRegisteredItems();
        for (const auto& iter : l)
        {
            const CreatureAICreator *factory = iter.second;
            const SelectableAI *p = dynamic_cast<const SelectableAI *>(factory);
            MANGOS_ASSERT(p != nullptr);
            int val = p->Permit(creature);
            if (val > best_val)
            {
                best_val = val;
                ai_factory = p;
            }
        }
    }

    // select NullCreatureAI if not another cases
    ainame = (ai_factory == nullptr) ? "NullCreatureAI" : ai_factory->key();

    DEBUG_FILTER_LOG(LOG_FILTER_AI_AND_MOVEGENSS, "Creature %u used AI is %s.", creature->GetGUIDLow(), ainame.c_str());
    return (ai_factory == nullptr ? new NullCreatureAI(creature) : ai_factory->Create(creature));
}

selectMovementGenerator.body:
MovementGenerator* selectMovementGenerator(Creature* creature)
{
    MovementGeneratorRegistry &mv_registry(MovementGeneratorRepository::Instance());
    MANGOS_ASSERT(creature->GetCreatureInfo() != nullptr);
    MovementGeneratorType type = creature->GetOwnerGuid().IsPlayer() ? FOLLOW_MOTION_TYPE : creature->GetDefaultMovementType();
    if (CreatureGroup* group = creature->GetCreatureGroup())
        if (group->IsFormation() && group->GetLeaderGuid() != creature->GetObjectGuid() && group->GetOriginalLeaderGuid() != creature->GetObjectGuid())
            type = PATROL_MOTION_TYPE;
    MovementGeneratorCreator const* mv_factory = mv_registry.GetRegistryItem(type);
    return (mv_factory == nullptr ? nullptr : mv_factory->Create(creature));
}

CreatureEventAIHolder::UpdateRepeatTimer.body:
bool CreatureEventAIHolder::UpdateRepeatTimer(Creature* creature, uint32 repeatMin, uint32 repeatMax)
{
    if (repeatMin == repeatMax)
        Time = repeatMin;
    else if (repeatMax > repeatMin)
        Time = urand(repeatMin, repeatMax);
    else
    {
        sLog.Out(LOG_SCRIPTS, LOG_LVL_MINIMAL, "CreatureEventAI: Creature %u using Event %u (Type = %u) has RandomMax < RandomMin. Event repeating disabled.", creature->GetEntry(), Event.event_id, Event.event_type);
        Enabled = false;
        return false;
    }

    return true;
}

