CreatureEventAI::UpdateAI.body:
void CreatureEventAI::UpdateAI(uint32 const diff)
{
    //Check if we are in combat (also updates calls threat update code)
    m_creature->SelectHostileTarget();
    bool Combat =  m_creature->GetVictim();

    //Must return if creature isn't alive. Normally select hostil target and get victim prevent this
    if (!m_creature->IsAlive())
        return;

    if (!m_bEmptyList)
        UpdateEventsOn_UpdateAI(diff, Combat);

    if (Combat)
    {
        if (!m_CreatureSpells.empty())
            UpdateSpellsList(diff);

        DoMeleeAttackIfReady();
    }
}

CreatureEventAI::UpdateEventsOn_UpdateAI.body:
void CreatureEventAI::UpdateEventsOn_UpdateAI(uint32 const diff, bool Combat)
{
    //Events are only updated once every EVENT_UPDATE_TIME ms to prevent lag with large amount of events
    if (m_EventUpdateTime < diff)
    {
        m_EventDiff += diff;

        //Check for time based events
        for (auto& i : m_CreatureEventAIList)
        {
            //Decrement Timers
            if (i.Time)
            {
                if (i.Time > m_EventDiff)
                {
                    //Do not decrement timers if event cannot trigger in this phase
                    if (!(i.Event.event_inverse_phase_mask & (1 << m_Phase)))
                        i.Time -= m_EventDiff;

                    //Skip processing of events that have time remaining
                    continue;
                }
                else i.Time = 0;
            }

            //Events that are updated every EVENT_UPDATE_TIME
            switch (i.Event.event_type)
            {
                case EVENT_T_TIMER_OOC:
                case EVENT_T_FRIENDLY_MISSING_BUFF:
                    ProcessEvent(i);
                    break;
                case EVENT_T_TIMER_IN_COMBAT:
                case EVENT_T_MANA:
                case EVENT_T_HP:
                case EVENT_T_TARGET_HP:
                case EVENT_T_TARGET_CASTING:
                case EVENT_T_FRIENDLY_HP:
                case EVENT_T_FRIENDLY_IS_CC:
                case EVENT_T_AURA:
                case EVENT_T_TARGET_AURA:
                case EVENT_T_MISSING_AURA:
                case EVENT_T_TARGET_MISSING_AURA:
                case EVENT_T_VICTIM_ROOTED:
                    if (Combat)
                        ProcessEvent(i);
                    break;
                case EVENT_T_RANGE:
                    if (Combat)
                    {
                        if (m_creature->GetVictim() && m_creature->IsInMap(m_creature->GetVictim()))
                            if (m_creature->IsInRange(m_creature->GetVictim(), (float)i.Event.range.minDist, (float)i.Event.range.maxDist))
                                ProcessEvent(i);
                    }
                    break;
            }
        }

        m_EventDiff = 0;
        m_EventUpdateTime = EVENT_UPDATE_TIME;
    }
    else
    {
        m_EventDiff += diff;
        m_EventUpdateTime -= diff;
    }
}

CreatureEventAI::ReceiveEmote.body:
void CreatureEventAI::ReceiveEmote(Player* pPlayer, uint32 text_emote)
{
    if (m_bEmptyList)
