PetEventAI::MoveInLineOfSight.body:
void PetEventAI::MoveInLineOfSight(Unit* pWho)
{
    if (m_creature->GetVictim())
        return;

    //Check for OOC LOS Event
    if (!m_bEmptyList)
        UpdateEventsOn_MoveInLineOfSight(pWho);

    if (m_creature->GetCharmInfo() && m_creature->GetCharmInfo()->IsReturning())
        return;

    if (m_creature->GetDistanceZ(pWho) > CREATURE_Z_ATTACK_RANGE)
        return;

    // World of Warcraft Client Patch 1.8.0 (2005-10-11)
    // - Guardians and pets in aggressive mode no longer attack civilians.
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_7_1
    if (m_creature->IsPet() && pWho->IsCreature() && static_cast<Creature*>(pWho)->IsCivilian())
        return;
#endif

    if (m_creature->CanInitiateAttack() && pWho->IsTargetableBy(m_creature))
    {
        float const attackRadius = m_creature->GetAttackDistance(pWho);
        if (m_creature->IsWithinDistInMap(pWho, attackRadius, true, SizeFactor::None) && m_creature->IsHostileTo(pWho) &&
            pWho->IsInAccessablePlaceFor(m_creature) && m_creature->IsWithinLOSInMap(pWho))
            AttackStart(pWho);
    }
}

PetEventAI::AttackStart.body:
void PetEventAI::AttackStart(Unit* pWho)
{
    if (m_creature->IsPet() && !static_cast<Pet*>(m_creature)->IsEnabled())
        return;

    Unit* pOwner = m_creature->GetCharmerOrOwner();
    if (pWho == pOwner)
        return;

    if (m_creature->GetCharmInfo() && !m_creature->GetCharmInfo()->IsCommandAttack())
    {
        // Passive - passive pets can attack if told to
        if (m_creature->HasReactState(REACT_PASSIVE))
            return;

        // Player's pet should not attack PvP flagged target unless told to
        if (!m_creature->IsPvP() && pWho->IsPvP() && pOwner && pOwner->IsPlayer())
            return;

        // CC - mobs under crowd control can be attacked if owner commanded
        if (pWho->HasAuraPetShouldAvoidBreaking() && pOwner && pOwner->IsAlive())
            return;
    }

    if (m_creature->Attack(pWho, m_bMeleeAttack))
    {
        m_creature->AddThreat(pWho);
        m_creature->SetInCombatWith(pWho);
        pWho->SetInCombatWith(m_creature);

        if (pOwner && pOwner->IsPlayer())
        {
            if (!pOwner->IsInCombat())
            {
                if (m_creature->HasReactState(REACT_AGGRESSIVE))
                    m_creature->SendPetAIReaction();

                pOwner->SetInCombatWith(pWho);
                pWho->SetInCombatWith(pOwner);
            }

            if (!pOwner->IsPvP())
                pOwner->TogglePlayerPvPFlagOnAttackVictim(pWho);
        }

        if (m_bCombatMovement)
        {
            if (m_creature->GetCharmInfo())
                m_creature->GetCharmInfo()->SetIsReturning(false);
            m_creature->GetMotionMaster()->MoveChase(pWho);
        }   
    } 
}

PetEventAI::FindTargetForAttack.body:
Unit* PetEventAI::FindTargetForAttack() const
{
    if (Unit* pTaunter = m_creature->GetTauntTarget())
        return pTaunter;

    if (m_creature->CanHaveThreatList())
    {
        // Check for valid targets on threat list.
        if (!m_creature->GetThreatManager().isThreatListEmpty())
            if (Unit* pTarget = m_creature->GetThreatManager().getHostileTarget())
                if (!pTarget->HasAuraPetShouldAvoidBreaking())
                    return pTarget;
    }
    else if (!m_creature->GetAttackers().empty())
    {
        Unit* pAttacker = *(m_creature->GetAttackers().begin());
        if (pAttacker->IsInCombat() && m_creature->IsValidAttackTarget(pAttacker))
            return pAttacker;
    }

    Unit const* pOwner = m_creature->GetCharmerOrOwner();
    if (!pOwner)
        return nullptr;

    // Pet has no attackers, check for anyone attacking Owner.
    if (Unit* const pTarget = pOwner->GetAttackerForHelper())
    {
        // Prevent pets from breaking CC effects
        if (!pTarget->HasAuraPetShouldAvoidBreaking())
            return pTarget;
        else
        {
            // Main target is CC-ed, so pick another attacker.
            Unit::AttackerSet owner_attackers = pOwner->GetAttackers();
            for (const auto& itr : owner_attackers)
            {
                if (itr->IsInMap(m_creature) && m_creature->IsValidAttackTarget(itr) && !itr->HasAuraPetShouldAvoidBreaking())
                    return itr;
            }
        }
    }
    return nullptr;
}

PetEventAI::UpdateAI.body:
void PetEventAI::UpdateAI(uint32 const uiDiff)
{
    //Must return if creature isn't alive. Normally select hostile target and get victim prevent this
    if (!m_creature->IsAlive())
        return;

    Unit const* pOwner = m_creature->GetCharmerOrOwner();
    bool const hasAliveOwner = pOwner && pOwner->IsAlive() && m_creature->GetCharmInfo();

    if (m_creature->IsInCombat() || (hasAliveOwner && pOwner->IsInCombat()))
        if (Unit* pVictim = FindTargetForAttack())
            if (pVictim != m_creature->GetVictim())
                AttackStart(pVictim);

    if (!m_bEmptyList)
        UpdateEventsOn_UpdateAI(uiDiff, m_creature->GetVictim());

    if (m_creature->GetVictim())
    {
        if (!m_CreatureSpells.empty())
            UpdateSpellsList(uiDiff);

        DoMeleeAttackIfReady();
    }
    else
    {
        if (m_creature->IsInCombat() && !(hasAliveOwner && pOwner->IsInCombat()))
            m_creature->OnLeaveCombat();

        if (hasAliveOwner && m_creature->GetCharmInfo()->HasCommandState(COMMAND_FOLLOW) && !m_creature->HasUnitState(UNIT_STATE_FOLLOW))
        {
            m_creature->GetMotionMaster()->MoveFollow(m_creature->GetCharmerOrOwner(), PET_FOLLOW_DIST,
                                                      m_creature->IsPet() ? static_cast<Pet*>(m_creature)->GetFollowAngle() : PET_FOLLOW_ANGLE);
            if (m_creature->GetCharmInfo())
                m_creature->GetCharmInfo()->SetIsReturning(true);
        }     
    }
}

PetEventAI::OwnerAttackedBy.body:
void PetEventAI::OwnerAttackedBy(Unit* pAttacker)
{
    // Called when owner takes damage. This function helps keep pets from running off
    //  simply due to owner gaining aggro.

    // Prevent pet from disengaging from current target
    if (m_creature->GetVictim() && m_creature->GetVictim()->IsAlive())
        return;

    // If owner attacked by fire, attacker=owner. Don't attack our owner !
    if (!m_creature->IsValidAttackTarget(pAttacker))
        return;

    // Continue to evaluate and attack if necessary
    AttackStart(pAttacker);
}

PetEventAI::OwnerAttacked.body:
void PetEventAI::OwnerAttacked(Unit* pTarget)
{
    // Called when owner attacks something. Allows defensive pets to know
    //  that they need to assist

    // Prevent pet from disengaging from current target
    if (m_creature->GetVictim() && m_creature->GetVictim()->IsAlive())
        return;

    if (!m_creature->IsValidAttackTarget(pTarget))
        return;

    // Continue to evaluate and attack if necessary
    AttackStart(pTarget);
}

PetEventAI::MovementInform.body:
void PetEventAI::MovementInform(uint32 moveType, uint32 data)
{
    CreatureEventAI::MovementInform(moveType, data);

    // Receives notification when pet reaches owner
    if (moveType == FOLLOW_MOTION_TYPE)
    {
        // If data is owner's GUIDLow then we've reached follow point,
        // otherwise we're probably chasing a creature.
        if (m_creature->GetCharmInfo() && m_creature->GetCharmInfo()->IsReturning() && data == m_creature->GetCharmerOrOwnerGuid().GetCounter())
        {
            m_creature->GetCharmInfo()->SetIsReturning(false);
        }
    }
}

PlayerAI::CanCastSpell.body:
bool PlayerAI::CanCastSpell(Unit* pTarget, SpellEntry const* pSpell, bool isTriggered, bool checkControlled)
{
    if (!pTarget)
        return false;

    // If not triggered, we check
    if (!isTriggered)
    {
        // State does not allow
        if (me->HasUnitState(checkControlled ? UNIT_STATE_CAN_NOT_REACT_OR_LOST_CONTROL : UNIT_STATE_CAN_NOT_REACT))
            return false;

        if (pSpell->PreventionType == SPELL_PREVENTION_TYPE_SILENCE && me->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_SILENCED))
            return false;

        if (pSpell->PreventionType == SPELL_PREVENTION_TYPE_PACIFY && me->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_PACIFIED))
            return false;

        // Check for power (also done by Spell::CheckCast())
        if (me->GetPower((Powers)pSpell->powerType) < pSpell->manaCost)
            return false;
    }

    if (SpellRangeEntry const* pSpellRange = sSpellRangeStore.LookupEntry(pSpell->rangeIndex))
    {
        if (pTarget != me)
        {
            // pTarget is out of range of this spell (also done by Spell::CheckCast())
            float fDistance = me->GetCombatDistance(pTarget);

            if (fDistance > pSpellRange->maxRange)
                return false;

            float fMinRange = pSpellRange->minRange;

            if (fMinRange && fDistance < fMinRange)
                return false;
        }
        return true;
    }

    return false;
}

PlayerControlledAI::UpdateTarget.body:
void PlayerControlledAI::UpdateTarget(Unit* victim)
{
    if ((victim->IsCharmed() && victim->GetCharmerGuid() == me->GetCharmerGuid()) || me->IsFeared() || me->IsPolymorphed())
    {
        me->AttackStop();
        me->InterruptNonMeleeSpells(false);
        return;
    }

    Unit* controller = FindController();

    bool isNewVictim = me->GetVictim() != victim;

    if (isNewVictim)
        me->Attack(victim, true);

    // Mode combat
    if (controller && controller->GetTypeId() == TYPEID_PLAYER)
    {
        me->SetInCombatWith(victim);
        controller->SetInCombatWith(victim);

        if (!me->GetMotionMaster()->empty() && me->GetMotionMaster()->GetCurrentMovementGeneratorType() != IDLE_MOTION_TYPE)
            return;
        me->GetMotionMaster()->Clear();
        me->GetMotionMaster()->MoveChase(victim);
    }
    else
    {
        me->SetInCombatWith(victim);
        victim->SetInCombatWith(me);
        if (controller)
        {
            controller->SetInCombatWith(victim);
            victim->SetInCombatWith(controller);
        }

        if (!bIsMelee)
            me->SetCasterChaseDistance(25.0f);

        if (isNewVictim)
        {
            me->GetMotionMaster()->Clear();
            me->GetMotionMaster()->MoveChase(victim);
            return;
        }
        else
        {
            bool inMeleeRange = me->CanReachWithMeleeAutoAttack(victim);
            if ((bIsMelee && inMeleeRange) || (!bIsMelee && !me->IsMoving() && me->IsWithinDist(victim, 30.0f)))
            {
                me->GetMotionMaster()->Clear();
                if (bIsMelee && !me->HasInArc(victim, 0.2f))
                {
                    me->SetFacingToObject(victim);
                }
                else if (!me->HasInArc(victim, 0.5f))
                {
                    me->SetFacingToObject(victim);
                }
            }
            else
            {
                // melee not in melee range or nonmoving caster not in caster range
                if (!me->IsInRoots() && !me->IsMoving())
                {
                    me->GetMotionMaster()->Clear();
                    me->GetMotionMaster()->MoveChase(victim);
                }
            }
        }
    }
}

PlayerControlledAI::UpdateAI.body:
void PlayerControlledAI::UpdateAI(uint32 const uiDiff)
{
    if (me->IsDeleted() || !me->IsInWorld() || !me->IsAlive())
    {
        me->RemoveAI();
        return;
    }

    Unit* victim = nullptr;
    CharmInfo* charmInfo = me->GetCharmInfo();
    Unit* controller = FindController();

    // If controller is a player
    if (controller && controller->GetTypeId() == TYPEID_PLAYER)
    {
        Player* Pcontroller = ((Player*)controller);

        if (!Pcontroller->IsAlive())
        {
            me->RemoveCharmAuras();
            // Note that we CANNOT continue after this point since this object has been deleted
            // Pcontroller is a local var on the stack, not a member object, so it is safe to use
            Pcontroller->RemoveCharmAuras();
            return;
        }

        if (charmInfo)
        {
            if (charmInfo->HasReactState(REACT_PASSIVE))
                victim = me->GetVictim();
            else if (charmInfo->HasReactState(REACT_DEFENSIVE) || charmInfo->HasReactState(REACT_AGGRESSIVE))
            {
                victim = me->GetVictim();
                if (!victim || (victim == Pcontroller))
                    victim = Pcontroller->GetVictim();
            }
        }
        else
        {
            victim = me->GetVictim();
            if (!victim || (victim == Pcontroller))
                victim = Pcontroller->GetVictim();
        }

        if (!victim || (victim == me))
            return;

        UpdateTarget(victim);
    }
    else // If controller is a creature
    {
        Creature* Ccontroller = controller ? controller->ToCreature() : nullptr;

        // Unit* victim = controller-> getVictim ();
        // Ivina <Nostalrius>: chooses the target randomly and not always the target of the controller.
        victim = Ccontroller ? Ccontroller->SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0) : me->SelectNearestTarget(50.0f);
        if (Unit* v2 = me->GetVictim())
            if (me->CanAttack(v2, false))
                victim = v2;

        if (Ccontroller && (!Ccontroller->IsAlive() || !Ccontroller->IsInCombat()))
        {
            me->RemoveCharmAuras();
            // Note that we CANNOT continue after this point since this object has been deleted
            // Ccontroller is a local var on the stack, not a member object, so it is safe to use
            Ccontroller->RemoveCharmAuras();
            return;
        }

        if (!victim || (victim == me)) // Ivina <Nostalrius>: avoid being targeted
            return;

        // Need a valid target
        if (!me->IsHostileTo(victim))
            return;

        UpdateTarget(victim);
    }

    if (uiGlobalCD < uiDiff)
    {
        if (me->IsNonMeleeSpellCasted(true))
            uiGlobalCD = 200;
        else
        {
            // Since we are going to do something usableSpells [0, urand (0, usableSpells.size () - 1)], we must have at least one element.
            if (usableSpells.empty())
                return;

            uint32 spellId = usableSpells[urand(0, usableSpells.size() - 1)];
            SpellEntry const* spellInfo = sSpellMgr.GetSpellEntry(spellId);

            // If its a positive spell we prioritize controller, if he's out of range,
            // ourself, otherwise it will probably not be cast.
            Unit* spellTarget = victim;
            if (controller && spellInfo->IsPositiveSpell(me, controller))
                spellTarget = controller;
            else if (spellInfo->IsPositiveSpell(me, me))
                spellTarget = me;

            if (spellInfo)
            {
                if (CanCastSpell(spellTarget, spellInfo, false, false))
                {
                    me->CastSpell(spellTarget, spellId, false);
                    uiGlobalCD = 1500;
                    if (!bIsMelee)
                        me->SetCasterChaseDistance(25.0f);
                }
                else
                {
                    if (!bIsMelee)
                        me->SetCasterChaseDistance(0.0f);
                }
            }
        }
    }
    else
        uiGlobalCD -= uiDiff;
}

