ScriptedAI::EnterEvadeIfOutOfCombatArea.body:
bool ScriptedAI::EnterEvadeIfOutOfCombatArea(uint32 const uiDiff)
{
    if (m_uiEvadeCheckCooldown < uiDiff)
        m_uiEvadeCheckCooldown = 2500;
    else
    {
        m_uiEvadeCheckCooldown -= uiDiff;
        return false;
    }

    if (m_creature->IsInEvadeMode() || !m_creature->GetVictim())
        return false;

    float fX = m_creature->GetPositionX();
    float fY = m_creature->GetPositionY();
    float fZ = m_creature->GetPositionZ();

    switch(m_creature->GetEntry())
    {
        case NPC_BROODLORD:                                 // broodlord (not move down stairs)
            if (fZ > 448.60f)
                return false;
            break;
        case NPC_VISCIDUS:
            if (fZ < -30.0f)
                return false;
            break;
        case NPC_SYLVANAS:
        case NPC_VARIMATHRAS:
            if (m_creature->GetDistance(fX, fY, fZ) < 120.0f)
                return false;
            break;
        default:
            sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "EnterEvadeIfOutOfCombatArea used for creature entry %u, but does not have any definition.", m_creature->GetEntry());
            return false;
    }

    EnterEvadeMode();
    return true;
}

