void ScriptedAI::DoTeleportAll(float fX, float fY, float fZ, float fO)
{
    Map* map = me->GetMap();
    if (!map->IsDungeon())
        return;

    Map::PlayerList const& PlayerList = map->GetPlayers();
    for (const auto& i : PlayerList)
        if (Player* i_pl = i.getSource())
