ScriptedInstance::DoUpdateWorldState.body:
void ScriptedInstance::DoUpdateWorldState(uint32 uiStateId, uint32 uiStateData)
{
    Map::PlayerList const& lPlayers = instance->GetPlayers();

    if (!lPlayers.isEmpty())
    {
        for(const auto & itr : lPlayers)
        {
            if (Player* pPlayer = itr.getSource())
                pPlayer->SendUpdateWorldState(uiStateId, uiStateData);
        }
    }
    else
        sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "DoUpdateWorldState attempt send data but no players in map.");
}

ScriptedInstance::GenSaveData.body:
std::string ScriptedInstance::GenSaveData(uint32* encounters, uint32 maxIndex)
{
    bool first = true;
    std::ostringstream saveStream;
    for (uint32 i = 0; i <= maxIndex; ++i)
    {
        if (!first)
            saveStream << " ";
        first = false;
        saveStream << encounters[i];
    }
    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "Sauvegarde : `%s`", saveStream.str().c_str());
    return saveStream.str();
}

ScriptedInstance::LoadSaveData.body:
void ScriptedInstance::LoadSaveData(char const* pStr, uint32* encounters, uint32 maxIndex)
{
    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "Chargement : `%s`", pStr);
    std::istringstream loadStream(pStr);
    for (uint32 i = 0; i <= maxIndex; ++i)
    {
        loadStream >> encounters[i];
        sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "* %u = %u", i, encounters[i]);
    }
}

ScriptedInstance::GetPlayerInMap.body:
Player* ScriptedInstance::GetPlayerInMap(bool bOnlyAlive /*=false*/, bool bCanBeGamemaster /*=true*/)
{
    Map::PlayerList const& lPlayers = instance->GetPlayers();

    for (const auto& itr : lPlayers)
    {
        Player* pPlayer = itr.getSource();
        if (pPlayer && (!bOnlyAlive || pPlayer->IsAlive()) && (bCanBeGamemaster || !pPlayer->IsGameMaster()))
            return pPlayer;
    }

    return nullptr;
}

ScriptedInstance::GetSingleGameObjectFro.body:
GameObject* ScriptedInstance::GetSingleGameObjectFromStorage(uint32 uiEntry)
{
    EntryGuidMap::iterator find = m_mGoEntryGuidStore.find(uiEntry);
    if (find != m_mGoEntryGuidStore.end())
        return instance->GetGameObject(find->second);

    // Output log, possible reason is not added GO to map, or not yet loaded;
    sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Script requested gameobject with entry %u, but no gameobject of this entry was created yet, or it was not stored by script for map %u.", uiEntry, instance->GetId());

    return nullptr;
}

ScriptedInstance::GetSingleCreatureFromS.body:
Creature* ScriptedInstance::GetSingleCreatureFromStorage(uint32 uiEntry, bool bSkipDebugLog /*=false*/)
{
    EntryGuidMap::iterator find = m_mNpcEntryGuidStore.find(uiEntry);
    if (find != m_mNpcEntryGuidStore.end())
        return instance->GetCreature(find->second);

    // Output log, possible reason is not added GO to map, or not yet loaded;
    if (!bSkipDebugLog)
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Script requested creature with entry %u, but no npc of this entry was created yet, or it was not stored by script for map %u.", uiEntry, instance->GetId());

    return nullptr;
}

ScriptedInstance_PTR::OnCreatureEnterCom.body:
void ScriptedInstance_PTR::OnCreatureEnterCombat(Creature* creature)
{
    if (creature->IsWorldBoss())
    {
        std::map<ObjectGuid, time_t>::iterator it = boss_expirations.find(creature->GetObjectGuid());
        if (it == boss_expirations.end())
        {
            boss_expirations[creature->GetObjectGuid()] = time(nullptr);
            creature->MonsterSay("Remaining time before despawn: 30 minutes.");
        }
    }
    ScriptedInstance::OnCreatureEnterCombat(creature);
}

ScriptedInstance_PTR::Update.body:
void ScriptedInstance_PTR::Update(uint32 diff)
{
    time_t expiration = time(nullptr) - 30*60;
    std::map<ObjectGuid, time_t>::iterator it = boss_expirations.begin();
    for (; it != boss_expirations.end(); ++it)
    {
        if (it->second < expiration)
            if (GetMap())
                if (Creature* c = GetMap()->GetCreature(it->first))
                {
                    if (!c->IsAlive())
                        c->DoKillUnit();
                    c->SaveRespawnTime();
                    c->AddObjectToRemoveList();
                }
    }
    ScriptedInstance::Update(diff);
}

DialogueHelper::StartNextDialogueText.body:
void DialogueHelper::StartNextDialogueText(int32 iTextEntry)
{
    // Find iTextEntry
    bool bFound = false;

    if (m_pDialogueArray)                                   // One Side
    {
        for (SIDialogueEntry const* pEntry = m_pDialogueArray; pEntry->iTextEntry; ++pEntry)
        {
            if (pEntry->iTextEntry == iTextEntry)
            {
                m_pCurrentEntry = pEntry;
                bFound = true;
                break;
            }
        }
    }
    else                                                    // Two Sides
    {
        for (SIDialogueEntryTwoSide const* pEntry = m_pDialogueTwoSideArray; pEntry->iTextEntry; ++pEntry)
        {
            if (pEntry->iTextEntry == iTextEntry)
            {
                m_pCurrentEntryTwoSide = pEntry;
                bFound = true;
                break;
            }
        }
   }

    if (!bFound)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Script call DialogueHelper::StartNextDialogueText, but textEntry %i is not in provided dialogue (on map id %u)", iTextEntry, m_pInstance ? m_pInstance->instance->GetId() : 0);
        return;
    }

    DoNextDialogueStep();
}

DialogueHelper::DoNextDialogueStep.body:
void DialogueHelper::DoNextDialogueStep()
{
    // Last Dialogue Entry done?
    if ((m_pCurrentEntry && !m_pCurrentEntry->iTextEntry) || (m_pCurrentEntryTwoSide && !m_pCurrentEntryTwoSide->iTextEntry))
    {
        m_uiTimer = 0;
        return;
    }

    // Get Text, SpeakerEntry and Timer
    int32 iTextEntry = 0;
    uint32 uiSpeakerEntry = 0;

    if (m_pDialogueArray)                               // One Side
    {
        uiSpeakerEntry = m_pCurrentEntry->uiSayerEntry;
        iTextEntry = m_pCurrentEntry->iTextEntry;

        m_uiTimer = m_pCurrentEntry->uiTimer;
    }
    else                                                // Two Sides
    {
        // Second Entries can be 0, if they are the entry from first side will be taken
        uiSpeakerEntry = !m_bIsFirstSide && m_pCurrentEntryTwoSide->uiSayerEntryAlt ? m_pCurrentEntryTwoSide->uiSayerEntryAlt : m_pCurrentEntryTwoSide->uiSayerEntry;
        iTextEntry = !m_bIsFirstSide && m_pCurrentEntryTwoSide->iTextEntryAlt ? m_pCurrentEntryTwoSide->iTextEntryAlt : m_pCurrentEntryTwoSide->iTextEntry;

        m_uiTimer = m_pCurrentEntryTwoSide->uiTimer;
    }

    // Simulate Case
    if (uiSpeakerEntry && iTextEntry)
    {
        // Use Speaker if directly provided
        Creature* pSpeaker = GetSpeakerByEntry(uiSpeakerEntry);
        if (m_pInstance && !pSpeaker)                       // Get Speaker from instance
        {
            if (m_bCanSimulate)                             // Simulate case
                m_pInstance->DoOrSimulateScriptTextForThisInstance(iTextEntry, uiSpeakerEntry);
            else
                pSpeaker = m_pInstance->GetSingleCreatureFromStorage(uiSpeakerEntry);
        }

        if (pSpeaker)
            DoScriptText(iTextEntry, pSpeaker);
    }

    JustDidDialogueStep(m_pDialogueArray ?  m_pCurrentEntry->iTextEntry : m_pCurrentEntryTwoSide->iTextEntry);

    // Increment position
    if (m_pDialogueArray)
        ++m_pCurrentEntry;
    else
        ++m_pCurrentEntryTwoSide;
}

DialogueHelper::DialogueUpdate.body:
void DialogueHelper::DialogueUpdate(uint32 uiDiff)
{
    if (m_uiTimer)
    {
        if (m_uiTimer <= uiDiff)
            DoNextDialogueStep();
        else
            m_uiTimer -= uiDiff;
    }
}

ScriptedPetAI::MoveInLineOfSight.body:
void ScriptedPetAI::MoveInLineOfSight(Unit* pWho)
{
    if (m_creature->GetVictim())
        return;

    if (!m_creature->HasReactState(REACT_AGGRESSIVE))
        return;

    if (!m_creature->IsValidAttackTarget(pWho) || !pWho->IsVisibleForOrDetect(m_creature, m_creature, true) ||
        !m_creature->CanInitiateAttack() || !pWho->IsInAccessablePlaceFor(m_creature) || !m_creature->CanAttack(pWho, true))
        return;

    if (!m_creature->CanFly() && m_creature->GetDistanceZ(pWho) > CREATURE_Z_ATTACK_RANGE)
        return;

    if (m_creature->IsWithinDistInMap(pWho, m_creature->GetAttackDistance(pWho), true, SizeFactor::None) && m_creature->IsWithinLOSInMap(pWho))
    {
        //pWho->RemoveSpellsCausingAura(SPELL_AURA_MOD_STEALTH);
        AttackStart(pWho);
    }
}

ScriptedPetAI::AttackedBy.body:
void ScriptedPetAI::AttackedBy(Unit* pAttacker)
{
    if (m_creature->GetVictim())
        return;

    if (!m_creature->HasReactState(REACT_PASSIVE) &&
        m_creature->CanReachWithMeleeAutoAttack(pAttacker))
        AttackStart(pAttacker);
}

ScriptedPetAI::ResetPetCombat.body:
void ScriptedPetAI::ResetPetCombat()
{
    Unit* pOwner = m_creature->GetCharmerOrOwner();

    if (pOwner && m_creature->GetCharmInfo() && m_creature->GetCharmInfo()->HasCommandState(COMMAND_FOLLOW))
    {
        m_creature->GetMotionMaster()->MoveFollow(pOwner, PET_FOLLOW_DIST, PET_FOLLOW_ANGLE);
    }
    else
    {
        m_creature->GetMotionMaster()->Clear(false);
        m_creature->GetMotionMaster()->MoveIdle();
    }

    m_creature->AttackStop();

    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "ScriptedPetAI reset pet combat and stop attack.");
    Reset();
}

ScriptedPetAI::UpdatePetAI.body:
void ScriptedPetAI::UpdatePetAI(uint32 const uiDiff)
{
    if (!m_CreatureSpells.empty())
        UpdateSpellsList(uiDiff);

    DoMeleeAttackIfReady();
}

ScriptedPetAI::UpdateAI.body:
void ScriptedPetAI::UpdateAI(uint32 const uiDiff)
{
    if (!m_creature->IsAlive())                             // should not be needed, isAlive is checked in mangos before calling UpdateAI
        return;

    // UpdateAllies() is done in the generic PetAI in Mangos, but we can't do this from script side.
    // Unclear what side effects this has, but is something to be resolved from Mangos.

    if (Unit* const pTarget = m_creature->GetVictim())                            // in combat
    {
        if (!pTarget->IsTargetableBy(m_creature))
        {
            // target no longer valid for pet, so either attack stops or new target are selected
            // doesn't normally reach this, because of how petAi is designed in Mangos. CombatStop
            // are called before this update diff, and then pet will already have no victim.
            ResetPetCombat();
            return;
        }
        else if (pTarget->HasAuraPetShouldAvoidBreaking() && m_creature->GetCharmInfo() && (m_creature->GetReactState() != REACT_AGGRESSIVE))
        {
            m_creature->InterruptNonMeleeSpells(false);
            m_creature->AttackStop(true);
            return;
        }

        // update when in combat
        UpdatePetAI(uiDiff);
    }
    else if (m_creature->GetCharmInfo())
    {
        Unit* pOwner = m_creature->GetCharmerOrOwner();

        if (!pOwner)
            return;

        if (pOwner->IsInCombat() && !m_creature->HasReactState(REACT_PASSIVE))
        {
            // Not correct in all cases.
            // When mob initiate attack by spell, pet should not start attack before spell landed.
            if (Unit* const pTarget = pOwner->GetAttackerForHelper())
            {
                // Prevent scripted pets from breaking CC effects
                if (!pTarget->HasAuraPetShouldAvoidBreaking())
                    AttackStart(pTarget);
                else
                {
                    // Main target is CC-ed, so pick another attacker.
                    for (const auto pAttacker : pOwner->GetAttackers())
                    {
                        if (pAttacker->IsInMap(m_creature) && pAttacker->IsTargetableBy(m_creature) && !pAttacker->HasAuraPetShouldAvoidBreaking())
                        { 
                            AttackStart(pAttacker);
                            return;
                        }
                    }
                    // If we are out of the FOR it means no valid targets, so follow master.
                    if (!m_creature->HasUnitState(UNIT_STATE_FOLLOW))
                        m_creature->GetMotionMaster()->MoveFollow(pOwner, PET_FOLLOW_DIST, PET_FOLLOW_ANGLE);
                }
            }
        }
        else if (m_creature->GetCharmInfo()->HasCommandState(COMMAND_FOLLOW))
        {
            // not following, so start follow
            if (!m_creature->HasUnitState(UNIT_STATE_FOLLOW))
                m_creature->GetMotionMaster()->MoveFollow(pOwner, PET_FOLLOW_DIST, PET_FOLLOW_ANGLE);

            // update when not in combat
            UpdatePetOOCAI(uiDiff);
        }
    }
}

