TotemAI::UpdateAI.body:
void TotemAI::UpdateAI(uint32 const /*diff*/)
{
    if (!m_creature->HasUnitState(UNIT_STATE_ROOT))
        m_creature->AddUnitState(UNIT_STATE_ROOT);

    if (m_totemType != TOTEM_ACTIVE)
        return;

    if (!m_creature->IsAlive() || m_creature->IsNonMeleeSpellCasted(false))
        return;

    SpellEntry const* spellInfo = sSpellMgr.GetSpellEntry(m_spellId);
    if (!spellInfo)
        return;

    SpellRangeEntry const* srange = sSpellRangeStore.LookupEntry(spellInfo->rangeIndex);
    float max_range = Spells::GetSpellMaxRange(srange);

    Unit* victim = m_creature->GetMap()->GetUnit(m_victimGuid);
    Unit* owner = m_creature->GetCharmerOrOwner();

    // Check owner's attackers for targets.
    if (!victim && owner)
        victim = owner->GetAttackerForHelper();

    // Search for another target if current is invalid.
    if (!victim || !m_creature->IsWithinDistInMap(victim, max_range) ||
            !m_creature->IsValidAttackTarget(victim) || !victim->IsVisibleForOrDetect(m_creature, m_creature, false))
    {
        victim = nullptr;

        MaNGOS::NearestAttackableUnitInObjectRangeCheck u_check(m_creature, m_creature, owner, max_range);
        MaNGOS::UnitLastSearcher<MaNGOS::NearestAttackableUnitInObjectRangeCheck> checker(victim, u_check);
        Cell::VisitAllObjects(m_creature, checker, max_range);
    }

    if (victim)
    {
        m_victimGuid = victim->GetObjectGuid();

        m_creature->SetInFront(victim);                      // client change orientation by self
        m_creature->CastSpell(victim, m_spellId, false);
    }
    else
        m_victimGuid.Clear();
}

AccountMgr::CreateAccount.body:
AccountOpResult AccountMgr::CreateAccount(std::string username, std::string password)
{
    if (utf8length(username).value_or(MAX_ACCOUNT_STR + 1) > MAX_ACCOUNT_STR)
        return AOR_NAME_TOO_LONG;                           // username's too long

    normalizeString(username);
    normalizeString(password);

    if (GetId(username))
    {
        return AOR_NAME_ALREDY_EXIST;                       // username does already exist
    }

    SRP6 srp;
    srp.CalculateVerifier(CalculateShaPassHash(username, password));
    std::string s_hex = srp.GetSalt().AsHexStr();
    std::string v_hex = srp.GetVerifier().AsHexStr();

    bool update_sv = LoginDatabase.PExecute(
        "INSERT INTO account(`username`, `v`, `s`, `joindate`) VALUES('%s','%s','%s',NOW())",
        username.c_str(), v_hex.c_str(), s_hex.c_str());

    if (!update_sv)
        return AOR_DB_INTERNAL_ERROR;                       // unexpected error

    LoginDatabase.Execute("REPLACE INTO `realmcharacters` (`realmid`, `acctid`, `numchars`) SELECT `realmlist`.`id`, `account`.`id`, 0 FROM `realmlist`,`account` LEFT JOIN `realmcharacters` ON `acctid`=`account`.`id` WHERE `acctid` IS NULL");

    return AOR_OK;                                          // everything's fine
}

AccountMgr::DeleteAccount.body:
AccountOpResult AccountMgr::DeleteAccount(uint32 accid)
{
    std::unique_ptr<QueryResult> result = LoginDatabase.PQuery("SELECT 1 FROM `account` WHERE `id`='%u'", accid);
    if (!result)
        return AOR_NAME_NOT_EXIST;                          // account doesn't exist

    // existing characters list
    result = CharacterDatabase.PQuery("SELECT `guid` FROM `characters` WHERE `account`='%u'", accid);
    if (result)
    {
        do
        {
            Field* fields = result->Fetch();
            uint32 guidlo = fields[0].GetUInt32();
            ObjectGuid guid = ObjectGuid(HIGHGUID_PLAYER, guidlo);

            // kick if player currently
            ObjectAccessor::KickPlayer(guid);
            Player::DeleteFromDB(guid, accid, false);       // no need to update realm characters
        }
        while (result->NextRow());
    }

    // table realm specific but common for all characters of account for realm
    CharacterDatabase.PExecute("DELETE FROM `character_tutorial` WHERE `account` = '%u'", accid);

    LoginDatabase.BeginTransaction();

    bool res =
        LoginDatabase.PExecute("DELETE FROM `account` WHERE `id`='%u'", accid) &&
        LoginDatabase.PExecute("DELETE FROM `realmcharacters` WHERE `acctid`='%u'", accid);

    LoginDatabase.CommitTransaction();

    if (!res)
        return AOR_DB_INTERNAL_ERROR;                       // unexpected error;

    return AOR_OK;
}

AccountMgr::ChangeUsername.body:
AccountOpResult AccountMgr::ChangeUsername(uint32 accid, std::string new_uname, std::string new_passwd)
{
    std::unique_ptr<QueryResult> result = LoginDatabase.PQuery("SELECT 1 FROM `account` WHERE `id`='%u'", accid);
    if (!result)
        return AOR_NAME_NOT_EXIST;                          // account doesn't exist

    if (utf8length(new_uname).value_or(MAX_ACCOUNT_STR + 1) > MAX_ACCOUNT_STR)
        return AOR_NAME_TOO_LONG;

    if (utf8length(new_passwd).value_or(MAX_ACCOUNT_STR + 1) > MAX_ACCOUNT_STR)
        return AOR_PASS_TOO_LONG;

    normalizeString(new_uname);
    normalizeString(new_passwd);

    SRP6 srp;

    srp.CalculateVerifier(CalculateShaPassHash(new_uname, new_passwd));

    std::string safe_new_uname = new_uname;
    LoginDatabase.escape_string(safe_new_uname);

    std::string s_hex = srp.GetSalt().AsHexStr();
    std::string v_hex = srp.GetVerifier().AsHexStr();

    bool update_sv = LoginDatabase.PExecute(
        "UPDATE `account` SET `v`='%s', `s`='%s', `username`='%s' WHERE `id`='%u'",
        v_hex.c_str(), s_hex.c_str(), safe_new_uname.c_str(), accid);

    if (!update_sv)
        return AOR_DB_INTERNAL_ERROR;                       // unexpected error

    GetAccountPersistentData(accid).m_username = new_uname;

    return AOR_OK;
}

AccountMgr::ChangePassword.body:
AccountOpResult AccountMgr::ChangePassword(uint32 accid, std::string new_passwd, std::string username)
{
    if (username.empty())
    {
        if (!GetName(accid, username))
            return AOR_NAME_NOT_EXIST;
    }
    else
        normalizeString(username);                       // account doesn't exist

    if (utf8length(new_passwd).value_or(MAX_ACCOUNT_STR + 1) > MAX_ACCOUNT_STR)
        return AOR_PASS_TOO_LONG;

    normalizeString(new_passwd);

    SRP6 srp;

    srp.CalculateVerifier(CalculateShaPassHash(username, new_passwd));

    std::string s_hex = srp.GetSalt().AsHexStr();
    std::string v_hex = srp.GetVerifier().AsHexStr();

    bool update_sv = LoginDatabase.PExecute(
        "UPDATE `account` SET `v`='%s', `s`='%s' WHERE `id`='%u'",
        v_hex.c_str(), s_hex.c_str(), accid);

    // also reset s and v to force update at next realmd login
    if (!update_sv)
        return AOR_DB_INTERNAL_ERROR;                       // unexpected error

    return AOR_OK;
}

