WardenWin::InitializeClient.body:
void WardenWin::InitializeClient()
{
    if (m_module)
    {
        // should never call this while still using maiev
        MANGOS_ASSERT(!m_maiev);

        if (auto const offsets = GetClientOffets(m_clientBuild))
        {
            // initialize lua
            ByteBuffer lua;
            BuildLuaInit("", true, offsets->GetText, lua);

            // initialize SFile*
            ByteBuffer file;
            BuildFileHashInit("", true, offsets->Open, offsets->Size, offsets->Read, offsets->Close, file);

            // initialize timing check
            ByteBuffer timing;
            BuildTimingInit("", offsets->TickCount, true, timing);

            ByteBuffer pkt(lua.wpos() + file.wpos() + timing.wpos());

            pkt.append(lua);
            pkt.append(file);
            pkt.append(timing);

            SendPacket(pkt);

            m_offsetsInitialized = true;
            sLog.OutWarden(this, LOG_LVL_DEBUG, "Initialized module offsets.");
        }
    }

    m_initialized = true;
}

WardenWin::Update.body:
void WardenWin::Update()
{
    Warden::Update();

    if (!m_initialized)
    {
        if (m_maiev && !TimeoutClockStarted())
        {
            RequestScans(SelectScans(ScanFlags::Maiev));

            if (!m_module)
                BeginScanClock();
        }
        return;
    }

    // 'lpMaximumApplicationAddress' should never be zero if the structure has been read
    if (!m_sysInfoSaved && !!m_sysInfo.lpMaximumApplicationAddress)
    {
        auto activeProcCount = 0;
        for (auto i = 0; i < 8 * sizeof(m_sysInfo.dwActiveProcessorMask); ++i)
            if (!!(m_sysInfo.dwActiveProcessorMask & (1 << i)))
                ++activeProcCount;

        LogsDatabase.BeginTransaction();

        static SqlStatementID fingerprintUpdate;

        auto stmt = LogsDatabase.CreateStatement(fingerprintUpdate,
            "INSERT INTO `system_fingerprint_usage` (`fingerprint`, `account`, `ip`, `realm`, `architecture`, `cputype`, `activecpus`, `totalcpus`, `pagesize`) "
            "VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)");

        stmt.addUInt32(0); // fingerprint not implemented
        stmt.addUInt32(m_accountId);
        stmt.addString(m_sessionIP);
        stmt.addUInt32(realmID);
        stmt.addString(ArchitectureString(m_sysInfo.wProcessorArchitecture));
        stmt.addString(CPUTypeAndRevision(m_sysInfo.dwProcessorType, m_sysInfo.wProcessorRevision));
        stmt.addUInt32(activeProcCount);
        stmt.addUInt32(m_sysInfo.dwNumberOfProcessors);
        stmt.addUInt32(m_sysInfo.dwPageSize);
        stmt.Execute();

        LogsDatabase.CommitTransaction();

        //_session->CleanupFingerprintHistory();

        m_sysInfoSaved = true;

        // at this point if we have the character enum packet, it is okay to send
        if (!m_charEnum.empty())
        {
            sWorld.GetMessager().AddMessage([pkt = std::move(m_charEnum), accountId = m_accountId, sessionGuid = m_sessionGuid](World* world)
            {
                if (WorldSession* session = world->FindSession(accountId))
                {
                    if (session->GetGUID() == sessionGuid)
                        session->SendPacket(&pkt);
                }
            });
            m_charEnum.clear();
        }
    }
}

WardenWin::SetCharEnumPacket.body:
void WardenWin::SetCharEnumPacket(WorldPacket&& packet)
{
    // if we have already recorded system information, send the packet immediately.  otherwise delay
    if (m_sysInfoSaved)
    {
        sWorld.GetMessager().AddMessage([pkt = std::move(packet), accountId = m_accountId, sessionGuid = m_sessionGuid](World* world)
        {
            if (WorldSession* session = world->FindSession(accountId))
            {
                if (session->GetGUID() == sessionGuid)
                    session->SendPacket(&pkt);
            }
        });
    }
    else
        m_charEnum = std::move(packet);
}

WardenWin::GetPlayerInfo.body:
void WardenWin::GetPlayerInfo(std::string& clock, std::string& fingerprint, std::string& hypervisors,
    std::string& renderer, std::string& proxifier) const
{
    if (!!m_lastTimeCheckServer)
    {
        std::stringstream s;
        s << "Last hardware action: " << m_lastHardwareActionTime
            << " client time: " << m_lastClientTime
            << " idle time: " << (m_lastClientTime - m_lastHardwareActionTime) / 1000
            << " seconds info age: " << WorldTimer::getMSTimeDiffToNow(m_lastTimeCheckServer) / 1000
            << " seconds";
        clock = s.str();
    }

    // 'lpMaximumApplicationAddress' should never be zero if the structure has been read
    if (!!m_sysInfo.lpMaximumApplicationAddress)
    {
        std::stringstream s;

        s << "Architecture: " << ArchitectureString(m_sysInfo.wProcessorArchitecture)
            << " CPU Type: " << CPUTypeAndRevision(m_sysInfo.dwProcessorType, m_sysInfo.wProcessorRevision)
            << " Page Size: 0x" << std::hex << std::uppercase << m_sysInfo.dwPageSize << std::dec;

        auto activeProcCount = 0;
        for (auto i = 0; i < 8*sizeof(m_sysInfo.dwActiveProcessorMask); ++i)
            if (!!(m_sysInfo.dwActiveProcessorMask & (1 << i)))
                ++activeProcCount;

        s << " Active CPUs: " << activeProcCount;
        s << " Total CPUs: " << m_sysInfo.dwNumberOfProcessors;

        fingerprint = s.str();
    }

    if (m_hypervisors.length() > 0)
        hypervisors = "Hypervisor(s) found: " + m_hypervisors;

    if (m_renderingApi.has_value())
    {
        std::stringstream s;
        s << "Renderer: " << ClientRenderingApiToString(m_renderingApi.value());
        renderer = s.str();
    }
    else
    {
        std::stringstream s;
        s << "Renderer: Unknown";
        renderer = s.str();
    }

    if (m_endSceneFound)
    {
        std::stringstream s;
        s << " (EndScene: 0x" << std::hex << m_endSceneAddress << ")";
        renderer += s.str();
    }

    if (m_proxifierFound)
        proxifier = "Proxifier is running";
}

AuctionHouseBotMgr::Load.body:
void AuctionHouseBotMgr::Load()
{
    /* 1 - DELETE */
    m_items.clear();
    m_loaded = false;

    if (m_config)
        m_config.reset();

    /*2 - LOAD */
    std::unique_ptr<QueryResult> result(WorldDatabase.Query("SELECT `item`, `stack`, `bid`, `buyout` FROM `auctionhousebot`"));

    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded 0 AuctionHouseBot items");
        return;
    }

    uint32 count = 0;
    BarGoLink bar(result->GetRowCount());

    Field* fields;
    do
    {
        bar.step();
        AuctionHouseBotEntry e;
        fields    = result->Fetch();
        e.item    = fields[0].GetUInt32();
        e.stack   = fields[1].GetUInt32();
        e.bid     = fields[2].GetUInt32();
        e.buyout  = fields[3].GetUInt32();

        m_items.push_back(e);

        ++count;
    }
    while (result->NextRow());

    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u AuctionHouseBot items", count);

    /* CONFIG */
    m_config                 = std::make_unique<AuctionHouseBotConfig>();
    m_config->enable         = sConfig.GetBoolDefault("AHBot.Enable", false);
    m_config->ahfid          = sConfig.GetIntDefault("AHBot.ah.fid", 120);
    m_config->itemcount      = sConfig.GetIntDefault("AHBot.itemcount", 2);

    m_auctionHouseEntry = sAuctionMgr.GetAuctionHouseEntry(m_config->ahfid);
    if (!m_auctionHouseEntry)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "AHBot::Load() : No auction house for faction %u.", m_config->ahfid);
        return;
    }
    m_loaded = true;
}

AuctionHouseBotMgr::Update.body:
void AuctionHouseBotMgr::Update(bool force /* = false */)
{
    if (!m_loaded)
        return;

    ASSERT(m_config);
    ASSERT(m_auctionHouseEntry);

    if (!(m_config->enable || force))
        return;

    if (m_items.empty())
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "AHBot::Update() : Bad config or empty table.");
        return;
    }

    AuctionHouseObject* auctionHouse = sAuctionMgr.GetAuctionsMap(m_auctionHouseEntry);
    if (!auctionHouse)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "AHBot::Update() : No auction house for faction %u.", m_config->ahfid);
        return;
    }

    uint32 auctions     = auctionHouse->GetCount();
    uint32 items        = m_config->itemcount;
    uint32 entriesCount = m_items.size();

    while (auctions < items)
    {
        AuctionHouseBotEntry item = m_items[urand(0, entriesCount - 1)];
        AddItem(item, auctionHouse);
        auctions++;
    }
}

AuctionHouseBotMgr::AddItem.body:
void AuctionHouseBotMgr::AddItem(AuctionHouseBotEntry e, AuctionHouseObject *auctionHouse)
{
    ASSERT(m_auctionHouseEntry);

    ItemPrototype const* prototype = sObjectMgr.GetItemPrototype(e.item);
    if (prototype == nullptr)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "AHBot::AddItem() : Item %u does not exist.", e.item);
        return;
    }

    Item* item = Item::CreateItem(e.item, 1);
    if (!item)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "AHBot::AddItem() : Cannot create item.");
        return;
    }

    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "AHBot::AddItem() : Adding item %u.", e.item);

    uint32 randomPropertyId = Item::GenerateItemRandomPropertyId(e.item);
    if (randomPropertyId != 0)
        item->SetItemRandomProperties(randomPropertyId);

    uint32 etime = urand(1, 3);
    switch (etime)
    {
        case 1:
            etime = 43200;
            break;
        case 2:
            etime = 86400;
            break;
        case 3:
            etime = 172800;
            break;
        default:
            etime = 86400;
            break;
    }
    item->SetCount(e.stack);

    uint32 dep = sAuctionMgr.GetAuctionDeposit(m_auctionHouseEntry, etime, item);

    AuctionEntry* auctionEntry       = new AuctionEntry;
    auctionEntry->Id                 = sObjectMgr.GenerateAuctionID();
    auctionEntry->auctionHouseEntry  = m_auctionHouseEntry;
    auctionEntry->itemGuidLow        = item->GetGUIDLow();
    auctionEntry->itemTemplate       = item->GetEntry();
    auctionEntry->owner              = 0;
    auctionEntry->startbid           = e.bid;
    auctionEntry->buyout             = e.buyout;
    auctionEntry->bidder             = 0;
    auctionEntry->bid                = 0;
    auctionEntry->deposit            = dep;
    auctionEntry->depositTime        = time(nullptr);
    auctionEntry->expireTime         = (time_t) etime + time(nullptr);

    item->SaveToDB();

    sAuctionMgr.AddAItem(item);
    auctionHouse->AddAuction(auctionEntry);
    auctionEntry->SaveToDB();
}

