AuraRemovalManager::LoadFromDB.body:
void AuraRemovalManager::LoadFromDB()
{
    m_data.clear();

    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "> Loading table `instance_buff_removal`");
    uint32 count = 0;
    std::unique_ptr<QueryResult> result = WorldDatabase.Query("SELECT map_id, spell_id, enabled, flags, comment FROM instance_buff_removal");
    if (!result)
    {
        BarGoLink bar(1);
        bar.step();
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table instance_buff_removal is empty.");
    }
    else
    {
        BarGoLink bar(result->GetRowCount());
        do
        {
            bar.step();

            Field* fields = result->Fetch();

            uint32 mapId  = fields[0].GetUInt32();
            uint32 auraId = fields[1].GetUInt32();
            bool enabled = (bool)fields[2].GetUInt8();
            uint32 flags = fields[3].GetUInt32();

            ++count;

            if (enabled)
                m_data[mapId].push_back(AuraRemovalEntry{ auraId, flags });

        } while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u entries from instance_buff_removal", count);
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
    }
}

AuraRemovalManager::PlayerEnterMap.body:
void AuraRemovalManager::PlayerEnterMap(uint32 mapId, Player* pPlayer)
{
    if (!pPlayer)
        return;

    auto it = m_data.find(mapId);
    if (it == m_data.end()) 
        return;

    for(const auto& aura : it->second)
    {

        if (pPlayer->GetTeam() == Team::HORDE && (aura.flags & AURA_REM_FLAG_EXCLUDE_HORDE))
            continue;
        else if (pPlayer->GetTeam() == Team::ALLIANCE && (aura.flags & AURA_REM_FLAG_EXCLUDE_ALLIANCE))
            continue;

        if (pPlayer->HasAura(aura.auraEntry))
            pPlayer->RemoveAurasDueToSpellByCancel(aura.auraEntry);
    }
}

AutoBroadCastMgr::Load.body:
void AutoBroadCastMgr::Load()
{
    entries.clear();
    std::unique_ptr<QueryResult> result(WorldDatabase.Query("SELECT `string_id` FROM `autobroadcast`"));

    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded 0 AutoBroadCast message");
        return;
    }

    uint32 count = 0;
    BarGoLink bar(result->GetRowCount());

    Field* fields;
    do
    {
        bar.step();
        AutoBroadCastEntry e;
        fields = result->Fetch();

        e.stringId = fields[0].GetInt32();

        entries.push_back(e);
        ++count;
    }
    while (result->NextRow());

    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u AutoBroadCast messages", count);

}

AutoBroadCastMgr::Update.body:
void AutoBroadCastMgr::Update(uint32 diff)
{
    if (entries.empty())
        return;

    _current += diff;

    if (_current >= _constInterval)
    {
        AutoBroadCastEntry entry = SelectRandomContainerElement(entries);
        sWorld.SendWorldText(entry.stringId);
        _current = 0;
    }
}

