void BattleGround::IncreaseInvitedCount(Team team)
{
    switch (team)
    {
        case ALLIANCE:
        {
            ++m_invitedAlliance;
            break;
        }
        case HORDE:
        {
            ++m_invitedHorde;
            break;
        }
        default:
        {
            sLog.Out(LOG_BG, LOG_LVL_ERROR, "BattleGround::IncreaseInvitedCount - Unknown player team %u.", team);
            break;
        }
    }
}

