        obj->SetLootState(GO_READY);
        obj->UseDoorOrButton(RESPAWN_NEVER);
    }
    else
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "BattleGround: Door %s not found! - doors will be closed.", guid.GetString().c_str());
