BattleGround::HandleCommand.body:
void BattleGround::HandleCommand(Player* player, ChatHandler* handler, char* args)
{
    std::stringstream in(args);
    std::string commandType;
    in >> commandType;
    if (commandType == "event")
    {
        in >> commandType;
        bool spawn = false;
        bool force = true;
        int event1, event2;
        if (commandType == "spawn")
            spawn = true;
        in >> event1 >> event2;
        in >> commandType;
        if (commandType == "respawn")
            force = false;
        SpawnEvent(event1, event2, spawn, force);
        handler->PSendSysMessage("Event (%u, %u) %s", event1, event2, spawn ? "spawned" : "despawned");
    }
    else if (commandType == "eventi")
    {
        int eventIdx;
        in >> eventIdx;
        handler->PSendSysMessage("Event %u current status: %u", eventIdx, m_activeEvents[eventIdx]);
        for (int j = 0; j < 0xFF; ++j)
            if (!m_eventObjects[MAKE_PAIR32(eventIdx, j)].gameobjects.empty() || !m_eventObjects[MAKE_PAIR32(eventIdx, j)].creatures.empty())
                handler->PSendSysMessage("Event (%u, %u): %u gobj / %u creatures", eventIdx, j, m_eventObjects[MAKE_PAIR32(eventIdx, j)].gameobjects.size(), m_eventObjects[MAKE_PAIR32(eventIdx, j)].creatures.size());
    }
}

BattleGroundAB::Update.body:
void BattleGroundAB::Update(uint32 diff)
{
    if (GetStatus() == STATUS_IN_PROGRESS)
    {
        int team_points[BG_TEAMS_COUNT] = { 0, 0 };

        for (int node = 0; node < BG_AB_NODES_MAX; ++node)
        {

            // 1-minute to occupy a node from contested state
            if (m_nodeTimers[node])
            {
                if (m_nodeTimers[node] > diff)
                    m_nodeTimers[node] -= diff;
                else
                {
                    m_nodeTimers[node] = 0;
                    // Change from contested to occupied !
                    uint8 teamIndex = m_nodes[node] - 1;
                    m_prevNodes[node] = m_nodes[node];
                    m_nodes[node] += 2;
                    // create new occupied banner
                    _CreateBanner(node, BG_AB_NODE_TYPE_OCCUPIED, teamIndex);
                    _SendNodeUpdate(node);
                    _NodeOccupied(node, (teamIndex == 0) ? ALLIANCE : HORDE);
                    // Message to chatlog

                    if (teamIndex == 0)
                    {
                        SendMessage2ToAll(LANG_BG_AB_NODE_TAKEN, CHAT_MSG_BG_SYSTEM_ALLIANCE, nullptr, LANG_BG_ALLY, _GetNodeNameId(node));
                        PlaySoundToAll(BG_AB_SOUND_NODE_CAPTURED_ALLIANCE);
                    }
                    else
                    {
                        SendMessage2ToAll(LANG_BG_AB_NODE_TAKEN, CHAT_MSG_BG_SYSTEM_HORDE, nullptr, LANG_BG_HORDE, _GetNodeNameId(node));
                        PlaySoundToAll(BG_AB_SOUND_NODE_CAPTURED_HORDE);
                    }
                }
            }

            for (int team = 0; team < BG_TEAMS_COUNT; ++team)
                if (m_nodes[node] == team + BG_AB_NODE_TYPE_OCCUPIED)
                    ++team_points[team];
        }

        // Accumulate points
        for (int team = 0; team < BG_TEAMS_COUNT; ++team)
        {
            int points = team_points[team];
            if (!points)
                continue;
            m_lastTick[team] += diff;
            if (m_lastTick[team] > BG_AB_TickIntervals[points])
            {
                m_lastTick[team] -= BG_AB_TickIntervals[points];
                m_teamScores[team] += BG_AB_TickPoints[points];
                m_honorScoreTics[team] += BG_AB_TickPoints[points];
                m_reputationScoreTics[team] += BG_AB_TickPoints[points];
                if (m_reputationScoreTics[team] >= m_reputationTics)
                {
                    (team == BG_TEAM_ALLIANCE) ? RewardReputationToTeam(509, 10, ALLIANCE) : RewardReputationToTeam(510, 10, HORDE);
                    m_reputationScoreTics[team] -= m_reputationTics;
                }
                if (m_honorScoreTics[team] >= m_honorTics)
                {
                    RewardHonorToTeam(BG_AB_PerTickHonor[GetBracketId()], (team == BG_TEAM_ALLIANCE) ? ALLIANCE : HORDE);
                    m_honorScoreTics[team] -= m_honorTics;
                }
                if (!m_isInformedNearVictory && m_teamScores[team] > BG_AB_WARNING_NEAR_VICTORY_SCORE)
                {
                    if (team == BG_TEAM_ALLIANCE)
                    {
                        SendMessageToAll(BCT_BG_AB_A_NEAR_VICTORY, CHAT_MSG_BG_SYSTEM_NEUTRAL);
                        PlaySoundToAll(BG_AB_SOUND_NEAR_VICTORY_ALLIANCE);
                    }
                    else
                    {
                        SendMessageToAll(BCT_BG_AB_H_NEAR_VICTORY, CHAT_MSG_BG_SYSTEM_NEUTRAL);
                        PlaySoundToAll(BG_AB_SOUND_NEAR_VICTORY_HORDE);
                    }
                    m_isInformedNearVictory = true;
                }

                if (m_teamScores[team] > BG_AB_MAX_TEAM_SCORE)
                    m_teamScores[team] = BG_AB_MAX_TEAM_SCORE;
                if (team == BG_TEAM_ALLIANCE)
                    UpdateWorldState(BG_AB_OP_RESOURCES_ALLY, m_teamScores[team]);
                if (team == BG_TEAM_HORDE)
                    UpdateWorldState(BG_AB_OP_RESOURCES_HORDE, m_teamScores[team]);
            }
        }

        // Test win condition
        if (m_teamScores[BG_TEAM_ALLIANCE] >= BG_AB_MAX_TEAM_SCORE)
            EndBattleGround(ALLIANCE);
        if (m_teamScores[BG_TEAM_HORDE] >= BG_AB_MAX_TEAM_SCORE)
            EndBattleGround(HORDE);
    }
    // Execute this at the end, since it can delete the BattleGround object!
    BattleGround::Update(diff);
}

