void AccountSearchHandler::ShowAccountListHelper(std::unique_ptr<QueryResult> result, ChatHandler& chatHandler, uint32& count, uint32 limit, bool title)
{
    // Display the list of account/characters online
    if (!chatHandler.GetSession() && title)                                // not output header for online case
    {
        chatHandler.SendSysMessage(LANG_ACCOUNT_LIST_BAR);
        chatHandler.SendSysMessage(LANG_ACCOUNT_LIST_HEADER);
        chatHandler.SendSysMessage(LANG_ACCOUNT_LIST_BAR);
    }

    // Circle through accounts
    AccountTypes sessionAccess = chatHandler.GetSession() ? chatHandler.GetSession()->GetSecurity() : SEC_CONSOLE;
    do
    {
        // check limit
        if (count == limit)
            break;

        Field* fields = result->Fetch();
        uint32 account = fields[0].GetUInt32();

        WorldSession* session = sWorld.FindSession(account);
        Player* player = session ? session->GetPlayer() : nullptr;
        char const* char_name = player ? player->GetName() : " - ";

        std::string lastIp = chatHandler.GetMangosString(LANG_ERROR);
        bool showIp = true;

        AccountTypes security = sAccountMgr.GetSecurity(account);
        if (sessionAccess < security)
            showIp = false;
        else if (sessionAccess < SEC_ADMINISTRATOR && security > SEC_PLAYER) // Only admins can see GM IPs
            showIp = false;

        if (showIp)
        {
            lastIp = fields[2].GetCppString();
        }
        else
        {
            lastIp = "-";
        }

        std::string acc_name = fields[1].GetCppString();
        if (sAccountMgr.IsAccountBanned(account))
            acc_name = acc_name + " [BANNED]";

        if (chatHandler.GetSession())
            chatHandler.PSendSysMessage(LANG_ACCOUNT_LIST_LINE_CHAT,
                account, acc_name.c_str(), char_name,
                chatHandler.playerLink(lastIp).c_str(),
                security, fields[4].GetUInt32());
        else
            chatHandler.PSendSysMessage(LANG_ACCOUNT_LIST_LINE_CONSOLE,
                account, acc_name.c_str(), char_name,
                chatHandler.playerLink(lastIp).c_str(),
                security, fields[4].GetUInt32());

        ++count;
    } while (result->NextRow());

    if (!chatHandler.GetSession())                                         // not output header for online case
        chatHandler.SendSysMessage(LANG_ACCOUNT_LIST_BAR);
}

PlayerGoldRemovalHandler::HandleGoldLook.body:
void PlayerGoldRemovalHandler::HandleGoldLookupResult(std::unique_ptr<QueryResult> result, uint32 accountId, uint32 removeAmount)
{
    WorldSession* session = sWorld.FindSession(accountId);
    if (!session)
    {
        return;
    }

    ChatHandler chatHandler(session);
    if (!result)
    {
        chatHandler.PSendSysMessage(LANG_PLAYER_NOT_FOUND);
        return;
    }

    uint32 prevMoney = 0;
    uint32 newMoney = 0;
    uint32 guidLow = 0;
    Field* fields = result->Fetch();
    prevMoney = fields[0].GetUInt32();
    guidLow = fields[1].GetUInt32();
    std::string name(fields[2].GetString());

    if (removeAmount > prevMoney)
        newMoney = 0;
    else
        newMoney = prevMoney - removeAmount;
    // Wrap inside user serial or they might login while the query is in progress and all the gold is back
    CharacterDatabase.BeginTransaction(guidLow);
    auto res = CharacterDatabase.PExecute("UPDATE characters SET money = %u WHERE guid = '%u'", newMoney, guidLow);
    CharacterDatabase.CommitTransaction();

    if (!res)
    {
        chatHandler.PSendSysMessage("Encountered a database error during gold removal - see log for details");
        return;
    }

    chatHandler.PSendSysMessage("Removed %ug %us %uc from %s", removeAmount / GOLD, (removeAmount % GOLD) / SILVER, (removeAmount % GOLD) % SILVER, name.c_str());
    chatHandler.PSendSysMessage("%s previously had %ug %us %uc", name.c_str(), prevMoney / GOLD, (prevMoney % GOLD) / SILVER, (prevMoney % GOLD) % SILVER);
    chatHandler.PSendSysMessage("%s now has %ug %us %uc", name.c_str(), newMoney / GOLD, (newMoney % GOLD) / SILVER, (newMoney % GOLD) % SILVER);
}

Channel::Join.body:
void Channel::Join(ObjectGuid guid, char const* password)
{
    WorldPacket data;
    if (IsOn(guid))
    {
        if (!IsConstant())                                  // non send error message for built-in channels
        {
            MakePlayerAlreadyMember(&data, guid);
            SendToOne(&data, guid);
        }
        return;
    }

    if (IsBanned(guid))
    {
        MakeBanned(&data);
        SendToOne(&data, guid);
        return;
    }

    if (m_password.length() > 0 && strcmp(password, m_password.c_str()) != 0)
    {
        MakeWrongPassword(&data);
        SendToOne(&data, guid);
        return;
    }

    PlayerPointer pPlayer = GetPlayer(guid);

    if (m_securityLevel && (!pPlayer.get() || pPlayer->GetSession()->GetSecurity() < m_securityLevel))
    {
        MakeWrongPassword(&data);
        SendToOne(&data, guid);
        return;
    }

    if (pPlayer && pPlayer->ToPlayer())
    {
        if (pPlayer->GetGuildId() && (GetFlags() == 0x38))
            return;

        pPlayer->ToPlayer()->JoinedChannel(this);
    }

    if (m_announce && (!pPlayer.get() || pPlayer->GetSession()->GetSecurity() < SEC_GAMEMASTER || !sWorld.getConfig(CONFIG_BOOL_SILENTLY_GM_JOIN_TO_CHANNEL)))
    {
        MakeJoined(&data, guid);
        SendToAll(&data);
    }

    data.clear();

    PlayerInfo& pinfo = m_players[guid];
    pinfo.player = guid;
    pinfo.flags = MEMBER_FLAG_NONE;

    MakeYouJoined(&data);
    SendToOne(&data, guid);

    JoinNotify(guid);

    // if no owner first logged will become
    if (HasFlag(CHANNEL_FLAG_CUSTOM) && !IsConstant() && !m_ownerGuid)
    {
        SetOwner(guid, (m_players.size() > 1));
        m_players[guid].SetModerator(true);
    }
}

Channel::Leave.body:
void Channel::Leave(ObjectGuid guid, bool send)
{
    if (!IsOn(guid))
    {
        if (send)
        {
            WorldPacket data;
            MakeNotMember(&data);
            SendToOne(&data, guid);
        }
        return;
    }

    PlayerPointer pPlayer = GetPlayer(guid);

    // leave channel
    if (send)
    {
        WorldPacket data;
        MakeYouLeft(&data);
        SendToOne(&data, guid);
        pPlayer->LeftChannel(this);
        data.clear();
    }

    bool changeowner = m_players[guid].IsOwner();

    m_players.erase(guid);
    if (m_announce && (!pPlayer.get() || pPlayer->GetSession()->GetSecurity() < SEC_GAMEMASTER || !sWorld.getConfig(CONFIG_BOOL_SILENTLY_GM_JOIN_TO_CHANNEL)))
    {
        WorldPacket data;
        MakeLeft(&data, guid);
        SendToAll(&data);
    }

    LeaveNotify(guid);

    if (changeowner)
    {
        ObjectGuid newowner = !m_players.empty() ? m_players.begin()->second.player : ObjectGuid();
        SetOwner(newowner);
    }
}

Channel::KickOrBan.body:
void Channel::KickOrBan(ObjectGuid guid, char const* targetName, bool ban)
{
    AccountTypes sec = SEC_PLAYER;
    PlayerPointer gplr = GetPlayer(guid);
    if (gplr)
        sec = gplr->GetSession()->GetSecurity();

    if (!IsOn(guid))
    {
        WorldPacket data;
        MakeNotMember(&data);
        SendToOne(&data, guid);
        return;
    }

    if (!m_players[guid].IsModerator() && sec < SEC_GAMEMASTER)
    {
        WorldPacket data;
        MakeNotModerator(&data);
        SendToOne(&data, guid);
        return;
    }

    Player* pTarget = sObjectMgr.GetPlayer(targetName);
    if (!pTarget)
    {
        WorldPacket data;
        MakePlayerNotFound(&data, targetName);
        SendToOne(&data, guid);
        return;
    }

    ObjectGuid targetGuid = pTarget->GetObjectGuid();
    if (!IsOn(targetGuid))
    {
        WorldPacket data;
        MakePlayerNotFound(&data, targetName);
        SendToOne(&data, guid);
        return;
    }

    bool changeowner = (m_ownerGuid == targetGuid);

    if (sec < SEC_GAMEMASTER && changeowner && guid != m_ownerGuid)
    {
        WorldPacket data;
        MakeNotOwner(&data);
        SendToOne(&data, guid);
        return;
    }

    // kick or ban player
    WorldPacket data;

    if (ban && !IsBanned(targetGuid))
    {
        m_banned.insert(targetGuid);
        MakePlayerBanned(&data, targetGuid, guid);
    }
    else
        MakePlayerKicked(&data, targetGuid, guid);

    SendToAll(&data);
    m_players.erase(targetGuid);
    pTarget->LeftChannel(this);

    if (changeowner)
    {
        ObjectGuid newowner = !m_players.empty() ? guid : ObjectGuid();
        SetOwner(newowner);
    }
}

