MasterPlayer::IsVisibleGloballyFor.body:
bool MasterPlayer::IsVisibleGloballyFor(MasterPlayer* viewer) const
{
    if (!viewer)
        return false;

    // Always can see self
    if (viewer == this)
        return true;

    // GMs are visible for higher gms (or players are visible for gms)
    uint8 security = viewer->GetSession()->GetSecurity();
    if (security > SEC_PLAYER)
        return GetGMInvisibilityRank() <= security;

    return true;
}

MasterPlayer::UpdateSpeakTime.body:
void MasterPlayer::UpdateSpeakTime()
{
    // ignore chat spam protection for GMs in any mode
    if (GetSession()->GetSecurity() > SEC_PLAYER)
        return;

    time_t current = time(nullptr);
    if (m_speakTime > current)
    {
        uint32 max_count = sWorld.getConfig(CONFIG_UINT32_CHATFLOOD_MESSAGE_COUNT);
        if (!max_count)
            return;

        ++m_speakCount;
        if (m_speakCount >= max_count)
        {
            // prevent overwrite mute time, if message send just before mutes set, for example.
            time_t new_mute = current + sWorld.getConfig(CONFIG_UINT32_CHATFLOOD_MUTE_TIME);
            if (GetSession()->m_muteTime < new_mute)
                GetSession()->m_muteTime = new_mute;

            m_speakCount = 0;
        }
    }
    else
        m_speakCount = 0;

    m_speakTime = current + sWorld.getConfig(CONFIG_UINT32_CHATFLOOD_MESSAGE_DELAY);
}

MasterPlayer::Whisper.body:
void MasterPlayer::Whisper(char const* text, uint32 language, MasterPlayer* receiver)
{
    if (language != LANG_ADDON)                             // if not addon data
        language = LANG_UNIVERSAL;                          // whispers should always be readable

    WorldPacket data;
    ChatHandler::BuildChatPacket(data, CHAT_MSG_WHISPER, text, Language(language), GetChatTag(), GetObjectGuid(), GetName());
    receiver->GetSession()->SendPacket(&data);

    // not send confirmation for addon messages
    if (language != LANG_ADDON)
    {
        data.clear();
        ChatHandler::BuildChatPacket(data, CHAT_MSG_WHISPER_INFORM, text, Language(language), receiver->GetChatTag(), receiver->GetObjectGuid());
        GetSession()->SendPacket(&data);
    }

    if (receiver->IsDND())
    {
        data.clear();
        ChatHandler::BuildChatPacket(data, CHAT_MSG_DND, receiver->dndMsg.c_str(), LANG_UNIVERSAL, CHAT_TAG_NONE, receiver->GetObjectGuid());
        GetSession()->SendPacket(&data);
    } 
    else if (receiver->IsAFK())
    {
        data.clear();
        ChatHandler::BuildChatPacket(data, CHAT_MSG_AFK, receiver->afkMsg.c_str(), LANG_UNIVERSAL, CHAT_TAG_NONE, receiver->GetObjectGuid());
        GetSession()->SendPacket(&data);
    }

    if (!IsAcceptWhispers())
        AddAllowedWhisperer(receiver->GetObjectGuid());
}

