ChatHandler::HandleMuteCommand.body:
bool ChatHandler::HandleMuteCommand(char* args)
{
    char* nameStr = ExtractOptNotLastArg(&args);

    Player* target;
    ObjectGuid target_guid;
    std::string target_name;
    if (!ExtractPlayerTarget(&nameStr, &target, &target_guid, &target_name))
        return false;

    uint32 notspeaktime;
    if (!ExtractUInt32(&args, notspeaktime))
        return false;

    std::string givenReason;
    if (char* givenReasonC = ExtractQuotedOrLiteralArg(&args))
        givenReason = givenReasonC;

    uint32 account_id = target ? target->GetSession()->GetAccountId() : sObjectMgr.GetPlayerAccountIdByGUID(target_guid);

    // find only player from same account if any
    if (!target)
    {
        if (WorldSession* session = sWorld.FindSession(account_id))
            target = session->GetPlayer();
    }

    // must have strong lesser security level
    if (HasLowerSecurity(target, target_guid, true))
        return false;

    time_t mutetime = time(nullptr) + notspeaktime * MINUTE;

    if (target)
        target->GetSession()->m_muteTime = mutetime;

    LoginDatabase.PExecute("UPDATE `account` SET `mutetime` = " UI64FMTD " WHERE `id` = '%u'", uint64(mutetime), account_id);

    if (target)
    {
        if (SpellAuraHolder* pAura = target->AddAura(SPELL_PLAYER_MUTED_VISUAL, 0, nullptr))
        {
            pAura->SetAuraDuration(notspeaktime * MINUTE * IN_MILLISECONDS);
            pAura->SetAuraMaxDuration(notspeaktime * MINUTE * IN_MILLISECONDS);
            pAura->RefreshHolder();
        }

        target->PSendSysMessage(LANG_YOUR_CHAT_DISABLED, notspeaktime);
    }

    std::string nameLink = playerLink(target_name);

    PSendSysMessage(LANG_YOU_DISABLE_CHAT, nameLink.c_str(), notspeaktime);

    // Add warning to the account
    std::string authorName = m_session ? m_session->GetPlayerName() : "Console";
    PlayerCacheData const* playerData = sObjectMgr.GetPlayerDataByGUID(target_guid);
    ASSERT(playerData);
    std::stringstream reason;
    reason << playerData->sName << " muted " << notspeaktime << " minutes";
    if (!givenReason.empty())
        reason << " for \"" << givenReason << "\"";
    sWorld.WarnAccount(playerData->uiAccount, authorName, reason.str(), "WARNING");
    return true;
}

ChatHandler::HandleUnmuteCommand.body:
bool ChatHandler::HandleUnmuteCommand(char* args)
{
    Player* target;
    ObjectGuid target_guid;
    std::string target_name;
    if (!ExtractPlayerTarget(&args, &target, &target_guid, &target_name))
        return false;

    uint32 account_id = target ? target->GetSession()->GetAccountId() : sObjectMgr.GetPlayerAccountIdByGUID(target_guid);

    // find only player from same account if any
    if (!target)
    {
        if (WorldSession* session = sWorld.FindSession(account_id))
            target = session->GetPlayer();
    }

    // must have strong lesser security level
    if (HasLowerSecurity(target, target_guid, true))
        return false;

    if (target)
    {
        if (target->CanSpeak())
        {
            SendSysMessage(LANG_CHAT_ALREADY_ENABLED);
            SetSentErrorMessage(true);
            return false;
        }

        target->GetSession()->m_muteTime = 0;
    }

    LoginDatabase.PExecute("UPDATE `account` SET `mutetime` = '0' WHERE `id` = '%u'", account_id);

    if (target)
    {
        target->RemoveAurasDueToSpell(SPELL_PLAYER_MUTED_VISUAL);
        target->PSendSysMessage(LANG_YOUR_CHAT_ENABLED);
    } 

    std::string nameLink = playerLink(target_name);

    PSendSysMessage(LANG_YOU_ENABLE_CHAT, nameLink.c_str());
    return true;
}

ChatHandler::HandleSniffCommand.body:
bool ChatHandler::HandleSniffCommand(char* args)
{
    Player* pPlayer = GetSelectedPlayer();
    if (!pPlayer)
    {
        SendSysMessage(LANG_NO_CHAR_SELECTED);
        SetSentErrorMessage(true);
        return false;
    }

    if (!pPlayer->GetSession()->IsConnected())
    {
        SendSysMessage("Player is disconnected.");
        SetSentErrorMessage(true);
        return false;
    }

    bool value;
    if (!ExtractOnOff(&args, value))
    {
        SendSysMessage(LANG_USE_BOL);
        SetSentErrorMessage(true);
        return false;
    }

    if (value)
    {
        pPlayer->GetSession()->StartSniffing();
        PSendSysMessage("Enabled packet dump for %s.", pPlayer->GetName());
    }
    else
    {
        pPlayer->GetSession()->StopSniffing();
        PSendSysMessage("Disabled packet dump for %s.", pPlayer->GetName());
    }

    return true;
}

