        chr->PSendSysMessage(LANG_YOURS_ENERGY_CHANGED, GetNameLink().c_str(), energyMin, energyMax);

    chr->SetMaxPower(POWER_ENERGY, energyMax);
    chr->SetPower(POWER_ENERGY, energyMin);

    return true;
