    {
        TempSummonType despawnType = static_cast<TemporarySummon*>(pTarget)->GetDespawnType();
        PSendSysMessage("Despawn Type: %s (%u)", TempSummonTypeToString(despawnType), despawnType);
    }
    pTarget->AI()->GetAIInformation(*this);

    return true;
}

