        player = m_session->GetPlayer();

    uint32 mapid = 0;
    bool got_map = false;

    if (strncmp(args, "all", strlen(args)) != 0)
    {
        if (!isNumeric(args[0]))
            return false;

        got_map = true;
        mapid = atoi(args);
    }

    HandleInstanceUnbindHelper(player, got_map, mapid);

    return true;
