            break;
        case SEC_GAMEMASTER:
            secName = "Gamemaster";
            break;
        case SEC_ADMINISTRATOR:
            secName = "Administrator";
            break;
        default:
            secName = "<unknown>";
            break;
    }

    PSendSysMessage("Player limits: amount %u, min. security level %s.", pLimit, secName);

    return true;
}

