CharacterDatabaseCache::DeleteCharacterP.body:
void CharacterDatabaseCache::DeleteCharacterPetById(uint32 id)
{
    PetGuidToPetMap::iterator petStruct = m_petsByGuid.find(id);
    if (petStruct == m_petsByGuid.end())
        return;
    CharPetMap::iterator ownerPets = m_petsByCharacter.find(petStruct->second->ownerGuid);
    if (ownerPets != m_petsByCharacter.end())
    {
        for (CharPetVector::iterator it = ownerPets->second.begin(); it != ownerPets->second.end(); ++it)
            if ((*it)->id == id)
            {
                ownerPets->second.erase(it);
                break;
            }
    }

    delete petStruct->second;
    m_petsByGuid.erase(petStruct);
}

CharacterDatabaseCache::GetNextAvailable.body:
uint32 CharacterDatabaseCache::GetNextAvailablePetNumber(uint32 minimumValue) const
{
    // Returns an iterator pointing to $minimumValue if exists, or greater than $minimumValue
    PetGuidToPetMap::const_iterator it = m_petsByGuid.lower_bound(minimumValue);
    while (it != m_petsByGuid.end() && it->first == minimumValue)
    {
        ++minimumValue;
        ++it;
    }
    return minimumValue;
}

CharacterDatabaseCleaner::CleanDatabase.body:
void CharacterDatabaseCleaner::CleanDatabase()
{
    // config to disable
    if (!sWorld.getConfig(CONFIG_BOOL_CLEAN_CHARACTER_DB))
        return;

    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "Cleaning character database...");

    // check flags which clean ups are necessary
    std::unique_ptr<QueryResult> result = CharacterDatabase.PQuery("SELECT cleaning_flags FROM saved_variables");
    if (!result)
        return;
    uint32 flags = (*result)[0].GetUInt32();

    // clean up
    if (flags & CLEANING_FLAG_SKILLS)
        CleanCharacterSkills();
    if (flags & CLEANING_FLAG_SPELLS)
        CleanCharacterSpell();
    CharacterDatabase.Execute("UPDATE saved_variables SET cleaning_flags = 0");
}

CharacterDatabaseCleaner::CheckUnique.body:
void CharacterDatabaseCleaner::CheckUnique(char const* column, char const* table, bool (*check)(uint32))
{
    std::unique_ptr<QueryResult> result = CharacterDatabase.PQuery("SELECT DISTINCT %s FROM %s", column, table);
    if (!result)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "Table %s is empty.", table);
        return;
    }

    bool found = false;
    std::ostringstream ss;
    BarGoLink bar(result->GetRowCount());
    do
    {
        bar.step();

        Field* fields = result->Fetch();

        uint32 id = fields[0].GetUInt32();

        if (!check(id))
        {
            if (!found)
            {
                ss << "DELETE FROM " << table << " WHERE " << column << " IN (";
                found = true;
            }
            else
                ss << ",";
            ss << id;
        }
    }
    while (result->NextRow());

    if (found)
    {
        ss << ")";
        CharacterDatabase.Execute(ss.str().c_str());
    }
}

