void GmTicket::DeleteFromDB()
{
    static SqlStatementID delTicket;
    SqlStatement stmt = CharacterDatabase.CreateStatement(delTicket, "DELETE FROM `gm_tickets` WHERE `ticket_id` = ?");
    stmt.addUInt32(m_id);
