PlayerMenu::SendQuestGiverQuestDetails.body:
void PlayerMenu::SendQuestGiverQuestDetails(Quest const* pQuest, ObjectGuid npcGUID, bool ActivateAccept)
{
    char const* Title      = pQuest->GetTitle().c_str();
    size_t titleLen        = pQuest->GetTitle().length();
    char const* Details    = pQuest->GetDetails().c_str();
    size_t detailsLen      = pQuest->GetDetails().length();
    char const* Objectives = pQuest->GetObjectives().c_str();
    size_t objectivesLen   = pQuest->GetObjectives().length();

    int loc_idx = GetMenuSession()->GetSessionDbLocaleIndex();
    if (loc_idx >= 0)
    {
        if (QuestLocale const* ql = sObjectMgr.GetQuestLocale(pQuest->GetQuestId()))
        {
            if (ql->Title.size() > (size_t)loc_idx && !ql->Title[loc_idx].empty())
            {
                Title = ql->Title[loc_idx].c_str();
                titleLen = ql->Title[loc_idx].length();
            }
            if (ql->Details.size() > (size_t)loc_idx && !ql->Details[loc_idx].empty())
            {
                Details = ql->Details[loc_idx].c_str();
                detailsLen = ql->Details[loc_idx].length();
            }
            if (ql->Objectives.size() > (size_t)loc_idx && !ql->Objectives[loc_idx].empty())
            {
                Objectives = ql->Objectives[loc_idx].c_str();
                objectivesLen = ql->Objectives[loc_idx].length();
            }
        }
    }

    constexpr size_t mainPartSize =
        sizeof(ObjectGuid) + // npcGUID
        sizeof(uint32) + // QuestId
        sizeof(char) + // Title
        sizeof(char) + // Details
        sizeof(char) + // Objectives
        sizeof(uint32) + // ActivateAccept
        sizeof(uint32) + // RewChoiceItemsCount
        sizeof(uint32) + // RewItemsCount
        sizeof(uint32) + // RewOrReqMoney
        sizeof(uint32) + // RewSpell
        sizeof(uint32) + // QUEST_EMOTE_COUNT
        sizeof(uint32) * QUEST_EMOTE_COUNT + // DetailsEmote
        sizeof(uint32) * QUEST_EMOTE_COUNT; // DetailsEmoteDelay

    constexpr size_t rewChoiceItemsPartSize =
        sizeof(uint32) + // RewChoiceItemId
        sizeof(uint32) + // RewChoiceItemCount
        sizeof(uint32); // DisplayInfoID

    constexpr size_t rewItemsPartSize =
        sizeof(uint32) + // RewItemId
        sizeof(uint32) + // RewItemCount
        sizeof(uint32); // DisplayInfoID

    WorldPacket data(SMSG_QUESTGIVER_QUEST_DETAILS, mainPartSize + titleLen + detailsLen + objectivesLen + 
        pQuest->GetRewChoiceItemsCount() * rewChoiceItemsPartSize +
        pQuest->GetRewItemsCount() * rewItemsPartSize);

    data << ObjectGuid(npcGUID);
    data << uint32(pQuest->GetQuestId());
    data.append(Title, titleLen + 1);
    data.append(Details, detailsLen + 1);
    data.append(Objectives, objectivesLen + 1);
    data << uint32(ActivateAccept ? 1 : 0);                 // auto finish

    if (pQuest->HasQuestFlag(QUEST_FLAGS_HIDDEN_REWARDS))
    {
        data << uint32(0);                                  // Rewarded chosen items hidden
        data << uint32(0);                                  // Rewarded items hidden
        data << uint32(0);                                  // Rewarded money hidden
    }
    else
    {
        ItemPrototype const* IProto;

        auto count = pQuest->GetRewChoiceItemsCount(); // QUEST_REWARD_CHOICES_COUNT
        data << uint32(count); 

        for (uint32 i = 0; i < count; ++i)
        {
            data << uint32(pQuest->RewChoiceItemId[i]);
            data << uint32(pQuest->RewChoiceItemCount[i]);

            IProto = sObjectMgr.GetItemPrototype(pQuest->RewChoiceItemId[i]);

            if (IProto)
                data << uint32(IProto->DisplayInfoID);
            else
                data << uint32(0x00);
        }

        count = pQuest->GetRewItemsCount(); // QUEST_REWARDS_COUNT
        data << uint32(count);

        for (uint32 i = 0; i < count; ++i)
        {
            data << uint32(pQuest->RewItemId[i]);
            data << uint32(pQuest->RewItemCount[i]);

            IProto = sObjectMgr.GetItemPrototype(pQuest->RewItemId[i]);

            if (IProto)
                data << uint32(IProto->DisplayInfoID);
            else
                data << uint32(0x00);
        }

        data << uint32(pQuest->GetRewOrReqMoney());
    }

    data << uint32(pQuest->GetRewSpell());                  // reward spell, this spell will display (icon) (casted if RewSpellCast==0)
    data << uint32(QUEST_EMOTE_COUNT);

    for (uint32 i = 0; i < QUEST_EMOTE_COUNT; ++i)
    {
        data << uint32(pQuest->DetailsEmote[i]);
        data << uint32(pQuest->DetailsEmoteDelay[i]); // delay between emotes in ms
    }

    GetMenuSession()->SendPacket(&data);
}

PlayerMenu::SendQuestGiverOfferReward.body:
void PlayerMenu::SendQuestGiverOfferReward(Quest const* pQuest, ObjectGuid npcGUID, bool EnableNext)
{
    char const* Title = pQuest->GetTitle().c_str();
    size_t titleLen = pQuest->GetTitle().length();
    char const* OfferRewardText = pQuest->GetOfferRewardText().c_str();
    size_t offerRewardLen = pQuest->GetOfferRewardText().length();

    int loc_idx = GetMenuSession()->GetSessionDbLocaleIndex();
    if (loc_idx >= 0)
    {
        if (QuestLocale const* ql = sObjectMgr.GetQuestLocale(pQuest->GetQuestId()))
        {
            if (ql->Title.size() > (size_t)loc_idx && !ql->Title[loc_idx].empty())
            {
                Title = ql->Title[loc_idx].c_str();
                titleLen = ql->Title[loc_idx].length();
            }
            if (ql->OfferRewardText.size() > (size_t)loc_idx && !ql->OfferRewardText[loc_idx].empty())
            {
                OfferRewardText = ql->OfferRewardText[loc_idx].c_str();
                offerRewardLen = ql->OfferRewardText[loc_idx].length();
            }
        }
    }

    constexpr size_t mainPartSize =
        sizeof(ObjectGuid) + // npcGUID
        sizeof(uint32) + // QuestId
        sizeof(char) + // Title
        sizeof(char) + // OfferRewardText
        sizeof(uint32) + // EnableNext
        sizeof(uint32) + // EmoteCount
        sizeof(uint32) + // RewChoiceItemsCount
        sizeof(uint32) + // RewItemsCount
        sizeof(uint32) + // RewOrReqMoney
        sizeof(uint32) + // unused
        sizeof(uint32); // RewSpell

    constexpr size_t emotePartSize =
        sizeof(uint32) + // OfferRewardEmoteDelay
        sizeof(uint32); // OfferRewardEmote

    constexpr size_t rewChoiceItemsPartSize =
        sizeof(uint32) + // RewChoiceItemId
        sizeof(uint32) + // RewChoiceItemCount
        sizeof(uint32); // DisplayInfoID

    constexpr size_t rewItemsPartSize =
        sizeof(uint32) + // RewItemId
        sizeof(uint32) + // RewItemCount
        sizeof(uint32); // DisplayInfoID

    uint32 EmoteCount = 0;
    for (uint32 i : pQuest->OfferRewardEmote)
    {
        if (i <= 0)
            break;
        ++EmoteCount;
    }

    WorldPacket data(SMSG_QUESTGIVER_OFFER_REWARD, mainPartSize + titleLen + offerRewardLen + EmoteCount * emotePartSize +
        pQuest->GetRewChoiceItemsCount() * rewChoiceItemsPartSize +
        pQuest->GetRewItemsCount() * rewItemsPartSize
    );

    data << ObjectGuid(npcGUID);
    data << uint32(pQuest->GetQuestId());
    data.append(Title, titleLen + 1);
    data.append(OfferRewardText, offerRewardLen + 1);
    data << uint32(EnableNext ? 1 : 0);                     // Auto Finish

    data << EmoteCount;                                     // Emote Count
    for (uint32 i = 0; i < EmoteCount; ++i)
    {
        data << uint32(pQuest->OfferRewardEmoteDelay[i]);   // Delay Emote
        data << uint32(pQuest->OfferRewardEmote[i]);
    }

    ItemPrototype const* pItem;

    data << uint32(pQuest->GetRewChoiceItemsCount());
    for (uint32 i = 0; i < pQuest->GetRewChoiceItemsCount(); ++i)
    {
        pItem = sObjectMgr.GetItemPrototype(pQuest->RewChoiceItemId[i]);

        data << uint32(pQuest->RewChoiceItemId[i]);
        data << uint32(pQuest->RewChoiceItemCount[i]);

        if (pItem)
            data << uint32(pItem->DisplayInfoID);
        else
            data << uint32(0x00);
    }

    data << uint32(pQuest->GetRewItemsCount());
    for (uint32 i = 0; i < pQuest->GetRewItemsCount(); ++i)
    {
        pItem = sObjectMgr.GetItemPrototype(pQuest->RewItemId[i]);
        data << uint32(pQuest->RewItemId[i]);
        data << uint32(pQuest->RewItemCount[i]);

        if (pItem)
            data << uint32(pItem->DisplayInfoID);
        else
            data << uint32(0x00);
    }

    data << uint32(pQuest->GetRewOrReqMoney());

    data << uint32(0);              // unused
    data << uint32(pQuest->GetRewSpell());                  // reward spell, this spell will display (icon) (casted if RewSpellCast==0)
    GetMenuSession()->SendPacket(&data);
}

PlayerMenu::SendQuestGiverRequestItems.body:
void PlayerMenu::SendQuestGiverRequestItems(Quest const* pQuest, ObjectGuid npcGUID, bool Completable, bool CloseOnCancel)
{
    // We can always call to RequestItems, but this packet only goes out if there are actually
    // items.  Otherwise, we'll skip straight to the OfferReward

    char const* Title = pQuest->GetTitle().c_str();
    size_t titleLen = pQuest->GetTitle().length();
    char const* RequestItemsText = pQuest->GetRequestItemsText().c_str();
    size_t requestItemsLen = pQuest->GetRequestItemsText().length();

    int loc_idx = GetMenuSession()->GetSessionDbLocaleIndex();
    if (loc_idx >= 0)
    {
        if (QuestLocale const* ql = sObjectMgr.GetQuestLocale(pQuest->GetQuestId()))
        {
            if (ql->Title.size() > (size_t)loc_idx && !ql->Title[loc_idx].empty())
            {
                Title = ql->Title[loc_idx].c_str();
                titleLen = ql->Title[loc_idx].length();
            }
            if (ql->RequestItemsText.size() > (size_t)loc_idx && !ql->RequestItemsText[loc_idx].empty())
            {
                RequestItemsText = ql->RequestItemsText[loc_idx].c_str();
                requestItemsLen = ql->RequestItemsText[loc_idx].length();
            }
        }
    }

    // Quests that don't require items use the RequestItemsText field to store the text
    // that is shown when you talk to the quest giver while the quest is incomplete.
    // Therefore the text should not be shown for them when the quest is complete.
    // For quests that do require items, it is self explanatory.
    if (!requestItemsLen || ((pQuest->GetReqItemsCount() == 0) && Completable))
    {
        SendQuestGiverOfferReward(pQuest, npcGUID, true);
        return;
    }

    constexpr size_t mainPartSize =
        sizeof(ObjectGuid) + // npcGUID
        sizeof(uint32) + // QuestId
        sizeof(char) + // Title
        sizeof(char) + // RequestItemsText
        sizeof(uint32) + // emote delay
        sizeof(uint32) + // emote id
        sizeof(uint32) + // CloseOnCancel
        sizeof(uint32) + // RewOrReqMoney
        sizeof(uint32) + // ReqItemsCount
        sizeof(uint32) + // unknown
        sizeof(uint32) + // flags1
        sizeof(uint32) + // flags2
        sizeof(uint32); // flags3

    constexpr size_t reqItemsPartSize =
        sizeof(uint32) + // ReqItemId
        sizeof(uint32) + // ReqItemCount
        sizeof(uint32); // DisplayInfoID

    WorldPacket data(SMSG_QUESTGIVER_REQUEST_ITEMS, mainPartSize + titleLen + requestItemsLen + pQuest->GetReqItemsCount() * reqItemsPartSize);
    data << ObjectGuid(npcGUID);
    data << uint32(pQuest->GetQuestId());
    data.append(Title, titleLen + 1);
    data.append(RequestItemsText, requestItemsLen + 1);

    data << uint32(0x00);                                   // emote delay

    if (Completable)
        data << pQuest->GetCompleteEmote();                 // emote id
    else
        data << pQuest->GetIncompleteEmote();

    // Close Window after cancel
    if (CloseOnCancel)
        data << uint32(0x01);                               // auto finish
    else
        data << uint32(0x00);

    // Required Money
    data << uint32(pQuest->GetRewOrReqMoney() < 0 ? -pQuest->GetRewOrReqMoney() : 0);

    data << uint32(pQuest->GetReqItemsCount());
    ItemPrototype const* pItem;
    for (int i = 0; i < QUEST_ITEM_OBJECTIVES_COUNT; ++i)
    {
        if (!pQuest->ReqItemId[i])
            continue;
        pItem = sObjectMgr.GetItemPrototype(pQuest->ReqItemId[i]);
        data << uint32(pQuest->ReqItemId[i]);
        data << uint32(pQuest->ReqItemCount[i]);

        if (pItem)
            data << uint32(pItem->DisplayInfoID);
        else
            data << uint32(0);
    }

    data << uint32(0x02);

    if (!Completable)                                       // Completable = flags1 && flags2 && flags3 && flags4
        data << uint32(0x00);                               // flags1
    else
        data << uint32(0x03);

    data << uint32(0x04);                                   // flags2
    data << uint32(0x08);                                   // flags3
    //data << uint32(0x10);                                 // [-ZERO] flags4

    GetMenuSession()->SendPacket(&data);
}

CreatureLinkingMgr::LoadFromDB.body:
void CreatureLinkingMgr::LoadFromDB()
{
    // Clear maps
    m_creatureLinkingMap.clear();
    m_creatureLinkingGuidMap.clear();
    m_eventTriggers.clear();                              // master
    m_eventGuidTriggers.clear();

    // Load `creature_linking_template`
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "> Loading table `creature_linking_template`");
    uint32 count = 0;
    std::unique_ptr<QueryResult> result(WorldDatabase.Query("SELECT `entry`, `map`, `master_entry`, `flag`, `search_range` FROM `creature_linking_template`"));
    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table creature_linking_template is empty.");
    }
    else
    {
        BarGoLink bar(result->GetRowCount());
        do
        {
            bar.step();
            Field* fields = result->Fetch();

            CreatureLinkingInfo tmp;

            uint32 entry 	= fields[0].GetUInt32();
            tmp.mapId 		= fields[1].GetUInt32();
            tmp.masterId 	= fields[2].GetUInt32();
            tmp.linkingFlag 	= fields[3].GetUInt16();
            tmp.searchRange 	= fields[4].GetUInt16();
            tmp.masterDBGuid 	= 0;                        // Will be initialized for unique mobs in IsLinkingEntryValid (only for spawning dependend)

            if (!IsLinkingEntryValid(entry, &tmp, true))
                continue;

            ++count;

            // Add it to the map
            m_creatureLinkingMap.insert(CreatureLinkingMap::value_type(entry, tmp));

            // Store master_entry
            m_eventTriggers.insert(tmp.masterId);
        } while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded creature linking for %u creature-entries", count);
    }

    // Load `creature_linking`
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "> Loading table `creature_linking`");
    count = 0;
    result = WorldDatabase.Query("SELECT `guid`, `master_guid`, `flag` FROM `creature_linking`");
    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table creature_linking is empty.");
        return;
    }

    BarGoLink guidBar(result->GetRowCount());
    do
    {
        guidBar.step();

        Field* fields = result->Fetch();
        CreatureLinkingInfo tmp;

        uint32 guid 		= fields[0].GetUInt32();
        tmp.mapId 		= INVALID_MAP_ID;           // some invalid value, this marks the guid-linking
        tmp.masterId 		= fields[1].GetUInt32();
        tmp.linkingFlag 	= fields[2].GetUInt16();
        tmp.masterDBGuid 	= tmp.masterId;
        tmp.searchRange 	= 0;

        if (!IsLinkingEntryValid(guid, &tmp, false))
            continue;

        ++count;

        // Add it to the map
        m_creatureLinkingGuidMap.insert(CreatureLinkingMap::value_type(guid, tmp));

        // Store master_guid
        m_eventGuidTriggers.insert(tmp.masterId);
    } while (result->NextRow());

    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded creature linking for %u creature-Guids", count);
}

CreatureLinkingMgr::IsLinkingEntryValid.body:
bool CreatureLinkingMgr::IsLinkingEntryValid(uint32 slaveEntry, CreatureLinkingInfo* pTmp, bool byEntry)
{
    // Basic checks first
    if (byEntry)                                            // Entry given
    {
        CreatureInfo const* pInfo = sObjectMgr.GetCreatureTemplate(slaveEntry);
        CreatureInfo const* pMasterInfo = sObjectMgr.GetCreatureTemplate(pTmp->masterId);

        if (!pInfo)
        {
            if (!sObjectMgr.IsExistingCreatureId(slaveEntry))
                sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking_template` has a non existing slave_entry (slave: %u, master %u), skipped.", slaveEntry, pTmp->masterId);
            return false;
        }
        if (!pMasterInfo)
        {
            if (!sObjectMgr.IsExistingCreatureId(pTmp->masterId))
                sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking_template` has a non existing master_entry (slave: %u, master %u), skipped", slaveEntry, pTmp->masterId);
            return false;
        }
        if (pTmp->mapId && !sMapStorage.LookupEntry<MapEntry>(pTmp->mapId))
        {
            sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking_template` has a non existing map %u (slave %u, master %u), skipped", pTmp->mapId, slaveEntry, pTmp->masterId);
            return false;
        }
    }
    else                                                    // guid given
    {
        CreatureData const* slaveData = sObjectMgr.GetCreatureData(slaveEntry);
        CreatureData const* masterData = sObjectMgr.GetCreatureData(pTmp->masterId);

        if (!slaveData)
        {
            if (!sObjectMgr.IsExistingCreatureGuid(slaveEntry))
                sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking` has a non existing slave (guid: %u, master_guid %u), skipped", slaveEntry, pTmp->masterId);
            return false;
        }
        if (!masterData)
        {
            if (!sObjectMgr.IsExistingCreatureGuid(pTmp->masterId))
                sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking` has a non existing master (guid: %u,, master_guid: %u), skipped", slaveEntry, pTmp->masterId);
            return false;
        }
        if (slaveData->position.mapId != masterData->position.mapId)
        {
            sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking` has a slave and master on different maps (guid: %u, master_guid: %u), skipped", slaveEntry, pTmp->masterId);
            return false;
        }
    }

    if (pTmp->linkingFlag & ~(LINKING_FLAG_INVALID - 1) || pTmp->linkingFlag == 0)
    {
        sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking%s` has invalid flag, (entry: %u, map: %u, flags: %u), skipped", byEntry ? "_template" : "", slaveEntry, pTmp->mapId, pTmp->linkingFlag);
        return false;
    }

    // Additional checks, depending on flags
    if (pTmp->linkingFlag & FLAG_DESPAWN_ON_RESPAWN && slaveEntry == pTmp->masterId)
    {
        sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking%s` has pointless FLAG_DESPAWN_ON_RESPAWN for self, (entry: %u, map: %u), skipped", byEntry ? "_template" : "", slaveEntry, pTmp->mapId);
        return false;
    }

    if (byEntry)
    {
        // Check for uniqueness of mob whom is followed, on whom spawning is dependend
        if (pTmp->searchRange == 0 && pTmp->linkingFlag & (FLAG_FOLLOW | FLAG_CANT_SPAWN_IF_BOSS_DEAD | FLAG_CANT_SPAWN_IF_BOSS_ALIVE))
        {
            std::unique_ptr<QueryResult> result = WorldDatabase.PQuery("SELECT guid FROM creature WHERE id=%u AND map=%u LIMIT 2", pTmp->masterId, pTmp->mapId);
            if (!result)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking_template` has FLAG_FOLLOW, but no master, (entry: %u, map: %u, master: %u)", slaveEntry, pTmp->mapId, pTmp->masterId);
                return false;
            }

            if (result->GetRowCount() > 1)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "`creature_linking_template` has FLAG_FOLLOW, but non unique master, (entry: %u, map: %u, master: %u)", slaveEntry, pTmp->mapId, pTmp->masterId);
                return false;
            }
            Field* fields = result->Fetch();
            pTmp->masterDBGuid = fields[0].GetUInt32();
        }
    }

    // All checks are passed, entry/guid is valid
    return true;
}

CreatureLinkingMgr::IsLinkedEventTrigger.body:
bool CreatureLinkingMgr::IsLinkedEventTrigger(Creature* pCreature) const
{
    // Entry case
    if (m_eventTriggers.find(pCreature->GetEntry()) != m_eventTriggers.end())
        return true;

    // Guid case
    if (m_eventGuidTriggers.find(pCreature->GetGUIDLow()) != m_eventGuidTriggers.end())
        return true;

    // Also return true for npcs that trigger reverse actions, or for followers(needed in respawn)
    if (CreatureLinkingInfo const* pInfo = GetLinkedTriggerInformation(pCreature))
        return !!(pInfo->linkingFlag & EVENT_MASK_TRIGGER_TO);

    return false;
}

