            0x98, 0x56, 0x5D, 0x5E, 0x69, 0x72, 0x0A, 0x0D, 0x03, 0x0A, 0x85, 0xA2, 0x85, 0x9C, 0xCB, 0xFB,
            0x56, 0x6E, 0x8F, 0x44, 0xBB, 0x8F, 0x02, 0x22, 0x68, 0x63, 0x97, 0xBC, 0x85, 0xBA, 0xA8, 0xF7,
            0xB5, 0x40, 0x68, 0x3C, 0x77, 0x86, 0x6F, 0x4B, 0xD7, 0x88, 0xCA, 0x8A, 0xD7, 0xCE, 0x36, 0xF0,
            0x45, 0x6E, 0xD5, 0x64, 0x79, 0x0F, 0x17, 0xFC, 0x64, 0xDD, 0x10, 0x6F, 0xF3, 0xF5, 0xE0, 0xA6,
            0xC3, 0xFB, 0x1B, 0x8C, 0x29, 0xEF, 0x8E, 0xE5, 0x34, 0xCB, 0xD1, 0x2A, 0xCE, 0x79, 0xC3, 0x9A,
            0x0D, 0x36, 0xEA, 0x01, 0xE0, 0xAA, 0x91, 0x20, 0x54, 0xF0, 0x72, 0xD8, 0x1E, 0xC7, 0x89, 0xD2
        };
        static constexpr uint32 correctModulusCRC = 0x4C1C776D;

#if SUPPORTED_CLIENT_BUILD <= CLIENT_BUILD_1_10_2
        uint8 unknown0;
        uint32 unknown1;
        decompressedPacket >> unknown0;
        decompressedPacket >> unknown1;

        // wowdev.pub
        *targetPacket << uint8(0);
#endif

        while (decompressedPacket.rpos() < decompressedPacket.size())
        {
            std::string addonName;
            uint8 flags;
            uint32 modulusCRC;
            uint32 urlCRC;

            decompressedPacket >> addonName;
            decompressedPacket >> flags >> modulusCRC >> urlCRC;

            //sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "ADDON: Name: %s Flags %u Modulus CRC: %u URL CRC %u", addonName.c_str(), flags, modulusCRC, urlCRC);

            if (addonName.find("Blizzard") != std::string::npos) // hide standard addons
            {
                *targetPacket << uint8(ADDON_STATUS_HIDDEN);
                *targetPacket << uint8(1);  // InfoProvided
                if (modulusCRC != correctModulusCRC)
                {
                    *targetPacket << uint8(1);  // KeyProvided
                    targetPacket->append(tdata, sizeof(tdata)); // KeyData
                }
                else
                {
                    *targetPacket << uint8(0);  // KeyProvided
                }
                *targetPacket << uint32(0); // Revision
                *targetPacket << uint8(0); // UrlProvided
            }
            else // if addon is custom
                *targetPacket << uint8(ADDON_STATUS_VISIBLE)
                              << uint8(0)  // InfoProvided
                              << uint8(0); // UrlProvided
        }
#endif
    }
    else
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Addon packet uncompress error :(");
        return false;
    }
    return true;
}

WorldSession::HandleAuctionHelloOpcode.body:
void WorldSession::HandleAuctionHelloOpcode(WorldPackets::AuctionHouse::AuctionHello const& packet)
{
    Creature* unit = GetPlayer()->GetNPCIfCanInteractWith(packet.auctioneerGuid, UNIT_NPC_FLAG_AUCTIONEER);
    if (!unit)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "WORLD: HandleAuctionHelloOpcode - %s not found or you can't interact with him.", packet.auctioneerGuid.GetString().c_str());
        return;
    }

    // remove fake death
    if (GetPlayer()->HasUnitState(UNIT_STATE_FEIGN_DEATH))
        GetPlayer()->RemoveSpellsCausingAura(SPELL_AURA_FEIGN_DEATH);

    SendAuctionHello(unit);
}

WorldSession::SendAuctionHello.body:
void WorldSession::SendAuctionHello(Unit* unit)
{
    // always return pointer
    AuctionHouseEntry const* ahEntry = AuctionHouseMgr::GetAuctionHouseEntry(unit);

    WorldPacket data(MSG_AUCTION_HELLO, 12);
    data << unit->GetObjectGuid();
    data << uint32(ahEntry->houseId);
    SendPacket(&data);
}

WorldSession::SendAuctionCommandResult.body:
void WorldSession::SendAuctionCommandResult(AuctionEntry* auc, AuctionAction Action, AuctionError ErrorCode, InventoryResult invError)
{
    WorldPacket data(SMSG_AUCTION_COMMAND_RESULT, 16);
    data << uint32(auc ? auc->Id : 0);
    data << uint32(Action);
    data << uint32(ErrorCode);

    switch (ErrorCode)
    {
        case AUCTION_OK:
            if (Action == AUCTION_BID_PLACED)
                data << uint32(auc->GetAuctionOutBid());    // new AuctionOutBid?
            break;
        case AUCTION_ERR_INVENTORY:
            data << uint32(invError);
            break;
        case AUCTION_ERR_HIGHER_BID:
            data << ObjectGuid(HIGHGUID_PLAYER, auc->bidder); // new bidder guid
            data << uint32(auc->bid);                       // new bid
            data << uint32(auc->GetAuctionOutBid());        // new AuctionOutBid?
            break;
        default:
            break;
    }

    SendPacket(&data);
}

WorldSession::SendAuctionBidderNotificat.body:
void WorldSession::SendAuctionBidderNotification(AuctionEntry* auction, bool won)
{
    WorldPacket data(SMSG_AUCTION_BIDDER_NOTIFICATION, (8 * 4));
    data << uint32(auction->GetHouseId());
    data << uint32(auction->Id);
    data << ObjectGuid(HIGHGUID_PLAYER, auction->bidder);

    // if 0, client shows ERR_AUCTION_WON_S, else ERR_AUCTION_OUTBID_S
    data << uint32(won ? 0 : auction->bid);
    data << uint32(auction->GetAuctionOutBid());            // AuctionOutBid?
    data << uint32(auction->itemTemplate);

    Item *item = sAuctionMgr.GetAItem(auction->itemGuidLow);
    uint32 randomId = item ? item->GetItemRandomPropertyId() : 0;

    data << uint32(randomId);                               // random property (value > 0) or suffix (value < 0)

    SendPacket(&data);
}

WorldSession::SendAuctionOwnerNotificati.body:
void WorldSession::SendAuctionOwnerNotification(AuctionEntry* auction, bool sold)
{
    WorldPacket data(SMSG_AUCTION_OWNER_NOTIFICATION, (7 * 4));
    data << uint32(auction->Id);
    data << uint32(auction->bid);                           // if 0, client shows ERR_AUCTION_EXPIRED_S, else ERR_AUCTION_SOLD_S (works only when guid==0)
    data << uint32(auction->GetAuctionOutBid());            // AuctionOutBid?

    ObjectGuid guid = ObjectGuid();
    if (!sold)                                               // not sold yet
        guid = ObjectGuid(HIGHGUID_PLAYER, auction->bidder);// bidder==0 and !sold for expired auctions, so it will show error message properly

    // if guid!=0, client updates auctions with new bid, outbid and bidderGuid, else it shows error messages as described above
    data << guid;                                           // bidder guid
    data << uint32(auction->itemTemplate);                  // item entry

    Item *item = sAuctionMgr.GetAItem(auction->itemGuidLow);
    uint32 randomId = item ? item->GetItemRandomPropertyId() : 0;

    data << uint32(randomId);                               // random property (value > 0) or suffix (value < 0)
    SendPacket(&data);
}

WorldSession::SendAuctionRemovedNotifica.body:
void WorldSession::SendAuctionRemovedNotification(AuctionEntry* auction)
{
    WorldPacket data(SMSG_AUCTION_REMOVED_NOTIFICATION, (3 * 4));
