        SetTutorialInt(iI, 0x00000000);
}

WorldSession::HandleCharRenameOpcode.body:
void WorldSession::HandleCharRenameOpcode(WorldPackets::Character::CharRename const& packet)
{
    // prevent character rename to invalid name
    if (!normalizePlayerName(const_cast<std::string&>(packet.newname)))
    {
        WorldPacket data(SMSG_CHAR_RENAME, 1);
        data << uint8(CHAR_NAME_NO_NAME);
        SendPacket(&data);
        return;
    }

    uint8 res = ObjectMgr::CheckPlayerName(packet.newname, true);
    if (res != CHAR_NAME_SUCCESS)
    {
        WorldPacket data(SMSG_CHAR_RENAME, 1);
        data << uint8(res);
        SendPacket(&data);
        return;
    }

    // check name limitations
    if (GetSecurity() == SEC_PLAYER && sObjectMgr.IsReservedName(packet.newname))
    {
        WorldPacket data(SMSG_CHAR_RENAME, 1);
        data << uint8(CHAR_NAME_RESERVED);
        SendPacket(&data);
        return;
    }

    std::string escaped_newname = packet.newname;
    CharacterDatabase.escape_string(escaped_newname);

    // make sure that the character belongs to the current account, that rename at login is enabled
    // and that there is no character with the desired new name
    CharacterDatabase.AsyncPQuery(&WorldSession::HandleChangePlayerNameOpcodeCallBack,
                                  GetAccountId(), packet.newname,
                                  "SELECT `guid`, `name` FROM `characters` WHERE `guid` = %u AND `account` = %u AND (`character_flags` & %u) = %u AND NOT EXISTS (SELECT NULL FROM `characters` WHERE `name` = '%s')",
                                  packet.guid.GetCounter(), GetAccountId(), CHARACTER_FLAG_RENAME, CHARACTER_FLAG_RENAME, escaped_newname.c_str()
                                 );
}

WorldSession::HandleChangePlayerNameOpco.body:
void WorldSession::HandleChangePlayerNameOpcodeCallBack(std::unique_ptr<QueryResult> result, uint32 accountId, std::string newname)
{
    WorldSession* session = sWorld.FindSession(accountId);
    if (!session)
    {
        return;
    }

    if (!result)
    {
        WorldPacket data(SMSG_CHAR_RENAME, 1);
        data << uint8(CHAR_CREATE_ERROR);
        session->SendPacket(&data);
        return;
    }

    uint32 guidLow = result->Fetch()[0].GetUInt32();
    ObjectGuid guid = ObjectGuid(HIGHGUID_PLAYER, guidLow);
    std::string oldname = result->Fetch()[1].GetCppString();

    CharacterDatabase.BeginTransaction();
    CharacterDatabase.PExecute("UPDATE `characters` SET `name` = '%s', `character_flags` = (`character_flags` & ~ %u), `character_flags` = (`character_flags` | %u) WHERE `guid` ='%u'", newname.c_str(), uint32(CHARACTER_FLAG_RENAME), uint32(CHARACTER_FLAG_RENAME_NEEDS_GM_REVIEW), guidLow);
    CharacterDatabase.CommitTransaction();

    sLog.Player(session->GetAccountId(), LOG_CHAR, LOG_LVL_BASIC,
        "Account: %d (IP: %s) Character:[%s] (guid:%u) Changed name to: %s",
        session->GetAccountId(), session->GetRemoteAddress().c_str(), oldname.c_str(), guidLow, newname.c_str());

    WorldPacket data(SMSG_CHAR_RENAME, 1 + 8 + (newname.size() + 1));
    data << uint8(RESPONSE_SUCCESS);
    data << guid;
    data << newname;
    session->SendPacket(&data);

    sObjectMgr.ChangePlayerNameInCache(guidLow, oldname, newname);
    sWorld.InvalidatePlayerDataToAllClient(guid);
}

WorldSession::SanitizeChatMessage.body:
bool WorldSession::SanitizeChatMessage(std::string& msg, uint32 lang, uint32 msgType)
{
    if (msg.empty())
        return false;

    if (lang == LANG_ADDON)
        return true; // dont verify addon chat

    if (sWorld.getConfig(CONFIG_BOOL_CHAT_FAKE_MESSAGE_PREVENTING))
        stripLineInvisibleChars(msg); // modifies `msg`

    if (sWorld.getConfig(CONFIG_UINT32_CHAT_STRICT_LINK_CHECKING_SEVERITY) && !ChatHandler(this).isValidChatMessage(msg))
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Player %s (GUID: %u) sent a chatmessage with an invalid link: %s", GetPlayer()->GetName(), GetPlayer()->GetGUIDLow(), msg.c_str());
        if (sWorld.getConfig(CONFIG_UINT32_CHAT_STRICT_LINK_CHECKING_KICK))
            KickPlayer();
        return false;
    }

    return true;
}

WorldSession::SanitizeChatMessageAndProc.body:
bool WorldSession::SanitizeChatMessageAndProcessCommand(std::string& msg, uint32 lang, uint32 msgType)
{
    if (!SanitizeChatMessage(msg, lang, msgType))
        return false; // was invalid message

    ChatHandler handler(this);
    if (handler.ParseCommands(msg.c_str()) == ParseCommandResult::CommandDetectedAndHandled)
        return false; // was handled

    return true;
}

WorldSession::IsLanguageAllowedForChatTy.body:
bool WorldSession::IsLanguageAllowedForChatType(uint32 lang, uint32 msgType)
{
    // Right now we'll just restrict addon language to the appropriate chat types
    // Anything else is OK (default previous behaviour)
    switch (lang)
    {
        case LANG_ADDON:
        {
            switch (msgType)
            {
                case CHAT_MSG_PARTY:
                case CHAT_MSG_GUILD:
                case CHAT_MSG_OFFICER:
                case CHAT_MSG_RAID:
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_10_2
                case CHAT_MSG_RAID_LEADER:
                case CHAT_MSG_RAID_WARNING:
#endif
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_11_2
                case CHAT_MSG_BATTLEGROUND:
                case CHAT_MSG_BATTLEGROUND_LEADER:
#endif
                case CHAT_MSG_CHANNEL:
                    return true;
            }
            return false;
        }
        case LANG_UNIVERSAL:
        {
            switch (msgType)
            {
                case CHAT_MSG_AFK:
                case CHAT_MSG_DND:
                    return true;
            }
            return false;
        }
        default:
            return true;
    }

    return true;
}

WorldSession::ChatCooldown.body:
uint32 WorldSession::ChatCooldown()
{
    ASSERT(GetPlayer());

    auto cooldown = sWorld.getConfig(CONFIG_UINT32_WORLD_CHAN_CD);
    const auto minLevel = sWorld.getConfig(CONFIG_UINT32_WORLD_CHAN_MIN_LEVEL);
    const auto cooldownMaxLvl = sWorld.getConfig(CONFIG_UINT32_WORLD_CHAN_CD_MAX_LEVEL);
    const auto cooldownScaling = sWorld.getConfig(CONFIG_UINT32_WORLD_CHAN_CD_SCALING);
    const auto cooldownUseAcctLvl = sWorld.getConfig(CONFIG_UINT32_WORLD_CHAN_CD_USE_ACCOUNT_MAX_LEVEL);
    const auto playerLevel = cooldownUseAcctLvl? GetAccountMaxLevel() : GetPlayer()->GetLevel();

    if (cooldown && cooldownMaxLvl > playerLevel)
    {
        const auto currTime = time(nullptr);
        const auto delta = currTime - GetLastPubChanMsgTime();

        if (cooldownScaling)
        {
            auto factor = static_cast<double>((cooldownMaxLvl - playerLevel)) / (cooldownMaxLvl - minLevel);
            cooldown *= factor;
        }

        if (delta < cooldown)
        {
            return cooldown - delta;
        }
    }

    return 0;
}

WorldSession::HandleChatMessageOpcode.body:
void WorldSession::HandleChatMessageOpcode(WorldPackets::Chat::ChatMessage const& packet)
{
    if (packet.type >= MAX_CHAT_MSG_TYPE)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "CHAT: Wrong message type received: %u", packet.type);
        return;
    }

    if (!IsLanguageAllowedForChatType(packet.lang, packet.type))
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "CHAT: Wrong language %u received for chat type %u.", packet.lang, packet.type);
        return;
    }

    if (packet.lang == LANG_ADDON)
    {
        // Disabled addon channel?
        if (!sWorld.getConfig(CONFIG_BOOL_ADDON_CHANNEL))
            return;
    }
    // LANG_ADDON should not be changed nor be affected by flood control
    else
    {
        // prevent talking in unknown language (cheating)
        if (packet.lang != LANG_UNIVERSAL && _player && !_player->KnowsLanguage(packet.lang))
        {
            SendNotification(LANG_NOT_LEARNED_LANGUAGE);
            return;
        }

        // send in universal language if player in .gmon mode (ignore spell effects)
        if (_player && _player->IsGameMaster())
            const_cast<uint32&>(packet.lang) = LANG_UNIVERSAL;
        else
        {
            // Send message in universal language if crossfaction chat is enabled and player is using default faction languages.
            if (sWorld.getConfig(CONFIG_BOOL_ALLOW_TWO_SIDE_INTERACTION_CHAT) && (packet.lang == LANG_COMMON || packet.lang == LANG_ORCISH))
                const_cast<uint32&>(packet.lang) = LANG_UNIVERSAL;
            else
            {
                switch (packet.type)
                {
                    case CHAT_MSG_PARTY:
                    case CHAT_MSG_RAID:
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_10_2
                    case CHAT_MSG_RAID_LEADER:
                    case CHAT_MSG_RAID_WARNING:
#endif
                        // allow two side chat at group channel if two side group allowed
                        if (sWorld.getConfig(CONFIG_BOOL_ALLOW_TWO_SIDE_INTERACTION_GROUP))
                            const_cast<uint32&>(packet.lang) = LANG_UNIVERSAL;
                        break;
                    case CHAT_MSG_GUILD:
                    case CHAT_MSG_OFFICER:
                        // allow two side chat at guild channel if two side guild allowed
                        if (sWorld.getConfig(CONFIG_BOOL_ALLOW_TWO_SIDE_INTERACTION_GUILD))
                            const_cast<uint32&>(packet.lang) = LANG_UNIVERSAL;
                        break;
                }
            }

            // but overwrite it by SPELL_AURA_MOD_LANGUAGE auras (only single case used)
            if (_player)
            {
                Unit::AuraList const& ModLangAuras = _player->GetAurasByType(SPELL_AURA_MOD_LANGUAGE);
                if (!ModLangAuras.empty())
                    const_cast<uint32&>(packet.lang) = ModLangAuras.front()->GetModifier()->m_miscvalue;
            }
        }

        if (packet.type != CHAT_MSG_AFK && packet.type != CHAT_MSG_DND) // is not AFK or DND message update
        {
            if (packet.type != CHAT_MSG_WHISPER) // whisper checked later
            {
                auto currTime = time(nullptr);

                if (m_muteTime > currTime) // Muted
                {
                    std::string timeStr = secsToTimeString(m_muteTime - currTime);
                    SendNotification(GetMangosString(LANG_WAIT_BEFORE_SPEAKING), timeStr.c_str());
                    return;
                }
            }

            if (GetMasterPlayer())
                GetMasterPlayer()->UpdateSpeakTime(); // Anti chat flood

            // process message
            if (!SanitizeChatMessageAndProcessCommand(const_cast<std::string&>(packet.message), packet.lang, packet.type)) // <-- includes `CheckChatMessageValidity`
                return;
        }
    }

    /** Enable various spam chat detections */
    if (packet.lang != LANG_ADDON)
    {
        if (AntispamInterface *a = sAnticheatMgr->GetAntispam())
            if (a->isMuted(GetAccountId(), true, packet.type))
                return;
    }

    // Message handling
    switch (packet.type)
    {
        case CHAT_MSG_CHANNEL:
        {
            PlayerPointer playerPointer(GetPlayerPointer());
            ASSERT(playerPointer);
            if (ChannelMgr* cMgr = channelMgr(playerPointer->GetTeam()))
            {
                if (Channel *chn = cMgr->GetChannel(packet.whisperTargetOrChannel, playerPointer))
                {
                    // Level channels restrictions
                    if (chn->IsLevelRestricted() && playerPointer->GetLevel() < sWorld.getConfig(CONFIG_UINT32_WORLD_CHAN_MIN_LEVEL)
                        && GetAccountMaxLevel() < sWorld.getConfig(CONFIG_UINT32_PUB_CHANS_MUTE_VANISH_LEVEL))
                    {
                        ChatHandler(this).SendSysMessage("You cannot use this channel yet.");
                        return;
                    }

                    // Public channels restrictions
                    if (!chn->HasFlag(Channel::CHANNEL_FLAG_CUSTOM))
                    {
                        if (HasTrialRestrictions())
                        {
                            SendNotification(LANG_CANT_USE_PUBLIC_CHANNELS);
                            return;
                        }

                        // GMs should not be able to use public channels
                        if (GetSecurity() > SEC_PLAYER && !sWorld.getConfig(CONFIG_BOOL_GMS_ALLOW_PUBLIC_CHANNELS))
                        {
                            SendNotification(LANG_CANT_USE_PUBLIC_CHANNELS);
                            return;
                        }

                        // Check strict Latin for general chat channels
                        if (sWorld.getConfig(CONFIG_BOOL_STRICT_LATIN_IN_GENERAL_CHANNELS))
                        {
                            // remove color, punct, ctrl, space
                            if (AntispamInterface *a = sAnticheatMgr->GetAntispam())
                            {
                                std::string normMsg = a->normalizeMessage(packet.message, 0x1D);
                                std::wstring w_normMsg;
                                if (Utf8toWStr(normMsg, w_normMsg))
                                {
                                    if (!isBasicLatinString(w_normMsg, true))
                                    {
                                        ChatHandler(this).SendSysMessage("Sorry, only Latin characters are allowed in this channel.");
                                        return;
                                    }
                                }
                            }
                        }

                        if (auto cooldown = ChatCooldown())
                        {
                            ChatHandler(this).PSendSysMessage("Please wait %u seconds before sending another message.", cooldown);
                            return;
                        }
                    }

                    chn->Say(playerPointer->GetObjectGuid(), packet.message.c_str(), packet.lang);
                    SetLastPubChanMsgTime(time(nullptr));

                    if (packet.lang != LANG_ADDON && chn->HasFlag(Channel::ChannelFlags::CHANNEL_FLAG_GENERAL))
                        if (AntispamInterface *a = sAnticheatMgr->GetAntispam())
                            a->addMessage(packet.message, packet.type, GetPlayerPointer(), nullptr);
                }
            }

            if (packet.lang != LANG_ADDON)
            {
                normalizePlayerName(const_cast<std::string&>(packet.whisperTargetOrChannel));
                sWorld.LogChat(this, "Chan", packet.message.c_str(), nullptr, 0, packet.whisperTargetOrChannel.c_str());
            }
        }
        break;

        case CHAT_MSG_SAY:
            if (GetPlayer()->GetLevel() < sWorld.getConfig(CONFIG_UINT32_SAY_MIN_LEVEL)
                && GetAccountMaxLevel() < sWorld.getConfig(CONFIG_UINT32_PUB_CHANS_MUTE_VANISH_LEVEL))
            {
                ChatHandler(this).SendSysMessage("You cannot speak yet (too low level).");
                return;
            }

            if (!GetPlayer()->IsAlive())
                return;

            GetPlayer()->Say(packet.message.c_str(), packet.lang);

            if (packet.lang != LANG_ADDON)
            {
                sWorld.LogChat(this, "Say", packet.message.c_str());

                if (AntispamInterface *a = sAnticheatMgr->GetAntispam())
                    a->addMessage(packet.message, packet.type, GetPlayerPointer(), nullptr);
            }

            break;
        case CHAT_MSG_EMOTE:
            if (GetPlayer()->GetLevel() < sWorld.getConfig(CONFIG_UINT32_SAY_EMOTE_MIN_LEVEL)
                && GetAccountMaxLevel() < sWorld.getConfig(CONFIG_UINT32_PUB_CHANS_MUTE_VANISH_LEVEL))
            {
                ChatHandler(this).SendSysMessage("You cannot use emotes yet (too low level).");
                return;
            }

            if (!GetPlayer()->IsAlive())
                return;

            GetPlayer()->TextEmote(packet.message.c_str());

            if (packet.lang != LANG_ADDON)
            {
                sWorld.LogChat(this, "Emote", packet.message.c_str());

                if (AntispamInterface *a = sAnticheatMgr->GetAntispam())
                    a->addMessage(packet.message, packet.type, GetPlayerPointer(), nullptr);
            }

            break;
        case CHAT_MSG_YELL:
        {
            if (GetPlayer()->GetLevel() < sWorld.getConfig(CONFIG_UINT32_YELL_MIN_LEVEL)
                && GetAccountMaxLevel() < sWorld.getConfig(CONFIG_UINT32_PUB_CHANS_MUTE_VANISH_LEVEL))
            {
                ChatHandler(this).SendSysMessage("You cannot yell yet (too low level).");
                return;
            }

            if (!GetPlayer()->IsAlive())
                return;

            GetPlayer()->Yell(packet.message.c_str(), packet.lang);

            if (packet.lang != LANG_ADDON)
            {
                sWorld.LogChat(this, "Yell", packet.message.c_str());

                if (AntispamInterface *a = sAnticheatMgr->GetAntispam())
                    a->addMessage(packet.message, packet.type, GetPlayerPointer(), nullptr);
            }
        }
        break;

        case CHAT_MSG_WHISPER: // Master Side
        {
            if (!normalizePlayerName(const_cast<std::string&>(packet.whisperTargetOrChannel)))
            {
                SendPlayerNotFoundNotice(packet.whisperTargetOrChannel);
                break;
            }
            MasterPlayer* masterPlr = GetMasterPlayer();
            ASSERT(masterPlr);

            MasterPlayer* player = ObjectAccessor::FindMasterPlayer(packet.whisperTargetOrChannel.c_str());
            uint32 tSecurity = GetSecurity();
            uint32 pSecurity = player ? player->GetSession()->GetSecurity() : SEC_PLAYER;
            if (!player || (tSecurity == SEC_PLAYER && pSecurity > SEC_PLAYER && !player->AcceptsWhispersFrom(masterPlr->GetObjectGuid())))
            {
                SendPlayerNotFoundNotice(packet.whisperTargetOrChannel);
                return;
            }

            // Can only whisper GMs while muted.
            if (pSecurity == SEC_PLAYER)
            {
                auto currTime = time(nullptr);

                if (m_muteTime > currTime) // Muted
                {
                    std::string timeStr = secsToTimeString(m_muteTime - currTime);
                    SendNotification(GetMangosString(LANG_WAIT_BEFORE_SPEAKING), timeStr.c_str());
                    return;
                }
            }

            if (tSecurity == SEC_PLAYER && pSecurity == SEC_PLAYER)
            {
                if (!sWorld.getConfig(CONFIG_BOOL_ALLOW_TWO_SIDE_INTERACTION_CHAT) && GetPlayer()->GetTeam() != player->GetTeam())
                {
                    SendWrongFactionNotice();
                    return;
                }
                if (/*player->GetZoneId() != masterPlr->GetZoneId() && */masterPlr->GetLevel() < sWorld.getConfig(CONFIG_UINT32_WHISP_DIFF_ZONE_MIN_LEVEL))
                {
                    ChatHandler(this).SendSysMessage("You cannot whisper yet.");
                    return;
                }
            }

            if (Player* toPlayer = player->GetSession()->GetPlayer())
            {
                bool allowIgnoreAntispam = toPlayer->IsAllowedWhisperFrom(masterPlr->GetObjectGuid());
                bool allowSendWhisper = allowIgnoreAntispam;

                if (!allowSendWhisper)
                {
                    if (pSecurity == SEC_PLAYER && HasTrialRestrictions())
                        SendNotification(LANG_CAN_ONLY_WHISPER_FRIENDS);
                    else if (!sWorld.getConfig(CONFIG_BOOL_WHISPER_RESTRICTION) || !toPlayer->IsEnabledWhisperRestriction())
                        allowSendWhisper = true;
                }

                if (masterPlr->IsGameMaster() || allowSendWhisper)
                    masterPlr->Whisper(packet.message.c_str(), packet.lang, player);

                if (packet.lang != LANG_ADDON)
                {
                    sWorld.LogChat(this, "Whisp", packet.message.c_str(), PlayerPointer(new PlayerWrapper<MasterPlayer>(player)));

                    if (!allowIgnoreAntispam)
                        if (AntispamInterface *a = sAnticheatMgr->GetAntispam())
                            a->addMessage(packet.message, packet.type, GetPlayerPointer(), PlayerPointer(new PlayerWrapper<MasterPlayer>(player)));
                }
            }
        }
        break;

        case CHAT_MSG_PARTY: // Master Side: TODO
        {
            // if player is in battleground, he cannot say to battleground members by /p
            Group* group = GetPlayer()->GetOriginalGroup();
            if (!group)
            {
                group = _player->GetGroup();
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_11_2
                if (!group || group->isBGGroup())
#else
                if (!group)
#endif
                    return;
            }

            WorldPacket data;
            ChatHandler::BuildChatPacket(data, ChatMsg(packet.type), packet.message.c_str(), Language(packet.lang), _player->GetChatTag(), _player->GetObjectGuid(), _player->GetName());
            group->BroadcastPacket(&data, false, group->GetMemberGroup(GetPlayer()->GetObjectGuid()));
            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "Group", packet.message.c_str(), nullptr, group->GetId());
        }
        break;
        case CHAT_MSG_GUILD: // Master side
        {
            if (GetMasterPlayer()->GetGuildId())
                if (Guild* guild = sGuildMgr.GetGuildById(GetMasterPlayer()->GetGuildId()))
                    guild->BroadcastToGuild(this, packet.message.c_str(), packet.lang == LANG_ADDON ? LANG_ADDON : LANG_UNIVERSAL);

            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "Guild", packet.message.c_str(), nullptr, GetMasterPlayer()->GetGuildId());
            break;
        }
        case CHAT_MSG_OFFICER: // Master side
        {
            if (GetMasterPlayer()->GetGuildId())
                if (Guild* guild = sGuildMgr.GetGuildById(GetMasterPlayer()->GetGuildId()))
                    guild->BroadcastToOfficers(this, packet.message.c_str(), packet.lang == LANG_ADDON ? LANG_ADDON : LANG_UNIVERSAL);

            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "Officer", packet.message.c_str(), nullptr, GetMasterPlayer()->GetGuildId());
            break;
        }
        case CHAT_MSG_RAID: // Master side: TODO
        {
            // if player is in battleground, he cannot say to battleground members by /ra
            Group* group = GetPlayer()->GetOriginalGroup();
            if (!group)
            {
                group = GetPlayer()->GetGroup();
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_11_2
                if (!group || group->isBGGroup() || !group->isRaidGroup())
#else
                if (!group || !group->isRaidGroup())
#endif
                    return;
            }

            WorldPacket data;
            ChatHandler::BuildChatPacket(data, CHAT_MSG_RAID, packet.message.c_str(), Language(packet.lang), _player->GetChatTag(), _player->GetObjectGuid(), _player->GetName());
            group->BroadcastPacket(&data, false);

            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "Raid", packet.message.c_str(), nullptr, group->GetId());
        }
        break;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_10_2
        case CHAT_MSG_RAID_LEADER: // Master side: TODO
        {
            // if player is in battleground, he cannot say to battleground members by /ra
            Group* group = GetPlayer()->GetOriginalGroup();
            if (!group)
            {
                group = GetPlayer()->GetGroup();
                if (!group ||  !group->isRaidGroup() || !group->IsLeader(_player->GetObjectGuid()))
                    return;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_11_2
                if (group->isBGGroup())
                    return;
#endif
            }

            WorldPacket data;
            ChatHandler::BuildChatPacket(data, CHAT_MSG_RAID_LEADER, packet.message.c_str(), Language(packet.lang), _player->GetChatTag(), _player->GetObjectGuid(), _player->GetName());
            group->BroadcastPacket(&data, false);
            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "Raid", packet.message.c_str(), nullptr, group->GetId());
        }
        break;

        case CHAT_MSG_RAID_WARNING: // Master side: TODO
        {
            Group* group = GetPlayer()->GetGroup();
            if (!group || !group->isRaidGroup() ||
                    !(group->IsLeader(GetPlayer()->GetObjectGuid()) || group->IsAssistant(GetPlayer()->GetObjectGuid())))
                return;

            WorldPacket data;
            //in battleground, raid warning is sent only to players in battleground - code is ok
            ChatHandler::BuildChatPacket(data, CHAT_MSG_RAID_WARNING, packet.message.c_str(), Language(packet.lang), _player->GetChatTag(), _player->GetObjectGuid(), _player->GetName());
            group->BroadcastPacket(&data, false);

            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "Raid", packet.message.c_str(), nullptr, group->GetId());
        }
        break;
#endif
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_11_2
        case CHAT_MSG_BATTLEGROUND: // Node side
        {
            // battleground raid is always in Player->GetGroup(), never in GetOriginalGroup()
            Group* group = GetPlayer()->GetGroup();
            if (!group || !group->isBGGroup())
                return;

            WorldPacket data;
            ChatHandler::BuildChatPacket(data, CHAT_MSG_BATTLEGROUND, packet.message.c_str(), Language(packet.lang), _player->GetChatTag(), _player->GetObjectGuid(), _player->GetName());
            group->BroadcastPacket(&data, false);

            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "BG", packet.message.c_str(), nullptr, group->GetId());
        }
        break;

        case CHAT_MSG_BATTLEGROUND_LEADER: // Node side
        {
            // battleground raid is always in Player->GetGroup(), never in GetOriginalGroup()
            Group* group = GetPlayer()->GetGroup();
            if (!group || !group->isBGGroup() || !group->IsLeader(GetPlayer()->GetObjectGuid()))
                return;

            WorldPacket data;
            ChatHandler::BuildChatPacket(data, CHAT_MSG_BATTLEGROUND_LEADER, packet.message.c_str(), Language(packet.lang), _player->GetChatTag(), _player->GetObjectGuid(), _player->GetName());
            group->BroadcastPacket(&data, false);

            if (packet.lang != LANG_ADDON)
                sWorld.LogChat(this, "BG", packet.message.c_str(), nullptr, group->GetId());
        }
        break;
#endif
        case CHAT_MSG_AFK: // Node side (for combat Check)
        {
            if (_player && _player->IsInCombat())
                break;

            if (!packet.message.empty() || !_player->IsAFK())
            {
                if (MasterPlayer* masterPlr = GetMasterPlayer())
                    masterPlr->afkMsg = packet.message;
            }

            if (packet.message.empty() || !_player->IsAFK())
            {
                _player->ToggleAFK();

                if (_player->IsAFK() && _player->IsDND())
                    _player->ToggleDND();
            }
        }
        break;

        case CHAT_MSG_DND:
        {
            if (!packet.message.empty() || !_player->IsDND())
            {
                if (MasterPlayer* masterPlr = GetMasterPlayer())
                    masterPlr->dndMsg = packet.message;
            }

            if (packet.message.empty() || !_player->IsDND())
            {
                _player->ToggleDND();

                if (_player->IsDND() && _player->IsAFK())
                    _player->ToggleAFK();
            }
        }
        break;

        default:
        {
            sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "CHAT: Unknown message type %u, lang: %u sent by %s", packet.type, packet.lang, _player->GetName());
            return;
        }
    }
}

WorldSession::HandleEmoteOpcode.body:
void WorldSession::HandleEmoteOpcode(WorldPackets::Misc::Emote const& packet)
{
    if (!GetPlayer()->IsAlive() || GetPlayer()->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_PREVENT_ANIM))
        return;

    if (!GetPlayer()->CanSpeak())
    {
        std::string timeStr = secsToTimeString(m_muteTime - time(nullptr));
        SendNotification(GetMangosString(LANG_WAIT_BEFORE_SPEAKING), timeStr.c_str());
        return;
    }

    // restrict to the only emotes hardcoded in client
    if (packet.emote != EMOTE_ONESHOT_NONE && packet.emote != EMOTE_ONESHOT_WAVE)
        return;

    GetPlayer()->InterruptSpellsWithChannelFlags(AURA_INTERRUPT_ANIM_CANCELS);
    GetPlayer()->RemoveAurasWithInterruptFlags(AURA_INTERRUPT_ANIM_CANCELS);
    GetPlayer()->HandleEmoteCommand(packet.emote);
}

WorldSession::HandleTextEmoteOpcode.body:
void WorldSession::HandleTextEmoteOpcode(WorldPackets::Misc::TextEmote const& packet)
{
    if (!GetPlayer()->IsAlive() || GetPlayer()->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_PREVENT_ANIM))
        return;

    if (!GetPlayer()->CanSpeak())
    {
        std::string timeStr = secsToTimeString(m_muteTime - time(nullptr));
        SendNotification(GetMangosString(LANG_WAIT_BEFORE_SPEAKING), timeStr.c_str());
        return;
    }

    EmotesTextEntry const* em = sEmotesTextStore.LookupEntry(packet.textEmote);
    if (!em)
        return;

    switch (em->textid)
    {
        case EMOTE_STATE_SLEEP:
        case EMOTE_STATE_SIT:
        case EMOTE_STATE_KNEEL:
        case EMOTE_ONESHOT_NONE:
            break;
        default:
        {
            GetPlayer()->InterruptSpellsWithChannelFlags(AURA_INTERRUPT_ANIM_CANCELS);
            GetPlayer()->RemoveAurasWithInterruptFlags(AURA_INTERRUPT_ANIM_CANCELS);
            GetPlayer()->HandleEmote(em->textid);
            break;
        }
    }

    Unit* unit = GetPlayer()->GetMap()->GetUnit(packet.guid);

    MaNGOS::EmoteChatBuilder emote_builder(*GetPlayer(), packet.textEmote, packet.emoteNum, unit);
    MaNGOS::LocalizedPacketDo<MaNGOS::EmoteChatBuilder > emote_do(emote_builder);
    MaNGOS::CameraDistWorker<MaNGOS::LocalizedPacketDo<MaNGOS::EmoteChatBuilder > > emote_worker(GetPlayer(), sWorld.getConfig(CONFIG_FLOAT_LISTEN_RANGE_TEXTEMOTE), emote_do);
    Cell::VisitWorldObjects(GetPlayer(), emote_worker,  sWorld.getConfig(CONFIG_FLOAT_LISTEN_RANGE_TEXTEMOTE));

    //Send scripted event call
    if (unit && unit->IsCreature() && ((Creature*)unit)->AI())
        ((Creature*)unit)->AI()->ReceiveEmote(GetPlayer(), packet.textEmote);
}

WorldSession::HandleChatIgnoredOpcode.body:
void WorldSession::HandleChatIgnoredOpcode(WorldPackets::Misc::ChatIgnored const& packet)
{
    Player* player = sObjectMgr.GetPlayer(packet.guid);
    if (!player)
        return;

    WorldPacket data;
    ChatHandler::BuildChatPacket(data, CHAT_MSG_IGNORED, _player->GetName(), LANG_UNIVERSAL, CHAT_TAG_NONE, _player->GetObjectGuid());
    player->GetSession()->SendPacket(&data);
}

WorldSession::SendPlayerNotFoundNotice.body:
void WorldSession::SendPlayerNotFoundNotice(std::string const& name)
{
    WorldPacket data(SMSG_CHAT_PLAYER_NOT_FOUND, name.size() + 1);
    data << name;
    SendPacket(&data);
}

WorldSession::SendChatRestrictedNotice.body:
void WorldSession::SendChatRestrictedNotice()
{
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
    WorldPacket data(SMSG_CHAT_RESTRICTED, 0);
    SendPacket(&data);
#endif
}

WorldSession::HandleAttackSwingOpcode.body:
void WorldSession::HandleAttackSwingOpcode(WorldPackets::Combat::AttackSwing const& packet)
{
    if (!packet.targetGuid.IsUnit())
        return;

    Unit* pEnemy = _player->GetMap()->GetUnit(packet.targetGuid);

    if (!pEnemy)
    {
        // stop attack state at client
        SendAttackStop(nullptr);
        return;
    }

    if (_player->IsFriendlyTo(pEnemy) || pEnemy->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_SPAWNING | UNIT_FLAG_NOT_SELECTABLE))
    {
        // stop attack state at client
        SendAttackStop(pEnemy);
        return;
    }

    if (!pEnemy->IsAlive())
    {
        // client can generate swing to known dead target if autoswitch between autoshot and autohit is enabled in client options
        // stop attack state at client
        SendAttackStop(pEnemy);
        return;
    }

    _player->Attack(pEnemy, true);
}

WorldSession::HandleAttackStopOpcode.body:
void WorldSession::HandleAttackStopOpcode(NullClientPacket const& /*packet*/)
{
    GetPlayer()->AttackStop();

    /*
    I wanted to take a moment to provide some clarification around what changed in 1.13.3 with Reckoning.
    There were several systemic issues with extra attack procs behaving incorrectly, which we fixed in the patch.
    A secondary effect of these fixes were two notable changes to Reckoning:
    - Reckoning stacks are lost when you mount up.
    - Reckoning stacks are lost when you initiate an auto-attack against a target and cancel it before it goes off.
    However, both of these behaviors were correct behaviors in the 1.12 reference client and as such are considered bug fixes.
    https://us.forums.blizzard.com/en/wow/t/reckoning-is-broken-after-yesterdays-patch/386476/123
    */
    GetPlayer()->ResetExtraAttacks();
}

WorldSession::HandleSetSheathedOpcode.body:
void WorldSession::HandleSetSheathedOpcode(WorldPackets::Combat::SetSheathed const& packet)
{
    if (packet.sheathed >= MAX_SHEATH_STATE)
        return;

    GetPlayer()->InterruptSpellsWithChannelFlags(AURA_INTERRUPT_SHEATHING_CANCELS);
    GetPlayer()->RemoveAurasWithInterruptFlags(AURA_INTERRUPT_SHEATHING_CANCELS);
    GetPlayer()->SetSheath(SheathState(packet.sheathed));
}

