    SendPacket(&data);
}

WorldSession::HandleSplitItemOpcode.body:
void WorldSession::HandleSplitItemOpcode(WorldPackets::Item::SplitItem const& packet)
{
    uint16 src = ((packet.srcbag << 8) | packet.srcslot);
    uint16 dst = ((packet.dstbag << 8) | packet.dstslot);

    if (src == dst)
        return;

    if (packet.count == 0)
        return;                                             //check count - if zero it's fake packet

    if (!_player->IsValidPos(packet.srcbag, packet.srcslot, true))
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, nullptr, nullptr);
        return;
    }

    if (!_player->IsValidPos(packet.dstbag, packet.dstslot, false))       // can be autostore pos
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_DOESNT_GO_TO_SLOT, nullptr, nullptr);
        return;
    }

    _player->SplitItem(src, dst, packet.count);
}

WorldSession::HandleSwapInvItemOpcode.body:
void WorldSession::HandleSwapInvItemOpcode(WorldPackets::Item::SwapInvItem const& packet)
{
    // prevent attempt swap same item to current position generated by client at special cheating sequence
    if (packet.srcslot == packet.dstslot)
        return;

    if (!_player->IsValidPos(INVENTORY_SLOT_BAG_0, packet.srcslot, true))
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, nullptr, nullptr);
        return;
    }

    if (!_player->IsValidPos(INVENTORY_SLOT_BAG_0, packet.dstslot, true))
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_DOESNT_GO_TO_SLOT, nullptr, nullptr);
        return;
    }

    if ((_player->IsBankPos(INVENTORY_SLOT_BAG_0, packet.srcslot) || _player->IsBankPos(INVENTORY_SLOT_BAG_0, packet.dstslot)) && !_player->CanUseBank())
    {
        _player->SendEquipError(EQUIP_ERR_TOO_FAR_AWAY_FROM_BANK, nullptr, nullptr);
        ProcessAnticheatAction("ItemsCheck", "Attempt to cheat-bank items", CHEAT_ACTION_REPORT_GMS);
        return;
    }

    uint16 src = ((INVENTORY_SLOT_BAG_0 << 8) | packet.srcslot);
    uint16 dst = ((INVENTORY_SLOT_BAG_0 << 8) | packet.dstslot);

    _player->SwapItem(src, dst);
}

WorldSession::HandleAutoEquipItemSlotOpc.body:
void WorldSession::HandleAutoEquipItemSlotOpcode(WorldPackets::Item::AutoEquipItemSlot const& packet)
{
    // cheating attempt, client should never send opcode in that case
    if (!Player::IsEquipmentPos(INVENTORY_SLOT_BAG_0, packet.dstslot))
        return;

    Item* item = _player->GetItemByGuid(packet.itemGuid);
    uint16 dstpos = packet.dstslot | (INVENTORY_SLOT_BAG_0 << 8);

    if (!item || item->GetPos() == dstpos)
        return;

    _player->SwapItem(item->GetPos(), dstpos);
}

WorldSession::HandleSwapItem.body:
void WorldSession::HandleSwapItem(WorldPackets::Item::SwapItem const& packet)
{
    uint16 src = ((packet.srcbag << 8) | packet.srcslot);
    uint16 dst = ((packet.dstbag << 8) | packet.dstslot);

    // prevent attempt swap same item to current position generated by client at special cheating sequence
    if (src == dst)
        return;

    if (!_player->IsValidPos(packet.srcbag, packet.srcslot, true))
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, nullptr, nullptr);
        return;
    }

    if (!_player->IsValidPos(packet.dstbag, packet.dstslot, true))
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_DOESNT_GO_TO_SLOT, nullptr, nullptr);
        return;
    }

    if ((_player->IsBankPos(packet.srcbag, packet.srcslot) || _player->IsBankPos(packet.dstbag, packet.dstslot)) && !_player->CanUseBank())
    {
        _player->SendEquipError(EQUIP_ERR_TOO_FAR_AWAY_FROM_BANK, nullptr, nullptr);
        ProcessAnticheatAction("ItemsCheck", "Attempt to cheat-bank items", CHEAT_ACTION_REPORT_GMS);
        return;
    }

    _player->SwapItem(src, dst);
}

WorldSession::HandleAutoEquipItemOpcode.body:
void WorldSession::HandleAutoEquipItemOpcode(WorldPackets::Item::AutoEquipItem const& packet)
{
    Item *pSrcItem  = _player->GetItemByPos(packet.srcbag, packet.srcslot);
    if (!pSrcItem)
        return;                                             // only at cheat

    uint16 dest;
    InventoryResult msg = _player->CanEquipItem(NULL_SLOT, dest, pSrcItem, !pSrcItem->IsBag());
    if (msg != EQUIP_ERR_OK)
    {
        _player->SendEquipError(msg, pSrcItem, nullptr);
        return;
    }

    uint16 src = pSrcItem->GetPos();
    if (dest == src)                                        // prevent equip in same slot, only at cheat
        return;

    Item *pDstItem = _player->GetItemByPos(dest);
    if (!pDstItem)                                          // empty slot, simple case
    {
        _player->RemoveItem(packet.srcbag, packet.srcslot, true);
        _player->EquipItem(dest, pSrcItem, true);
        _player->AutoUnequipOffhandIfNeed();
    }
    else                                                    // have currently equipped item, not simple case
    {
        uint8 dstbag = pDstItem->GetBagSlot();
        uint8 dstslot = pDstItem->GetSlot();

        msg = _player->CanUnequipItem(dest, !pSrcItem->IsBag());
        if (msg != EQUIP_ERR_OK)
        {
            _player->SendEquipError(msg, pDstItem, pSrcItem);
            return;
        }

        // check dest->src move possibility
        ItemPosCountVec sSrc;
        uint16 eSrc = 0;
        if (_player->IsInventoryPos(src))
        {
            msg = _player->CanStoreItem(packet.srcbag, packet.srcslot, sSrc, pDstItem, true);
            if (msg != EQUIP_ERR_OK)
                msg = _player->CanStoreItem(packet.srcbag, NULL_SLOT, sSrc, pDstItem, true);
            if (msg != EQUIP_ERR_OK)
                msg = _player->CanStoreItem(NULL_BAG, NULL_SLOT, sSrc, pDstItem, true);
        }
        else if (_player->IsBankPos(src))
        {
            msg = _player->CanBankItem(packet.srcbag, packet.srcslot, sSrc, pDstItem, true);
            if (msg != EQUIP_ERR_OK)
                msg = _player->CanBankItem(packet.srcbag, NULL_SLOT, sSrc, pDstItem, true);
            if (msg != EQUIP_ERR_OK)
                msg = _player->CanBankItem(NULL_BAG, NULL_SLOT, sSrc, pDstItem, true);
        }
        else if (_player->IsEquipmentPos(src))
        {
            msg = _player->CanEquipItem(packet.srcslot, eSrc, pDstItem, true);
            if (msg == EQUIP_ERR_OK)
                msg = _player->CanUnequipItem(eSrc, true);
        }

        if (msg != EQUIP_ERR_OK)
        {
            _player->SendEquipError(msg, pDstItem, pSrcItem);
            return;
        }

        // now do moves, remove...
        _player->RemoveItem(dstbag, dstslot, false);
        _player->RemoveItem(packet.srcbag, packet.srcslot, false);

        // add to dest
        _player->EquipItem(dest, pSrcItem, true);

        // add to src
        if (_player->IsInventoryPos(src))
            _player->StoreItem(sSrc, pDstItem, true);
        else if (_player->IsBankPos(src))
            _player->BankItem(sSrc, pDstItem, true);
        else if (_player->IsEquipmentPos(src))
            _player->EquipItem(eSrc, pDstItem, true);

        _player->AutoUnequipOffhandIfNeed();
    }

    if (Player::IsBagPos(dest))
        _player->SendOpenContainer(pSrcItem->GetObjectGuid());
}

WorldSession::HandleDestroyItemOpcode.body:
void WorldSession::HandleDestroyItemOpcode(WorldPackets::Item::DestroyItem const& packet)
{
    uint16 pos = (packet.bag << 8) | packet.slot;

    // prevent drop unequipable items (in combat, for example) and non-empty bags
    if (_player->IsEquipmentPos(pos) || _player->IsBagPos(pos))
    {
        InventoryResult msg = _player->CanUnequipItem(pos, false);
        if (msg != EQUIP_ERR_OK)
        {
            _player->SendEquipError(msg, _player->GetItemByPos(pos), nullptr);
            return;
        }
    }

    Item *pItem  = _player->GetItemByPos(packet.bag, packet.slot);
    if (!pItem)
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, nullptr, nullptr);
        return;
    }

    // checked at client side and not have server side appropriate error output
    if (pItem->GetProto()->Flags & ITEM_FLAG_INDESTRUCTIBLE)
    {
        _player->SendEquipError(EQUIP_ERR_CANT_DROP_SOULBOUND, nullptr, nullptr);
        return;
    }

    if (packet.count)
    {
        uint32 i_count = packet.count;
        _player->DestroyItemCount(pItem, i_count, true);
    }
    else
        _player->DestroyItem(packet.bag, packet.slot, true);
}

WorldSession::HandleItemQuerySingleOpcod.body:
void WorldSession::HandleItemQuerySingleOpcode(WorldPackets::Item::QueryItem const& packet)
{
    ItemPrototype const* pProto = sObjectMgr.GetItemPrototype(packet.itemEntry);
    if (!pProto || (!pProto->Discovered && GetSecurity() <= SEC_PLAYER))
    {
        WorldPacket data(SMSG_ITEM_QUERY_SINGLE_RESPONSE, 4);
        data << uint32(packet.itemEntry | 0x80000000);
        SendPacket(&data);
        return;
    }

    char const* name        = pProto->Name1;
    char const* description = pProto->Description;

    int loc_idx = GetSessionDbLocaleIndex();
    if (loc_idx >= 0)
    {
        ItemLocale const* il = sObjectMgr.GetItemLocale(pProto->ItemId);
        if (il)
        {
            if (il->Name.size() > size_t(loc_idx) && !il->Name[loc_idx].empty())
                name = il->Name[loc_idx].c_str();
            if (il->Description.size() > size_t(loc_idx) && !il->Description[loc_idx].empty())
                description = il->Description[loc_idx].c_str();
        }
    }
    // guess size
    WorldPacket data(SMSG_ITEM_QUERY_SINGLE_RESPONSE, 600);
    data << pProto->ItemId;
    data << pProto->Class;
    // client known only 0 subclass (and 1-2 obsolute subclasses)
    data << (pProto->Class == ITEM_CLASS_CONSUMABLE ? uint32(0) : pProto->SubClass);
    data << name;                                       // max length of any of 4 names: 256 bytes
    data << "";                                         //pProto->Name2; // blizz not send name there, just empty string
    data << "";                                         //pProto->Name3; // blizz not send name there, just empty string
    data << "";                                         //pProto->Name4; // blizz not send name there, just empty string
    data << pProto->DisplayInfoID;
    data << pProto->Quality;
    data << pProto->Flags;
    data << pProto->BuyPrice;
    data << pProto->SellPrice;
    data << pProto->InventoryType;
    data << pProto->AllowableClass;
    data << pProto->AllowableRace;
    data << pProto->ItemLevel;
    data << pProto->RequiredLevel;
    data << pProto->RequiredSkill;
    data << pProto->RequiredSkillRank;
    data << pProto->RequiredSpell;
    data << pProto->RequiredHonorRank;
    data << pProto->RequiredCityRank;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_6_1
    data << pProto->RequiredReputationFaction;
    data << (pProto->RequiredReputationFaction > 0  ? pProto->RequiredReputationRank : 0);   // send value only if reputation faction id setted (needed for some items)
#endif
    data << pProto->MaxCount;
    data << pProto->Stackable;
    data << pProto->ContainerSlots;
    for (const auto& i : pProto->ItemStat)
    {
        data << i.ItemStatType;
        data << i.ItemStatValue;
    }
    for (const auto& i : pProto->Damage)
    {
        data << i.DamageMin;
        data << i.DamageMax;
        data << i.DamageType;
    }

    // resistances (7)
    data << pProto->Armor;
    data << pProto->HolyRes;
    data << pProto->FireRes;
    data << pProto->NatureRes;
    data << pProto->FrostRes;
    data << pProto->ShadowRes;
    data << pProto->ArcaneRes;

    data << pProto->Delay;
    data << pProto->AmmoType;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_9_4
    data << (float)pProto->RangedModRange;
#endif

    for (const auto& itr : pProto->Spells)
    {
        // send DBC data for cooldowns in same way as it used in Spell::SendSpellCooldown
        // use `item_template` or if not set then only use spell cooldowns
        SpellEntry const* spell = sSpellMgr.GetSpellEntry(itr.SpellId);
        if (spell)
        {
            bool db_data = itr.SpellCooldown >= 0 || itr.SpellCategoryCooldown >= 0;

            data << itr.SpellId;
            data << itr.SpellTrigger;

            // let the database control the sign here.  negative means that the item should be consumed once the charges are consumed.
            data << itr.SpellCharges;

            if (db_data)
            {
                data << uint32(itr.SpellCooldown);
                data << uint32(itr.SpellCategory);
                data << uint32(itr.SpellCategoryCooldown);
            }
            else
            {
                data << uint32(spell->RecoveryTime);
                data << uint32(spell->Category);
                data << uint32(spell->CategoryRecoveryTime);
            }
        }
        else
        {
            data << uint32(0);
            data << uint32(0);
            data << uint32(0);
            data << uint32(-1);
            data << uint32(0);
            data << uint32(-1);
        }
    }
    data << pProto->Bonding;
    data << description;
    data << pProto->PageText;
    data << pProto->LanguageID;
    data << pProto->PageMaterial;
    data << pProto->StartQuest;
    data << pProto->LockID;
    data << pProto->Material;
    data << pProto->Sheath;
    data << pProto->RandomProperty;
    data << pProto->Block;
    data << pProto->ItemSet;
    data << pProto->MaxDurability;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_6_1
    data << pProto->Area;
#endif
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_10_2
    data << pProto->Map;
#endif
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
    data << pProto->BagFamily;
#endif
    SendPacket(&data);
}

WorldSession::HandleReadItemOpcode.body:
void WorldSession::HandleReadItemOpcode(WorldPackets::Item::ReadItem const& packet)
{
    Item *pItem = _player->GetItemByPos(packet.bag, packet.slot);

    if (pItem && pItem->GetProto()->PageText)
    {
        WorldPacket data;

        InventoryResult msg = _player->CanUseItem(pItem);
        if (msg == EQUIP_ERR_OK)
        {
            data.Initialize(SMSG_READ_ITEM_OK, 8);
            data << ObjectGuid(pItem->GetObjectGuid());
        }
        else
        {
            data.Initialize(SMSG_READ_ITEM_FAILED, 8 + 1);
            data << ObjectGuid(pItem->GetObjectGuid());
            data << uint8(0);                       // 0..2, read failure reason? if == 1, use next command
            _player->SendEquipError(msg, pItem, nullptr);
        }
        data << ObjectGuid(pItem->GetObjectGuid());
        SendPacket(&data);
    }
    else
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, nullptr, nullptr);
}

