WorldSession::HandleItemNameQueryOpcode.body:
void WorldSession::HandleItemNameQueryOpcode(WorldPackets::Query::ItemNameQuery const& packet)
{
    ItemPrototype const* pProto = sObjectMgr.GetItemPrototype(packet.itemId);
    if (pProto)
    {
        char const* name = pProto->Name1;

        int loc_idx = GetSessionDbLocaleIndex();
        if (loc_idx >= 0)
        {
            ItemLocale const* il = sObjectMgr.GetItemLocale(pProto->ItemId);
            if (il)
            {
                if (il->Name.size() > size_t(loc_idx) && !il->Name[loc_idx].empty())
                    name = il->Name[loc_idx].c_str();
            }
        }

        size_t const nameLen = strlen(name) + 1;

        WorldPacket data(SMSG_ITEM_NAME_QUERY_RESPONSE, (4 + nameLen));
        data << uint32(pProto->ItemId);
        data.append(name, nameLen);
        //data << uint32(pProto->InventoryType);    [-ZERO]
        SendPacket(&data);
        return;
    }
}

WorldSession::HandleWrapItemOpcode.body:
void WorldSession::HandleWrapItemOpcode(WorldPackets::Item::WrapItem const& packet)
{
    Item *gift = _player->GetItemByPos(packet.giftBag, packet.giftSlot);
    if (!gift)
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, gift, nullptr);
        return;
    }

    if (!(gift->GetProto()->Flags & ITEM_FLAG_WRAPPER) || !gift->GetProto()->WrappedGift)
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, gift, nullptr);
        return;
    }

    Item *item = _player->GetItemByPos(packet.itemBag, packet.itemSlot);

    if (!item)
    {
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, item, nullptr);
        return;
    }

    if (item == gift)                                       // not possible with packet from real client
    {
        _player->SendEquipError(EQUIP_ERR_WRAPPED_CANT_BE_WRAPPED, item, nullptr);
        return;
    }

    if (item->IsEquipped())
    {
        _player->SendEquipError(EQUIP_ERR_EQUIPPED_CANT_BE_WRAPPED, item, nullptr);
        return;
    }

    if (item->GetGuidValue(ITEM_FIELD_GIFTCREATOR))         // HasFlag(ITEM_FIELD_FLAGS, ITEM_DYNFLAG_WRAPPED);
    {
        _player->SendEquipError(EQUIP_ERR_WRAPPED_CANT_BE_WRAPPED, item, nullptr);
        return;
    }

    if (item->IsBag())
    {
        _player->SendEquipError(EQUIP_ERR_BAGS_CANT_BE_WRAPPED, item, nullptr);
        return;
    }

    if (item->IsSoulBound())
    {
        _player->SendEquipError(EQUIP_ERR_BOUND_CANT_BE_WRAPPED, item, nullptr);
        return;
    }

    if (item->GetMaxStackCount() != 1)
    {
        _player->SendEquipError(EQUIP_ERR_STACKABLE_CANT_BE_WRAPPED, item, nullptr);
        return;
    }

    // maybe not correct check  (it is better than nothing)
    if (item->GetProto()->MaxCount > 0)
    {
        _player->SendEquipError(EQUIP_ERR_UNIQUE_CANT_BE_WRAPPED, item, nullptr);
        return;
    }

    // don't allow wrapping while casting - fixes an exploit where you could use
    // items multiple times by wrapping them during use
    if (_player->IsNonMeleeSpellCasted(true, false, false))
    {
        _player->SendEquipError(EQUIP_ERR_CANT_DO_RIGHT_NOW, item, nullptr);
        return;
    }

    CharacterDatabase.BeginTransaction(_player->GetGUIDLow());
    CharacterDatabase.PExecute("INSERT INTO character_gifts VALUES ('%u', '%u', '%u', '%u')", item->GetOwnerGuid().GetCounter(), item->GetGUIDLow(), item->GetEntry(), item->GetUInt32Value(ITEM_FIELD_FLAGS));

    item->SetEntry(gift->GetProto()->WrappedGift);
    item->SetGuidValue(ITEM_FIELD_GIFTCREATOR, _player->GetObjectGuid());
    item->SetUInt32Value(ITEM_FIELD_FLAGS, ITEM_DYNFLAG_WRAPPED);
    item->SetState(ITEM_CHANGED, _player);

    if (item->GetState() == ITEM_NEW)                       // save new item, to have alway for `character_gifts` record in `item_instance`
    {
        _player->SaveInventoryAndGoldToDB();
    }
    CharacterDatabase.CommitTransaction();

    uint32 count = 1;
    _player->DestroyItemCount(gift, count, true);
}

WorldSession::HandleAutostoreLootItemOpc.body:
void WorldSession::HandleAutostoreLootItemOpcode(WorldPackets::Loot::AutoStoreLootItem const& packet)
{
    Player*    player = GetPlayer();
    ObjectGuid lguid = player->GetLootGuid();
    Loot*      loot;
    Item*      pItem = nullptr;

    if (lguid.IsEmpty())
        return;

    switch (lguid.GetHigh())
    {
        case HIGHGUID_GAMEOBJECT:
        {
            GameObject* go = player->GetMap()->GetGameObject(lguid);

            // not check distance for GO in case owned GO (fishing bobber case, for example) or Fishing hole GO
            auto ShouldCheckDistance = [go, player = _player]()
            {
                if (go->GetOwnerGuid() == player->GetObjectGuid())
                    return false;

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_6_1
                if (go->GetGoType() == GAMEOBJECT_TYPE_FISHINGHOLE)
                    return false;
#endif

                return true;
            };

            if (!go || (ShouldCheckDistance() && !go->IsWithinDistInMap(_player, INTERACTION_DISTANCE)))
            {
                player->SendLootRelease(lguid);
                return;
            }

            loot = &go->loot;
            break;
        }
        case HIGHGUID_ITEM:
        {
            pItem = player->GetItemByGuid(lguid);

            if (!pItem || !pItem->HasGeneratedLoot())
            {
                player->SendLootRelease(lguid);
                return;
            }

            loot = &pItem->loot;
            break;
        }
        case HIGHGUID_CORPSE:
        {
            Corpse* bones = player->GetMap()->GetCorpse(lguid);
            if (!bones)
            {
                player->SendLootRelease(lguid);
                return;
            }
            loot = &bones->loot;
            break;
        }
        case HIGHGUID_UNIT:
        {
            Creature* pCreature = GetPlayer()->GetMap()->GetCreature(lguid);

            bool ok_loot = pCreature && pCreature->IsAlive() == (player->GetClass() == CLASS_ROGUE && pCreature->lootForPickPocketed);

            if (!ok_loot)
            {
                player->SendLootError(lguid, LOOT_ERROR_DIDNT_KILL);
                return;
            }

            // skinning uses the spell range which is 5 yards
            if (pCreature->lootForSkin)
            {
                if (!pCreature->IsWithinCombatDistInMap(player, INTERACTION_DISTANCE + 1.25f))
                {
                    player->SendLootError(lguid, LOOT_ERROR_TOO_FAR);
                    return;
                }
            }
            else
            {
                if (!pCreature->IsWithinDistInMap(_player, _player->GetMaxLootDistance(pCreature), true, SizeFactor::None))
                {
                    player->SendLootError(lguid, LOOT_ERROR_TOO_FAR);
                    return;
                }
            }

            loot = &pCreature->loot;
            break;
        }
        default:
        {
            sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "%s is unsupported for looting. (%s)", lguid.GetString().c_str(), player->GetObjectGuid().GetString().c_str());
            return;
        }
    }

    QuestItem* qitem = nullptr;
    QuestItem* ffaitem = nullptr;
    QuestItem* conditem = nullptr;

    LootItem* item = loot->LootItemInSlot(packet.lootSlot, player->GetGUIDLow(), &qitem, &ffaitem, &conditem);

    if (!item)
    {
        player->SendEquipError(EQUIP_ERR_ALREADY_LOOTED, nullptr, nullptr);
        return;
    }

    if (!item->AllowedForPlayer(player, loot->GetLootTarget()))
    {
        player->SendLootError(lguid, LOOT_ERROR_DIDNT_KILL);
        return;
    }

    // questitems use the blocked field for other purposes
    if (!qitem && item->is_blocked)
    {
        player->SendLootError(lguid, LOOT_ERROR_DIDNT_KILL);
        return;
    }

    // prevent stealing items if using master loot
    if (lguid.IsCreature() && !item->is_underthreshold && !qitem && !ffaitem)
    {
        if (Group* pGroup = player->GetGroup())
        {
            if (pGroup->GetLootMethod() == MASTER_LOOT)
            {
                player->SendLootError(lguid, LOOT_ERROR_DIDNT_KILL);
                return;
            }
        }
    }

    if (pItem)
        pItem->SetLootState(ITEM_LOOT_CHANGED);

    ItemPosCountVec dest;
    InventoryResult msg = player->CanStoreNewItem(NULL_BAG, NULL_SLOT, dest, item->itemid, item->count);
    if (msg == EQUIP_ERR_OK)
    {
        Item * newitem = player->StoreNewItem(dest, item->itemid, true, item->randomPropertyId);
        if (!newitem)
        {
            sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "Unable to store loot item #%u from %s !", item->itemid, lguid.GetString().c_str());
            return;
        }

        if (qitem)
        {
            qitem->is_looted = true;
            //freeforall is 1 if everyone's supposed to get the quest item.
            if (item->freeforall || loot->GetPlayerQuestItems().size() == 1)
                player->SendNotifyLootItemRemoved(packet.lootSlot);
            else
                loot->NotifyQuestItemRemoved(qitem->index);
        }
        else if (ffaitem)
        {
            //freeforall case, notify only one player of the removal
            ffaitem->is_looted = true;
            player->SendNotifyLootItemRemoved(packet.lootSlot);
        }
        else if (conditem)
        {
            //not freeforall, notify everyone
            conditem->is_looted = true;
            loot->NotifyItemRemoved(packet.lootSlot);
        }
        else
            loot->NotifyItemRemoved(packet.lootSlot);

        //if only one person is supposed to loot the item, then set it to looted
        if (!item->freeforall)
            item->is_looted = true;

        --loot->unlootedCount;


        sLog.Player(this, LOG_LOOTS, LOG_LVL_MINIMAL, "%s loots %ux%u [loot from %s]", _player->GetShortDescription().c_str(), item->count, item->itemid, lguid.GetString().c_str());
        player->SendNewItem(newitem, uint32(item->count), false, false, true);
        player->OnReceivedItem(newitem);
    }
    else
        player->SendEquipError(msg, nullptr, nullptr, item->itemid);
}

WorldSession::HandleLootMoneyOpcode.body:
void WorldSession::HandleLootMoneyOpcode(NullClientPacket const& /*packet*/)
{
    Player* player = GetPlayer();
    if (!player || !player->IsInWorld())
        return;
    ObjectGuid guid = player->GetLootGuid();
    if (!guid)
        return;

    Loot* pLoot = nullptr;
    Item* pItem = nullptr;
    bool shareMoneyWithGroup = true;

    switch (guid.GetHigh())
    {
        case HIGHGUID_GAMEOBJECT:
        {
            GameObject* pGameObject = GetPlayer()->GetMap()->GetGameObject(guid);

            // not check distance for GO in case owned GO (fishing bobber case, for example)
            if (pGameObject && (pGameObject->GetOwnerGuid() == _player->GetObjectGuid() || pGameObject->IsWithinDistInMap(_player, INTERACTION_DISTANCE)))
                pLoot = &pGameObject->loot;

            break;
        }
        case HIGHGUID_CORPSE:                               // remove insignia ONLY in BG
        {
            Corpse* bones = _player->GetMap()->GetCorpse(guid);

            if (bones && bones->IsWithinDistInMap(_player, INTERACTION_DISTANCE))
                pLoot = &bones->loot;

            break;
        }
        case HIGHGUID_ITEM:
        {
            pItem = GetPlayer()->GetItemByGuid(guid);
            if (!pItem || !pItem->HasGeneratedLoot())
                return;

            pLoot = &pItem->loot;
            shareMoneyWithGroup = false;
            break;
        }
        case HIGHGUID_UNIT:
        {
            Creature* pCreature = GetPlayer()->GetMap()->GetCreature(guid);

            if (player->GetClass() == CLASS_ROGUE && pCreature && pCreature->lootForPickPocketed)
                shareMoneyWithGroup = false;
            bool ok_loot = pCreature && pCreature->IsAlive() == (player->GetClass() == CLASS_ROGUE && pCreature->lootForPickPocketed);

            if (ok_loot && pCreature->IsWithinDistInMap(_player, _player->GetMaxLootDistance(pCreature), true, SizeFactor::None))
                pLoot = &pCreature->loot ;

            break;
        }
        default:
            return;                                         // unlootable type
    }

    if (pLoot)
    {
        pLoot->NotifyMoneyRemoved();

        if (shareMoneyWithGroup && player->GetGroup())           //item can be looted only single player
        {
            Group* group = player->GetGroup();

            std::vector<Player*> playersNear;
            playersNear.reserve(group->GetMembersCount());
            for (GroupReference* itr = group->GetFirstMember(); itr != nullptr; itr = itr->next())
            {
                Player* playerGroup = itr->getSource();
                if (!playerGroup)
                    continue;

                if (player->IsWithinLootXPDist(playerGroup))
                    playersNear.push_back(playerGroup);
            }

            uint32 moneyPerPlayer = uint32((pLoot->gold) / (playersNear.size()));

            for (const auto i : playersNear)
            {
                i->LootMoney(moneyPerPlayer, pLoot);
                i->SendLootMoneyNotify(moneyPerPlayer);
            }
        }
        else
        {
            player->LootMoney(pLoot->gold, pLoot);

            // in wotlk and after this should be sent for solo looting too
            //player->SendLootMoneyNotify(pLoot->gold);
        }

        pLoot->gold = 0;

        if (pItem)
            pItem->SetLootState(ITEM_LOOT_CHANGED);
    }
}

WorldSession::HandleLootOpcode.body:
void WorldSession::HandleLootOpcode(WorldPackets::Loot::LootUnit const& packet)
{
    if (!packet.guid.IsAnyTypeCreature() && !packet.guid.IsPlayer() && !packet.guid.IsCorpse())
    {
        _player->SendLootError(packet.guid, LOOT_ERROR_DIDNT_KILL);
        ProcessAnticheatAction("ItemsCheck", "CMSG_LOOT on non-unit guid", CHEAT_ACTION_LOG);
        return;
    }

    // Check possible cheat
    if (!_player->IsAlive() || !_player->IsInWorld())
    {
        _player->SendLootError(packet.guid, LOOT_ERROR_PLAYER_NOT_FOUND);
        return;
    }

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_7_1
    if (_player->HasFlag(PLAYER_FLAGS, PLAYER_FLAGS_NO_PLAY_TIME))
    {
        _player->SendLootError(packet.guid, LOOT_ERROR_PLAY_TIME_EXCEEDED);
        return;
    }
#endif

    if (_player->GetStandState() != UNIT_STAND_STATE_STAND)
    {
        _player->SendLootError(packet.guid, LOOT_ERROR_NOTSTANDING);
        return;
    }

    if (_player->HasUnitState(UNIT_STATE_STUNNED))
    {
        _player->SendLootError(packet.guid, LOOT_ERROR_STUNNED);
        return;
    }

    if (_player->IsNonMeleeSpellCasted())
        _player->InterruptNonMeleeSpells(false);

    GetPlayer()->SendLoot(packet.guid, LOOT_CORPSE);
}

WorldSession::HandleLootReleaseOpcode.body:
void WorldSession::HandleLootReleaseOpcode(WorldPackets::Loot::LootRelease const& /*packet*/)
{
    // cheaters can modify lguid to prevent correct apply loot release code and re-loot
    // use internal stored guid
    if (ObjectGuid lootGuid = GetPlayer()->GetLootGuid())
        DoLootRelease(lootGuid);
}

WorldSession::DoLootRelease.body:
void WorldSession::DoLootRelease(ObjectGuid lguid)
{
    Player*  player = GetPlayer();
    Loot*    loot;

    player->SetLootGuid(ObjectGuid());

    // for disenchanted items first show loot as removed before release
    if (lguid.GetHigh() != HIGHGUID_ITEM)
        player->SendLootRelease(lguid);

    player->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_LOOTING);

    if (!player->IsInWorld())
        return;

    switch (lguid.GetHigh())
    {
        case HIGHGUID_GAMEOBJECT:
        {
            GameObject* go = player->GetMap()->GetGameObject(lguid);
            if (!go)
                return;

            // Chest closed animation
            if (go->GetGoType() == GAMEOBJECT_TYPE_CHEST)
                go->SetGoState(GO_STATE_READY);

            loot = &go->loot;

            // Don't despawn temporarily spawned chests that contain group wide quest items.
            if (loot->HasFFAQuestItems() && !go->isSpawnedByDefault() && go->GetGoType() == GAMEOBJECT_TYPE_CHEST)
            {
                go->SetLootState(GO_READY);
                break;
            }

            if (go->GetGoType() == GAMEOBJECT_TYPE_DOOR)
            {
                // locked doors are opened with spelleffect openlock, prevent remove its as looted
                go->UseDoorOrButton();
                if (go->AI())
                    go->AI()->OnUse(player);
            }
            else if (loot->isLooted() || go->GetGoType() == GAMEOBJECT_TYPE_FISHINGNODE)
            {
                // GO is mineral vein? so it is not removed after its looted
                if (go->GetGoType() == GAMEOBJECT_TYPE_CHEST)
                {
                    uint32 go_min = go->GetGOInfo()->chest.minSuccessOpens;
                    uint32 go_max = go->GetGOInfo()->chest.maxSuccessOpens;

                    // trigger loot events
                    if (go->GetGOInfo()->chest.eventId)
                    {
                        sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "Chest ScriptStart id %u for GO %u", go->GetGOInfo()->chest.eventId, go->GetGUIDLow());

                        if (!sScriptMgr.OnProcessEvent(go->GetGOInfo()->chest.eventId, _player, go, true))
                            go->GetMap()->ScriptsStart(sEventScripts, go->GetGOInfo()->chest.eventId, _player->GetObjectGuid(), go->GetObjectGuid());
                    }

                    // only vein pass this check
                    if (go_min != 0 && go_max > go_min)
                    {
                        float amount_rate = sWorld.getConfig(CONFIG_FLOAT_RATE_MINING_AMOUNT);
                        float min_amount = go_min * amount_rate;
                        float max_amount = go_max * amount_rate;

                        go->AddUse();
                        float uses = float(go->GetUseCount());

                        if (uses < max_amount)
                        {
                            if (uses >= min_amount)
                            {
                                float chance_rate = sWorld.getConfig(CONFIG_FLOAT_RATE_MINING_NEXT);

                                int32 ReqValue = 175;
                                LockEntry const* lockInfo = sLockStore.LookupEntry(go->GetGOInfo()->chest.lockId);
                                if (lockInfo)
                                    ReqValue = lockInfo->Skill[0];
                                float skill = float(player->GetSkillValue(SKILL_MINING)) / (ReqValue + 25);
                                double chance = pow(0.8 * chance_rate, 4 * (1 / double(max_amount)) * double(uses));
                                if (roll_chance_f(float(100.0f * chance + skill)))
                                    go->SetLootState(GO_READY);
                                else                            // not have more uses
                                    go->SetLootState(GO_JUST_DEACTIVATED);
                            }
                            else                                // 100% chance until min uses
                                go->SetLootState(GO_READY);
                        }
                        else                                    // max uses already
                            go->SetLootState(GO_JUST_DEACTIVATED);
                    }
                    else                                        // not vein
                        go->SetLootState(GO_JUST_DEACTIVATED);
                }
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_6_1
                else if (go->GetGoType() == GAMEOBJECT_TYPE_FISHINGHOLE)
                {
                    // The fishing hole used once more
                    go->AddUse();                               // if the max usage is reached, will be despawned at next tick
                    if (go->GetUseCount() >= urand(go->GetGOInfo()->fishinghole.minSuccessOpens, go->GetGOInfo()->fishinghole.maxSuccessOpens))
                        go->SetLootState(GO_JUST_DEACTIVATED);
                    else
                        go->SetLootState(GO_READY);
                }
#endif
                else // not chest (or vein/herb/etc)
                    go->SetLootState(GO_JUST_DEACTIVATED);

                loot->clear();
            }
            else
            {
                // not fully looted object
                go->SetLootState(GO_ACTIVATED);

                // respawn partially looted chests 5 mins after being opened
                if (go->GetGoType() == GAMEOBJECT_TYPE_CHEST)
                {
                    go->SetCooldownTime(time(nullptr) + 5 * MINUTE);
                }
            }
            break;
        }
        case HIGHGUID_CORPSE:                               // ONLY remove insignia at BG
        {
            Corpse* corpse = _player->GetMap()->GetCorpse(lguid);
            if (!corpse)
                return;

            loot = &corpse->loot;

            if (loot->isLooted())
            {
                loot->clear();
                corpse->RemoveFlag(CORPSE_FIELD_DYNAMIC_FLAGS, CORPSE_DYNFLAG_LOOTABLE);
            }
            corpse->ForceValuesUpdateAtIndex(CORPSE_FIELD_DYNAMIC_FLAGS);
            corpse->ExecuteDelayedActions();
            break;
        }
        case HIGHGUID_ITEM:
        {
            Item *pItem = player->GetItemByGuid(lguid);
            if (!pItem)
                return;

            switch (pItem->loot.loot_type)
            {
                // temporary loot, auto loot move
                case LOOT_DISENCHANTING:
                {
                    if (!pItem->loot.isLooted())
                        player->AutoStoreLoot(pItem->loot); // can be lost if no space
                    pItem->loot.clear();
                    pItem->SetLootState(ITEM_LOOT_REMOVED);
                    player->DestroyItem(pItem->GetBagSlot(), pItem->GetSlot(), true);
                    break;
                }
                // normal persistence loot
                default:
                {
                    // must be destroyed only if no loot
                    if (pItem->loot.isLooted() && !pItem->IsBag())
                    {
                        pItem->SetLootState(ITEM_LOOT_REMOVED);
                        player->DestroyItem(pItem->GetBagSlot(), pItem->GetSlot(), true);
                    }
                    break;
                }
            }
            player->SendLootRelease(lguid);
            return;                                         // item can be looted only single player
        }
        case HIGHGUID_UNIT:
        {
            Creature* creature = player->GetMap()->GetCreature(lguid);
            if (!creature)
                return;

            loot = &creature->loot;

            if (loot->isLooted())
            {
                // skip pickpocketing loot for speed, skinning timer reduction is no-op in fact
                if (!creature->IsAlive())
                    creature->AllLootRemovedFromCorpse();

                creature->RemoveFlag(UNIT_DYNAMIC_FLAGS, UNIT_DYNFLAG_LOOTABLE);
                loot->clear();
            }
            else
            {
                // if the round robin player release, reset it.
                if (player->GetGUID() == loot->roundRobinPlayer)
                {
                    if (Group* group = player->GetGroup())
                    {
                        if (group->GetLootMethod() != MASTER_LOOT)
                        {
                            loot->roundRobinPlayer = 0;
                            group->SendLooter(creature, nullptr);

                            // force update of dynamic flags, otherwise other group's players still not able to loot.
                            creature->ForceValuesUpdateAtIndex(UNIT_DYNAMIC_FLAGS);
                        }
                    }
                    else
                        loot->roundRobinPlayer = 0;
                }
            }
            break;
        }
        default:
        {
            sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "%s is unsupported for looting.", lguid.GetString().c_str());
            return;
        }
    }

    // Player is not looking at loot list, he doesn't need to see updates on the loot list
    loot->RemoveLooter(player->GetObjectGuid());
}

WorldSession::HandleLootMasterGiveOpcode.body:
void WorldSession::HandleLootMasterGiveOpcode(WorldPackets::Loot::LootMasterGive const& packet)
{
    if (!_player->GetGroup() || _player->GetGroup()->GetLootMethod() != MASTER_LOOT || _player->GetGroup()->GetLooterGuid() != _player->GetObjectGuid())
    {
        _player->SendLootError(packet.lootGuid, LOOT_ERROR_DIDNT_KILL);
        return;
    }

    Player* target = ObjectAccessor::FindPlayer(packet.playerGuid);
    if (!target || !target->IsInWorld())
    {
        _player->SendLootError(packet.lootGuid, LOOT_ERROR_PLAYER_NOT_FOUND);
        return;
    }

    // No loot for a player on another map, or not in the raid.
    if (!_player->IsInRaidWith(target) || !_player->IsInMap(target))
    {
        _player->SendLootError(packet.lootGuid, LOOT_ERROR_MASTER_OTHER);
        return;
    }

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_7_1
    if (target->HasFlag(PLAYER_FLAGS, PLAYER_FLAGS_NO_PLAY_TIME))
    {
        _player->SendLootError(packet.lootGuid, LOOT_ERROR_MASTER_OTHER);
        return;
    }
#endif

    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "WorldSession::HandleLootMasterGiveOpcode (CMSG_LOOT_MASTER_GIVE, 0x02A3) Target = %s [%s].", packet.playerGuid.GetString().c_str(), target->GetName());

    if (_player->GetLootGuid() != packet.lootGuid)
    {
        _player->SendLootError(packet.lootGuid, LOOT_ERROR_DIDNT_KILL);
        return;
    }

    Loot *pLoot = nullptr;

    if (packet.lootGuid.IsCreature())
    {
        Creature* creature = GetPlayer()->GetMap()->GetCreature(packet.lootGuid);
        if (!creature)
        {
            _player->SendLootError(packet.lootGuid, LOOT_ERROR_DIDNT_KILL);
            return;
        }

        if (!_player->IsAtGroupRewardDistance(creature))
        {
            _player->SendLootError(packet.lootGuid, LOOT_ERROR_TOO_FAR);
            return;
        }

        pLoot = &creature->loot;
    }
    else if (packet.lootGuid.IsGameObject())
    {
        GameObject* go = GetPlayer()->GetMap()->GetGameObject(packet.lootGuid);
        if (!go)
        {
            _player->SendLootError(packet.lootGuid, LOOT_ERROR_DIDNT_KILL);
            return;
        }

        if (!_player->IsAtGroupRewardDistance(go))
        {
            _player->SendLootError(packet.lootGuid, LOOT_ERROR_TOO_FAR);
            return;
        }

        pLoot = &go->loot;
    }
    else
    {
        _player->SendLootError(packet.lootGuid, LOOT_ERROR_DIDNT_KILL);
        return;
    }

    if (packet.slotId >= pLoot->items.size())
    {
        _player->SendLootRelease(packet.lootGuid);
        _player->SendEquipError(EQUIP_ERR_ITEM_NOT_FOUND, nullptr, nullptr);
        sLog.Player(this, LOG_BASIC, LOG_LVL_BASIC,
            "AutoLootItem: Player %s might be using a hack! (slot %d, size %lu)",
            GetPlayer()->GetName(), packet.slotId, (unsigned long)pLoot->items.size());
        return;
    }

    if (!pLoot->IsAllowedLooter(packet.playerGuid, false))
    {
        _player->SendLootError(packet.lootGuid, LOOT_ERROR_MASTER_OTHER);
        return;
    }

    LootItem& item = pLoot->items[packet.slotId];

    ItemPosCountVec dest;
    InventoryResult msg = target->CanStoreNewItem(NULL_BAG, NULL_SLOT, dest, item.itemid, item.count);
    if (msg != EQUIP_ERR_OK)
    {
        target->SendEquipError(msg, nullptr, nullptr, item.itemid);

        // send duplicate of error massage to master looter
        if (msg == EQUIP_ERR_BAG_FULL || msg == EQUIP_ERR_INVENTORY_FULL)
            _player->SendLootError(packet.lootGuid, LOOT_ERROR_MASTER_INV_FULL);
        else if (msg == EQUIP_ERR_CANT_CARRY_MORE_OF_THIS)
            _player->SendLootError(packet.lootGuid, LOOT_ERROR_MASTER_UNIQUE_ITEM);
        else
            _player->SendLootError(packet.lootGuid, LOOT_ERROR_MASTER_OTHER);
        return;
    }

    // now move item from loot to target inventory
    if (Item* newitem = target->StoreNewItem(dest, item.itemid, true, item.randomPropertyId))
    {
        sLog.Player(this, LOG_LOOTS, LOG_LVL_BASIC,
            "Master loot %s gives %ux%u to %s [loot from %s]",
            _player->GetShortDescription().c_str(), item.count, item.itemid,
            target->GetShortDescription().c_str(), packet.lootGuid.GetString().c_str());
        target->SendNewItem(newitem, uint32(item.count), false, false, true);
        target->OnReceivedItem(newitem);
    }

    // mark as looted
    item.count = 0;
    item.is_looted = true;

    pLoot->NotifyItemRemoved(packet.slotId);
    --pLoot->unlootedCount;
}

WorldSession::SendMailResult.body:
void WorldSession::SendMailResult(uint32 mailId, MailResponseType mailAction, MailResponseResult mailError, uint32 equipError, uint32 item_guid, uint32 item_count)
{
    WorldPacket data(SMSG_SEND_MAIL_RESULT, (4 + 4 + 4 + (mailError == MAIL_ERR_EQUIP_ERROR ? 4 : (mailAction == MAIL_ITEM_TAKEN ? 4 + 4 : 0))));
    data << (uint32)mailId;
    data << (uint32)mailAction;
    data << (uint32)mailError;
    if (mailError == MAIL_ERR_EQUIP_ERROR)
        data << (uint32)equipError;
    else if (mailAction == MAIL_ITEM_TAKEN)
    {
        data << (uint32)item_guid;                         // item guid low?
        data << (uint32)item_count;                        // item count?
    }
    SendPacket(&data);
}

WorldSession::SendNewMail.body:
void WorldSession::SendNewMail()
{
    // deliver undelivered mail
    WorldPacket data(SMSG_RECEIVED_MAIL, 4);
    data << (uint32)0;
    SendPacket(&data);
}

WorldSession::CheckMailBox.body:
bool WorldSession::CheckMailBox(ObjectGuid guid)
{
    if (!GetPlayer()->GetGameObjectIfCanInteractWith(guid, GAMEOBJECT_TYPE_MAILBOX))
    {
        sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "Mailbox %s not found or you can't interact with it.", guid.GetString().c_str());
        return false;
    }

    return true;
}

WorldSession::HandleSendMail.body:
void WorldSession::HandleSendMail(WorldPackets::Mail::SendMail const& packet)
{
    if (!CheckMailBox(packet.mailboxGuid))
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    if (HasTrialRestrictions())
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_DISABLED_FOR_TRIAL_ACC);
        return;
    }

    std::unique_ptr<WorldSession::AsyncMailSendRequest> req = std::make_unique<WorldSession::AsyncMailSendRequest>();
    req->accountId = GetAccountId();
    req->senderGuid = GetMasterPlayer()->GetObjectGuid();

    req->receiverName = packet.receiverName;
    req->subject = packet.subject;
    req->body = packet.body;
    req->itemGuid = packet.itemGuid;
    req->money = packet.money;
    req->COD = packet.COD;

    // packet read complete, now do check
    if (req->subject.size() > 64)
        return;

    if (req->body.size() > 500)
        return;

    // client interface limit
    if (req->COD > 100000000)
    {
        ProcessAnticheatAction("PassiveAnticheat", "Attempt to send more than 10000g COD mail", CHEAT_ACTION_LOG | CHEAT_ACTION_REPORT_GMS);
        return;
    }

    if (req->COD && sWorld.getConfig(CONFIG_UINT32_COD_FORCE_TAG_MAX_LEVEL) &&
        sWorld.getConfig(CONFIG_UINT32_COD_FORCE_TAG_MAX_LEVEL) > GetAccountMaxLevel())
        req->subject = "(COD) " + req->subject;

    // Do not allow GMs to send money / items
    if (!sWorld.getConfig(CONFIG_BOOL_GM_ALLOW_TRADES) && GetSecurity() > SEC_PLAYER)
    {
        if (!req->itemGuid.IsEmpty() || req->money)
            return;
    }

    if (req->receiverName.empty())
        return;

    MasterPlayer* pl = GetMasterPlayer();

    if (normalizePlayerName(req->receiverName))
        req->receiver = sObjectMgr.GetPlayerGuidByName(req->receiverName);

    if (!req->receiver)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_DETAIL, "%s is sending mail to %s (GUID: nonexistent!) with subject %s and body %s includes %u items, %u copper and %u COD copper",
                   pl->GetGuidStr().c_str(), req->receiverName.c_str(), req->subject.c_str(), req->body.c_str(), req->itemGuid ? 1 : 0, req->money, req->COD);
        SendMailResult(0, MAIL_SEND, MAIL_ERR_RECIPIENT_NOT_FOUND);
        return;
    }

    sLog.Out(LOG_BASIC, LOG_LVL_DETAIL, "%s is sending mail to %s with subject %s and body %s includes %u items, %u copper and %u COD copper",
               pl->GetGuidStr().c_str(), req->receiverName.c_str(), req->subject.c_str(), req->body.c_str(), req->itemGuid ? 1 : 0, req->money, req->COD);

    if (pl->GetObjectGuid() == req->receiver)
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_CANNOT_SEND_TO_SELF);
        return;
    }

    req->receiverPtr = sObjectMgr.GetPlayer(req->receiver);

    // release ownership now cause we need to pass it to the query callback
    HandleSendMailRequest(req.release());
}

WorldSession::HandleSendMailRequest.body:
void WorldSession::HandleSendMailRequest(AsyncMailSendRequest* req)
{
    if (req->receiverPtr)
    {
        // check trial account restrictions for online receiver
        if (GetSecurity() <= SEC_PLAYER && req->receiverPtr->GetSession()->HasTrialRestrictions())
        {
            SendMailResult(0, MAIL_SEND, MAIL_ERR_DISABLED_FOR_TRIAL_ACC);
            delete req;
            return;
        }

        MasterPlayer* receiverMasterPlayer = req->receiverPtr->GetSession()->GetMasterPlayer();
        ASSERT(receiverMasterPlayer);
        req->rcTeam = receiverMasterPlayer->GetTeam();
        req->mailsCount = receiverMasterPlayer->GetMailSize();
        req->Callback(nullptr);
    }
    else
    {
        req->rcTeam = sObjectMgr.GetPlayerTeamByGUID(req->receiver);
        // Unsafe query: can modify items, accesses online players ...
        CharacterDatabase.AsyncPQueryUnsafe(req, &WorldSession::AsyncMailSendRequest::Callback, "SELECT COUNT(*) FROM `mail` WHERE `receiver_guid` = '%u'", req->receiver.GetCounter());
    }
}

WorldSession::HandleSendMailCallback.body:
void WorldSession::HandleSendMailCallback(WorldSession::AsyncMailSendRequest* req)
{
    MasterPlayer* pl = GetMasterPlayer();
    Player* loadedPlayer = GetPlayer();
    ASSERT(pl);

    uint32 reqmoney = req->money + 30;

    // Check for overflow
    if (reqmoney < req->money)
    {
        ProcessAnticheatAction("MailCheck", "Attempt to send free mails with money overflow", CHEAT_ACTION_LOG);
        SendMailResult(0, MAIL_SEND, MAIL_ERR_NOT_ENOUGH_MONEY);
        return;
    }
    if (reqmoney && (!loadedPlayer || loadedPlayer->GetMoney() < reqmoney))
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_NOT_ENOUGH_MONEY);
        return;
    }

    // do not allow to have more than 100 mails in mailbox.. mails count is in opcode uint8!!! - so max can be 255..
    if (req->mailsCount > 100)
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_RECIPIENT_CAP_REACHED);
        return;
    }

    // check the receiver's Faction...
    if (!sWorld.getConfig(CONFIG_BOOL_ALLOW_TWO_SIDE_INTERACTION_MAIL) && pl->GetTeam() != req->rcTeam && GetSecurity() == SEC_PLAYER)
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_NOT_YOUR_TEAM);
        return;
    }

    // A normal client can't open mail- and trade-window at the same time. Prevent spoofing packets.
    if (loadedPlayer->m_trade)
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    uint32 receiverAccount = sObjectMgr.GetPlayerAccountIdByGUID(req->receiver);

    Item* item = nullptr;

    if (req->itemGuid)
    {
        item = loadedPlayer->GetItemByGuid(req->itemGuid);

        // prevent sending bag with items (cheat: can be placed in bag after adding equipped empty bag to mail)
        if (!item || !item->IsInWorld())
        {
            SendMailResult(0, MAIL_SEND, MAIL_ERR_INTERNAL_ERROR);
            return;
        }

        // prevent sending item from bank slot
        if (_player->IsBankPos(item->GetPos()))
        {
            SendMailResult(0, MAIL_SEND, MAIL_ERR_INTERNAL_ERROR);
            return;
        }

        if (!item->CanBeTraded())
        {
            SendMailResult(0, MAIL_SEND, MAIL_ERR_INTERNAL_ERROR);
            return;
        }

        if ((item->GetProto()->Flags & ITEM_FLAG_CONJURED) || item->GetUInt32Value(ITEM_FIELD_DURATION))
        {
            SendMailResult(0, MAIL_SEND, MAIL_ERR_INTERNAL_ERROR);
            return;
        }
    }

    // check trial account restrictions for offline receiver
    if (!req->receiverPtr && GetSecurity() <= SEC_PLAYER && sAccountMgr.HasTrialRestrictions(receiverAccount))
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_DISABLED_FOR_TRIAL_ACC);
        return;
    }

    // Antispam checks
    if (loadedPlayer->GetLevel() < sWorld.getConfig(CONFIG_UINT32_MAILSPAM_LEVEL) &&
        req->money < sWorld.getConfig(CONFIG_UINT32_MAILSPAM_MONEY) &&
        (sWorld.getConfig(CONFIG_BOOL_MAILSPAM_ITEM) && !req->itemGuid))
    {
        SendMailResult(0, MAIL_SEND, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    AccountPersistentData& data = sAccountMgr.GetAccountPersistentData(GetAccountId());
    if (!data.CanMail(receiverAccount))
    {
        std::stringstream details;
        std::string from = ChatHandler(this).playerLink(GetMasterPlayer()->GetName());
        std::string to = ChatHandler(this).playerLink(req->receiverName);
        details << from << " -> " << to << "\n";
        details << req->subject << "\n";
        details << req->body << "\n";
        if (req->COD)
            details << "COD: " << req->COD << " coppers\n";
        uint32 logId = sWorld.InsertLog(details.str(), SEC_GAMEMASTER);

        std::stringstream oss;
        oss << "Mail limit reached (\"" << req->body.substr(0, 30) << "...\") [log #" << logId << "]";
        ProcessAnticheatAction("ChatSpam", oss.str().c_str(), CHEAT_ACTION_LOG | CHEAT_ACTION_REPORT_GMS);
        SendMailResult(0, MAIL_SEND, MAIL_OK);
        return;
    }
    data.JustMailed(receiverAccount);

    SendMailResult(0, MAIL_SEND, MAIL_OK);

    loadedPlayer->ModifyMoney(-int32(reqmoney));

    MailDraft draft(req->subject, req->body);

    if (!req->COD && (req->money || item))
    {
        PlayerTransactionData data;
        data.type = "Mail";
        data.parts[0].lowGuid = pl->GetGUIDLow();
        if (item)
        {
            data.parts[0].itemsEntries[0] = item->GetEntry();
            data.parts[0].itemsCount[0] = item->GetCount();
            data.parts[0].itemsGuid[0] = item->GetGUIDLow();
        }
        data.parts[0].money = req->money;
        data.parts[1].lowGuid = req->receiver.GetCounter();
        sWorld.LogTransaction(data);
    }

    if (req->itemGuid || req->money > 0)
    {
        if (item)
        {
            if (GetSecurity() > SEC_PLAYER && sWorld.getConfig(CONFIG_BOOL_GM_LOG_TRADE))
            {
                sLog.Player(GetAccountId(), LOG_GM, LOG_LVL_BASIC,
                    "GM %s (Account: %u) mail item: %s (Entry: %u Count: %u) to player: %s (Account: %u)",
                    GetPlayerName(), GetAccountId(), item->GetProto()->Name1, item->GetEntry(), item->GetCount(),
                    req->receiver.GetString().c_str(), receiverAccount);
            }

            loadedPlayer->MoveItemFromInventory(item->GetBagSlot(), item->GetSlot(), true);
            CharacterDatabase.BeginTransaction(loadedPlayer->GetGUIDLow());
            item->DeleteFromInventoryDB();                  // deletes item from character's inventory
            item->SaveToDB();                               // recursive and not have transaction guard into self, item not in inventory and can be save standalone
            // owner in data will set at mail receive and item extracting
            CharacterDatabase.PExecute("UPDATE `item_instance` SET `owner_guid` = '%u' WHERE `guid`='%u'", req->receiver.GetCounter(), item->GetGUIDLow());
            CharacterDatabase.CommitTransaction();

            draft.AddItem(item);
        }

        if (req->money > 0 &&  GetSecurity() > SEC_PLAYER && sWorld.getConfig(CONFIG_BOOL_GM_LOG_TRADE))
        {
            sLog.Player(GetAccountId(), LOG_GM, LOG_LVL_BASIC,
                "GM %s (Account: %u) mail money: %u to player: %s (Account: %u)",
                GetPlayerName(), GetAccountId(), req->money, req->receiver.GetString().c_str(), receiverAccount);
        }
    }

    // default delay for mails is one hour in WoW Classic https://eu.battle.net/support/de/article/98485
    // mails which only contain a text message will arrive instantly
    uint32 deliver_delay = (!req->itemGuid && req->money == 0) ? 0 : sWorld.getConfig(CONFIG_UINT32_MAIL_DELIVERY_DELAY);

    if (!item && req->COD)
    {
        req->COD = 0;
        ProcessAnticheatAction("MailCheck", "Attempt to send COD mail without any item", CHEAT_ACTION_LOG);
    }
    // will delete item or place to receiver mail list
    draft
    .SetMoney(req->money)
    .SetCOD(req->COD)
    .SendMailTo(MailReceiver(req->receiverPtr, req->receiver), loadedPlayer, req->body.empty() ? MAIL_CHECK_MASK_COPIED : MAIL_CHECK_MASK_HAS_BODY, deliver_delay);

    CharacterDatabase.BeginTransaction(loadedPlayer->GetGUIDLow());
    loadedPlayer->SaveInventoryAndGoldToDB();
    CharacterDatabase.CommitTransaction();
}

WorldSession::HandleMailMarkAsRead.body:
void WorldSession::HandleMailMarkAsRead(WorldPackets::Mail::MailMarkAsRead const& packet)
{
    if (!CheckMailBox(packet.mailboxGuid))
        return;

    MasterPlayer* pl = GetMasterPlayer();
    ASSERT(pl);

    if (Mail *m = pl->GetMail(packet.mailId))
    {
        if (m->state == MAIL_STATE_DELETED)
        {
            ProcessAnticheatAction("MailCheck", "Attempt to mark deleted mail as read", CHEAT_ACTION_LOG);
            return;
        }
        pl->DecreaseUnreadMailsCount();
        m->checked = m->checked | MAIL_CHECK_MASK_READ;
        pl->MarkMailsUpdated();
        m->state = MAIL_STATE_CHANGED;

        time_t time_now = time(nullptr);
        if ((m->expire_time - time_now) > (3 * DAY))
            m->expire_time = time_now + (3 * DAY);
    }
}

WorldSession::HandleMailDelete.body:
void WorldSession::HandleMailDelete(WorldPackets::Mail::MailDelete const& packet)
{
    if (!CheckMailBox(packet.mailboxGuid))
        return;

    MasterPlayer* pl = GetMasterPlayer();
    ASSERT(pl);
    pl->MarkMailsUpdated();

    if (Mail *m = pl->GetMail(packet.mailId))
    {
        // delete shouldn't show up for COD mails
        if (m->COD)
        {
            SendMailResult(packet.mailId, MAIL_DELETED, MAIL_ERR_INTERNAL_ERROR);
            return;
        }

        m->state = MAIL_STATE_DELETED;
    }
    SendMailResult(packet.mailId, MAIL_DELETED, MAIL_OK);
}

WorldSession::HandleMailReturnToSender.body:
void WorldSession::HandleMailReturnToSender(WorldPackets::Mail::MailReturnToSender const& packet)
{
    if (!CheckMailBox(packet.mailboxGuid))
        return;

    MasterPlayer* pl = GetMasterPlayer();
    ASSERT(pl);
    Mail *m = pl->GetMail(packet.mailId);
    if (!m || m->state == MAIL_STATE_DELETED || m->deliver_time > time(nullptr))
    {
        SendMailResult(packet.mailId, MAIL_RETURNED_TO_SENDER, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    // we can return mail now
    // so firstly delete the old one
    CharacterDatabase.BeginTransaction(pl->GetGUIDLow());
    CharacterDatabase.PExecute("DELETE FROM `mail` WHERE `id` = '%u'", packet.mailId);
    // needed?
    CharacterDatabase.PExecute("DELETE FROM `mail_items` WHERE `mail_id` = '%u'", packet.mailId);
    CharacterDatabase.CommitTransaction();
    pl->RemoveMail(packet.mailId);

    // send back only to existing players and simple drop for other cases
    if (m->messageType == MAIL_NORMAL && m->sender)
    {
        MailDraft draft;
        if (m->mailTemplateId)
            draft.SetMailTemplate(m->mailTemplateId, false); // items already included
        else
            draft.SetSubjectAndBodyId(m->subject, m->itemTextId);

        if (m->HasItems())
        {
            for (const auto& itr2 : m->items)
            {
                if (Item *item = pl->GetMItem(itr2.itemGuid))
                    draft.AddItem(item);

                pl->RemoveMItem(itr2.itemGuid);
            }
        }

        draft.SetMoney(m->money).SendReturnToSender(GetAccountId(), m->receiverGuid, ObjectGuid(HIGHGUID_PLAYER, m->sender));
    }

    delete m; // we can deallocate old mail
    SendMailResult(packet.mailId, MAIL_RETURNED_TO_SENDER, MAIL_OK);
}

WorldSession::HandleMailTakeItem.body:
void WorldSession::HandleMailTakeItem(WorldPackets::Mail::MailTakeItem const& packet)
{
    if (!CheckMailBox(packet.mailboxGuid))
        return;

    MasterPlayer* pl = GetMasterPlayer();
    Player* loadedPlayer = GetPlayer();
    ASSERT(pl);

    Mail* m = pl->GetMail(packet.mailId);
    if (!m || m->state == MAIL_STATE_DELETED || m->deliver_time > time(nullptr))
    {
        SendMailResult(packet.mailId, MAIL_ITEM_TAKEN, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    // Prevent spoofed packet accessing mail that doesn't actually have items
    if (!m->HasItems() || m->items.empty())
    {
        SendMailResult(packet.mailId, MAIL_ITEM_TAKEN, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    // prevent cheating with skip client money check
    if (loadedPlayer->GetMoney() < m->COD)
    {
        SendMailResult(packet.mailId, MAIL_ITEM_TAKEN, MAIL_ERR_NOT_ENOUGH_MONEY);
        return;
    }

    // Do not allow GMs to send COD
    if (!sWorld.getConfig(CONFIG_BOOL_GM_ALLOW_TRADES) && GetSecurity() > SEC_PLAYER && m->COD)
    {
        SendMailResult(packet.mailId, MAIL_ITEM_TAKEN, MAIL_ERR_NOT_ENOUGH_MONEY);
        return;
    }

    uint32 itemId = m->items[0].itemId;
    uint32 itemGuid = m->items[0].itemGuid;

    Item *it = pl->GetMItem(itemGuid);

    ItemPosCountVec dest;
    uint8 msg = _player->CanStoreItem(NULL_BAG, NULL_SLOT, dest, it, false);
    if (msg == EQUIP_ERR_OK)
    {
        m->RemoveItem(itemGuid);
        m->removedItems.push_back(itemGuid);

        if (m->COD > 0)                                     // if there is COD, take COD money from player and send them to sender by mail
        {
            ObjectGuid sender_guid = ObjectGuid(HIGHGUID_PLAYER, m->sender);
            Player* sender = sObjectMgr.GetPlayer(sender_guid);

            // Transaction log
            PlayerTransactionData data;
            data.type = "MailCOD";
            data.parts[0].lowGuid = sender_guid.GetCounter();
            if (it)
            {
                data.parts[0].itemsEntries[0] = it->GetEntry();
                data.parts[0].itemsCount[0] = it->GetCount();
                data.parts[0].itemsGuid[0] = it->GetGUIDLow();
            }
            data.parts[1].lowGuid = _player->GetGUIDLow();
            data.parts[1].money = m->COD;
            sWorld.LogTransaction(data);

            uint32 sender_accId = 0;

            if (GetSecurity() > SEC_PLAYER && sWorld.getConfig(CONFIG_BOOL_GM_LOG_TRADE))
            {
                std::string sender_name;
                if (sender)
                {
                    sender_accId = sender->GetSession()->GetAccountId();
                    sender_name = sender->GetName();
                }
                else
                {
                    // can be calculated early
                    sender_accId = sObjectMgr.GetPlayerAccountIdByGUID(sender_guid);

                    if (!sObjectMgr.GetPlayerNameByGUID(sender_guid, sender_name))
                        sender_name = sObjectMgr.GetMangosStringForDBCLocale(LANG_UNKNOWN);
                }
                sLog.Player(GetAccountId(), LOG_GM, LOG_LVL_BASIC,
                    "GM %s (Account: %u) receive mail item: %s (Entry: %u Count: %u) and send COD money: %u to player: %s (Account: %u)",
                    GetPlayerName(), GetAccountId(), it->GetProto()->Name1, it->GetEntry(), it->GetCount(), m->COD, sender_name.c_str(), sender_accId);
            }
            else if (!sender)
                sender_accId = sObjectMgr.GetPlayerAccountIdByGUID(sender_guid);

            // check player existence
            if (sender || sender_accId)
            {
                MailDraft(m->subject)
                .SetMoney(m->COD)
                .SendMailTo(MailReceiver(sender, sender_guid), _player, MAIL_CHECK_MASK_COD_PAYMENT);
            }

            loadedPlayer->ModifyMoney(-int32(m->COD));
        }
        m->COD = 0;
        m->state = MAIL_STATE_CHANGED;
        pl->MarkMailsUpdated();
        pl->RemoveMItem(it->GetGUIDLow());

        uint32 count = it->GetCount();                      // save counts before store and possible merge with deleting
        it->SetState(ITEM_UNCHANGED);                       // need to set this state, otherwise item cannot be removed later, if necessary
        loadedPlayer->MoveItemToInventory(dest, it, true);

        CharacterDatabase.BeginTransaction(loadedPlayer->GetGUIDLow());
        loadedPlayer->SaveInventoryAndGoldToDB();
        pl->SaveMails();
        CharacterDatabase.CommitTransaction();

        SendMailResult(packet.mailId, MAIL_ITEM_TAKEN, MAIL_OK, 0, itemId, count);
    }
    else
        SendMailResult(packet.mailId, MAIL_ITEM_TAKEN, MAIL_ERR_EQUIP_ERROR, msg);
}

WorldSession::HandleMailTakeMoney.body:
void WorldSession::HandleMailTakeMoney(WorldPackets::Mail::MailTakeMoney const& packet)
{
    if (!CheckMailBox(packet.mailboxGuid))
        return;

    MasterPlayer* pl = GetMasterPlayer();
    Player* loadedPlayer = GetPlayer();
    ASSERT(pl);

    Mail* m = pl->GetMail(packet.mailId);
    if (!m || m->state == MAIL_STATE_DELETED || m->deliver_time > time(nullptr))
    {
        SendMailResult(packet.mailId, MAIL_MONEY_TAKEN, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    // prevent losing money due to reaching gold cap
    if (int64(loadedPlayer->GetMoney()) + int64(m->money) > int64(loadedPlayer->GetMaxMoney()))
    {
        SendMailResult(packet.mailId, MAIL_MONEY_TAKEN, MAIL_ERR_INTERNAL_ERROR);
        return;
    }

    SendMailResult(packet.mailId, MAIL_MONEY_TAKEN, MAIL_OK);

    loadedPlayer->LogModifyMoney(m->money, "Mail", ObjectGuid(HIGHGUID_PLAYER, m->sender));
    m->money = 0;
    m->state = MAIL_STATE_CHANGED;
    pl->MarkMailsUpdated();

    // save money and mail to prevent cheating
    CharacterDatabase.BeginTransaction(loadedPlayer->GetGUIDLow());
    loadedPlayer->SaveGoldToDB();
    pl->SaveMails();
    CharacterDatabase.CommitTransaction();
}

WorldSession::HandleGetMailList.body:
void WorldSession::HandleGetMailList(WorldPackets::Mail::GetMailList const& packet)
{
    if (!CheckMailBox(packet.mailboxGuid))
        return;

    MasterPlayer* pl = GetMasterPlayer();
    ASSERT(pl);

    constexpr uint32 averageSizePerMail =
        sizeof(uint32) /*Message Id*/ +
        sizeof(uint8) /*Message Type*/ +
        sizeof(uint64) /*Sender Guid*/ +
        32 /*Subject (max 64)*/ +
        sizeof(uint32) /*Item Text Id*/ +
        sizeof(uint32) /*Unknown*/ +
        sizeof(uint32) /*Stationery*/ +
        sizeof(uint32) /*Item Entry*/ +
        sizeof(uint32) /*Item Enchantment Id*/ +
        sizeof(uint32) /*Item Random Property Id*/ +
        sizeof(uint32) /*Item Suffix Factor*/ +
        sizeof(uint8) /*Item Count*/ +
        sizeof(uint32) /*Item Spell Charges*/ +
        sizeof(uint32) /*Item Max Durability*/ +
        sizeof(uint32) /*Item Durability*/ +
        sizeof(uint32) /*Money*/ +
        sizeof(uint32) /*Cod*/ +
        sizeof(uint32) /*Checked*/ +
        sizeof(float) /*Expire Time*/
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_9_4
        + sizeof(uint32) /*Mail Template Id*/
#endif
        ;

    WorldPacket data(SMSG_MAIL_LIST_RESULT, 1 + std::min(pl->GetMailSize(), 253u) * averageSizePerMail);
    data << uint8(0);                                       // mail's count
    time_t cur_time = time(nullptr);

    uint32 mailsCount = 0;                                  // real send to client mails amount
    for (PlayerMails::iterator itr = pl->GetMailBegin(); itr != pl->GetMailEnd(); ++itr)
    {
        // packet send mail count as uint8, prevent overflow
        if (mailsCount >= 254)
            break;

        // skip deleted or not delivered (deliver delay not expired) mails
        if ((*itr)->state == MAIL_STATE_DELETED || cur_time < (*itr)->deliver_time || cur_time > (*itr)->expire_time)
            continue;

        data << uint32((*itr)->messageID);                  // Message ID
        data << uint8((*itr)->messageType);                 // Message Type

        switch ((*itr)->messageType)
        {
            case MAIL_NORMAL:                               // sender guid
                data << ObjectGuid(HIGHGUID_PLAYER, (*itr)->sender);
                break;
            case MAIL_CREATURE:
            case MAIL_GAMEOBJECT:
            case MAIL_AUCTION:
                data << (uint32)(*itr)->sender;             // creature/gameobject entry, auction id
                break;
            case MAIL_ITEM:                                 // item entry (?) sender = "Unknown", NYI
                break;
        }

        data << (*itr)->subject;                            // Subject string - once 00, when mail type = 3
        data << uint32((*itr)->itemTextId);                 // sure about this
        data << uint32(0);                                  // package (Package.dbc)
        data << uint32((*itr)->stationery);                 // stationery (Stationery.dbc)

        // 1.12.1 can have only single item
        Item *item = !(*itr)->items.empty() ? pl->GetMItem((*itr)->items[0].itemGuid) : nullptr;

        if (item)
        {
            data << uint32(item->GetEntry());
            data << uint32(item->GetEnchantmentId((EnchantmentSlot)PERM_ENCHANTMENT_SLOT)); // permanent enchantment
            data << uint32(item->GetItemRandomPropertyId());                                // can be negative
            data << uint32(item->GetItemSuffixFactor());                                    // unk
            data << uint8(item->GetCount());                                                // stack count
            data << uint32(item->GetSpellCharges());                                        // charges
            data << uint32(item->GetUInt32Value(ITEM_FIELD_MAXDURABILITY));                 // durability max
            data << uint32(item->GetUInt32Value(ITEM_FIELD_DURABILITY));                    // durability current
        }
        else
        {
            data << uint32(0) << uint32(0) << uint32(0) << uint32(0) << uint8(0) << uint32(0) << uint32(0) << uint32(0);
        }

        data << uint32((*itr)->money);                      // copper
        data << uint32((*itr)->COD);                        // Cash on delivery
        data << uint32((*itr)->checked);                    // flags
        data << float(float((*itr)->expire_time - time(nullptr)) / float(DAY));// Time

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_9_4
        data << uint32((*itr)->mailTemplateId);             // mail template (MailTemplate.dbc)
#endif

        mailsCount += 1;
    }

    data.put<uint8>(0, mailsCount);                         // set real send mails to client
    SendPacket(&data);

    // recalculate m_nextMailDelivereTime and unReadMails
    pl->UpdateNextMailTimeAndUnreads();
}

WorldSession::HandleItemTextQuery.body:
void WorldSession::HandleItemTextQuery(WorldPackets::Misc::ItemTextQuery const& packet)
