HonorMgr::Load.body:
void HonorMgr::Load(std::unique_ptr<QueryResult> result)
{
    if (result)
    {
        m_honorCP.clear();

        do
        {
            Field* fields = result->Fetch();

            HonorCP honorCP;
            honorCP.victimType = fields[0].GetUInt8();
            honorCP.victimId   = fields[1].GetUInt32();
            honorCP.cp         = fields[2].GetFloat();
            honorCP.date       = fields[3].GetUInt32();
            honorCP.type       = fields[4].GetUInt8();
            honorCP.state      = STATE_UNCHANGED;

            m_honorCP.push_back(honorCP);
        }
        while (result->NextRow());

        // result will be delete in character query holder later
    }
}

HonorMgr::Add.body:
bool HonorMgr::Add(float cp, uint8 type, Unit const* source)
{
    // Prevent give fake records to db with 0 honor
    if (!cp || !m_owner)
        return false;

    // If not source, then give yourself
    Unit const* realSource = source;
    if (!source)
        source = m_owner;

    HonorCP honorCP;
    honorCP.date = sWorld.GetGameDay();
    honorCP.cp = cp;
    honorCP.victimId = (source->GetTypeId() == TYPEID_PLAYER ? source->GetGUIDLow() : source->GetEntry());
    honorCP.victimType = (source == m_owner ? 0 : source->GetTypeId());
    honorCP.type = type;
    honorCP.state = STATE_NEW;

    float honor = (type == DISHONORABLE) ? -cp : cp;

    // get IP if source is player
    std::string ip;
    if (Player const* victim = source->ToPlayer())
        ip = victim->GetSession()->GetRemoteAddress();

    bool plr = source->GetTypeId() == TYPEID_PLAYER;

    if (m_owner->GetMap()->IsBattleGround())
        sLog.Out(LOG_HONOR, LOG_LVL_BASIC, "[BATTLEGROUND]: Player %s (account: %u) got %f honor for type %u, source %s %s (IP: %s)",
            m_owner->GetSession()->GetPlayerName(), m_owner->GetSession()->GetAccountId(), honor, type, plr ? "player" : "unit", source->GetName(), ip.c_str());
    else
        sLog.Out(LOG_HONOR, LOG_LVL_BASIC, "[OPEN WORLD]: Player %s (account: %u) got %f honor for type %u, source %s %s (IP: %s)",
            m_owner->GetSession()->GetPlayerName(), m_owner->GetSession()->GetAccountId(), honor, type, plr ? "player" : "unit", source->GetName(), ip.c_str());

    if (type == DISHONORABLE)
    {
        // DK penalties are subtracted from your RP score immediately
        // and are not included in weekly adjustment
        // remove this check to have negative ranks
        m_rankPoints = m_rankPoints > honorCP.cp ? m_rankPoints - honorCP.cp : 0;
    }

    m_honorCP.push_back(honorCP);

    SendPVPCredit(realSource, honor);

    Update();
    return true;
}

HonorMgr::Update.body:
void HonorMgr::Update()
{
    if (!m_owner)
        return;

    uint32 todayHK = 0;
    uint32 todayDK = 0;
    uint32 yesterdayKills = 0;
    uint32 thisWeekKills = 0;
    float yesterdayCP = 0.0f;
    float thisWeekCP = 0.0f;

    uint32 today = sWorld.GetGameDay();
    uint32 yesterday = today - 1;
    uint32 thisWeekBegin = sHonorMaintenancer.GetWeekBeginDay();

    m_totalDK = m_storedDK;
    m_totalHK = m_storedHK;

    for (auto& itr : m_honorCP)
    {
        if (itr.type == HONORABLE)
        {
            if (itr.date == today)
                ++todayHK;

            if (itr.date == yesterday)
                ++yesterdayKills;

            if (itr.date >= thisWeekBegin)
            {
                ++thisWeekKills;
                ++m_totalHK;
            }
        }

        if (itr.type != DISHONORABLE)
        {
            if (itr.date == yesterday)
                yesterdayCP += itr.cp;

            if (itr.date >= thisWeekBegin)
                thisWeekCP += itr.cp;
        }

        if (itr.type == DISHONORABLE)
        {
            if (itr.date == today)
                ++todayDK;

            ++m_totalDK;
        }
    }

    m_rank = CalculateRank(m_rankPoints, m_totalHK);
    if (m_rank.visualRank > 0 && (m_rank.visualRank > m_highestRank.visualRank))
        SetHighestRank(m_rank);

    // HIGHEST RANK
    m_owner->SetByteValue(PLAYER_FIELD_BYTES, PLAYER_FIELD_BYTES_OFFSET_HIGHEST_HONOR_RANK, m_highestRank.rank);
    // RANK (Patent)
    m_owner->SetByteValue(PLAYER_BYTES_3, PLAYER_BYTES_3_OFFSET_HONOR_RANK, m_rank.rank);

// World of Warcraft Client Patch 1.6.0 (2005-07-12)
// - There is now a progress bar on the Honor tab of your character window that displays how close you are to your next rank.
#if SUPPORTED_CLIENT_BUILD >= CLIENT_BUILD_1_6_1
    uint32 honorBar = uint32(m_rankPoints >= 0.0f ? m_rankPoints : -1 * m_rankPoints);
    honorBar = uint8(((honorBar - m_rank.minRP) / (m_rank.maxRP - m_rank.minRP)) * (m_rank.positive ? 255 : -255));

    // PLAYER_FIELD_HONOR_BAR
    m_owner->SetByteValue(PLAYER_FIELD_BYTES2, PLAYER_FIELD_BYTES_2_OFFSET_HONOR_RANK_BAR, honorBar);
#endif

    // TODAY
    m_owner->SetUInt16Value(PLAYER_FIELD_SESSION_KILLS, 0, todayHK);
    m_owner->SetUInt16Value(PLAYER_FIELD_SESSION_KILLS, 1, todayDK);

    // YESTERDAY
    m_owner->SetUInt32Value(PLAYER_FIELD_YESTERDAY_KILLS, yesterdayKills);
    m_owner->SetUInt32Value(PLAYER_FIELD_YESTERDAY_CONTRIBUTION, uint32(yesterdayCP > 0.0f ? yesterdayCP : 0.0f));

// World of Warcraft Client Patch 1.6.0 (2005-07-12)
// - There is a new "This Week" section of the Honor tab, which will display PvP accomplishments of the current week.
#if SUPPORTED_CLIENT_BUILD >= CLIENT_BUILD_1_6_1
    // THIS WEEK
    m_owner->SetUInt32Value(PLAYER_FIELD_THIS_WEEK_KILLS, thisWeekKills);
    m_owner->SetUInt32Value(PLAYER_FIELD_THIS_WEEK_CONTRIBUTION, uint32(thisWeekCP > 0.0f ? thisWeekCP : 0.0f));
#endif

    // LAST WEEK
    m_owner->SetUInt32Value(PLAYER_FIELD_LAST_WEEK_KILLS, m_lastWeekHK);
    m_owner->SetUInt32Value(PLAYER_FIELD_LAST_WEEK_CONTRIBUTION, uint32(m_lastWeekCP > 0.0f ? m_lastWeekCP : 0.0f));
    m_owner->SetUInt32Value(PLAYER_FIELD_LAST_WEEK_RANK, m_standing);

    // LIFE TIME
    m_owner->SetUInt32Value(PLAYER_FIELD_LIFETIME_HONORBALE_KILLS, m_totalHK);
    m_owner->SetUInt32Value(PLAYER_FIELD_LIFETIME_DISHONORBALE_KILLS, m_totalDK);
}

HonorMgr::InitRankInfo.body:
void HonorMgr::InitRankInfo(HonorRankInfo &prk)
{
    prk.positive = true;
    prk.rank = 0;
    prk.visualRank = 0;
    prk.maxRP = 2000.00f;
    prk.minRP = 0.00f;
}

HonorMgr::CalculateTotalKills.body:
uint32 HonorMgr::CalculateTotalKills(Unit* victim) const
{
    if (!victim)
        return 0;

    uint32 totalKills = 0;
    uint32 id = 0;
    uint32 today = sWorld.GetGameDay();
    uint8 victimType = victim->GetTypeId();

    switch (victimType)
    {
        case TYPEID_PLAYER:
            id = ((Player*)victim)->GetGUIDLow();
            break;
        case TYPEID_UNIT:
            id = victim->GetEntry();
            break;
        default:
            return 0;
    }

    for (auto& honorCP : m_honorCP)
        if (honorCP.victimType == victimType && honorCP.victimId == id && honorCP.date == today)
            totalKills++;

    return totalKills;
}

HonorMgr::CalculateRankInfo.body:
void HonorMgr::CalculateRankInfo(HonorRankInfo& prk)
{
    if (prk.rank != 0)
    {
        int8 rank = prk.positive ? prk.rank - NEGATIVE_HONOR_RANK_COUNT - 1 : prk.rank - NEGATIVE_HONOR_RANK_COUNT;
        prk.maxRP = (rank) * 5000.00f;
        if (prk.maxRP < 0) // in negative rank case
            prk.maxRP *= -1;
        prk.minRP = prk.maxRP > 5000.0f ? prk.maxRP  - 5000.00f : 2000.00f;

        if (prk.rank == 5)
        {
            prk.maxRP = 2000.0f;
            prk.minRP = 0.0f;
        }
        prk.visualRank = prk.rank > NEGATIVE_HONOR_RANK_COUNT ? prk.rank - NEGATIVE_HONOR_RANK_COUNT : prk.rank * -1;
    }
    else
        InitRankInfo(prk);
}

HonorMgr::CalculateRank.body:
HonorRankInfo HonorMgr::CalculateRank(float rankPoints, uint32 totalHK)
{
    HonorRankInfo prk;
    InitRankInfo(prk);

    // rank none
    if (rankPoints == 0)
        return prk;

    prk.positive = rankPoints > 0;
    if (!prk.positive)
        rankPoints *= -1;

    uint8 rankCount = prk.positive ? POSITIVE_HONOR_RANK_COUNT - 2 : NEGATIVE_HONOR_RANK_COUNT;
    uint8 firstRank = prk.positive ? NEGATIVE_HONOR_RANK_COUNT + 1 : 1;

    if (rankPoints < 2000.00f)
        prk.rank = prk.positive ? firstRank : NEGATIVE_HONOR_RANK_COUNT;
    else
    {
        if (rankPoints > (rankCount - 1) * 5000.00f)
            prk.rank = prk.positive ? HONOR_RANK_COUNT - 1 : firstRank;
        else
        {
            prk.rank = uint32(rankPoints / 5000.00f) + firstRank;
            prk.rank = (prk.positive ? prk.rank  + 1 : NEGATIVE_HONOR_RANK_COUNT - prk.rank);
        }
    }

    CalculateRankInfo(prk);

    return prk;
}

HonorMgr::DishonorableKillPoints.body:
float HonorMgr::DishonorableKillPoints(uint8 level)
{
    float result = 10.0f;
    if (level >= 30 && level <= 35)
        result = result + 1.5f * (level - 29);
    if (level >= 36 && level <= 41)
        result = result + 9 + 2 * (level - 35);
    if (level >= 42 && level <= 50)
        result = result + 21 + 3.2f * (level - 41);
    if (level >= 51)
        result = result + 50 + 4 * (level - 50);
    if (result > 100)
        return 100.0f;
    else
        return result;
}

HonorMgr::HonorableKillPoints.body:
float HonorMgr::HonorableKillPoints(Player* killer, Player* victim, uint32 groupSize)
{
    if (!killer || !victim || !groupSize)
        return 0.0;

    uint32 totalKills = killer->GetHonorMgr().CalculateTotalKills(victim);
    uint32 victimRank = victim->GetHonorMgr().GetRank().visualRank;
    uint8 killerLevel = killer->GetLevel();
    uint8 victimLevel = victim->GetLevel();

    return MaNGOS::Honor::GetHonorGain(killerLevel, victimLevel, victimRank, totalKills, groupSize);
}

HonorMgr::SendPVPCredit.body:
void HonorMgr::SendPVPCredit(Unit const* victim, float honor)
{
    if (!m_owner)
        return;

    WorldPacket data(SMSG_PVP_CREDIT, 4 + 8 + 4);
    data << int32(honor);

    if (!victim)
    {
        data << int64(0);
        data << int32(0);
    }
    else
    {
        data << victim->GetObjectGuid();

        if (victim->IsCreature())
        {
            if (((Creature*)victim)->IsRacialLeader())
                data << int32(19);
            else
                data << int32(0);
        }
        else if (victim->IsPlayer())
        {
            // Never display just "HK:" without rank name.
            // When killing a player with no rank,
            // we need to send first rank instead.
            // https://youtu.be/hef06Cs6Q34?t=191
            // New classic client does this on its own.
            int32 rank = ((Player const*)victim)->GetHonorMgr().GetRank().rank;
            if (!rank)
                rank = (HONOR_RANK_COUNT - POSITIVE_HONOR_RANK_COUNT) + 1;
            data << uint32(rank);
        }
    }

    m_owner->SendDirectMessage(&data);
}

InstanceStatisticsMgr::LoadFromDB.body:
void InstanceStatisticsMgr::LoadFromDB()
{
    m_instanceWipes.clear();
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "> Loading table `instance_wipes`");
    uint32 count = 0;
    std::unique_ptr<QueryResult> result(LogsDatabase.Query("SELECT `mapId`, `creatureEntry`, `count` FROM `instance_wipes`"));
    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table instance_wipes is empty.");
    }
    else
    {
        BarGoLink bar(result->GetRowCount());
        do
        {
            bar.step();
            Field* fields = result->Fetch();

            uint32 mapId = fields[0].GetUInt32();
            uint32 creatureEntry = fields[1].GetUInt32();
            uint32 killCount = fields[2].GetUInt32();

            m_instanceWipes[std::make_pair(mapId, creatureEntry)] = InstanceWipes{ mapId,creatureEntry,killCount };
            ++count;
        } while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u entries from `instance_wipes`", count);
    }


    m_instanceCreatureKills.clear();
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "> Loading table `instance_creature_kills`");
    count = 0;
    result = LogsDatabase.Query("SELECT `mapId`, `creatureEntry`, `spellEntry`, `count` FROM `instance_creature_kills`");
    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table instance_creature_kills is empty.");
    }
    else
    {
        BarGoLink bar(result->GetRowCount());
        do
        {
            bar.step();
            Field* fields = result->Fetch();

            uint32 mapId = fields[0].GetUInt32();
            uint32 creatureEntry = fields[1].GetUInt32();
            uint32 spellEntry = fields[2].GetUInt32();
            uint32 killCount = fields[3].GetUInt32();
            auto it = m_instanceCreatureKills.find(std::make_pair(mapId, creatureEntry));
            if (it == m_instanceCreatureKills.end())
            {
                InstanceCreatureKlls obj;
                obj.mapId = mapId;
                obj.creatureEntry = creatureEntry;
                obj.killsBySpells[spellEntry] = killCount;
                m_instanceCreatureKills.insert(std::make_pair(std::make_pair(mapId, creatureEntry), std::move(obj)));
            }
            else
            {
                it->second.killsBySpells[spellEntry] = killCount;
            }
            ++count;
        } while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u entries from `instance_creature_kills`", count);
    }



    m_instanceCustomCounters.clear();
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "> Loading table `instance_custom_counters`");
    count = 0;
    result = LogsDatabase.Query("SELECT `index`, `count` FROM `instance_custom_counters`");
    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table `instance_custom_counters` is empty.");
    }
    else
    {
        BarGoLink bar(result->GetRowCount());
        do
        {
            bar.step();

            Field* fields = result->Fetch();

            uint32 index = fields[0].GetUInt32();
            uint32 count = fields[1].GetUInt32();
            m_instanceCustomCounters[index] = count;
            ++count;
        } while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u entries from `instance_custom_counters`", count);
    }
}

