void LoadRandomEnchantmentsTable()
{
    RandomItemEnch.clear();                                 // for reload case

    uint32 entry, ench;
    uint32 count = 0;

    std::unique_ptr<QueryResult> result = WorldDatabase.PQuery("SELECT entry, ench, chance FROM item_enchantment_template WHERE ((%u >= patch_min) && (%u <= patch_max))", sWorld.GetWowPatch(), sWorld.GetWowPatch());

    if (result)
    {
        BarGoLink bar(result->GetRowCount());

        do
        {
            Field* fields = result->Fetch();
            bar.step();

            entry = fields[0].GetUInt32();
            ench = fields[1].GetUInt32();
            float chance = fields[2].GetFloat();

            if (chance > 0.000001f && chance <= 100.0f)
            {
                RandomItemEnch[entry].emplace_back(ench, chance);
            }
            else
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "Entry %u ench %u has chance < 0.000001 or chance > 100 (%f), skipping.", entry, ench, chance);
            }

            ++count;
        }
        while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u Item Enchantment definitions", count);
    }
    else
    {
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, ">> Loaded 0 Item Enchantment definitions. DB table `item_enchantment_template` is empty.");
    }
}

GetItemEnchantMod.body:
uint32 GetItemEnchantMod(uint32 entry)
{
    if (!entry)
        return 0;

    EnchantmentStore::const_iterator tab = RandomItemEnch.find(entry);

    if (tab == RandomItemEnch.end())
    {
        sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "Item RandomProperty id #%u used in `item_template` but it doesn't have records in `item_enchantment_template` table.", entry);
        return 0;
    }

    float chance = 0;

    EnchStoreList const& enchantList = tab->second;
    for (auto const& ench_iter : enchantList)
    {
        chance += ench_iter.chance;
    }

    float const roll = rand_chance_f() * (chance / 100.f);
    chance = 0.f;

    for (auto const& ench_iter : enchantList)
    {
        chance += ench_iter.chance;

        if (chance >= roll)
            return ench_iter.ench;
    }

    return 0;
}

WorldSession::HandleMeetingStoneJoinOpco.body:
void WorldSession::HandleMeetingStoneJoinOpcode(WorldPackets::Misc::MeetingStoneJoin const& packet)
{
    // ignore for remote control state
    if (!_player->IsSelfMover())
        return;

    GameObject* obj = _player->GetGameObjectIfCanInteractWith(packet.guid);

    if (!obj)
        return;

    // Never expect this opcode for some type GO's
    if (obj->GetGoType() != GAMEOBJECT_TYPE_MEETINGSTONE)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "HandleMeetingStoneJoinOpcode: CMSG_MEETINGSTONE_JOIN for not allowed GameObject type %u (Entry %u), didn't expect this to happen.", obj->GetGoType(), obj->GetEntry());
        return;
    }

    if (Group* grp = _player->GetGroup())
    {
        if (!grp->IsLeader(_player->GetObjectGuid()))
        {
            SendMeetingstoneFailed(MEETINGSTONE_FAIL_PARTYLEADER);

            return;
        }

        if (grp->isRaidGroup())
        {
            SendMeetingstoneFailed(MEETINGSTONE_FAIL_RAID_GROUP);
            return;
        }

        if (grp->IsFull())
        {
            SendMeetingstoneFailed(MEETINGSTONE_FAIL_FULL_GROUP);
            return;
        }
    }


   GameObjectInfo const* gInfo = sObjectMgr.GetGameObjectTemplate(obj->GetEntry());

   sLFGMgr.AddToQueue(_player, gInfo->meetingstone.areaID);
}

