    std::map<Player*, uint16>::iterator it;
    for (int continent = 0; continent < LAST_CONTINENT_ID; ++continent)
    {
        for (it = m_scheduledInstanceSwitches[continent].begin(); it != m_scheduledInstanceSwitches[continent].end(); ++it)
