    }
    else
    {
        SqlStatement stmt = CharacterDatabase.CreateStatement(delSpawnTime, "DELETE FROM `creature_respawn` WHERE `guid` = ? AND `instance` = ?");
        stmt.PExecute(loguid, m_instanceid);
    }
}

