bool PathInfo::calculate(Vector3 const& start, Vector3 dest, bool forceDest, bool offsets)
{
    m_pathPoints.clear();
    m_forceDestination = forceDest;
    m_type = PATHFIND_BLANK;

    Vector3 oldDest = getEndPosition();
    setEndPosition(dest);
    setStartPosition(start);

    // A m_navMeshQuery object is not thread safe, but a same PathInfo can be shared between threads.
    // So need to get a new one.
    MMAP::MMapManager* mmap = MMAP::MMapFactory::createOrGetMMapManager();
    if (m_transport)
    {
        if (!offsets)
        {
            m_transport->CalculatePassengerOffset(dest.x, dest.y, dest.z);
            setEndPosition(dest);
        }
        m_navMeshQuery = mmap->GetModelNavMeshQuery(m_transport->GetDisplayId());
    }
    else if (!(m_navMeshQuery = mmap->GetNavMeshQuery(m_sourceUnit->GetMapId())))
    {
        BuildPathWithoutMMaps(start, dest);
        return true;
    }

    if (m_navMeshQuery)
        m_navMesh = m_navMeshQuery->getAttachedNavMesh();

    //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ PathFinder::calculate() for %u \n", m_sourceUnit->GetGUIDLow());

    // make sure navMesh works - we can run on map w/o mmap
    // check if the start and end point have a .mmtile loaded (can we pass via not loaded tile on the way?)
    if (!m_navMesh || !m_navMeshQuery || m_sourceUnit->HasUnitState(UNIT_STATE_IGNORE_PATHFINDING) ||
        !HaveTiles(start) || !HaveTiles(dest))
    {
        BuildShortcut();
        m_type = PathType(PATHFIND_NORMAL | PATHFIND_NOT_USING_PATH);
        return true;
    }

    updateFilter();

    // check if destination moved - if not we can optimize something here
    // we are following old, precalculated path?
    float dist = m_sourceUnit->GetObjectBoundingRadius();
    if (inRange(oldDest, dest, dist, dist) && m_pathPoints.size() > 2)
    {
        // our target is not moving - we just coming closer
        // we are moving on precalculated path - enjoy the ride
        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ PathFinder::calculate:: precalculated path\n");
        m_pathPoints.erase(m_pathPoints.begin());
        return false;
    }
    else
    {
        // target moved, so we need to update the poly path
        BuildPolyPath(start, dest);
        return true;
    }
}

PathInfo::FindWalkPoly.body:
dtPolyRef PathInfo::FindWalkPoly(dtNavMeshQuery const* query, float const* pointYZX, dtQueryFilter const& filter, float* closestPointYZX, float zSearchDist)
{
    ASSERT(query);

    // WARNING : Nav mesh coords are Y, Z, X (and not X, Y, Z)
    float extents[3] = {5.0f, zSearchDist, 5.0f};
    dtPolyRef polyRef;

    // Default recastnavigation method
    if (dtStatusFailed(query->findNearestPoly(pointYZX, extents, &filter, &polyRef, closestPointYZX)))
        return 0;
    // Do not select points over player pos
    if (closestPointYZX[1] > pointYZX[1] + 3.0f)
        return 0;
    return polyRef;
}

PathInfo::getPolyByLocation.body:
dtPolyRef PathInfo::getPolyByLocation(float const* point, float *distance, uint32 allowedFlags)
{
    float closestPoint[VERTEX_SIZE] = {0.0f, 0.0f, 0.0f};
    dtQueryFilter filter;
    filter.setIncludeFlags(m_filter.getIncludeFlags() | allowedFlags);
    dtPolyRef polyRef = FindWalkPoly(m_navMeshQuery, point, filter, closestPoint);
    if (polyRef != INVALID_POLYREF)
    {
        *distance = dtVdist(closestPoint, point);
        return polyRef;
    }
    return INVALID_POLYREF;
}

PathInfo::BuildPolyPath.body:
void PathInfo::BuildPolyPath(Vector3 const& startPos, Vector3 const& endPos)
{
    // *** getting start/end poly logic ***

    float distToStartPoly, distToEndPoly;
    float startPoint[VERTEX_SIZE] = {startPos.y, startPos.z, startPos.x};
    float endPoint[VERTEX_SIZE] = {endPos.y, endPos.z, endPos.x};

    bool const canSwimToDestination = m_sourceUnit->CanSwim() && (!m_sourceUnit->IsCreature() || m_sourceUnit->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_USE_SWIM_ANIMATION)) &&
                                      m_sourceUnit->CanSwimAtPosition(startPos) &&
                                      m_sourceUnit->CanSwimAtPosition(endPos);

    // First case : easy flying / swimming
    if (canSwimToDestination || m_sourceUnit->CanFly())
    {
        if (!m_sourceUnit->GetMap()->FindCollisionModel(startPos.x, startPos.y, startPos.z, endPos.x, endPos.y, endPos.z))
        {
            if (canSwimToDestination)
                BuildUnderwaterPath();
            else
            {
                BuildShortcut();
                m_type = PathType(PATHFIND_NORMAL | PATHFIND_NOT_USING_PATH | PATHFIND_FLYPATH);
            }
            return;
        }
        else if (m_sourceUnit->CanFly())
            m_forceDestination = true;
    }
    dtPolyRef startPoly = getPolyByLocation(startPoint, &distToStartPoly);
    dtPolyRef endPoly = getPolyByLocation(endPoint, &distToEndPoly, m_targetAllowedFlags);

    // we have a hole in our mesh
    // make shortcut path and mark it as NOPATH ( with flying exception )
    // its up to caller how he will use this info
    if (startPoly == INVALID_POLYREF || endPoly == INVALID_POLYREF)
    {
        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ BuildPolyPath :: (startPoly == 0 || endPoly == 0)\n");
        BuildShortcut();
        // Check for swimming or flying shortcut
        if ((startPoly == INVALID_POLYREF && m_sourceUnit->GetTerrain()->IsSwimmable(startPos.x, startPos.y, startPos.z)) ||
            (endPoly == INVALID_POLYREF && m_sourceUnit->GetTerrain()->IsSwimmable(endPos.x, endPos.y, endPos.z)))
            m_type = m_sourceUnit->CanSwim() ? PathType(PATHFIND_NORMAL | PATHFIND_NOT_USING_PATH) : PATHFIND_NOPATH;
        else
            m_type = (m_sourceUnit->GetTypeId() == TYPEID_UNIT && ((Creature*)m_sourceUnit)->CanFly())
                     ? PathType(PATHFIND_NORMAL | PATHFIND_NOT_USING_PATH | PATHFIND_FLYPATH) : PATHFIND_NOPATH;
        return;
    }

    // we may need a better number here
    bool farFromPoly = (distToStartPoly > 7.0f || distToEndPoly > 7.0f);
    if (farFromPoly)
    {
        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ BuildPolyPath :: farFromPoly distToStartPoly=%.3f distToEndPoly=%.3f\n", distToStartPoly, distToEndPoly);
        if (canSwimToDestination)
        {
            //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ BuildPolyPath :: underWater case\n");
            BuildUnderwaterPath();
            return;
        }

        if (m_sourceUnit->CanFly())
        {
            BuildShortcut();
            m_type = PathType(PATHFIND_NORMAL | PATHFIND_NOT_USING_PATH);
            return;
        }

        float closestPoint[VERTEX_SIZE];
        if (dtStatusSucceed(m_navMeshQuery->closestPointOnPolyBoundary(endPoly, endPoint, closestPoint)))
        {
            dtVcopy(endPoint, closestPoint);
            setActualEndPosition(Vector3(endPoint[2], endPoint[0], endPoint[1]));
        }

        if (!(m_sourceUnit->CanSwim() && m_sourceUnit->CanSwimAtPosition(m_actualEndPosition)))
            m_type = PATHFIND_INCOMPLETE;
    }

    // *** poly path generating logic ***

    // look for startPoly/endPoly in current path
    // TODO: we can merge it with getPathPolyByPosition() loop
    bool startPolyFound = false;
    bool endPolyFound = false;
    uint32 pathStartIndex = 0;
    uint32 pathEndIndex = 0;

    if (m_polyLength)
    {
        for (pathStartIndex = 0; pathStartIndex < m_polyLength; ++pathStartIndex)
        {
            // here to carch few bugs
            MANGOS_ASSERT(m_pathPolyRefs[pathStartIndex] != INVALID_POLYREF);

            if (m_pathPolyRefs[pathStartIndex] == startPoly)
            {
                startPolyFound = true;
                break;
            }
        }

        for (pathEndIndex = m_polyLength - 1; pathEndIndex > pathStartIndex; --pathEndIndex)
            if (m_pathPolyRefs[pathEndIndex] == endPoly)
            {
                endPolyFound = true;
                break;
            }
    }

    if (startPolyFound && endPolyFound)
    {
        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ BuildPolyPath :: (startPolyFound && endPolyFound)\n");

        // we moved along the path and the target did not move out of our old poly-path
        // our path is a simple subpath case, we have all the data we need
        // just "cut" it out

        m_polyLength = pathEndIndex - pathStartIndex + 1;
        memmove(m_pathPolyRefs, m_pathPolyRefs + pathStartIndex, m_polyLength * sizeof(dtPolyRef));
    }
    else if (startPolyFound && !endPolyFound)
    {
        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ BuildPolyPath :: (startPolyFound && !endPolyFound)\n");

        // we are moving on the old path but target moved out
        // so we have atleast part of poly-path ready

        m_polyLength -= pathStartIndex;

        // try to adjust the suffix of the path instead of recalculating entire length
        // at given interval the target cannot get too far from its last location
        // thus we have less poly to cover
        // sub-path of optimal path is optimal

        // take ~80% of the original length
        // TODO : play with the values here
        uint32 prefixPolyLength = uint32(m_polyLength * 0.8f + 0.5f);
        memmove(m_pathPolyRefs, m_pathPolyRefs + pathStartIndex, prefixPolyLength * sizeof(dtPolyRef));

        dtPolyRef suffixStartPoly = m_pathPolyRefs[prefixPolyLength - 1];

        // we need any point on our suffix start poly to generate poly-path, so we need last poly in prefix data
        float suffixEndPoint[VERTEX_SIZE];
        bool PosOverBody = false;
        if (dtStatusFailed(m_navMeshQuery->closestPointOnPoly(suffixStartPoly, endPoint, suffixEndPoint, &PosOverBody)))
        {
            // we can hit offmesh connection as last poly - closestPointOnPoly() don't like that
            // try to recover by using prev polyref
            if (prefixPolyLength > 1) // Prevent out-of-bounds access
            {
                --prefixPolyLength;
                suffixStartPoly = m_pathPolyRefs[prefixPolyLength - 1];
                if (dtStatusFailed(m_navMeshQuery->closestPointOnPoly(suffixStartPoly, endPoint, suffixEndPoint, &PosOverBody)))
                {
                    // suffixStartPoly is still invalid, error state
                    BuildShortcut();
                    m_type = PATHFIND_NOPATH;
                    return;
                }
            }
            else
            {
                BuildShortcut();
                m_type = PATHFIND_NOPATH;
                return;
            }
        }

        // generate suffix
        uint32 suffixPolyLength = 0;
        dtStatus dtResult = m_navMeshQuery->findPath(
                                suffixStartPoly,    // start polygon
                                endPoly,            // end polygon
                                suffixEndPoint,     // start position
                                endPoint,           // end position
                                &m_filter,            // polygon search filter
                                m_pathPolyRefs + prefixPolyLength - 1,    // [out] path
                                (int*)&suffixPolyLength,
                                MAX_PATH_LENGTH - prefixPolyLength); // max number of polygons in output path

        if (!suffixPolyLength || dtStatusFailed(dtResult))
        {
            // this is probably an error state, but we'll leave it
            // and hopefully recover on the next Update
            // we still need to copy our preffix
            sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "%u's Path Build failed: 0 length path r=0x%x", m_sourceUnit->GetGUIDLow(), dtResult);
        }

        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++  m_polyLength=%u prefixPolyLength=%u suffixPolyLength=%u \n",m_polyLength, prefixPolyLength, suffixPolyLength);

        // new path = prefix + suffix - overlap
        m_polyLength = prefixPolyLength + suffixPolyLength - 1;
    }
    else
    {
        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ BuildPolyPath :: (!startPolyFound && !endPolyFound)\n");

        // either we have no path at all -> first run
        // or something went really wrong -> we aren't moving along the path to the target
        // just generate new path

        // free and invalidate old path data
        clear();

        // std::thread::id const threadId = std::this_thread::get_id();

        //if (threadId != m_navMeshQuery->m_owningThread)
            //sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "CRASH: We are using a dtNavMeshQuery from thread %u which belongs to thread %u!", threadId, m_navMeshQuery->m_owningThread);

        dtStatus dtResult = m_navMeshQuery->findPath(
                                startPoly,          // start polygon
                                endPoly,            // end polygon
                                startPoint,         // start position
                                endPoint,           // end position
                                &m_filter,           // polygon search filter
                                m_pathPolyRefs,     // [out] path
                                (int*)&m_polyLength,
                                MAX_PATH_LENGTH);   // max number of polygons in output path

        if (!m_polyLength || dtStatusFailed(dtResult))
        {
            // only happens if we passed bad data to findPath(), or navmesh is messed up
            sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "%u's Path Build failed: 0 length path. Result=0x%x", m_sourceUnit->GetGUIDLow(), dtResult);
            BuildShortcut();
            m_type = PATHFIND_NOPATH;
            return;
        }
    }

    // by now we know what type of path we can get
    if (m_pathPolyRefs[m_polyLength - 1] == endPoly && !(m_type & (PATHFIND_INCOMPLETE | PATHFIND_NOPATH)))
        m_type = PATHFIND_NORMAL;
    else
        m_type = PATHFIND_INCOMPLETE;

    BuildPointPath(startPoint, endPoint, distToStartPoly, distToEndPoly);
}

PathInfo::BuildPointPath.body:
void PathInfo::BuildPointPath(float const* startPoint, float const* endPoint, float distToStartPoly, float distToEndPoly)
{
    // generate the point-path out of our up-to-date poly-path
    float pathPoints[MAX_POINT_PATH_LENGTH * VERTEX_SIZE];
    uint32 pointCount = 0;
    dtStatus dtResult = DT_FAILURE;
    if (m_useStraightPath)
    {
        dtResult = m_navMeshQuery->findStraightPath(
                       startPoint,         // start position
                       endPoint,           // end position
                       m_pathPolyRefs,     // current path
                       m_polyLength,       // lenth of current path
                       pathPoints,         // [out] path corner points
                       nullptr,            // [out] flags
                       nullptr,            // [out] shortened path
                       (int*)&pointCount,
                       m_pointPathLimit);   // maximum number of points/polygons to use
    }
    else
    {
        dtResult = findSmoothPath(
                       startPoint,         // start position
                       endPoint,           // end position
                       m_pathPolyRefs,     // current path
                       m_polyLength,       // length of current path
                       pathPoints,         // [out] path corner points
                       (int*)&pointCount,
                       m_pointPathLimit);    // maximum number of points
    }

    if (pointCount < 2 || dtStatusFailed(dtResult))
    {
        // only happens if pass bad data to findStraightPath or navmesh is broken
        // single point paths can be generated here
        // TODO : check the exact cases
        //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ PathFinder::BuildPointPath FAILED! path sized %d returned\n", pointCount);
        BuildShortcut();
        m_type = PATHFIND_NOPATH;
        return;
    }

    m_pathPoints.resize(pointCount);
    for (uint32 i = 0; i < pointCount; ++i)
    {
        Vector3 p = Vector3(pathPoints[i * VERTEX_SIZE + 2], pathPoints[i * VERTEX_SIZE], pathPoints[i * VERTEX_SIZE + 1]);
        m_sourceUnit->UpdateAllowedPositionZ(p.x, p.y, p.z);
        m_pathPoints[i] = p;
    }

    // first point is always our current location - we need the next one
    setActualEndPosition(m_pathPoints[pointCount - 1]);

    // force the given destination, if needed
    bool forceDestination = (m_forceDestination && (!(m_type & PATHFIND_NORMAL) || !inRange(getEndPosition(), getActualEndPosition(), 1.0f, 1.0f)));
    if (forceDestination)
    {
        // we may want to keep partial subpath
        if (dist3DSqr(getActualEndPosition(), getEndPosition()) <
                0.3f * dist3DSqr(getStartPosition(), getEndPosition()))
        {
            setActualEndPosition(getEndPosition());
            m_pathPoints[m_pathPoints.size() - 1] = getEndPosition();
        }
        else
        {
            setActualEndPosition(getEndPosition());
            BuildShortcut();
        }


        m_type |= PATHFIND_DEST_FORCED;
        if (m_sourceUnit->CanFly())
            m_type |= PATHFIND_FLYPATH;
    }

    //DEBUG_FILTER_LOG(LOG_FILTER_PATHFINDING, "++ PathFinder::BuildPointPath path type %d size %d poly-size %d\n", m_type, pointCount, m_polyLength);
}

PathInfo::BuildShortcut.body:
void PathInfo::BuildShortcut()
{
    clear();

    // make two point path, our curr pos is the start, and dest is the end
    m_pathPoints.resize(2);

    // set start and a default next position
    m_pathPoints[0] = getStartPosition();
    m_pathPoints[1] = getActualEndPosition();

    m_type = PATHFIND_SHORTCUT;
    if (m_sourceUnit->CanFly())
        m_type |= PATHFIND_FLYPATH | PATHFIND_NORMAL;
}

PathInfo::BuildUnderwaterPath.body:
void PathInfo::BuildUnderwaterPath()
{
    clear();

    // make two point path, our curr pos is the start, and dest is the end
    m_pathPoints.resize(2);

    // set start and a default next position
    m_pathPoints[0] = getStartPosition();
    m_pathPoints[1] = getActualEndPosition();

    GridMapLiquidData liquidData;
    uint32 liquidStatus = m_sourceUnit->GetTerrain()->getLiquidStatus(getActualEndPosition().x, getActualEndPosition().y, getActualEndPosition().z, MAP_ALL_LIQUIDS, &liquidData);
    // No water here ...
    if (liquidStatus == LIQUID_MAP_NO_WATER)
    {
        m_type = PATHFIND_SHORTCUT;
        if (m_sourceUnit->CanWalk())
        {
            // Find real height
            m_type |= PATHFIND_NORMAL;
            m_sourceUnit->UpdateGroundPositionZ(m_pathPoints[1].x, m_pathPoints[1].y, m_pathPoints[1].z);
        }
        else
        {
            m_type |= PATHFIND_INCOMPLETE;
            m_pathPoints[1] = getStartPosition();
        }
        return;
    }
    m_type = PATHFIND_BLANK;
    if (m_pathPoints[1].z > liquidData.level)
    {
        if (!m_sourceUnit->CanFly())
        {
            m_pathPoints[1].z = liquidData.level;
            if (m_pathPoints[1].z > (liquidData.level + 2))
                m_type |= PATHFIND_INCOMPLETE;
        }
    }
    if (!(m_type & PATHFIND_INCOMPLETE))
        m_type |= PATHFIND_NORMAL;
    m_type |= PATHFIND_UNDERWATER;
}

BuildPathStep.body:
bool BuildPathStep(Vector3 const& currentPos, Vector3 const& targetPos, Map const* pMap, std::vector<Vector3>& fullPath, std::vector<Vector3>& checkedPositions, uint32& stepsRemaining, float angle)
{
    float const currentDistance = Geometry::GetDistance3D(targetPos, currentPos);
    if (currentDistance < (STEP_SIZE + 1))
        return true;

    if (!stepsRemaining)
        return false;

    stepsRemaining--;

    for (int i = 0; i < 12; i++)
    {
        Vector3 newPos;
        Geometry::GetNearPoint2DAroundPosition(currentPos.x, currentPos.y, newPos.x, newPos.y, STEP_SIZE, Geometry::NormalizeOrientation(angle + ORIENTATION_OFFSETS[i]));
        newPos.z = pMap->GetHeight(newPos.x, newPos.y, currentPos.z + 0.1f, true);

        float const zdiff = newPos.z - currentPos.z;
        if (((zdiff < -0.0f) ? (-zdiff > STEP_SIZE) : (zdiff > STEP_SIZE * 0.9f)))
            continue;

        bool skip = false;
        for (auto const& checkedPos : checkedPositions)
        {
            if (Geometry::GetDistance3D(checkedPos, newPos) < STEP_SIZE * 0.5f)
            {
                skip = true;
                break;
            }
        }

        if (skip)
            continue;

        checkedPositions.push_back(newPos);
        if (BuildPathStep(newPos, targetPos, pMap, fullPath, checkedPositions, stepsRemaining, Geometry::GetAngle(targetPos, newPos)))
        {
            fullPath.push_back(newPos);
            return true;
        }
    }


    return false;
}

PathInfo::BuildPathWithoutMMaps.body:
void PathInfo::BuildPathWithoutMMaps(Vector3 const& start, Vector3 const& dest)
{
    bool const destInWater = m_sourceUnit->CanSwimAtPosition(dest);

    if (!m_sourceUnit->CanSwim() && destInWater)
    {
        BuildShortcut();
        m_type = PathType(PATHFIND_NOPATH);
        return;
    }

    if (m_sourceUnit->CanFly())
    {
        BuildShortcut();
        return;
    }

    if (!m_sourceUnit->CanWalk() && !destInWater)
    {
        BuildShortcut();
        m_type = PathType(PATHFIND_NOPATH);
        return;
    }

    float totalDistance = Geometry::GetDistance3D(start, dest);
    if (totalDistance <= STEP_SIZE ||
        (m_sourceUnit->CanSwim() && destInWater && m_sourceUnit->CanSwimAtPosition(start)))
    {
        BuildShortcut();
        m_type |= PATHFIND_NORMAL;
        return;
    }

    uint32 maxSteps = (totalDistance / STEP_SIZE) + 3;
    std::vector<Vector3> checkedPositions; // positions we've already been to
    checkedPositions.reserve(maxSteps);

    clear();
    m_pathPoints.reserve(maxSteps);
    m_pathPoints.push_back(start);

    maxSteps *= 2;

    if (BuildPathStep(dest, start, m_sourceUnit->FindMap(), m_pathPoints, checkedPositions, maxSteps, Geometry::GetAngle(start, dest)))
    {
        m_pathPoints.push_back(dest);
        m_type = PathType(PATHFIND_NORMAL);
    }
    else
    {
        BuildShortcut();
        m_type = PathType(PATHFIND_NORMAL | PATHFIND_NOT_USING_PATH);
    }
}

PathInfo::createFilter.body:
void PathInfo::createFilter()
{
    unsigned short includeFlags = 0x0;
    unsigned short excludeFlags = 0x0;

    if (m_sourceUnit->CanWalk())
        includeFlags |= NAV_GROUND;          // walk

    if (m_sourceUnit->CanSwim())
    {
        if (m_sourceUnit->GetTypeId() == TYPEID_PLAYER)
            includeFlags |= NAV_WATER;
        else // creatures don't take environmental damage
            includeFlags |= (NAV_WATER | NAV_MAGMA | NAV_SLIME);
    }

    m_filter.setIncludeFlags(includeFlags);
    m_filter.setExcludeFlags(excludeFlags);

    updateFilter();
}

PathInfo::FillTargetAllowedFlags.body:
void PathInfo::FillTargetAllowedFlags(Unit* target)
{
    m_targetAllowedFlags = 0;
    if (target->CanSwim())
        m_targetAllowedFlags |= NAV_WATER | NAV_SLIME | NAV_MAGMA;
    if (target->CanWalk())
        m_targetAllowedFlags |= NAV_GROUND;
    if (!target->IsPlayer())
        m_targetAllowedFlags |= NAV_STEEP_SLOPES;
}

PathInfo::HaveTiles.body:
bool PathInfo::HaveTiles(Vector3 const& p) const
{
    if (m_transport)
        return true;

    int tx, ty;
    float point[VERTEX_SIZE] = {p.y, p.z, p.x};

    // check if the start and end point have a .mmtile loaded
    m_navMesh->calcTileLoc(point, &tx, &ty);
    return (m_navMesh->getTileAt(tx, ty, 0) != nullptr);
}

PathInfo::fixupCorridor.body:
uint32 PathInfo::fixupCorridor(dtPolyRef* path, uint32 const npath, uint32 const maxPath,
                               dtPolyRef const* visited, uint32 const nvisited)
{
    int32 furthestPath = -1;
    int32 furthestVisited = -1;

    // Find furthest common polygon.
    for (int32 i = npath - 1; i >= 0; --i)
    {
        bool found = false;
        for (int32 j = nvisited - 1; j >= 0; --j)
        {
            if (path[i] == visited[j])
            {
                furthestPath = i;
                furthestVisited = j;
                found = true;
            }
        }
        if (found)
            break;
    }

    // If no intersection found just return current path.
    if (furthestPath == -1 || furthestVisited == -1)
        return npath;

    // Concatenate paths.

    // Adjust beginning of the buffer to include the visited.
    uint32 req = nvisited - furthestVisited;
    uint32 orig = uint32(furthestPath + 1) < npath ? furthestPath + 1 : npath;
    uint32 size = npath > orig ? npath - orig : 0;
    if (req + size > maxPath)
        size = maxPath - req;

    if (size)
        memmove(path + req, path + orig, size * sizeof(dtPolyRef));

    // Store visited
    for (uint32 i = 0; i < req; ++i)
        path[i] = visited[(nvisited - 1) - i];

    return req + size;
}

fixupShortcuts.body:
int fixupShortcuts(dtPolyRef* path, int npath, dtNavMeshQuery const* navQuery)
{
    if (npath < 3)
        return npath;

    // Get connected polygons
    static int const maxNeis = 16;
    dtPolyRef neis[maxNeis];
    int nneis = 0;

    dtMeshTile const* tile = 0;
    dtPoly const* poly = 0;
    if (dtStatusFailed(navQuery->getAttachedNavMesh()->getTileAndPolyByRef(path[0], &tile, &poly)))
        return npath;

    for (unsigned int k = poly->firstLink; k != DT_NULL_LINK; k = tile->links[k].next)
    {
        dtLink const* link = &tile->links[k];
        if (link->ref != 0)
        {
            if (nneis < maxNeis)
                neis[nneis++] = link->ref;
        }
    }

    // If any of the neighbour polygons is within the next few polygons
    // in the path, short cut to that polygon directly.
    static int const maxLookAhead = 6;
    int cut = 0;
    for (int i = dtMin(maxLookAhead, npath) - 1; i > 1 && cut == 0; i--)
    {
        for (int j = 0; j < nneis; j++)
        {
            if (path[i] == neis[j])
            {
                cut = i;
                break;
            }
        }
    }
    if (cut > 1)
    {
        int offset = cut - 1;
        npath -= offset;
        for (int i = 1; i < npath; i++)
            path[i] = path[i + offset];
    }

    return npath;
}

PathInfo::getSteerTarget.body:
bool PathInfo::getSteerTarget(float const* startPos, float const* endPos,
                              float const minTargetDist, dtPolyRef const* path, uint32 const pathSize,
                              float* steerPos, unsigned char& steerPosFlag, dtPolyRef& steerPosRef) const
{
    // Find steer target.
    static uint32 const MAX_STEER_POINTS = 3;
    float steerPath[MAX_STEER_POINTS * VERTEX_SIZE];
    unsigned char steerPathFlags[MAX_STEER_POINTS];
    dtPolyRef steerPathPolys[MAX_STEER_POINTS];
    uint32 nsteerPath = 0;
    dtStatus dtResult = m_navMeshQuery->findStraightPath(startPos, endPos, path, pathSize,
                        steerPath, steerPathFlags, steerPathPolys, (int*)&nsteerPath, MAX_STEER_POINTS);
    if (!nsteerPath || dtStatusFailed(dtResult))
        return false;

    // Find vertex far enough to steer to.
    uint32 ns = 0;
    while (ns < nsteerPath)
    {
        // Stop at Off-Mesh link or when point is further than slop away.
        if ((steerPathFlags[ns] & DT_STRAIGHTPATH_OFFMESH_CONNECTION) ||
                !inRangeYZX(&steerPath[ns * VERTEX_SIZE], startPos, minTargetDist, 1000.0f))
            break;
        ns++;
    }
    // Failed to find good point to steer to.
    if (ns >= nsteerPath)
        return false;

    dtVcopy(steerPos, &steerPath[ns * VERTEX_SIZE]);
    steerPos[1] = startPos[1];  // keep Z value
    steerPosFlag = steerPathFlags[ns];
    steerPosRef = steerPathPolys[ns];

    return true;
}

CrossProduct.body:
float CrossProduct(float* pointA, float* pointB, float* pointC)
{
    float AB[2];
    float AC[2];
    AB[0] = pointB[0] - pointA[0];
    AB[1] = pointB[1] - pointA[1];
    AC[0] = pointC[0] - pointA[0];
    AC[1] = pointC[1] - pointA[1];
    float cross = AB[0] * AC[1] - AB[1] * AC[0];

    return cross;
}

Distance.body:
float Distance(float* pointA, float* pointB)
{
    float d1 = pointA[0] - pointB[0];
    float d2 = pointA[2] - pointB[2];

    return sqrt(d1 * d1 + d2 * d2);
}

Distance2DPointToLineYZX.body:
float Distance2DPointToLineYZX(float* lineA, float* lineB, float* point)
{
    return std::abs(CrossProduct(lineA, lineB, point) / Distance(lineA, lineB));
}

PathInfo::findSmoothPath.body:
dtStatus PathInfo::findSmoothPath(float const* startPos, float const* endPos,
                                  dtPolyRef const* polyPath, uint32 polyPathSize,
                                  float* smoothPath, int* smoothPathSize, uint32 maxSmoothPathSize)
{
    bool simplifyPath = false;
    *smoothPathSize = 0;
    uint32 nsmoothPath = 0;

    dtPolyRef polys[MAX_PATH_LENGTH];
    memcpy(polys, polyPath, sizeof(dtPolyRef)*polyPathSize);
    uint32 npolys = polyPathSize;

    float iterPos[VERTEX_SIZE], targetPos[VERTEX_SIZE];
    int32 nSkippedPoints = 0;
    if (dtStatusFailed(m_navMeshQuery->closestPointOnPolyBoundary(polys[0], startPos, iterPos)))
        return DT_FAILURE;

    if (dtStatusFailed(m_navMeshQuery->closestPointOnPolyBoundary(polys[npolys - 1], endPos, targetPos)))
        return DT_FAILURE;

    dtVcopy(&smoothPath[nsmoothPath * VERTEX_SIZE], iterPos);
    nsmoothPath++;

    // Move towards target a small advancement at a time until target reached or
    // when ran out of memory to store the path.
    while (npolys && nsmoothPath < maxSmoothPathSize)
    {
        // Find location to steer towards.
        float steerPos[VERTEX_SIZE];
        unsigned char steerPosFlag;
        dtPolyRef steerPosRef = INVALID_POLYREF;

        if (!getSteerTarget(iterPos, targetPos, SMOOTH_PATH_SLOP, polys, npolys, steerPos, steerPosFlag, steerPosRef))
            break;

        bool const endOfPath = (steerPosFlag & DT_STRAIGHTPATH_END) != 0;
        bool const offMeshConnection = (steerPosFlag & DT_STRAIGHTPATH_OFFMESH_CONNECTION) != 0;

        // Find movement delta.
        float delta[VERTEX_SIZE];
        dtVsub(delta, steerPos, iterPos);
        float len = sqrtf(dtVdot(delta, delta));
        // If the steer target is end of path or off-mesh link, do not move past the location.
        if ((endOfPath || offMeshConnection) && len < SMOOTH_PATH_STEP_SIZE)
            len = 1.0f;
        else if (len < SMOOTH_PATH_STEP_SIZE*4)
            len = SMOOTH_PATH_STEP_SIZE / len;
        else
            len = SMOOTH_PATH_STEP_SIZE*4 / len;

        float moveTgt[VERTEX_SIZE];
        dtVmad(moveTgt, iterPos, delta, len);

        // Move
        float result[VERTEX_SIZE];
        static uint32 const MAX_VISIT_POLY = 16;
        dtPolyRef visited[MAX_VISIT_POLY];

        uint32 nvisited = 0;
        if (dtStatusFailed(m_navMeshQuery->moveAlongSurface(polys[0], iterPos, moveTgt, &m_filter, result, visited, (int*)&nvisited, MAX_VISIT_POLY)))
            return DT_FAILURE;
        npolys = fixupCorridor(polys, npolys, MAX_PATH_LENGTH, visited, nvisited);
        npolys = fixupShortcuts(polys, npolys, m_navMeshQuery);

        if (dtStatusFailed(m_navMeshQuery->getPolyHeight(polys[0], result, &result[1])))
            sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "Cannot find height at position X: %f Y: %f Z: %f for %s", result[2], result[0], result[1], m_sourceUnit->GetName());
        result[1] += 0.5f;
        dtVcopy(iterPos, result);

        // Handle end of path and off-mesh links when close enough.
        if (endOfPath && inRangeYZX(iterPos, steerPos, SMOOTH_PATH_SLOP, 1.0f))
        {
            // Reached end of path.
            if (dtStatusSucceed(m_navMeshQuery->getPolyHeight(polys[0], targetPos, &targetPos[1])))
            {
                targetPos[1] += 0.5f;
                dtVcopy(iterPos, targetPos);
            }
            if (nsmoothPath < maxSmoothPathSize)
            {
                if (nSkippedPoints)
                    dtVcopy(&smoothPath[(nsmoothPath - 1) * VERTEX_SIZE], &smoothPath[nsmoothPath * VERTEX_SIZE]);
                dtVcopy(&smoothPath[nsmoothPath * VERTEX_SIZE], iterPos);
                nsmoothPath++;
            }
            break;
        }
        else if (offMeshConnection && inRangeYZX(iterPos, steerPos, SMOOTH_PATH_SLOP, 1.0f))
        {
            // Advance the path up to and over the off-mesh connection.
            dtPolyRef prevRef = INVALID_POLYREF;
            dtPolyRef polyRef = polys[0];
            uint32 npos = 0;
            while (npos < npolys && polyRef != steerPosRef)
            {
                prevRef = polyRef;
                polyRef = polys[npos];
                npos++;
            }

            for (uint32 i = npos; i < npolys; ++i)
                polys[i - npos] = polys[i];

            npolys -= npos;

            // Handle the connection.
            float startPos[VERTEX_SIZE], endPos[VERTEX_SIZE];
            if (dtStatusSucceed(m_navMesh->getOffMeshConnectionPolyEndPoints(prevRef, polyRef, startPos, endPos)))
            {
                if (nsmoothPath < maxSmoothPathSize)
                {
                    dtVcopy(&smoothPath[nsmoothPath * VERTEX_SIZE], startPos);
                    nsmoothPath++;
                }
                // Move position at the other side of the off-mesh link.
                dtVcopy(iterPos, endPos);
                if (dtStatusFailed(m_navMeshQuery->getPolyHeight(polys[0], iterPos, &iterPos[1])))
                    return DT_FAILURE;
                iterPos[1] += 0.2f;
            }
        }

        // Store results.
        if (nsmoothPath < maxSmoothPathSize)
        {
            // Nostalrius: do we need to store this point ? Don't use 10 points to make a straight line: 2 are enough !
            // We eventually remove the last one
            if (simplifyPath && nsmoothPath >= 2 && nSkippedPoints >= 0)
            {
                // Check z-delta. Needed ... ?
                /*
                float currentZ = iterPos[1];
                float lastZ = smoothPath[(nsmoothPath - 1)* VERTEX_SIZE + 1];
                float lastLastZ = smoothPath[(nsmoothPath - 2)* VERTEX_SIZE + 1];*/
                if (nSkippedPoints < 20 &&  // Prevent infinite loop here
                        Distance2DPointToLineYZX(&smoothPath[(nsmoothPath - 2)* VERTEX_SIZE], &smoothPath[(nsmoothPath - 1)* VERTEX_SIZE], iterPos) < 0.8f) // Replace the last point.
                {
                    dtVcopy(&smoothPath[nsmoothPath * VERTEX_SIZE], iterPos);
                    ++nSkippedPoints;
                    continue;
                }
                else if (nSkippedPoints)
                    dtVcopy(&smoothPath[(nsmoothPath - 1) * VERTEX_SIZE], &smoothPath[nsmoothPath * VERTEX_SIZE]);
            }
            nSkippedPoints = 0;
            dtVcopy(&smoothPath[nsmoothPath * VERTEX_SIZE], iterPos);
            nsmoothPath++;
        }
    }

    *smoothPathSize = nsmoothPath;

    // this is most likely a loop
    return nsmoothPath < MAX_POINT_PATH_LENGTH ? DT_SUCCESS : DT_FAILURE;
}

PathInfo::UpdateForCaster.body:
bool PathInfo::UpdateForCaster(Unit* pTarget, float castRange)
{
    // If already in range and LOS
    if (pTarget->IsWithinDist3d(m_sourceUnit->GetPositionX(), m_sourceUnit->GetPositionY(), m_sourceUnit->GetPositionZ(), castRange) &&
            pTarget->IsWithinLOS(m_sourceUnit->GetPositionX(), m_sourceUnit->GetPositionY(), m_sourceUnit->GetPositionZ()))
    {
        clear();
        m_type = PathType(PATHFIND_SHORTCUT | PATHFIND_NORMAL | PATHFIND_CASTER);
        m_pathPoints.resize(2);
        m_pathPoints[0] = getStartPosition();
        m_pathPoints[1] = getStartPosition();
        return true;
    }
    uint32 maxIndex = m_pathPoints.size() - 1;
    // We have always keep at least 2 points (else, there is no mvt !)
    for (uint32 i = 1; i <= maxIndex; ++i)
    {
        if (pTarget->IsWithinDist3d(m_pathPoints[i].x, m_pathPoints[i].y, m_pathPoints[i].z, castRange) &&
                pTarget->IsWithinLOS(m_pathPoints[i].x, m_pathPoints[i].y, m_pathPoints[i].z))
        {
            Vector3 startPoint = m_pathPoints[i - 1];
            Vector3 endPoint = m_pathPoints[i];
            Vector3 dirVect = endPoint - startPoint;
            float targetDist1 = pTarget->GetDistance(m_pathPoints[i].x, m_pathPoints[i].y, m_pathPoints[i].z);
            float targetDist2 = pTarget->GetDistance(m_pathPoints[i - 1].x, m_pathPoints[i - 1].y, m_pathPoints[i - 1].z);
            if ((targetDist2 > targetDist1) && (targetDist2 > castRange))
            {
                float nonInRangeDist = (targetDist2 - castRange / targetDist2 - targetDist1);
                float directionLength = sqrt(dirVect.squaredLength());
                // Thales not applicable but still a valid start point due to conditions.
                startPoint += dirVect * nonInRangeDist / directionLength;
            }

            if (pTarget->IsWithinDist3d(startPoint.x, startPoint.y, startPoint.z, castRange) &&
                    pTarget->IsWithinLOS(startPoint.x, startPoint.y, startPoint.z))
                m_pathPoints[i] = startPoint;
            m_pathPoints.resize(i + 1);

            return false;
        }
    }
    return false;
}

PathInfo::UpdateForMelee.body:
bool PathInfo::UpdateForMelee(Unit* pTarget, float meleeReach)
{
    // If already within melee range, all good.
    if (m_sourceUnit->CanReachWithMeleeAutoAttack(pTarget))
    {
        clear();
        m_type = PathType(PATHFIND_SHORTCUT | PATHFIND_NORMAL | PATHFIND_CASTER);
        m_pathPoints.resize(2);
        m_pathPoints[0] = getStartPosition();
        m_pathPoints[1] = getStartPosition();
        return true;
    }

    uint32 maxIndex = m_pathPoints.size() - 1;
    // We have always keep at least 2 points (else, there is no mvt !)
    for (uint32 i = 1; i <= maxIndex; ++i)
    {
        if (pTarget->IsWithinDist3d(m_pathPoints[i].x, m_pathPoints[i].y, m_pathPoints[i].z, meleeReach, SizeFactor::None))
        {
            Vector3 dirVect;
            pTarget->GetPosition(dirVect.x, dirVect.y, dirVect.z);
            dirVect -= m_pathPoints[i - 1];
            float targetDist = pTarget->GetDistance(m_pathPoints[i - 1].x, m_pathPoints[i - 1].y, m_pathPoints[i - 1].z, SizeFactor::None);
            targetDist -= meleeReach;
            float directionLength = sqrt(dirVect.squaredLength());
            m_pathPoints[i] = m_pathPoints[i - 1] + dirVect * targetDist / directionLength;
            m_pathPoints.resize(i + 1);
            return false;
        }
    }
    return false;
}

PathInfo::CutPathWithDynamicLoS.body:
void PathInfo::CutPathWithDynamicLoS()
{
    uint32 maxIndex = m_pathPoints.size() - 1;
    Vector3 out;
    // We have always keep at least 2 points (else, there is no mvt !)
    for (uint32 i = 1; i <= maxIndex; ++i)
        if (m_sourceUnit->GetMap()->GetDynamicObjectHitPos(m_pathPoints[i - 1], m_pathPoints[i], out, -0.1f))
        {
            m_pathPoints[i] = out;
            m_pathPoints.resize(i + 1);
            break;
        }
}

PathInfo::Length.body:
float PathInfo::Length() const
{
    ASSERT(m_pathPoints.size());
    float length = 0.0f;
    uint32 maxIndex = m_pathPoints.size() - 1;
    for (uint32 i = 1; i <= maxIndex; ++i)
        length += (m_pathPoints[i - 1] - m_pathPoints[i]).length();
    return length;
}

PathInfo::inRangeYZX.body:
bool PathInfo::inRangeYZX(float const* v1, float const* v2, float r, float h)
{
    float const dx = v2[0] - v1[0];
    float const dy = v2[1] - v1[1]; // elevation
    float const dz = v2[2] - v1[2];
    return (dx * dx + dz * dz) < r * r && fabsf(dy) < h;
}

PathInfo::inRange.body:
bool PathInfo::inRange(Vector3 const& p1, Vector3 const& p2, float r, float h)
{
    Vector3 d = p1 - p2;
    return (d.x * d.x + d.y * d.y) < r * r && fabsf(d.z) < h;
}

PathInfo::dist3DSqr.body:
float PathInfo::dist3DSqr(Vector3 const& p1, Vector3 const& p2)
{
    return (p1 - p2).squaredLength();
}

WorldObject::HasMMapsForCurrentMap.body:
bool WorldObject::HasMMapsForCurrentMap() const
{
    MMAP::MMapManager* mmap = MMAP::MMapFactory::createOrGetMMapManager();
    dtNavMeshQuery const* m_navMeshQuery = GetTransport() ? mmap->GetModelNavMeshQuery(GetTransport()->GetDisplayId()) : mmap->GetNavMeshQuery(GetMapId());
    return m_navMeshQuery != nullptr;
}

PoolObject::CanBeSpawned.body:
bool PoolObject::CanBeSpawned() const
{
    if (exclude)
        return false;
    if (spawnFlags & FLAG_SPAWN_ENABLE_IF_WORLD_POP_OVER_BLIZZLIKE && sWorld.GetActiveSessionCount() <= BLIZZLIKE_REALM_POPULATION)
        return false;
    return true;
}

PoolTemplateData::GetSpawnCount.body:
uint32 PoolTemplateData::GetSpawnCount() const
{
    if (PoolFlags & POOL_FLAG_MAXLIMIT_SCALING_LINEAR && sWorld.GetActiveSessionCount() > BLIZZLIKE_REALM_POPULATION)
        return uint32(MaxLimit * float(sWorld.GetActiveSessionCount() / float(BLIZZLIKE_REALM_POPULATION)));

    return MaxLimit;
}

SpawnedPoolData::GetSpawnedObjects.body:
uint32 SpawnedPoolData::GetSpawnedObjects(uint32 pool_id) const
{
    SpawnedPoolPools::const_iterator itr = mSpawnedPools.find(pool_id);
    return itr != mSpawnedPools.end() ? itr->second : 0;
}

CheckPoolAndChance.body:
bool CheckPoolAndChance(char const* table, uint16 pool_id, float chance)
{
    if (pool_id > sPoolMgr.GetMaxPoolId())
    {
        sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` pool id (%i) is out of range compared to max pool id in `pool_template`, skipped.", table, pool_id);
        return false;
    }
    if (chance < 0 || chance > 100)
    {
        sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` has an invalid chance (%f) in pool id (%i), skipped.", table, chance, pool_id);
        return false;
    }
    return true;
}

PoolManager::LoadFromDB.body:
void PoolManager::LoadFromDB()
{
    std::unique_ptr<QueryResult> result = WorldDatabase.PQuery("SELECT MAX(`entry`) FROM `pool_template` WHERE %u BETWEEN `patch_min` AND `patch_max`", sWorld.GetWowPatch());
    if (!result)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table pool_template is empty.");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        return;
    }
    else
    {
        Field* fields = result->Fetch();
        m_maxPoolId = fields[0].GetUInt16();
    }

    m_poolTemplate.resize(m_maxPoolId + 1);

    result = WorldDatabase.PQuery("SELECT `entry`, `max_limit`, `flags`, `description`, `instance` FROM `pool_template` WHERE %u BETWEEN `patch_min` AND `patch_max`", sWorld.GetWowPatch());
    if (!result)
    {
        m_poolTemplate.clear();
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Table pool_template is empty:");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        return;
    }

    uint32 count = 0;

    BarGoLink bar(result->GetRowCount());
    do
    {
        ++count;
        Field* fields = result->Fetch();

        bar.step();

        uint16 pool_id = fields[0].GetUInt16();

        PoolTemplateData& pPoolTemplate = m_poolTemplate[pool_id];

        pPoolTemplate.MaxLimit    = fields[1].GetUInt32();
        if (pPoolTemplate.MaxLimit < 1)
            sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "Pool Id (%u) has no max limit set.", pool_id);
        pPoolTemplate.PoolFlags   = fields[2].GetUInt32();
        pPoolTemplate.description = fields[3].GetCppString();
        if (pPoolTemplate.description.empty())
            sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "Pool Id (%u) has no description set.", pool_id);
        pPoolTemplate.InstanceId  = sWorld.getConfig(CONFIG_BOOL_CONTINENTS_INSTANCIATE) ? fields[4].GetUInt32() : 0;
        pPoolTemplate.PoolFlags |= POOL_FLAG_AUTO_SPAWN;

    }
    while (result->NextRow());

    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u objects pools", count);

    PoolMapChecker mapChecker(m_poolTemplate);

    // Creatures (guids and entries)

    m_poolCreatureGroups.resize(m_maxPoolId + 1);
    m_creatureSearchMap.clear();

    result = WorldDatabase.PQuery(
            "SELECT `guid`, `pool_entry`, `chance`, 0, `flags`, `patch_min`, `patch_max` FROM `pool_creature` WHERE %u BETWEEN `patch_min` AND `patch_max` "
            "UNION "
            " SELECT `guid`, `pool_entry`, `chance`, `pool_creature_template`.`id`, `pool_creature_template`.`flags`, `pool_creature_template`.`patch_min`, `pool_creature_template`.`patch_max` "
            "FROM `pool_creature_template` LEFT JOIN `creature` ON `creature`.`id` = `pool_creature_template`.`id`;", sWorld.GetWowPatch());

    count = 0;
    if (!result)
    {
        BarGoLink bar2(1);
        bar2.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u creatures in pools from `pool_creature`", count);
    }
    else
    {

        BarGoLink bar2(result->GetRowCount());
        do
        {
            Field* fields = result->Fetch();

            bar2.step();

            uint32 guid    = fields[0].GetUInt32();
            uint16 pool_id = fields[1].GetUInt16();
            float chance   = fields[2].GetFloat();
            uint32 entry_id= fields[3].GetUInt32();
            uint32 flags   = fields[4].GetUInt32();
            uint32 patch_min = fields[5].GetUInt8();
            uint32 patch_max = fields[6].GetUInt8();

            if ((patch_min > sWorld.GetWowPatch()) || (patch_max < sWorld.GetWowPatch()))
                continue;

            char const* table = entry_id ? "pool_creature_template" : "pool_creature";

            CreatureData const* data = sObjectMgr.GetCreatureData(guid);
            if (!data)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` has a non existing creature spawn (GUID: %u) defined for pool id (%u), skipped.", table, guid, pool_id);
                continue;
            }

            // `pool_creature` and `pool_creature_template` can't have guids duplicates (in second case because entries also unique)
            // So if guid already listed in pools then this duplicate from alt.table
            // Also note: for added guid not important what case we skip from 2 tables
            if (uint16 alt_pool_id = IsPartOfAPool<Creature>(guid))
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` has guid %u for pool %u that already added to pool %u from `pool_creature_template` for creature entry %u, skipped.",
                                table, guid, pool_id, alt_pool_id, entry_id);
                continue;
            }

            if (!CheckPoolAndChance(table, pool_id, chance))
                continue;

            if (!m_poolTemplate[pool_id].MaxLimit)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` has guid %u for invalid pool %u, skipped.", table, guid, pool_id);
                continue;
            }

            if (!mapChecker.CheckAndRemember(data->position.mapId, pool_id, table, "creature guid"))
                continue;

            PoolTemplateData *pPoolTemplate = &m_poolTemplate[pool_id];

            ++count;

            PoolObject plObject = PoolObject(guid, chance, flags);
            PoolGroup<Creature>& cregroup = m_poolCreatureGroups[pool_id];
            cregroup.SetPoolId(pool_id);
            cregroup.AddEntry(plObject, pPoolTemplate->MaxLimit);
            SearchPair p(guid, pool_id);
            m_creatureSearchMap.insert(p);

        }
        while (result->NextRow());
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u creatures in pools from `pool_creature` and `pool_creature_template`", count);
    }

    // Gameobjects (guids and entries)
    m_poolGameObjectGroups.resize(m_maxPoolId + 1);
    m_gameObjectSearchMap.clear();
    //                                     0       1             2        3   4        5            6
    result = WorldDatabase.PQuery("SELECT `guid`, `pool_entry`, `chance`, 0, `flags`, `patch_min`, `patch_max` FROM `pool_gameobject` WHERE (%u BETWEEN `patch_min` AND `patch_max`) "
        "UNION "
        "SELECT `guid`, `pool_entry`, `chance`, `pool_gameobject_template`.`id`, `pool_gameobject_template`.`flags`, `pool_gameobject_template`.`patch_min`, `pool_gameobject_template`.`patch_max` "
        "FROM `pool_gameobject_template` LEFT JOIN `gameobject` ON `gameobject`.`id` = `pool_gameobject_template`.`id`", sWorld.GetWowPatch());

    count = 0;
    if (!result)
    {
        BarGoLink bar2(1);
        bar2.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u gameobject in pools from `pool_gameobject` and `pool_gameobject_template`", count);
    }
    else
    {

        BarGoLink bar2(result->GetRowCount());
        do
        {
            Field* fields = result->Fetch();

            bar2.step();

            uint32 guid    = fields[0].GetUInt32();
            uint16 pool_id = fields[1].GetUInt16();
            float chance   = fields[2].GetFloat();
            uint32 entry_id= fields[3].GetUInt32();
            uint32 flags   = fields[4].GetUInt32();
            uint32 patch_min = fields[5].GetUInt8();
            uint32 patch_max = fields[6].GetUInt8();

            if ((patch_min > sWorld.GetWowPatch()) || (patch_max < sWorld.GetWowPatch()))
                continue;

            char const* table = entry_id ? "pool_gameobject_template" : "pool_gameobject";

            GameObjectData const* data = sObjectMgr.GetGOData(guid);
            if (!data)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` has a non existing gameobject spawn (GUID: %u) defined for pool id (%u), skipped.", table, guid, pool_id);
                continue;
            }

            // `pool_gameobject` and `pool_gameobject_template` can't have guids duplicates (in second case because entries also unique)
            // So if guid already listed in pools then this duplicate from alt.table
            // Also note: for added guid not important what case we skip from 2 tables
            if (uint16 alt_pool_id = IsPartOfAPool<GameObject>(guid))
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` has guid %u for pool %u that already added to pool %u from `pool_gameobject_template` for gameobject entry %u, skipped.",
                                table, guid, pool_id, alt_pool_id, entry_id);
                continue;
            }

            if (!CheckPoolAndChance(table, pool_id, chance))
                continue;

            if (!m_poolTemplate[pool_id].MaxLimit)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`%s` has guid %u for invalid pool %u, skipped.", table, guid, pool_id);
                continue;
            }

            if (!mapChecker.CheckAndRemember(data->position.mapId, pool_id, table, "gameobject guid"))
                continue;

            PoolTemplateData *pPoolTemplate = &m_poolTemplate[pool_id];

            ++count;

            PoolObject plObject = PoolObject(guid, chance, flags);
            PoolGroup<GameObject>& gogroup = m_poolGameObjectGroups[pool_id];
            gogroup.SetPoolId(pool_id);
            gogroup.AddEntry(plObject, pPoolTemplate->MaxLimit);
            SearchPair p(guid, pool_id);
            m_gameObjectSearchMap.insert(p);

        }
        while (result->NextRow());
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u gameobject in pools from `pool_gameobject` and `pool_gameobject_template`", count);
    }

    // Pool of pools
    m_poolPoolGroups.resize(m_maxPoolId + 1);
    //                                    1          2              3         4
    result = WorldDatabase.Query("SELECT `pool_id`, `mother_pool`, `chance`, `flags` FROM `pool_pool`");

    count = 0;
    if (!result)
    {
        BarGoLink bar2(1);
        bar2.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u pools in pools", count);
    }
    else
    {

        BarGoLink bar2(result->GetRowCount());
        do
        {
            Field* fields = result->Fetch();

            bar2.step();

            uint16 child_pool_id  = fields[0].GetUInt16();
            uint16 mother_pool_id = fields[1].GetUInt16();
            float chance          = fields[2].GetFloat();
            uint32 flags          = fields[3].GetFloat();

            if (child_pool_id > m_maxPoolId)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`pool_pool` included pool_id (%i) is out of range compared to max pool id in `pool_template`, skipped.", child_pool_id);
                continue;
            }

            if (mother_pool_id == child_pool_id)
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "`pool_pool` pool_id (%i) includes itself, dead-lock detected, skipped.", child_pool_id);
                continue;
            }

            if (!CheckPoolAndChance("pool_pool", mother_pool_id, chance))
                continue;

            PoolTemplateData *pPoolTemplateMother = &m_poolTemplate[mother_pool_id];

            ++count;

            PoolObject plObject = PoolObject(child_pool_id, chance, flags);
            PoolGroup<Pool>& plgroup = m_poolPoolGroups[mother_pool_id];
            plgroup.SetPoolId(mother_pool_id);
            plgroup.AddEntry(plObject, pPoolTemplateMother->MaxLimit);
            SearchPair p(child_pool_id, mother_pool_id);
            m_poolSearchMap.insert(p);

            // update top independent pool flag
            m_poolTemplate[child_pool_id].PoolFlags &= ~POOL_FLAG_AUTO_SPAWN;

        }
        while (result->NextRow());

        // Now check for circular reference
        for (uint16 i = 0; i < m_maxPoolId; ++i)
        {
            std::set<uint16> checkedPools;
            for (SearchMap::iterator poolItr = m_poolSearchMap.find(i); poolItr != m_poolSearchMap.end(); poolItr = m_poolSearchMap.find(poolItr->second))
            {
                // if child pool not have map data then it empty or have not checked child then will checked and all line later
                if (MapEntry const* childMapEntry = m_poolTemplate[poolItr->first].mapEntry)
                {
                    if (!mapChecker.CheckAndRemember(childMapEntry->id, poolItr->second, "pool_pool", "pool with creature/gameobject"))
                    {
                        m_poolPoolGroups[poolItr->second].RemoveOneRelation(poolItr->first);
                        m_poolSearchMap.erase(poolItr);
                        --count;
                        break;
                    }
                }

                checkedPools.insert(poolItr->first);
                if (checkedPools.find(poolItr->second) != checkedPools.end())
                {
                    std::ostringstream ss;
                    ss << "The pool(s) ";
                    for (const auto checkedPool : checkedPools)
                        ss << checkedPool << " ";
                    ss << "create(s) a circular reference, which can cause the server to freeze.\nRemoving the last link between mother pool "
                       << poolItr->first << " and child pool " << poolItr->second;
                    sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "%s", ss.str().c_str());
                    m_poolPoolGroups[poolItr->second].RemoveOneRelation(poolItr->first);
                    m_poolSearchMap.erase(poolItr);
                    --count;
                    break;
                }
            }
        }

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u pools in mother pools", count);
    }

    for (uint16 pool_entry = 0; pool_entry < m_poolTemplate.size(); ++pool_entry)
    {
        if (m_poolTemplate[pool_entry].MaxLimit &&
            m_poolGameObjectGroups[pool_entry].isEmpty() &&
            m_poolCreatureGroups[pool_entry].isEmpty() &&
            m_poolPoolGroups[pool_entry].isEmpty())
        {
            sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "Pool Id (%u) is empty.", pool_entry);
        }

        if (!m_poolTemplate[pool_entry].InstanceId &&
            m_poolTemplate[pool_entry].mapEntry &&
            m_poolTemplate[pool_entry].mapEntry->IsContinent() &&
            sWorld.getConfig(CONFIG_BOOL_CONTINENTS_INSTANCIATE))
        {
            m_poolTemplate[pool_entry].InstanceId = GetContinentInstanceIdForPool(pool_entry);
        }

        // check chances integrity
        if (m_poolTemplate[pool_entry].IsAutoSpawn())
        {
            if (!CheckPool(pool_entry))
            {
                sLog.Out(LOG_DBERROR, LOG_LVL_ERROR, "Pool Id (%u) has all creatures or gameobjects with explicit chance sum <>100 and no equal chance defined. The pool system cannot pick one to spawn.", pool_entry);
                m_poolTemplate[pool_entry].PoolFlags &= ~POOL_FLAG_AUTO_SPAWN;
            }
        }
    }
}

PoolManager::GetContinentInstanceIdForPo.body:
uint32 PoolManager::GetContinentInstanceIdForPool(uint16 pool_id) const
{
    if (!m_poolGameObjectGroups[pool_id].isEmpty())
    {
        for (auto const& itr : m_poolGameObjectGroups[pool_id].GetEqualChanced())
        {
            if (GameObjectData const* data = sObjectMgr.GetGOData(itr.guid))
            {
                if (data->position.mapId <= MAX_CONTINENT_ID)
                    return sMapMgr.GetContinentInstanceId(data->position.mapId, data->position.x, data->position.y);
            }
        }

        for (auto const& itr : m_poolGameObjectGroups[pool_id].GetExplicitlyChanced())
        {
            if (GameObjectData const* data = sObjectMgr.GetGOData(itr.guid))
            {
                if (data->position.mapId <= MAX_CONTINENT_ID)
                    return sMapMgr.GetContinentInstanceId(data->position.mapId, data->position.x, data->position.y);
            }
        }
    }

    if (!m_poolCreatureGroups[pool_id].isEmpty())
    {
        for (auto const& itr : m_poolCreatureGroups[pool_id].GetEqualChanced())
        {
            if (CreatureData const* data = sObjectMgr.GetCreatureData(itr.guid))
            {
                if (data->position.mapId <= MAX_CONTINENT_ID)
                    return sMapMgr.GetContinentInstanceId(data->position.mapId, data->position.x, data->position.y);
            }
        }

        for (auto const& itr : m_poolCreatureGroups[pool_id].GetExplicitlyChanced())
        {
            if (CreatureData const* data = sObjectMgr.GetCreatureData(itr.guid))
            {
                if (data->position.mapId <= MAX_CONTINENT_ID)
                    return sMapMgr.GetContinentInstanceId(data->position.mapId, data->position.x, data->position.y);
            }
        }
    }

    return 0;
}

PoolManager::Initialize.body:
void PoolManager::Initialize(MapPersistentState* state)
{
    // spawn pools for expected map or for not initialized shared pools state for non-instanceable maps
    for (uint16 pool_entry = 0; pool_entry < m_poolTemplate.size(); ++pool_entry)
        if (m_poolTemplate[pool_entry].IsAutoSpawn())
            InitSpawnPool(*state, pool_entry);
}

