        sLog.Out(LOG_SCRIPTS, LOG_LVL_ERROR, "SCRIPT_COMMAND_ATTACK_START (script id %u) for an invalid attack target, skipping.", script.id);
        return ShouldAbortScript(script);
    }

    if (pAttacker->AI())
        pAttacker->AI()->AttackStart(pTarget);
    else
        return ShouldAbortScript(script);

    return false;
}

