            itr2 = m_ZoneScriptsMap.begin();
        }
}

TimedFearMovementGenerator::Finalize.body:
void TimedFearMovementGenerator::Finalize(Unit &owner)
{
    owner.ClearUnitState(UNIT_STATE_FLEEING | UNIT_STATE_FLEEING_MOVE);
    owner.UpdateControl();

    if (Unit* victim = owner.GetVictim())
    {
        if (owner.IsAlive())
        {
            owner.AttackStop(true);
            ((Creature*)&owner)->AI()->AttackStart(victim);
        }
    }
}

TimedFearMovementGenerator::Update.body:
bool TimedFearMovementGenerator::Update(Unit & owner, uint32 const&  time_diff)
{
    if (!owner.IsAlive())
        return false;

    if (owner.HasUnitState((UNIT_STATE_CAN_NOT_REACT | UNIT_STATE_CAN_NOT_MOVE | UNIT_STATE_STUNNED | UNIT_STATE_PENDING_STUNNED) & ~UNIT_STATE_FLEEING))
    {
        owner.ClearUnitState(UNIT_STATE_FLEEING_MOVE);
        return true;
    }

    i_totalFleeTime.Update(time_diff);

    if (i_totalFleeTime.Passed())
        return false;

    return MovementGeneratorMedium< Creature, FearMovementGenerator<Creature> >::Update(owner, time_diff);
}

TimedFleeingMovementGenerator::Finalize.body:
void TimedFleeingMovementGenerator::Finalize(Unit &owner)
{
    owner.ClearUnitState(UNIT_STATE_FLEEING | UNIT_STATE_FLEEING_MOVE);
    owner.UpdateControl();

    if (owner.IsAlive() && !owner.HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_CONFUSED | UNIT_FLAG_FLEEING | UNIT_FLAG_POSSESSED))
    {
        if (Unit* victim = owner.GetVictim())
        {
            owner.AttackStop(true);
            ((Creature*)&owner)->AI()->AttackStart(victim);
        }
    }
}

TimedFleeingMovementGenerator::Update.body:
bool TimedFleeingMovementGenerator::Update(Unit & owner, uint32 const&  time_diff)
{
    if (!owner.IsAlive())
        return false;

    // ignore in case other no reaction state
    if (owner.HasUnitState((UNIT_STATE_CAN_NOT_REACT | UNIT_STATE_CAN_NOT_MOVE | UNIT_STATE_STUNNED | UNIT_STATE_PENDING_STUNNED) & ~UNIT_STATE_FLEEING))
    {
        owner.ClearUnitState(UNIT_STATE_FLEEING_MOVE);
        return true;
    }

    i_totalFleeTime.Update(time_diff);
    if (i_totalFleeTime.Passed())
        return false;

    // This calls grant-parent Update method hiden by FleeingMovementGenerator::Update(Creature &, uint32 const&) version
    // This is done instead of casting Unit& to Creature& and call parent method, then we can use Unit directly
    return MovementGeneratorMedium< Creature, FleeingMovementGenerator<Creature> >::Update(owner, time_diff);
}

MotionMaster::Initialize.body:
void MotionMaster::Initialize()
{
    // stop current move
    if (!m_owner->IsStopped())
        m_owner->StopMoving();

    // clear ALL movement generators (including default)
    Clear(false, true);

    // set new default movement generator
    if (m_owner->IsCreature() && m_owner->IsAlive() && !m_owner->HasUnitState(UNIT_STATE_POSSESSED))
    {
        MovementGenerator* movement = FactorySelector::selectMovementGenerator(static_cast<Creature*>(m_owner));
        push(movement == nullptr ? &si_idleMovement : movement);
        top()->Initialize(*m_owner);

        switch (top()->GetMovementGeneratorType())
        {
            case WAYPOINT_MOTION_TYPE:
                (static_cast<WaypointMovementGenerator<Creature>*>(top()))->InitializeWaypointPath(*(static_cast<Creature*>(m_owner)), 0, PATH_NO_PATH, 0, 0, 0, true);
                break;
            case CYCLIC_MOTION_TYPE:
                (static_cast<CyclicMovementGenerator<Creature>*>(top()))->InitializeWaypointPath(*(static_cast<Creature*>(m_owner)), PATH_NO_PATH, 0, 0);
                break;
        }
    }
    else
        push(&si_idleMovement);

    // Pet movement after control movement spell.
    if (CharmInfo* ci = m_owner->GetCharmInfo())
    {
        ci->SetIsAtStay(false);
        ci->SetIsReturning(false);
        ci->SetIsFollowing(false);
    }
}

MotionMaster::InitializeNewDefault.body:
void MotionMaster::InitializeNewDefault(bool alwaysReplace)
{
    // This method changes the creature's default movement type
    // without interrupting the currently used movement generator

    if (empty())
    {
        Initialize();
        return;
    }

    Creature* pCreature = m_owner->ToCreature();
    if (!pCreature)
        return;

    MovementGeneratorType new_default = pCreature->GetDefaultMovementType();

    // Already using the same motion type as default
    if (!alwaysReplace && (size() == 1) && (top()->GetMovementGeneratorType() == new_default))
        return;

    // Get the current generator and eject it from the stack
    MovementGenerator* curr = top();
    pop();

    // Clear ALL other movement generators
    Clear(false, true);

    if (alwaysReplace || (curr->GetMovementGeneratorType() != new_default))
    {
        // Set new default movement generator
        if (!m_owner->HasUnitState(UNIT_STATE_POSSESSED))
        {
            MovementGenerator* movement = FactorySelector::selectMovementGenerator(pCreature);
            if (movement)
                new_default = movement->GetMovementGeneratorType();
            push(movement == nullptr ? &si_idleMovement : movement);
            top()->Initialize(*m_owner);

            switch (top()->GetMovementGeneratorType())
            {
                case WAYPOINT_MOTION_TYPE:
                    (static_cast<WaypointMovementGenerator<Creature>*>(top()))->InitializeWaypointPath(*(static_cast<Creature*>(m_owner)), 0, PATH_NO_PATH, 0, 0, 0, true);
                    break;
                case CYCLIC_MOTION_TYPE:
                    (static_cast<CyclicMovementGenerator<Creature>*>(top()))->InitializeWaypointPath(*(static_cast<Creature*>(m_owner)), PATH_NO_PATH, 0, 0);
                    break;
            }
        }
        else
            push(&si_idleMovement);

        // Restore the previous current generator, if its different from the new default
        if (curr->GetMovementGeneratorType() != new_default)
            push(curr);
        else
        {
            // Same as the new default, so we can delete it
            if (!m_expList)
                m_expList = new ExpireList();
            curr->Finalize(*m_owner);
            if (!isStatic(curr))
                m_expList->push_back(curr);
        }
    }
    else
        push(curr);
}

MotionMaster::UpdateMotion.body:
void MotionMaster::UpdateMotion(uint32 diff)
{
    if (m_owner->HasUnitState(UNIT_STATE_CAN_NOT_MOVE))
        return;

    MANGOS_ASSERT(!empty());
    m_cleanFlag |= MMCF_UPDATE;

    if (!top()->Update(*m_owner, diff))
    {
        m_cleanFlag &= ~MMCF_UPDATE;
        MovementExpired();
    }
    else
        m_cleanFlag &= ~MMCF_UPDATE;

    if (m_expList)
    {
        for (const auto mg : *m_expList)
        {
            if (!isStatic(mg))
                delete mg;
        }

        delete m_expList;
        m_expList = nullptr;

        if (empty())
            Initialize();

        if (m_cleanFlag & MMCF_RESET)
        {
            top()->Reset(*m_owner);
            m_cleanFlag &= ~MMCF_RESET;
        }
    }
}

MotionMaster::UpdateMotionAsync.body:
void MotionMaster::UpdateMotionAsync(uint32 diff)
{
    m_needsAsyncUpdate = false;
    if (m_owner->HasUnitState(UNIT_STATE_CAN_NOT_MOVE))
        return;

    MANGOS_ASSERT(!empty());
    m_cleanFlag |= MMCF_UPDATE;

    top()->UpdateAsync(*m_owner, diff);
}

MotionMaster::DirectClean.body:
void MotionMaster::DirectClean(bool reset, bool all)
{
    // Nostalrius: We need to clean top mvt gens, and call Finalize once it's done
    // because Finalize calls CreatureAI::MovementInform that can call MovePoint / ...

    std::vector<MovementGenerator*> mvtGensToFinalize;
    while (all ? !empty() : size() > 1)
    {
        MovementGenerator* curr = top();
        pop();
        mvtGensToFinalize.push_back(curr);
    }
    if (!all && reset)
    {
        if (empty()) // Should not happen
            Initialize();
        MANGOS_ASSERT(!empty());
        top()->Reset(*m_owner);
    }
    for (auto const& itr : mvtGensToFinalize)
    {
        itr->Finalize(*m_owner);
        if (!isStatic(itr))
            delete(itr);
    }
}

MotionMaster::DelayedClean.body:
void MotionMaster::DelayedClean(bool reset, bool all)
{
    if (reset)
        m_cleanFlag |= MMCF_RESET;
    else
        m_cleanFlag &= ~MMCF_RESET;

    if (empty() || (!all && size() == 1))
        return;

    if (!m_expList)
        m_expList = new ExpireList();
;
    std::vector<MovementGenerator*> mvtGensToFinalize;
    while (all ? !empty() : size() > 1)
    {
        MovementGenerator* curr = top();
        pop();
        mvtGensToFinalize.push_back(curr);
    }
    for (auto const& itr : mvtGensToFinalize)
    {
        itr->Finalize(*m_owner);

        if (!isStatic(itr))
            m_expList->push_back(itr);
    }
}

MotionMaster::DirectExpire.body:
void MotionMaster::DirectExpire(bool reset)
{
    if (empty() || size() == 1)
        return;

    MovementGenerator* curr = top();
    pop();

    // also drop stored under top() targeted motions
    std::vector<MovementGenerator*> mvtGensToFinalize;
    while (!empty() && (top()->GetMovementGeneratorType() == CHASE_MOTION_TYPE || top()->GetMovementGeneratorType() == FOLLOW_MOTION_TYPE) && (curr->GetMovementGeneratorType() != DISTANCING_MOTION_TYPE))
    {
        MovementGenerator* temp = top();
        pop();
        mvtGensToFinalize.push_back(temp);
    }
    for (auto const& itr : mvtGensToFinalize)
    {
        itr->Finalize(*m_owner);
        delete(itr);
    }
    // Store current top MMGen, as Finalize might push a new MMGen
    MovementGenerator* nowTop = empty() ? nullptr : top();
    // it can add another motions instead
    curr->Finalize(*m_owner);

    if (!isStatic(curr))
        delete curr;

    if (empty())
        Initialize();

    // Prevent reseting possible new pushed MMGen
    if (reset && top() == nowTop)
        top()->Reset(*m_owner);
}

MotionMaster::DelayedExpire.body:
void MotionMaster::DelayedExpire(bool reset)
{
    if (reset)
        m_cleanFlag |= MMCF_RESET;
    else
        m_cleanFlag &= ~MMCF_RESET;

    if (empty() || size() == 1)
        return;

    MovementGenerator* curr = top();
    pop();

    if (!m_expList)
        m_expList = new ExpireList();

    // also drop stored under top() targeted motions
    std::vector<MovementGenerator*> mvtGensToFinalize;
    while (!empty() && (top()->GetMovementGeneratorType() == CHASE_MOTION_TYPE || top()->GetMovementGeneratorType() == FOLLOW_MOTION_TYPE) && (curr->GetMovementGeneratorType() != DISTANCING_MOTION_TYPE))
    {
        MovementGenerator* temp = top();
        pop();
        mvtGensToFinalize.push_back(temp);
    }
    for (auto const& itr : mvtGensToFinalize)
    {
        itr->Finalize(*m_owner);
        m_expList->push_back(itr);
    }

    curr->Finalize(*m_owner);

    if (!isStatic(curr))
        m_expList->push_back(curr);
}

