SplineBase::InitLinear.body:
void SplineBase::InitLinear(Vector3 const* controls, index_type count, bool cyclic, index_type cyclic_point)
{
    MANGOS_ASSERT(count >= 2);
    int const real_size = count + 1;

    points.resize(real_size);

    memcpy(&points[0], controls, sizeof(Vector3) * count);

    // first and last two indexes are space for special 'virtual points'
    // these points are required for proper C_Evaluate and C_Evaluate_Derivative methtod work
    if (cyclic)
        points[count] = controls[cyclic_point];
    else
        points[count] = controls[count - 1];

    index_lo = 0;
    index_hi = cyclic ? count : (count - 1);
}

SplineBase::InitCatmullRom.body:
void SplineBase::InitCatmullRom(Vector3 const* controls, index_type count, bool cyclic, index_type cyclic_point)
{
    int const real_size = count + (cyclic ? (1 + 2) : (1 + 1));

    points.resize(real_size);

    int lo_index = 1;
    int high_index = lo_index + count - 1;

    memcpy(&points[lo_index], controls, sizeof(Vector3) * count);

    // first and last two indexes are space for special 'virtual points'
    // these points are required for proper C_Evaluate and C_Evaluate_Derivative methtod work
    if (cyclic)
    {
        if (cyclic_point == 0)
            points[0] = controls[count - 1];
        else
            points[0] = controls[0].lerp(controls[1], -1);

        points[high_index + 1] = controls[cyclic_point];
        points[high_index + 2] = controls[cyclic_point + 1];
    }
    else
    {
        points[0] = controls[0].lerp(controls[1], -1);
        points[high_index + 1] = controls[count - 1];
    }

    index_lo = lo_index;
    index_hi = high_index + (cyclic ? 1 : 0);
}

SplineBase::InitBezier3.body:
void SplineBase::InitBezier3(Vector3 const* controls, index_type count, bool /*cyclic*/, index_type /*cyclic_point*/)
{
    index_type c = count / 3u * 3u;
    index_type t = c / 3u;

    points.resize(c);
    memcpy(&points[0], controls, sizeof(Vector3) * c);

    index_lo = 0;
    index_hi = t - 1;
    // mov_assert(points.size() % 3 == 0);
}

