uint32 ObjectMgr::GetSavedVariable(uint32 index, uint32 defaultValue, bool* exist)
{
    SavedVariablesVector::iterator it;
    for (it = m_SavedVariables.begin(); it != m_SavedVariables.end(); ++it)
    {
        if (it->uiIndex == index)
        {
