void ObjectMgr::LoadSkillLineAbility()
{
    // Getting the maximum ID.
    std::unique_ptr<QueryResult> result(WorldDatabase.PQuery("SELECT MAX(`id`) FROM `skill_line_ability` WHERE `build`=%u", SUPPORTED_CLIENT_BUILD));

    if (!result)
