void GameObject::UpdateCollisionState()
{
    if (!m_model || !IsInWorld())
        return;

    bool enabled = GetGoType() == GAMEOBJECT_TYPE_CHEST ? getLootState() == GO_READY : GetGoState() == GO_STATE_READY;
