bool GameObject::CanAggroWhenOpening() const
{
    if (GetGoType() != GAMEOBJECT_TYPE_CHEST)
        return false;

    // only faction Treasure
    if (GetFactionId() != 77)
        return false;

    uint32 lockId = GetGOInfo()->GetLockId();
    if (!lockId)
        return false;

    LockEntry const* lock = sLockStore.LookupEntry(lockId);
    if (!lock)
        return false;

    for (uint8 i = 0; i < MAX_LOCK_CASE; ++i)
    {
        if (lock->Type[i] != LOCK_KEY_SKILL)
            continue;

        if (lock->Index[i] == LOCKTYPE_TREASURE)
            return true;
    }

    return false;
}

GameObject::DoAggroWhenOpening.body:
void GameObject::DoAggroWhenOpening(Unit* user) const
{
    if (!CanAggroWhenOpening())
        return;

    std::list<Creature*> targets;
    MaNGOS::AnyHostileUnitInObjectRangeCheck check(this, user, 10.0f);
    MaNGOS::CreatureListSearcher<MaNGOS::AnyHostileUnitInObjectRangeCheck> searcher(targets, check);
    Cell::VisitAllObjects(this, searcher, 10.0f);
    for (Creature* attacker : targets)
    {
        if (!attacker->HasUnitState(UNIT_STATE_CAN_NOT_REACT_OR_LOST_CONTROL) &&
            !attacker->GetCharmerGuid().IsPlayer() && !attacker->GetOwnerGuid().IsPlayer() &&
            attacker->IsValidAttackTarget(user) && attacker->IsWithinLOSInMap(user))
            attacker->EnterCombatWithTarget(user);
    }
}

AddItemsSetItem.body:
void AddItemsSetItem(Player* player, Item* item)
{
    ItemPrototype const* proto = item->GetProto();
    uint32 setid = proto->ItemSet;

    ItemSetEntry const* set = sItemSetStore.LookupEntry(setid);

    if (!set)
    {
        sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "Item set %u for item (id %u) not found, mods not applied.", setid, proto->ItemId);
        return;
    }

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_6_1
    if (set->required_skill_id && player->GetSkillValue(set->required_skill_id) < set->required_skill_value)
        return;
#endif

    ItemSetEffect* eff = player->GetItemSetEffect(setid);

    if (!eff)
        eff = player->AddItemSetEffect(setid);

    ++eff->item_count;

    for (uint32 x = 0; x < 8; x++)
    {
        if (!set->spells[x])
            continue;
        // not enough for  spell
        if (set->items_to_triggerspell[x] > eff->item_count)
            continue;

        uint32 z = 0;
        for (; z < 8; z++)
            if (eff->spells[z] && eff->spells[z]->Id == set->spells[x])
                break;

        if (z < 8)
            continue;

        // new spell
        for (auto& spell : eff->spells)
        {
            if (!spell)                             // free slot
            {
                SpellEntry const* spellInfo = sSpellMgr.GetSpellEntry(set->spells[x]);
                if (!spellInfo)
                {
                    sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "WORLD: unknown spell id %u in items set %u effects", set->spells[x], setid);
                    break;
                }

                // spell casted only if fit form requirement, in other case will casted at form change
                player->ApplyEquipSpell(spellInfo, nullptr, true);
                spell = spellInfo;
                break;
            }
        }
    }
}

RemoveItemsSetItem.body:
void RemoveItemsSetItem(Player* player, ItemPrototype const* proto)
{
    uint32 setid = proto->ItemSet;

    ItemSetEntry const* set = sItemSetStore.LookupEntry(setid);

    if (!set)
    {
        sLog.Out(LOG_DBERROR, LOG_LVL_MINIMAL, "Item set #%u for item #%u not found, mods not removed.", setid, proto->ItemId);
        return;
    }

    ItemSetEffect* eff = player->GetItemSetEffect(setid);

    // can be in case now enough skill requirement for set appling but set has been appliend when skill requirement not enough
    if (!eff)
        return;

    --eff->item_count;

    for (uint32 x = 0; x < 8; x++)
    {
        if (!set->spells[x])
            continue;

        // enough for spell
        if (set->items_to_triggerspell[x] <= eff->item_count)
            continue;

        for (auto& spell : eff->spells)
        {
            if (spell && spell->Id == set->spells[x])
            {
                // spell can be not active if not fit form requirement
                player->ApplyEquipSpell(spell, nullptr, false);
                spell = nullptr;
                break;
            }
        }
    }

    if (!eff->item_count)                                    // all items of a set were removed
        player->RemoveItemSetEffect(setid);
}

ItemCanGoIntoBag.body:
bool ItemCanGoIntoBag(ItemPrototype const* pProto, ItemPrototype const* pBagProto)
{
    if (!pProto || !pBagProto)
        return false;

    switch (pBagProto->Class)
    {
        case ITEM_CLASS_CONTAINER:
            switch (pBagProto->SubClass)
            {
                case ITEM_SUBCLASS_CONTAINER:
                    return true;
                case ITEM_SUBCLASS_SOUL_CONTAINER:
                    if (pProto->BagFamily != BAG_FAMILY_SOUL_SHARDS)
                        return false;
                    return true;
                case ITEM_SUBCLASS_HERB_CONTAINER:
                    if (pProto->BagFamily != BAG_FAMILY_HERBS)
                        return false;
                    return true;
                case ITEM_SUBCLASS_ENCHANTING_CONTAINER:
                    if (pProto->BagFamily != BAG_FAMILY_ENCHANTING_SUPP)
                        return false;
                    return true;
            }
            return false;
        case ITEM_CLASS_QUIVER:
            switch (pBagProto->SubClass)
            {
                case ITEM_SUBCLASS_QUIVER:
                    if (pProto->BagFamily != BAG_FAMILY_ARROWS)
                        return false;
                    return true;
                case ITEM_SUBCLASS_AMMO_POUCH:
                    if (pProto->BagFamily != BAG_FAMILY_BULLETS)
                        return false;
                    return true;
                default:
                    return false;
            }
    }
    return false;
}

