    if (slot < MAX_INSPECTED_ENCHANTMENT_SLOT && sendToClient)
    {
        if (Player* owner = GetOwner())
            owner->SendEnchantmentLog(ObjectGuid(), GetEntry(), GetEnchantmentId(slot));
