bool WorldObject::HasInArc(float const arcangle, float const x, float const y) const
{
    // always have self in arc
    if (x == m_position.x && y == m_position.y)
        return true;

    if (arcangle <= 0.0f)
        return false;
    if (arcangle >= 2.0f * M_PI_F)
        return true;

    float angle = GetAngle(x, y);
    angle -= m_position.o;

    // move angle to range -pi ... +pi
    angle = Geometry::NormalizeOrientation(angle);
    if (angle > M_PI_F)
        angle -= 2.0f * M_PI_F;

    float const halfArc = arcangle * 0.5f;
    return std::abs(angle) <= halfArc;
}

src/game/Objects/Object.cpp:1916:WorldOb.body:
bool WorldObject::HasInArc(WorldObject const* target, float const arcangle, float offset) const
{
    // always have self in arc
    if (target == this)
        return true;

    if (arcangle <= 0.0f)
        return false;
    if (arcangle >= 2.0f * M_PI_F)
        return true;

    float angle = GetAngle(target);
    angle -= m_position.o + offset;

    // move angle to range -pi ... +pi
    angle = Geometry::NormalizeOrientation(angle);
    if (angle > M_PI_F)
        angle -= 2.0f * M_PI_F;

    float const halfArc = arcangle * 0.5f;
    return std::abs(angle) <= halfArc;
}

