Player::_RemoveAllItemMods.body:
void Player::_RemoveAllItemMods()
{
    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "_RemoveAllItemMods start.");

    for (int i = 0; i < INVENTORY_SLOT_BAG_END; ++i)
    {
        if (m_items[i])
        {
            ItemPrototype const* proto = m_items[i]->GetProto();
            if (!proto)
                continue;

            // item set bonuses not dependent from item broken state
            if (proto->ItemSet)
                RemoveItemsSetItem(this, proto);

            if (m_items[i]->IsBroken())
                continue;

            ApplyItemEquipSpell(m_items[i], false);
            ApplyEnchantment(m_items[i], false);
        }
    }

    for (int i = 0; i < INVENTORY_SLOT_BAG_END; ++i)
    {
        if (m_items[i])
        {
            if (m_items[i]->IsBroken())
                continue;
            ItemPrototype const* proto = m_items[i]->GetProto();
            if (!proto)
                continue;

            uint32 attackType = Player::GetAttackBySlot(i);
            if (attackType < MAX_ATTACK)
                _ApplyWeaponDependentAuraMods(m_items[i], WeaponAttackType(attackType), false);

            _ApplyItemBonuses(proto, i, false);

            if (i == EQUIPMENT_SLOT_RANGED)
                _ApplyAmmoBonuses();
        }
    }

    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "_RemoveAllItemMods complete.");
}

Player::_ApplyAllItemMods.body:
void Player::_ApplyAllItemMods()
{
    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "_ApplyAllItemMods start.");

    for (int i = 0; i < INVENTORY_SLOT_BAG_END; ++i)
    {
        if (m_items[i])
        {
            if (m_items[i]->IsBroken())
                continue;

            ItemPrototype const* proto = m_items[i]->GetProto();
            if (!proto)
                continue;

            uint32 attackType = Player::GetAttackBySlot(i);
            if (attackType < MAX_ATTACK)
                _ApplyWeaponDependentAuraMods(m_items[i], WeaponAttackType(attackType), true);

            _ApplyItemBonuses(proto, i, true);

            if (i == EQUIPMENT_SLOT_RANGED)
                _ApplyAmmoBonuses();
        }
    }

    for (int i = 0; i < INVENTORY_SLOT_BAG_END; ++i)
    {
        if (m_items[i])
        {
            ItemPrototype const* proto = m_items[i]->GetProto();
            if (!proto)
                continue;

            // item set bonuses not dependent from item broken state
            if (proto->ItemSet)
                AddItemsSetItem(this, m_items[i]);

            if (m_items[i]->IsBroken())
                continue;

            ApplyItemEquipSpell(m_items[i], true);
            ApplyEnchantment(m_items[i], true);
        }
    }

    sLog.Out(LOG_BASIC, LOG_LVL_DEBUG, "_ApplyAllItemMods complete.");
}

Player::_ApplyAmmoBonuses.body:
void Player::_ApplyAmmoBonuses()
{
    // check ammo
    uint32 ammoId = GetUInt32Value(PLAYER_AMMO_ID);
    if (!ammoId)
        return;

    float currentAmmoDPS;

    ItemPrototype const* ammo_proto = sObjectMgr.GetItemPrototype(ammoId);
    if (!ammo_proto || ammo_proto->Class != ITEM_CLASS_PROJECTILE || !CheckAmmoCompatibility(ammo_proto))
        currentAmmoDPS = 0.0f;
    else
        currentAmmoDPS = (ammo_proto->Damage[0].DamageMin + ammo_proto->Damage[0].DamageMax) / 2.0f;

    if (currentAmmoDPS == GetAmmoDPS())
        return;

    m_ammoDPS = currentAmmoDPS;

    if (CanModifyStats())
        UpdateDamagePhysical(RANGED_ATTACK);
}

Player::CheckAmmoCompatibility.body:
bool Player::CheckAmmoCompatibility(ItemPrototype const* ammo_proto) const
{
    if (!ammo_proto)
        return false;

    // check ranged weapon
    Item* weapon = GetWeaponForAttack(RANGED_ATTACK, true, false);
    if (!weapon)
        return false;

    ItemPrototype const* weapon_proto = weapon->GetProto();
    if (!weapon_proto || weapon_proto->Class != ITEM_CLASS_WEAPON)
        return false;

    // check ammo ws. weapon compatibility
    switch (weapon_proto->SubClass)
    {
        case ITEM_SUBCLASS_WEAPON_BOW:
        case ITEM_SUBCLASS_WEAPON_CROSSBOW:
            if (ammo_proto->SubClass != ITEM_SUBCLASS_ARROW)
                return false;
            break;
        case ITEM_SUBCLASS_WEAPON_GUN:
            if (ammo_proto->SubClass != ITEM_SUBCLASS_BULLET)
                return false;
            break;
        default:
            return false;
    }

    return true;
}

Player::RemovedInsignia.body:
void Player::RemovedInsignia(Player* looterPlr, Corpse* corpse)
{
    if (!GetBattleGroundId())
        return;

    // If not released spirit, do it !
    if (GetDeathState() != DEAD)
    {
        BuildPlayerRepop();
        ScheduleRepopAtGraveyard();
    }

    if (!corpse)
        corpse = GetCorpse();
    if (!corpse)
        return;

    WorldPacket data(SMSG_PLAYER_SKINNED,1);
    data << uint8(0);
    GetSession()->SendPacket(&data);

    sObjectAccessor.ConvertCorpseForPlayer(GetObjectGuid(), looterPlr);
}

