Player::HasInstantCastingSpellMod.body:
bool Player::HasInstantCastingSpellMod(SpellEntry const* spellInfo) const
{
    for (const auto& mod : m_spellMods[SPELLMOD_CASTING_TIME])
    {
        if ((mod->type == SPELLMOD_PCT) && (mod->value <= -100) && mod->IsAffectedOnSpell(spellInfo))
            return true;
    }
    return false;
}

Player::IsAffectedBySpellmod.body:
bool Player::IsAffectedBySpellmod(SpellEntry const* spellInfo, SpellModifier const* mod, Spell const* spell) const
{
    if (!mod || !spellInfo)
        return false;

    // Mod out of charges
    if (spell)
    {
        std::list<SpellModifier*>::const_iterator iterMod = spell->m_appliedMods.cbegin();
        while (iterMod != spell->m_appliedMods.cend() && (*iterMod) != mod)
            ++iterMod;
        if (mod->charges == -1 && iterMod == spell->m_appliedMods.cend())
            return false;
    }

    return mod->IsAffectedOnSpell(spellInfo);
}

Player::AddSpellMod.body:
void Player::AddSpellMod(SpellModifier* mod, bool apply)
{
    ASSERT(mod);

    if (apply)
        m_spellMods[mod->op].push_back(mod);
    else
        m_spellMods[mod->op].remove(mod);

    SendSpellMod(mod);

    if (!apply)
        delete mod;
}

Player::SendSpellMod.body:
void Player::SendSpellMod(SpellModifier const* mod) const
{
    uint16 Opcode = (mod->type == SPELLMOD_FLAT) ? SMSG_SET_FLAT_SPELL_MODIFIER : SMSG_SET_PCT_SPELL_MODIFIER;

    for (int eff = 0; eff < 64; ++eff)
    {
        uint64 _mask = uint64(1) << eff;
        if (!!(mod->mask & _mask))
        {
            int32 val = 0;
            for (SpellModList::const_iterator itr = m_spellMods[mod->op].begin(); itr != m_spellMods[mod->op].end(); ++itr)
            {
                if ((*itr)->type == mod->type && !!((*itr)->mask & _mask))
                    val += (*itr)->value;
            }
            WorldPacket data(Opcode, (1 + 1 + 4));
            data << uint8(eff);
            data << uint8(mod->op);
            data << int32(val);
            SendDirectMessage(&data);
        }
    }
}

