{
    BattleGround* bg = sBattleGroundMgr.GetBattleGroundTemplate(bgTypeId);
    ASSERT(bg);

    if (level < bg->GetMinLevel())
        return BG_BRACKET_ID_NONE;

    uint32 bracket_id = (level - bg->GetMinLevel()) / 10;
    if (bracket_id > MAX_BATTLEGROUND_BRACKETS)
        return BG_BRACKET_ID_LAST;

    return BattleGroundBracketId(bracket_id);
}

Player::GetReputationPriceDiscount.body:
float Player::GetReputationPriceDiscount(Creature const* pCreature, bool taxi) const
{
    uint32 factionId = pCreature->GetFactionId();
    if (!factionId)
        return 1.0f;

    float mod = 1.0f;
    ReputationRank rank = GetReputationRank(factionId);
    if (rank >= REP_HONORED)
        mod -= 0.1f;

    switch (factionId)
    {
        // Alliance
        case 72:  // Stormwind
        case 47:  // Ironforge
        case 54:  // Gnomeregan
        case 69:  // Darnassus
        case 730: // Stormpike Guard
        // Horde
        case 68:  // Undercity
        case 76:  // Orgrimmar
        case 81:  // Thunder Bluff
        case 530: // Darkspear
        case 729: // Frostwolf Clan
        {
            // honor rank >= 3
            if (!taxi && m_honorMgr.GetRank().visualRank >= 3)
                mod -= 0.1f;

            if (taxi && m_honorMgr.GetRank().visualRank >= 2)
            {
                mod -= 0.05f;
                if (m_honorMgr.GetRank().visualRank >= 4)
                    mod -= 0.05f;
            }
            break;
        }
    }

    return mod;
}

Player::IsSpellFitByClassAndRace.body:
bool Player::IsSpellFitByClassAndRace(uint32 spellId, uint32* pReqlevel /*= nullptr*/) const
{
    uint32 racemask  = GetRaceMask();
    uint32 classmask = GetClassMask();

    SkillLineAbilityMapBounds bounds = sSpellMgr.GetSkillLineAbilityMapBoundsBySpellId(spellId);
    if (bounds.first == bounds.second)
        return true;

    for (SkillLineAbilityMap::const_iterator _spell_idx = bounds.first; _spell_idx != bounds.second; ++_spell_idx)
    {
        SkillLineAbilityEntry const* abilityEntry = _spell_idx->second;
        // skip wrong race skills
        if (abilityEntry->racemask && (abilityEntry->racemask & racemask) == 0)
            continue;

        // skip wrong class skills
        if (abilityEntry->classmask && (abilityEntry->classmask & classmask) == 0)
            continue;

        SkillRaceClassInfoMapBounds bounds = sSpellMgr.GetSkillRaceClassInfoMapBounds(abilityEntry->skillId);
        for (SkillRaceClassInfoMap::const_iterator itr = bounds.first; itr != bounds.second; ++itr)
        {
            SkillRaceClassInfoEntry const* skillRCEntry = itr->second;
            if ((skillRCEntry->raceMask & racemask) && (skillRCEntry->classMask & classmask))
            {
                if (skillRCEntry->flags & ABILITY_SKILL_NONTRAINABLE)
                    return false;

                if (pReqlevel)                              // show trainers list case
                {
                    if (skillRCEntry->reqLevel)
                    {
                        *pReqlevel = skillRCEntry->reqLevel;
                        return true;
                    }
                }
                else                                        // check availble case at train
                {
                    if (skillRCEntry->reqLevel && GetLevel() < skillRCEntry->reqLevel)
                        return false;
                }
            }
        }

        return true;
    }

    return false;
}

Player::HasQuestForGO.body:
bool Player::HasQuestForGO(int32 GOId) const
{
    for (int i = 0; i < MAX_QUEST_LOG_SIZE; ++i)
    {
        uint32 questid = GetQuestSlotQuestId(i);
        if (questid == 0)
            continue;

        QuestStatusMap::const_iterator qs_itr = mQuestStatus.find(questid);
        if (qs_itr == mQuestStatus.end())
            continue;

        QuestStatusData const& qs = qs_itr->second;

        if (qs.m_status == QUEST_STATUS_INCOMPLETE)
        {
            Quest const* qinfo = sObjectMgr.GetQuestTemplate(questid);
            if (!qinfo)
                continue;

            if (GetGroup() && GetGroup()->isRaidGroup() && !qinfo->IsAllowedInRaid())
                continue;

            for (int j = 0; j < QUEST_OBJECTIVES_COUNT; ++j)
            {
                if (qinfo->ReqCreatureOrGOId[j] >= 0)       //skip non GO case
                    continue;

                if ((-1)*GOId == qinfo->ReqCreatureOrGOId[j] && qs.m_creatureOrGOcount[j] < qinfo->ReqCreatureOrGOCount[j])
                    return true;
            }
        }
    }
    return false;
}

Player::UpdateForQuestWorldObjects.body:
void Player::UpdateForQuestWorldObjects()
{
    // Don't process updates if we're not in the world (map is nullptr)
    if (!IsInWorld() || !FindMap())
        return;

    UpdateData updateData;
    std::shared_lock<std::shared_timed_mutex> lock(m_visibleGUIDs_lock);
    for (const auto& guid : m_visibleGUIDs)
    {
        if (guid.IsGameObject())
        {
            if (GameObject* obj = GetMap()->GetGameObject(guid))
            {
                if (!obj->IsTransport())
                {
                    if (m_visibleGobjQuestActivated[obj->GetObjectGuid()] != obj->ActivateToQuest(this))
                        obj->BuildValuesUpdateBlockForPlayerWithFlags(updateData, this, UF_FLAG_DYNAMIC, true);
                }
            }
        }
    }
    lock.unlock();
    if (updateData.HasData())
        updateData.Send(GetSession());
}

