void TemporarySummon::InformSummonerOfDespawn()
{
    if (m_unSummonInformed)
        return;

    m_unSummonInformed = true;
    if (WorldObject* pSummoner = GetMap()->GetWorldObject(GetSummonerGuid()))
    {
        pSummoner->DecrementSummonCounter();

        if (Creature* cOwner = pSummoner->ToCreature())
            if (cOwner->AI())
                cOwner->AI()->SummonedCreatureDespawn(this);
    }
}

Totem::Create.body:
bool Totem::Create(uint32 guidlow, CreatureCreatePos& cPos, CreatureInfo const* cinfo, Unit* owner)
{
    SetMap(cPos.GetMap());

    if (!CreateFromProto(guidlow, cinfo, cinfo->entry))
        return false;

    cPos.SelectFinalPoint(this);

    // totem must be at same Z in case swimming caster and etc.
    if (fabs(cPos.m_pos.z - owner->GetPositionZ()) > 5.0f)
        cPos.m_pos.z = owner->GetPositionZ();

    if (!cPos.Relocate(this))
        return false;

    //Notify the map's instance data.
    //Only works if you create the object in it, not if it is moves to that map.
    //Normally non-players do not teleport to other maps.
    if (InstanceData* iData = GetMap()->GetInstanceData())
        iData->OnCreatureCreate(this);

    LoadCreatureAddon();

    SetWalk(true, true);

    return true;
}

Totem::Update.body:
void Totem::Update(uint32 update_diff, uint32 time)
{
    Unit* owner = GetOwner();
    if (!owner || 
        // Don't unsummon if owner is a creature - let them persist after creature death
        (owner->GetTypeId() != TYPEID_UNIT && !owner->IsAlive()) || 
        !IsAlive() || 
        !IsWithinVisibilityDistanceOf(owner, owner))
    {
        UnSummon();                                         // remove self
        return;
    }

    if (GetMotionMaster()->GetCurrentMovementGeneratorType() != IDLE_MOTION_TYPE)
        GetMotionMaster()->MoveIdle();

    // Do final update before unsummon, or we lose ticks on the totem's spell
    Creature::Update(update_diff, time);

    if (m_duration <= update_diff)
    {
        UnSummon();                                         // remove self
        return;
    }

    m_duration -= update_diff;
}

Totem::Summon.body:
void Totem::Summon(Unit* owner)
{
    AIM_Initialize();
    owner->GetMap()->Add((Creature*)this);

    SendObjectSpawnAnim();

    if (owner->GetTypeId() == TYPEID_UNIT && ((Creature*)owner)->AI())
        ((Creature*)owner)->AI()->JustSummoned((Creature*)this);

    // there are some totems, which exist just for their visual appeareance
    if (!GetSpell())
        return;

    if (m_type==TOTEM_PASSIVE)
    {
        CastSpell(this, GetSpell(), true);
    }
}

Totem::UnSummon.body:
void Totem::UnSummon()
{
    SendObjectDeSpawnAnim();

    CombatStop();
    RemoveAurasDueToSpell(GetSpell());

    if (Unit* owner = GetOwner())
    {
        owner->_RemoveTotem(this);
        owner->RemoveAurasDueToSpell(GetSpell());

        //remove aura all party members too
        if (owner->GetTypeId() == TYPEID_PLAYER)
        {
            // Not only the player can summon the totem (scripted AI)
            if (Group* pGroup = ((Player*)owner)->GetGroup())
            {
                for (GroupReference* itr = pGroup->GetFirstMember(); itr != nullptr; itr = itr->next())
                {
                    Player* Target = itr->getSource();
                    if (Target && pGroup->SameSubGroup((Player*)owner, Target))
                        Target->RemoveAurasDueToSpell(GetSpell());
                }
            }
        }

        if (owner->GetTypeId() == TYPEID_UNIT && ((Creature*)owner)->AI())
            ((Creature*)owner)->AI()->SummonedCreatureDespawn((Creature*)this);
    }

    // any totem unsummon look like as totem kill, req. for proper animation
    if (IsAlive())
        SetDeathState(DEAD);

    AddObjectToRemoveList();
}

