void CharmInfo::SetSpellAutocast(uint32 spellId, bool state)
{
    for (auto& i : m_petActionBar)
    {
        if (spellId == i.GetAction() && i.IsActionBarForSpell())
        {
            i.SetType(state ? ACT_ENABLED : ACT_DISABLED);
            break;
        }
    }
}

