void Unit::ScheduleAINotify(uint32 delay)
{
    if (HasUnitState(UNIT_STATE_NO_BROADCAST_TO_OTHERS))
        return;

    if (!delay)
    {
        // Instant
        RelocationNotifyEvent event(*this);
        event.Execute(0, 0);
