bool Unit::IsImmuneToMechanic(Mechanics mechanic) const
{
    SpellImmuneList const& mechanicList = m_spellImmune[IMMUNITY_MECHANIC];
    for (const auto& itr : mechanicList)
        if (itr.type == mechanic)
            return true;

    return false;
}

