    if (!CanHaveThreatList() || GetThreatManager().isThreatListEmpty())
    {
        if (IsCreature())
            sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "DoResetThreat called for creature that either cannot have threat list or has empty threat list (entry = %d)", GetEntry());
        return;
