src/game/Objects/UpdateData.cpp:133:Upda.body:
bool UpdateData::BuildPacket(WorldPacket* packet, UpdatePacket const* updPacket, bool hasTransport)
{
    MANGOS_ASSERT(packet->empty());                         // shouldn't happen

    ByteBuffer buf(4 + 1 + (m_outOfRangeGUIDs.empty() ? 0 : 1 + 4 + 9 * m_outOfRangeGUIDs.size()) + (updPacket ? updPacket->data.wpos() : 0));

    uint32 blockCount = updPacket ? updPacket->blockCount : 0;
    buf << (uint32)(!m_outOfRangeGUIDs.empty() ? blockCount + 1 : blockCount);
    buf << (uint8)(hasTransport ? 1 : 0);

    if (!m_outOfRangeGUIDs.empty())
    {
        buf << (uint8) UPDATETYPE_OUT_OF_RANGE_OBJECTS;
        buf << (uint32) m_outOfRangeGUIDs.size();

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
        for (const auto& guid : m_outOfRangeGUIDs)
            buf << guid.WriteAsPacked();
#else
        for (const auto& guid : m_outOfRangeGUIDs)
            buf << guid;
#endif
    }

    if (updPacket)
        buf.append(updPacket->data);

    size_t pSize = buf.wpos();                              // use real used data size

    // compress large packets
    if (pSize > sWorld.getConfig(CONFIG_UINT32_COMPRESSION_UPDATE_SIZE))
    {
        if (pSize >= 900000)
            sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "[CRASH-CLIENT] Too large packet: %u", pSize);

        uint32 destsize = compressBound(pSize);
        packet->resize(destsize + sizeof(uint32));

        packet->put<uint32>(0, pSize);
        PacketCompressor::Compress(const_cast<uint8*>(packet->contents()) + sizeof(uint32), &destsize, (void*)buf.contents(), pSize);
        if (destsize == 0)
            return false;

        packet->resize(destsize + sizeof(uint32));
        packet->SetOpcode(SMSG_COMPRESSED_UPDATE_OBJECT);
    }
    else                                                    // send small packets without compression
    {
        packet->append(buf);
        packet->SetOpcode(SMSG_UPDATE_OBJECT);
    }

    return true;
}

UpdateData::Send.body:
void UpdateData::Send(WorldSession* session, bool hasTransport)
{
    WorldPacket data;
    if (m_datas.empty() && !m_outOfRangeGUIDs.empty())
    {
        BuildPacket(&data, nullptr, hasTransport);
        session->SendPacket(&data);
        m_outOfRangeGUIDs.clear();
        return;
    }
    for (const auto& itr : m_datas)
    {
        BuildPacket(&data, &itr, hasTransport);
        session->SendPacket(&data);
        data.clear();
        m_outOfRangeGUIDs.clear();
    }
}

MovementData::CanAddPacket.body:
bool MovementData::CanAddPacket(WorldPacket const& data)
{
    // Since packet size is stored with an uint8, packet size is limited for compressed packets
    if ((data.wpos() + 2) > 0xFF)
        return false;

    if ((m_buffer.wpos() + (data.wpos() + 2)) >= 900000)
        return false;

    return true;
}

MovementData::AddPacket.body:
void MovementData::AddPacket(WorldPacket const& data)
{
    ASSERT(data.wpos() + 2 <= 0xFF); // Max packet size to be stored on uint8. Client crash else.
    m_buffer << uint8(data.wpos() + 2); // Packet + opcode size
    m_buffer << uint16(data.GetOpcode());
    m_buffer.append(data.contents(), data.wpos());
}

MovementData::BuildPacket.body:
bool MovementData::BuildPacket(WorldPacket& packet)
{
    MANGOS_ASSERT(packet.empty()); // We want a clean packet !

    size_t pSize = m_buffer.wpos();                              // use real used data size

    if (pSize >= 900000)
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "[CRASH-CLIENT] Too large packet size %u (SMSG_COMPRESSED_MOVES)", pSize);

    uint32 destsize = compressBound(pSize);
    packet.resize(destsize + sizeof(uint32));
    packet.put<uint32>(0, pSize);
    PacketCompressor::Compress(const_cast<uint8*>(packet.contents()) + sizeof(uint32), &destsize, (void*)m_buffer.contents(), pSize);
    if (destsize == 0)
        return false;

    packet.resize(destsize + sizeof(uint32));
    packet.SetOpcode(SMSG_COMPRESSED_MOVES);
    return true;
}

SetupUpdateFieldFlagsArray.body:
static std::array<uint16, SIZE> SetupUpdateFieldFlagsArray(uint8 objectTypeMask)
{
    std::array<uint16, SIZE> flagsArray;
    for (auto const& itr : g_updateFieldsData)
    {
        if ((itr.objectTypeMask & objectTypeMask) == 0)
            continue;

        for (uint16 i = itr.offset; i < itr.offset + itr.size; i++)
        {
            flagsArray.at(i) = itr.flags;
        }
    }
    return flagsArray;
}

UpdateFields::GetUpdateFieldFlagsArray.body:
uint16 const* UpdateFields::GetUpdateFieldFlagsArray(uint8 objectTypeId)
{
    switch (objectTypeId)
    {
        case TYPEID_ITEM:
        case TYPEID_CONTAINER:
        {
            return g_containerUpdateFieldFlags.data();
        }
        case TYPEID_UNIT:
        case TYPEID_PLAYER:
        {
            return g_playerUpdateFieldFlags.data();
        }
        case TYPEID_GAMEOBJECT:
        {
            return g_gameObjectUpdateFieldFlags.data();
        }
        case TYPEID_DYNAMICOBJECT:
        {
            return g_dynamicObjectUpdateFieldFlags.data();
        }
        case TYPEID_CORPSE:
        {
            return g_corpseUpdateFieldFlags.data();
        }
    }
    sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Unhandled object type id (%hhu) in GetUpdateFieldFlagsArray!", objectTypeId);
    return 0;
}

UpdateFields::GetUpdateFieldDataByName.body:
UpdateFieldData const* UpdateFields::GetUpdateFieldDataByName(char const* name)
{
    for (const auto& itr : g_updateFieldsData)
    {
        if (strcmp(itr.name, name) == 0)
            return &itr;
    }
    return nullptr;
}

UpdateFields::GetUpdateFieldDataByTypeMa.body:
UpdateFieldData const* UpdateFields::GetUpdateFieldDataByTypeMaskAndOffset(uint8 objectTypeMask, uint16 offset)
{
    for (auto const& itr : g_updateFieldsData)
    {
        if ((itr.objectTypeMask & objectTypeMask) == 0)
            continue;

        if (offset == itr.offset || (offset > itr.offset && offset < (itr.offset + itr.size)))
            return &itr;
    }
    return nullptr;
}

OPvPCapturePointEP_EWT::ChangeState.body:
void OPvPCapturePointEP_EWT::ChangeState()
{
    // If changing from controlling alliance to horde or vice versa.
    if (m_oldState == OBJECTIVESTATE_ALLIANCE && m_oldState != m_state)
    {
        ((OutdoorPvPEP*)m_PvP)->EP_Controls[EASTWALL_TOWER] = 0;
    }
    else if (m_oldState == OBJECTIVESTATE_HORDE && m_oldState != m_state)
    {
        ((OutdoorPvPEP*)m_PvP)->EP_Controls[EASTWALL_TOWER] = 0;
    }

    DelCreature(EASTWALL_TOWER_BUFFER);
    DelObject(EASTWALL_TOWER_FLAG_FLARE);

    switch (m_state)
    {
        case OBJECTIVESTATE_ALLIANCE:
        {
            m_TowerState = TOWERSTATE_ALLIANCE;
            PlaySound(SOUND_PVPVICTORYALLIANCE);
            AddObject(EASTWALL_TOWER_FLAG_FLARE, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].entry, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].map, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].x, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].y, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].z, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].o, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].rot0, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].rot1, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].rot2, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_ALLIANCE].rot3);

            break;
        }
        case OBJECTIVESTATE_HORDE:
        {
            m_TowerState = TOWERSTATE_HORDE;
            PlaySound(SOUND_PVPVICTORYHORDE);
            AddObject(EASTWALL_TOWER_FLAG_FLARE, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].entry, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].map, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].x, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].y, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].z, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].o, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].rot0, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].rot1, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].rot2, EP_TowerFlares[FLAG_FLARE_EASTWALL_TOWER_HORDE].rot3);

            break;
        }
        case OBJECTIVESTATE_ALLIANCE_PROGRESSING:
        {
            UpdateBannerArt(ARTKIT_ALLIANCE, ANIMATION_ALLIANCE);

            if (m_oldState == OBJECTIVESTATE_ALLIANCE)
            {
                m_TowerState = TOWERSTATE_ALLIANCE_PROGRESSING;
                PlaySound(SOUND_PVPWARNINGALLIANCE);
            }
            else if (m_oldState <= OBJECTIVESTATE_HORDE_CONTESTED) // m_oldState was grey.
            {
                m_TowerState = TOWERSTATE_ALLIANCE_PROGRESSING;
                PlaySound(SOUND_PVPFLAGCAPTUREDALLIANCE);
                SummonSquadAtEastWallTower(ALLIANCE);
                AddCreature(EASTWALL_TOWER_BUFFER, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_ALLIANCE].entry, ALLIANCE, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_ALLIANCE].map, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_ALLIANCE].x, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_ALLIANCE].y, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_ALLIANCE].z, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_ALLIANCE].o);

                ((OutdoorPvPEP*)m_PvP)->EP_Controls[EASTWALL_TOWER] = ALLIANCE;

                if (m_oldState != m_state)
                    ((OutdoorPvPEP*)m_PvP)->GetMap()->SendDefenseMessage(BCT_EASTWALL_TOWER_ALLIANCE, EP_Zone);
            }
            break;
        }
        case OBJECTIVESTATE_HORDE_PROGRESSING:
        {
            UpdateBannerArt(ARTKIT_HORDE, ANIMATION_HORDE);

            if (m_oldState == OBJECTIVESTATE_HORDE)
            {
                m_TowerState = TOWERSTATE_HORDE_PROGRESSING;
                PlaySound(SOUND_PVPWARNINGHORDE);
            }
            else if (m_oldState <= OBJECTIVESTATE_HORDE_CONTESTED) // m_oldState was grey.
            {
                m_TowerState = TOWERSTATE_HORDE_PROGRESSING;
                PlaySound(SOUND_PVPFLAGCAPTUREDHORDE);
                SummonSquadAtEastWallTower(HORDE);
                AddCreature(EASTWALL_TOWER_BUFFER, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_HORDE].entry, HORDE, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_HORDE].map, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_HORDE].x, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_HORDE].y, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_HORDE].z, EP_BufferNPCs[TOWER_BUFFER_EASTWALL_TOWER_HORDE].o);

                ((OutdoorPvPEP*)m_PvP)->EP_Controls[EASTWALL_TOWER] = HORDE;

                if (m_oldState != m_state)
                    ((OutdoorPvPEP*)m_PvP)->GetMap()->SendDefenseMessage(BCT_EASTWALL_TOWER_HORDE, EP_Zone);
            }
            break;
        }
        case OBJECTIVESTATE_NEUTRAL:
        {
            m_TowerState = TOWERSTATE_NEUTRAL;
            UpdateBannerArt(ARTKIT_NEUTRAL, ANIMATION_NEUTRAL);
            RemoveSquad();

            break;
        }
        case OBJECTIVESTATE_ALLIANCE_CONTESTED:
        {
            m_TowerState = TOWERSTATE_ALLIANCE_CONTESTED;
            UpdateBannerArt(ARTKIT_NEUTRAL, ANIMATION_NEUTRAL);
            RemoveSquad();

            break;
        }
        case OBJECTIVESTATE_HORDE_CONTESTED:
        {
            m_TowerState = TOWERSTATE_HORDE_CONTESTED;
            UpdateBannerArt(ARTKIT_NEUTRAL, ANIMATION_NEUTRAL);
            RemoveSquad();

            break;
        }
    }

    if (Creature* pCreature = m_PvP->GetCreature(m_Creatures[EASTWALL_TOWER_BUFFER]))
    {
        pCreature->CastSpell(pCreature, SPELL_TOWER_CAPTURE_TEST_DND, false);
    }

    UpdateTowerState();
}

