ChatHandler::HandlePBCastStatsCommand.body:
bool ChatHandler::HandlePBCastStatsCommand(char*)
{
    MovementBroadcaster* bcaster = sWorld.GetBroadcaster();
    auto const& stats = bcaster->GetStats();
    PSendSysMessage("PacketBroadcast: %u threads.", stats.size());
    for (int i = 0; i < stats.size(); ++i)
        PSendSysMessage("Thread #%02u: Update %03ums | %u packets",
            i, stats[i].update_time, stats[i].num_packets);
    PSendSysMessage("Created %u broadcasters | Deleted %u",
        PlayerBroadcaster::num_bcaster_created, PlayerBroadcaster::num_bcaster_deleted);
    return true;
}

ChatHandler::HandlePBCastSetThreadsComma.body:
bool ChatHandler::HandlePBCastSetThreadsCommand(char* args)
{
    MovementBroadcaster* bcaster = sWorld.GetBroadcaster();
    std::size_t num_threads_before = bcaster->GetNumThreads();
    uint32 num_threads_after;
    if (!ExtractUInt32(&args, num_threads_after))
        return false;

    if (num_threads_after > 50)
    {
        PSendSysMessage("PacketBroadcast: Please decrease the thread count (< 50)");
        return false;
    }

    if (!num_threads_after)
        PSendSysMessage("PacketBroadcast: Disabling broadcaster...");
    else
        PSendSysMessage("PacketBroadcast: Changing num of threads from %u to %u...",
            num_threads_before, num_threads_after);

    bcaster->UpdateConfiguration(num_threads_after, bcaster->GetSleepTimer());
    SendSysMessage(".. done!");
    return true;
}

MovementBroadcaster::IsEnabled.body:
bool MovementBroadcaster::IsEnabled()
{
    return (bool)m_num_threads; // explicit cast to shut msvc's warnings up
}

MovementBroadcaster::StartThreads.body:
void MovementBroadcaster::StartThreads()
{
    ASSERT(m_threads.empty());

    // Create new mutex vector - can't resize a vector of locks (non-copyable)
    std::vector<std::shared_timed_mutex> locks(m_num_threads);
    m_thread_locks = std::move(locks);
    m_thread_players.resize(m_num_threads);
    m_thread_update_stats.resize(m_num_threads);

    m_stop = false;

    // start the workers
    for(std::size_t i = 0; i < m_num_threads; ++i)
        m_threads.emplace_back(&MovementBroadcaster::Work, this, i);

}

MovementBroadcaster::RegisterPlayer.body:
void MovementBroadcaster::RegisterPlayer(std::shared_ptr<PlayerBroadcaster> const& player)
{
    if (!m_num_threads)
        return;

    std::size_t index = player->GetGUID().GetRawValue() % m_num_threads;
    std::lock_guard<std::shared_timed_mutex> guard(m_thread_locks[index]);
    m_thread_players[index].insert(player);
}

MovementBroadcaster::RemovePlayer.body:
void MovementBroadcaster::RemovePlayer(std::shared_ptr<PlayerBroadcaster> const& player)
{
    if (!m_num_threads)
        return;

    std::size_t index = player->GetGUID().GetRawValue() % m_num_threads;
    std::lock_guard<std::shared_timed_mutex> guard(m_thread_locks[index]);
    auto it = m_thread_players[index].find(player);

    if (it != m_thread_players[index].end())
        m_thread_players[index].erase(it);
}

MovementBroadcaster::Work.body:
void MovementBroadcaster::Work(std::size_t thread_id)
{
    while (!m_stop)
    {
        ThreadUpdateStats& stats = m_thread_update_stats[thread_id];
        uint32 num_packets = 0;
        uint32 begin_time = WorldTimer::getMSTime();
        BroadcastPackets(thread_id, num_packets);
        stats.num_packets = num_packets;
        stats.update_time = WorldTimer::getMSTimeDiffToNow(begin_time);

        if (sWorld.getConfig(CONFIG_UINT32_PERFLOG_SLOW_PACKET_BCAST) &&
            stats.update_time > sWorld.getConfig(CONFIG_UINT32_PERFLOG_SLOW_PACKET_BCAST))
            sLog.Out(LOG_PERFORMANCE, LOG_LVL_MINIMAL, "MovementBroadcaster thread %02u: %04ums to process queue [%u packets]",
                thread_id, stats.update_time, num_packets);

        if (sWorld.getConfig(CONFIG_UINT32_PBCAST_DIFF_LOWER_VISIBILITY_DISTANCE) &&
            stats.update_time > sWorld.getConfig(CONFIG_UINT32_PBCAST_DIFF_LOWER_VISIBILITY_DISTANCE))
            IdentifySlowMap(thread_id);
        else
            stats.slow_instance = -1;

        std::this_thread::sleep_for(m_sleep_timer);
    }
}

MovementBroadcaster::IdentifySlowMap.body:
uint32 MovementBroadcaster::IdentifySlowMap(std::size_t thread_id)
{
    std::map<uint32 /* instanceId */, uint32 /* numPackets */> map_packets;

    std::shared_lock<std::shared_timed_mutex> guard(m_thread_locks[thread_id]);

    for (auto& player : m_thread_players[thread_id])
        map_packets[player->instanceId] += player->lastUpdatePackets;

    uint32 max_number_packets = 0;
    uint32 max_instance_id = 0;
    for (auto it = map_packets.begin(); it != map_packets.end(); ++it)
        if (it->second > max_number_packets)
        {
            max_instance_id = it->first;
            max_number_packets = it->second;
        }
    return max_instance_id;
}

MovementBroadcaster::BroadcastPackets.body:
void MovementBroadcaster::BroadcastPackets(std::size_t index, uint32& num_packets)
{
    PlayersBCastSet my_players;
    {
        std::shared_lock<std::shared_timed_mutex> guard(m_thread_locks[index]);
        my_players = m_thread_players[index];
    }

    for (auto& player : my_players)
        player->ProcessQueue(num_packets);
}

MovementBroadcaster::Stop.body:
void MovementBroadcaster::Stop()
{
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "[NETWORK] Stopping movement broadcaster...");

    m_stop = true;

    for (auto& thread : m_threads)
    {
        if (thread.joinable())
            thread.join();
    }
    m_threads.clear();
}

MovementBroadcaster::UpdateConfiguration.body:
void MovementBroadcaster::UpdateConfiguration(std::size_t new_threads_count, std::chrono::milliseconds new_frequency)
{
    m_sleep_timer = new_frequency;

    if (m_num_threads == new_threads_count)
        return;

    std::size_t old_num_threads = m_num_threads;
    uint32 begin_time = WorldTimer::getMSTime();

    Stop();
    m_num_threads = new_threads_count;

    StartThreads();

    // Reregister all players
    auto const& sessions = sWorld.GetAllSessions();

    for (auto& session : sessions)
    {
        Player* player = session.second->GetPlayer();
        if (!player)
            continue;

        auto broadcaster = player->GetPacketBroadcaster();

        if (broadcaster)
            RegisterPlayer(broadcaster);
    }

    sLog.Out(LOG_PERFORMANCE, LOG_LVL_MINIMAL, "[MovementBroadcaster] Changing number of threads from %u to %u in %ums",
        old_num_threads, new_threads_count, WorldTimer::getMSTimeDiffToNow(begin_time));
}

MovementBroadcaster::IsMapSlow.body:
bool MovementBroadcaster::IsMapSlow(uint32 instanceId)
{
    for (auto& stat : m_thread_update_stats)
        if (stat.slow_instance == instanceId)
        {
            stat.slow_instance = -1;
            return true;
        }
    return false;
}

PlayerBroadcaster::AddListener.body:
void PlayerBroadcaster::AddListener(Player const* player)
{
    ASSERT(player);
    if (player->GetObjectGuid() == m_self)
        return;

    std::lock_guard<std::mutex> guard(m_listeners_lock);
    m_listeners[player->GetObjectGuid()] = player->m_broadcaster;
}

PlayerBroadcaster::RemoveListener.body:
void PlayerBroadcaster::RemoveListener(Player const* player)
{
    ASSERT(player);
    std::lock_guard<std::mutex> guard(m_listeners_lock);
    m_listeners.erase(player->GetObjectGuid());
}

PlayerBroadcaster::SendPacket.body:
void PlayerBroadcaster::SendPacket(WorldPacket const& packet)
{
    if (m_socket)
        m_socket->SendPacket(packet);
}

PlayerBroadcaster::ProcessQueue.body:
void PlayerBroadcaster::ProcessQueue(uint32& num_packets)
{
    if (m_queue.empty())
        return;

    std::unique_lock<std::mutex> q_g(m_queue_lock), v_g(m_listeners_lock);
    auto queue = std::move(m_queue);
    q_g.unlock();

    lastUpdatePackets = queue.size() * m_listeners.size();
    num_packets += lastUpdatePackets;

    for (auto& data : queue)
    {
        // Send to self?
        if (data.sendToSelf && data.except != GetGUID())
            SendPacket(data.packet);

        for (auto it = m_listeners.begin(); it != m_listeners.end(); ++it)
        {
            if (it->first == data.except)
                continue;

            it->second->SendPacket(data.packet);
        }
    }
}

PlayerBroadcaster::QueuePacket.body:
void PlayerBroadcaster::QueuePacket(WorldPacket packet, bool self, ObjectGuid except)
{
    BroadcastData data;
    data.packet = std::move(packet);
    data.sendToSelf = self;
    data.except = except;

    std::unique_lock<std::mutex> guard(m_queue_lock, std::defer_lock);

    guard.lock();

    // We need to drop a packet here - if possible
    if (m_queue.size() >= MAX_QUEUE_SIZE)
    {
        BroadcastData& last_in_queue = m_queue[m_queue.size() - 1];
        if (CanSkipPacket(last_in_queue.packet.GetOpcode()) && CanSkipPacket(packet.GetOpcode()))
        {
            m_queue[m_queue.size() - 1] = std::move(data);
            guard.unlock();
            return;
        }
    }
    m_queue.emplace_back(std::move(data));

    guard.unlock();
}

PlayerBroadcaster::FreeAtLogout.body:
void PlayerBroadcaster::FreeAtLogout()
{
    m_socket = nullptr;
    std::unique_lock<std::mutex> q_g(m_queue_lock), v_g(m_listeners_lock);
    m_queue.clear();
    m_listeners.clear();
}

AiBotAI::GetMountSpellId.body:
uint32 AiBotAI::GetMountSpellId() const
{
    if (me->GetLevel() >= 60)
    {
        if (me->GetClass() == CLASS_PALADIN)
            return AB_SPELL_MOUNT_60_PALADIN;
        if (me->GetClass() == CLASS_WARLOCK)
            return AB_SPELL_MOUNT_60_WARLOCK;

        switch (me->GetRace())
        {
            case RACE_HUMAN:    return AB_SPELL_MOUNT_60_HUMAN;
            case RACE_NIGHTELF: return AB_SPELL_MOUNT_60_NELF;
            case RACE_DWARF:    return AB_SPELL_MOUNT_60_DWARF;
            case RACE_GNOME:    return AB_SPELL_MOUNT_60_GNOME;
            case RACE_TROLL:    return AB_SPELL_MOUNT_60_TROLL;
            case RACE_ORC:      return AB_SPELL_MOUNT_60_ORC;
            case RACE_TAUREN:   return AB_SPELL_MOUNT_60_TAUREN;
            case RACE_UNDEAD:   return AB_SPELL_MOUNT_60_UNDEAD;
        }
    }
    else if (me->GetLevel() >= 40)
    {
        if (me->GetClass() == CLASS_PALADIN)
            return AB_SPELL_MOUNT_40_PALADIN;
        if (me->GetClass() == CLASS_WARLOCK)
            return AB_SPELL_MOUNT_40_WARLOCK;

        switch (me->GetRace())
        {
            case RACE_HUMAN:    return AB_SPELL_MOUNT_40_HUMAN;
            case RACE_NIGHTELF: return AB_SPELL_MOUNT_40_NELF;
            case RACE_DWARF:    return AB_SPELL_MOUNT_40_DWARF;
            case RACE_GNOME:    return AB_SPELL_MOUNT_40_GNOME;
            case RACE_TROLL:    return AB_SPELL_MOUNT_40_TROLL;
            case RACE_ORC:      return AB_SPELL_MOUNT_40_ORC;
            case RACE_TAUREN:   return AB_SPELL_MOUNT_40_TAUREN;
            case RACE_UNDEAD:   return AB_SPELL_MOUNT_40_UNDEAD;
        }
    }

    return 0;
}

AiBotAI::UseMount.body:
bool AiBotAI::UseMount()
{
    if (me->IsMounted())
        return false;

    if (me->IsMoving())
        return false;

    if (me->GetDisplayId() != me->GetNativeDisplayId())
        return false;

    if (me->GetClass() == CLASS_ROGUE)
        return false;

    if (me->HasAura(SPELL_AURA_MOD_STEALTH))
        return false;

    uint32 spellId = GetMountSpellId();
    if (!spellId)
        return false;

    if (me->CastSpell(me, spellId, false) == SPELL_CAST_OK)
        return true;

    return false;
}

AiBotAI::DrinkAndEat.body:
bool AiBotAI::DrinkAndEat()
{
    if (m_isBuffing)
        return false;

    if (me->IsMounted())
        return false;

    if (me->GetVictim())
        return false;

    bool const needToEat = me->GetHealthPercent() < 100.0f;
    bool const needToDrink = (me->GetPowerType() == POWER_MANA) && (me->GetPowerPercent(POWER_MANA) < 100.0f);

    if (!needToEat && !needToDrink)
        return false;

    bool const isEating = me->HasAura(AB_SPELL_FOOD);
    bool const isDrinking = me->HasAura(AB_SPELL_DRINK);

    if (!isEating && needToEat)
    {
        if (me->GetMotionMaster()->GetCurrentMovementGeneratorType())
        {
            StopMoving();
        }
        if (SpellEntry const* pSpellEntry = sSpellMgr.GetSpellEntry(AB_SPELL_FOOD))
        {
            me->CastSpell(me, pSpellEntry, true);
            me->RemoveSpellCooldown(*pSpellEntry);
        }
        return true;
    }

    if (!isDrinking && needToDrink)
    {
        if (me->GetMotionMaster()->GetCurrentMovementGeneratorType())
        {
            StopMoving();
        }
        if (SpellEntry const* pSpellEntry = sSpellMgr.GetSpellEntry(AB_SPELL_DRINK))
        {
            me->CastSpell(me, pSpellEntry, true);
            me->RemoveSpellCooldown(*pSpellEntry);
        }
        return true;
    }

    return needToEat || needToDrink;
}

AiBotAI::AttackStart.body:
bool AiBotAI::AttackStart(Unit* pVictim)
{
    m_isBuffing = false;

    if (me->IsMounted())
        me->RemoveSpellsCausingAura(SPELL_AURA_MOUNTED);

    if (me->Attack(pVictim, true))
    {
        if ((m_role == ROLE_RANGE_DPS || m_role == ROLE_HEALER) &&
            IsRangedDamageClass(me->GetClass()) &&
            me->GetPowerPercent(POWER_MANA) > 10.0f &&
            me->GetCombatDistance(pVictim) > 8.0f)
            me->SetCasterChaseDistance(25.0f);
        else if (me->HasDistanceCasterMovement())
            me->SetCasterChaseDistance(0.0f);

        me->GetMotionMaster()->MoveChase(pVictim, 1.0f, m_role == ROLE_MELEE_DPS ? 3.0f : 0.0f);
        return true;
    }

    return false;
}

AiBotAI::SelectAttackTarget.body:
Unit* AiBotAI::SelectAttackTarget(Unit* pExcept) const
{
    // 1. Check units we are currently in combat with.

    std::list<Unit*> targets;
    HostileReference* pReference = me->GetHostileRefManager().getFirst();

    while (pReference)
    {
        if (Unit* pTarget = pReference->getSourceUnit())
        {
            if (pTarget != pExcept &&
                IsValidHostileTarget(pTarget) &&
                me->IsWithinDist(pTarget, VISIBILITY_DISTANCE_NORMAL))
            {
                targets.push_back(pTarget);
            }
        }
        pReference = pReference->next();
    }

    if (!targets.empty())
    {
        targets.sort([this](Unit* pUnit1, const Unit* pUnit2)
        {
            return me->GetDistance(pUnit1) < me->GetDistance(pUnit2);
        });

        return *targets.begin();
    }

    // 2. Find nearby hostile creatures (mobs that aggro us in the open world).

    float const maxAggroDistance = GetMaxAggroDistanceForMap();

    // 3. Check party attackers.

    if (Group* pGroup = me->GetGroup())
    {
        for (GroupReference* itr = pGroup->GetFirstMember(); itr != nullptr; itr = itr->next())
        {
            if (Unit* pMember = itr->getSource())
            {
                if (pMember == me)
                    continue;

                if (me->GetDistance(pMember) > 30.0f)
                    continue;

                if (Unit* pAttacker = pMember->GetAttackerForHelper())
                {
                    if (pAttacker != pExcept &&
                        IsValidHostileTarget(pAttacker) &&
                        me->IsWithinDist(pAttacker, maxAggroDistance * 2.0f) &&
                        me->GetDistanceZ(pAttacker) < 10.0f &&
                        me->IsWithinLOSInMap(pAttacker))
                        return pAttacker;
                }
            }
        }
    }

    return nullptr;
}

AiBotAI::CheckForUnreachableTarget.body:
bool AiBotAI::CheckForUnreachableTarget()
{
    if (me->GetMotionMaster()->GetCurrentMovementGeneratorType() == CHASE_MOTION_TYPE &&
       !me->GetMotionMaster()->GetCurrent()->IsReachable())
    {
        if (Unit* pTarget = static_cast<ChaseMovementGenerator<Player> const*>(me->GetMotionMaster()->GetCurrent())->GetTarget())
        {
            if (!me->CanReachWithMeleeAutoAttack(pTarget))
            {
                if (!me->IsWithinDist(pTarget, VISIBILITY_DISTANCE_NORMAL))
                {
                    me->AttackStop(false);
                    StopMoving();
                    return true;
                }

                if (pTarget->IsCreature() && !me->IsMoving())
                {
                    // Cheating to prevent getting stuck because of bad mmaps.
                    me->NearTeleportTo(pTarget->GetPosition());
                    return true;
                }

                if (me->GetDistanceZ(pTarget) > 10.0f)
                {
                    me->AttackStop(false);
                    StopMoving();
                    return true;
                }
            }
        }
    }

    return false;
}

AiBotAI::DoRandomWander.body:
void AiBotAI::DoRandomWander()
{
    if (me->IsMoving() || me->IsInCombat())
        return;

    if (me->GetMotionMaster()->GetCurrentMovementGeneratorType() != IDLE_MOTION_TYPE)
        return;

    // Wander to a random nearby point every 10-20 seconds
    if (m_wanderTimer > 0)
        return;

    m_wanderTimer = urand(10000, 20000);

    float x, y, z;
    me->GetRandomPoint(me->GetPositionX(), me->GetPositionY(), me->GetPositionZ(), 15.0f, x, y, z);
    me->GetMotionMaster()->MovePoint(AIBOT_POINT_WANDER, x, y, z, MOVE_PATHFINDING);
}

