static bool findtoknth(std::string &str, int n, std::string::size_type &s, std::string::size_type &e)
{
    int i;
    s = e = 0;
    std::string::size_type size = str.size();
    for (i = 1; s < size && i < n; s++) if (str[s] == ' ') ++i;
    if (i < n)
        return false;

    e = str.find(' ', s);

    return e != std::string::npos;
}

