void PlayerDumpWriter::DumpTableContent(std::string& dump, uint32 guid, char const*tableFrom, char const*tableTo, DumpTableType type)
{
    GUIDs const* guids = nullptr;
    char const* fieldname = nullptr;

    switch (type)
    {
        case DTT_ITEM:
            fieldname = "guid";
            guids = &items;
            break;
        case DTT_ITEM_GIFT:
            fieldname = "item_guid";
            guids = &items;
            break;
        case DTT_ITEM_LOOT:
            fieldname = "guid";
            guids = &items;
            break;
        case DTT_PET:
            fieldname = "owner_guid";
            break;
        case DTT_PET_TABLE:
            fieldname = "guid";
            guids = &pets;
            break;
        case DTT_MAIL:
            fieldname = "receiver_guid";
            break;
        case DTT_MAIL_ITEM:
            fieldname = "mail_id";
            guids = &mails;
            break;
        case DTT_ITEM_TEXT:
            fieldname = "id";
            guids = &texts;
            break;
        default:
            fieldname = "guid";
            break;
    }

    // for guid set stop if set is empty
    if (guids && guids->empty())
        return;                                             // nothing to do

    // setup for guids case start position
    GUIDs::const_iterator guids_itr;
    if (guids)
        guids_itr = guids->begin();

    do
    {
        std::string wherestr;

        if (guids)                                          // set case, get next guids string
            wherestr = GenerateWhereStr(fieldname, *guids, guids_itr);
        else                                                // not set case, get single guid string
            wherestr = GenerateWhereStr(fieldname, guid);

        std::unique_ptr<QueryResult> result = CharacterDatabase.PQuery("SELECT * FROM %s WHERE %s", tableFrom, wherestr.c_str());
        if (!result)
            return;

        do
        {
            // collect guids
            switch (type)
            {
                case DTT_INVENTORY:
                    StoreGUID(result, 3, items);
                    break;       // item guid collection
                case DTT_ITEM:
                    StoreGUID(result, 0, ITEM_FIELD_ITEM_TEXT_ID, texts);
                    break;
                // item text id collection
                case DTT_PET:
                    StoreGUID(result, 0, pets);
                    break;       // pet pet number collection (character_pet.id)
                case DTT_MAIL:
                    StoreGUID(result, 0, mails);            // mail id collection (mail.id)
                    StoreGUID(result, 7, texts);
                    break;       // item text id collection
                case DTT_MAIL_ITEM:
                    StoreGUID(result, 1, items);
                    break;       // item guid collection (mail_items.item_guid)
                default:
                    break;
            }

            dump += CreateDumpString(tableTo, result);
            dump += "\n";
        }
        while (result->NextRow());
    }
    while (guids && guids_itr != guids->end());             // not set case iterate single time, set case iterate for all guids
}

