    Item* ranged_weapon = GetTarget()->ToPlayer()->GetItemByPos(INVENTORY_SLOT_BAG_0, EQUIPMENT_SLOT_RANGED);
    if ((!ranged_weapon || ranged_weapon->GetProto()->AmmoType == 0) && apply)
