    spell->EffectImplicitTargetA[2] = fields[88].GetUInt32();
    spell->EffectImplicitTargetB[0] = fields[89].GetUInt32();
    spell->EffectImplicitTargetB[1] = fields[90].GetUInt32();
    spell->EffectImplicitTargetB[2] = fields[91].GetUInt32();
    spell->EffectRadiusIndex[0] = fields[92].GetUInt32();
    spell->EffectRadiusIndex[1] = fields[93].GetUInt32();
    spell->EffectRadiusIndex[2] = fields[94].GetUInt32();
    spell->EffectApplyAuraName[0] = fields[95].GetUInt32();
    spell->EffectApplyAuraName[1] = fields[96].GetUInt32();
    spell->EffectApplyAuraName[2] = fields[97].GetUInt32();
    spell->EffectAmplitude[0] = fields[98].GetUInt32();
    spell->EffectAmplitude[1] = fields[99].GetUInt32();
    spell->EffectAmplitude[2] = fields[100].GetUInt32();
    spell->EffectMultipleValue[0] = fields[101].GetFloat();
    spell->EffectMultipleValue[1] = fields[102].GetFloat();
    spell->EffectMultipleValue[2] = fields[103].GetFloat();
    spell->EffectChainTarget[0] = fields[104].GetUInt32();
    spell->EffectChainTarget[1] = fields[105].GetUInt32();
    spell->EffectChainTarget[2] = fields[106].GetUInt32();
    spell->EffectItemType[0] = fields[107].GetUInt64();
    spell->EffectItemType[1] = fields[108].GetUInt64();
    spell->EffectItemType[2] = fields[109].GetUInt64();
    spell->EffectMiscValue[0] = fields[110].GetInt32();
    spell->EffectMiscValue[1] = fields[111].GetInt32();
    spell->EffectMiscValue[2] = fields[112].GetInt32();
    spell->EffectTriggerSpell[0] = fields[113].GetUInt32();
    spell->EffectTriggerSpell[1] = fields[114].GetUInt32();
    spell->EffectTriggerSpell[2] = fields[115].GetUInt32();
    spell->EffectPointsPerComboPoint[0] = fields[116].GetFloat();
    spell->EffectPointsPerComboPoint[1] = fields[117].GetFloat();
    spell->EffectPointsPerComboPoint[2] = fields[118].GetFloat();
    spell->SpellVisual = fields[119].GetUInt32();
    //spell->SpellVisual2 = fields[120].GetUInt32(); not used
    spell->SpellIconID = fields[121].GetUInt32();
    spell->activeIconID = fields[122].GetUInt32();
    spell->spellPriority = fields[123].GetUInt32();
    spell->SpellName[0] = fields[124].GetCppString();
    //spell->SpellNameFlag = fields[125].GetUInt32(); not used
    spell->Rank[0] = fields[126].GetCppString();
    /* not used
    spell->RankFlags = fields[127].GetUInt32();
    spell->Description[0] = fields[128].GetCppString();
    spell->DescriptionFlags = fields[129].GetUInt32();
    spell->ToolTip[0] = fields[130].GetCppString();
    spell->ToolTipFlags = fields[131].GetUInt32();
    */
    spell->ManaCostPercentage = fields[132].GetUInt32();
    spell->StartRecoveryCategory = fields[133].GetUInt32();
    spell->StartRecoveryTime = fields[134].GetUInt32();
    spell->MinTargetLevel = fields[135].GetUInt32();
    spell->MaxTargetLevel = fields[136].GetUInt32();
    spell->SpellFamilyName = fields[137].GetUInt32();
    spell->SpellFamilyFlags = fields[138].GetUInt64();
    spell->MaxAffectedTargets = fields[139].GetUInt32();
    spell->DmgClass = fields[140].GetUInt32();
    spell->PreventionType = fields[141].GetUInt32();
    //spell->StanceBarOrder = fields[142].GetInt32();
    spell->DmgMultiplier[0] = fields[143].GetFloat();
    spell->DmgMultiplier[1] = fields[144].GetFloat();
    spell->DmgMultiplier[2] = fields[145].GetFloat();
    //spell->MinFactionId = fields[146].GetUInt32();
    //spell->MinReputation = fields[147].GetUInt32();
    //spell->RequiredAuraVision = fields[148].GetUInt32();
    spell->Custom = fields[149].GetUInt32();
    spell->ScriptId = sScriptMgr.GetScriptId(fields[150].GetString());

    // It seems that in vanilla when the Amplitude of a
    // periodic aura was 0, it defaulted to a 5 seconds timer.
    // Check out Violet Tragan (Item 8526, Spell 6727).
    // There are comments from vanilla saying it does
    // damage every 5 seconds, while TBC comments say
    // it does no damage, so behavior changed then.
    // In classic the spell was edited in 1.13.6 and
    // the timer was set to 5000, as it didn't work before.
    for (int i = EFFECT_INDEX_0; i <= EFFECT_INDEX_2; ++i)
    {
        switch (spell->EffectApplyAuraName[i])
        {
        case SPELL_AURA_PERIODIC_DAMAGE:
        case SPELL_AURA_PERIODIC_HEAL:
        case SPELL_AURA_PERIODIC_TRIGGER_SPELL:
        case SPELL_AURA_PERIODIC_ENERGIZE:
        case SPELL_AURA_PERIODIC_LEECH:
        case SPELL_AURA_PERIODIC_HEALTH_FUNNEL:
        case SPELL_AURA_PERIODIC_MANA_FUNNEL:
        case SPELL_AURA_PERIODIC_MANA_LEECH:
        case SPELL_AURA_PERIODIC_DAMAGE_PERCENT:
        case SPELL_AURA_POWER_BURN_MANA:
            if (spell->EffectAmplitude[i] == 0)
                spell->EffectAmplitude[i] = 5000;
            break;
        }
    }

    // Attribute replaced with aura state in patch 1.8.
    if (spell->HasAttribute(SPELL_ATTR_EX2_ENABLE_AFTER_PARRY))
        spell->CasterAuraState = spell->SpellFamilyName == SPELLFAMILY_HUNTER ? AURA_STATE_HUNTER_PARRY : AURA_STATE_DEFENSE;

#if SUPPORTED_CLIENT_BUILD <= CLIENT_BUILD_1_10_2
    for (int i = EFFECT_INDEX_0; i <= EFFECT_INDEX_2; ++i)
    {
        if (IsEffectAppliesAura(spell->Effect[i]))
        {
            switch (spell->EffectApplyAuraName[i])
            {
                // Before 1.11, the spell data specifies TO what percent the speed is reduced, not BY what percent.
            case SPELL_AURA_MOD_DECREASE_SPEED:
            {
                spell->EffectBasePoints[i] = -(100 - spell->EffectBasePoints[i]);
                break;
            }

#if SUPPORTED_CLIENT_BUILD <= CLIENT_BUILD_1_8_4
            // Before 1.9, the creature family is not a mask.
            case SPELL_AURA_MOD_DAMAGE_DONE_CREATURE:
            {
                spell->EffectMiscValue[i] = 1 << (spell->EffectMiscValue[i] - 1);
                break;
            }
            // Before 1.9, value 0 means all schools.
            case SPELL_AURA_MOD_THREAT:
            {
                if (spell->EffectMiscValue[i] == 0)
                    spell->EffectMiscValue[i] = 127;
                break;
            }
            // Before 1.9, the school is not a mask.
            case SPELL_AURA_MOD_DAMAGE_DONE:
            case SPELL_AURA_MOD_DAMAGE_TAKEN:
            case SPELL_AURA_MOD_RESISTANCE:
            case SPELL_AURA_SCHOOL_IMMUNITY:
            case SPELL_AURA_DAMAGE_IMMUNITY:
            case SPELL_AURA_SCHOOL_ABSORB:
            case SPELL_AURA_MOD_SPELL_CRIT_CHANCE_SCHOOL:
            case SPELL_AURA_MOD_POWER_COST_SCHOOL_PCT:
            case SPELL_AURA_MOD_POWER_COST_SCHOOL:
            case SPELL_AURA_REFLECT_SPELLS_SCHOOL:
            case SPELL_AURA_MOD_DAMAGE_PERCENT_DONE:
            case SPELL_AURA_SPLIT_DAMAGE_PCT:
            case SPELL_AURA_MOD_BASE_RESISTANCE:
            case SPELL_AURA_MOD_DAMAGE_PERCENT_TAKEN:
            case SPELL_AURA_MOD_RESISTANCE_PCT:
            case SPELL_AURA_MOD_RANGED_DAMAGE_TAKEN:
            case SPELL_AURA_MOD_HEALING:
            case SPELL_AURA_MOD_HEALING_PCT:
            case SPELL_AURA_MOD_HEALING_DONE:
            case SPELL_AURA_MOD_HEALING_DONE_PERCENT:
            case SPELL_AURA_MOD_BASE_RESISTANCE_PCT:
            case SPELL_AURA_MOD_RESISTANCE_EXCLUSIVE:
            case SPELL_AURA_SPLIT_DAMAGE_FLAT:
            {
                if (spell->EffectMiscValue[i] == -2)
                    spell->EffectMiscValue[i] = 127; // all schools
                else if (spell->EffectMiscValue[i] == -1)
                    spell->EffectMiscValue[i] = 126; // all magic schools
                else
                    spell->EffectMiscValue[i] = 1 << spell->EffectMiscValue[i];
                break;
            }
#endif
            }
        }
    }
#endif

    // Before 1.10, the spell proc flags had completely different meanings.
#if SUPPORTED_CLIENT_BUILD <= CLIENT_BUILD_1_9_4
    spell->procFlags = ReplaceOldSpellProcFlags(spell->procFlags);
#endif
}

ModUInt64ValueIfExplicit.body:
inline void ModUInt64ValueIfExplicit(Field &f, uint64& value)
{
    if (f.GetInt64() >= 0)
        value = f.GetUInt64();
}

ModUInt32ValueIfExplicit.body:
inline void ModUInt32ValueIfExplicit(Field &f, uint32& value)
{
    if (f.GetInt32() >= 0)
        value = f.GetUInt32();
}

ModInt32ValueIfExplicit.body:
inline void ModInt32ValueIfExplicit(Field &f, int32& value)
{
    if (f.GetInt32() != -1)
        value = f.GetInt32();
}

ModFloatValueIfExplicit.body:
inline void ModFloatValueIfExplicit(Field &f, float &value)
{
    if (f.GetFloat() != -1.0f)
        value = f.GetFloat();
}

SpellModMgr::LoadSpellMods.body:
void SpellModMgr::LoadSpellMods()
{
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "Loading spell mods ...");

    // 1 : Table spell_mod
    std::unique_ptr<QueryResult> result(WorldDatabase.Query(
                              "SELECT Id, procChance, procFlags, Custom, DurationIndex, "
                              "Category, CastingTimeIndex, StackAmount, SpellIconID, activeIconID, manaCost, "
                              "Attributes, AttributesEx, AttributesEx2, AttributesEx3, AttributesEx4, "
                              "InterruptFlags, AuraInterruptFlags, ChannelInterruptFlags, Dispel, "
                              "Stances, StancesNot, SpellVisual, ManaCostPercentage, StartRecoveryCategory, StartRecoveryTime, MaxTargetLevel, MaxAffectedTargets, DmgClass, "
                              "rangeIndex, RecoveryTime, CategoryRecoveryTime, procCharges, SpellFamilyName, SpellFamilyFlags, Mechanic, EquippedItemClass "
                              "FROM spell_mod"));
    uint32 total_count = 0;
    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u spell modifications. Table spell_mod is empty.", total_count);
    }
    else
    {
        Field* fields;
        BarGoLink bar(result->GetRowCount());
        do
        {
            bar.step();
            fields = result->Fetch();
            uint32 const spellid = fields[0].GetUInt32();

#ifdef ENABLE_INSERT_NEW_SPELLS
            if (!sSpellMgr.GetSpellEntry(spellid))
            {
                if (!sSpellMgr.OverwriteSpellEntry(spellid))
                {
                    sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Unable to create spell %u, skipping.", spellid);
                    continue;
                }
            }
#endif
            SpellEntry* spell = const_cast<SpellEntry*>(sSpellMgr.GetSpellEntry(spellid));
            if (!spell)
            {
                if (!sSpellMgr.IsExistingSpellId(spellid))
                    sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Spell entry %u from `spell_mod` doesn't exist, ignoring.", spellid);
                continue;
            }

            // 0   1           2          3       4
            // Id, procChance, procFlags, custom, DurationIndex
            spell->Id = spellid;
            ModUInt32ValueIfExplicit(fields[1], spell->procChance);
            ModUInt32ValueIfExplicit(fields[2], spell->procFlags);
            ModUInt32ValueIfExplicit(fields[4], spell->DurationIndex);

            uint32 const customFlags = fields[3].GetUInt32();
            if (customFlags)
                spell->Custom = customFlags;

            // 5         6                 7            8            9             10
            // Category, CastingTimeIndex, StackAmount, SpellIconID, activeIconID, manaCost
            ModUInt32ValueIfExplicit(fields[5],  spell->Category);
            ModUInt32ValueIfExplicit(fields[6], spell->CastingTimeIndex);
            ModUInt32ValueIfExplicit(fields[7], spell->StackAmount);
            ModUInt32ValueIfExplicit(fields[8], spell->SpellIconID);
            ModUInt32ValueIfExplicit(fields[9], spell->activeIconID);
            ModUInt32ValueIfExplicit(fields[10], spell->manaCost);

            // 11          12            13              14            15
            // Attributes, AttributesEx, AttributesEx2, AttributesEx3, AttributesEx4
            ModUInt32ValueIfExplicit(fields[11], spell->Attributes);
            ModUInt32ValueIfExplicit(fields[12], spell->AttributesEx);
            ModUInt32ValueIfExplicit(fields[13], spell->AttributesEx2);
            ModUInt32ValueIfExplicit(fields[14], spell->AttributesEx3);
            ModUInt32ValueIfExplicit(fields[15], spell->AttributesEx4);

            // 16              17                  18                     19
            // InterruptFlags, AuraInterruptFlags, ChannelInterruptFlags, Dispel
            ModUInt32ValueIfExplicit(fields[16], spell->InterruptFlags);
            ModUInt32ValueIfExplicit(fields[17], spell->AuraInterruptFlags);
            ModUInt32ValueIfExplicit(fields[18], spell->ChannelInterruptFlags);
            ModUInt32ValueIfExplicit(fields[19], spell->Dispel);

            // 20       21          22           23                  24                     25                 26              27                  28
            // Stances, StancesNot, SpellVisual, ManaCostPercentage, StartRecoveryCategory, StartRecoveryTime, MaxTargetLevel, MaxAffectedTargets, DmgClass
            ModUInt32ValueIfExplicit(fields[20], spell->Stances);
            ModUInt32ValueIfExplicit(fields[21], spell->StancesNot);
            ModUInt32ValueIfExplicit(fields[22], spell->SpellVisual);
            ModUInt32ValueIfExplicit(fields[23], spell->ManaCostPercentage);
            ModUInt32ValueIfExplicit(fields[24], spell->StartRecoveryCategory);
            ModUInt32ValueIfExplicit(fields[25], spell->StartRecoveryTime);
            ModUInt32ValueIfExplicit(fields[26], spell->MaxTargetLevel);
            ModUInt32ValueIfExplicit(fields[27], spell->MaxAffectedTargets);
            ModUInt32ValueIfExplicit(fields[28], spell->DmgClass);

            // 29          30            31                    32
            // rangeIndex, RecoveryTime, CategoryRecoveryTime, procCharges
            ModUInt32ValueIfExplicit(fields[29], spell->rangeIndex);
            ModUInt32ValueIfExplicit(fields[30], spell->RecoveryTime);
            ModUInt32ValueIfExplicit(fields[31], spell->CategoryRecoveryTime);
            ModUInt32ValueIfExplicit(fields[32], spell->procCharges);

            // 33               34                35        36
            // SpellFamilyName, SpellFamilyFlags, Mechanic, EquippedItemClass
            ModUInt32ValueIfExplicit(fields[33], spell->SpellFamilyName);
            uint64 const familyFlags = fields[34].GetUInt64();
            if (familyFlags)
                spell->SpellFamilyFlags = familyFlags;
            ModUInt32ValueIfExplicit(fields[35], spell->Mechanic);
            ModInt32ValueIfExplicit(fields[36], spell->EquippedItemClass);

            ++total_count;
        }
        while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u spell modifications.", total_count);
    }

    // 2 : Table spell_effect_mod
    sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "Loading spell effect mods ...");
    result = WorldDatabase.Query(
                 "SELECT Id, EffectIndex, Effect, EffectApplyAuraName, EffectMechanic, EffectImplicitTargetA, EffectImplicitTargetB, "
                 "EffectRadiusIndex, EffectItemType, EffectMiscValue, EffectTriggerSpell, "
                 "EffectDieSides, EffectBaseDice, EffectBasePoints, EffectAmplitude, EffectChainTarget, " // Int
                 "EffectDicePerLevel, EffectRealPointsPerLevel, EffectPointsPerComboPoint, EffectMultipleValue " // Float
                 "FROM spell_effect_mod"
                );
    total_count = 0;

    if (!result)
    {
        BarGoLink bar(1);
        bar.step();

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u spell effect modifications. Table spell_effect_mod is empty.", total_count);
    }
    else
    {
        Field* fields;
        BarGoLink bar(result->GetRowCount());
        do
        {
            bar.step();
            fields = result->Fetch();
            uint32 spellid = fields[0].GetUInt32();
            uint32 effect_idx = fields[1].GetUInt32();
            SpellEntry* spell = ((SpellEntry*)sSpellMgr.GetSpellEntry(spellid));
            if (!spell)
            {
                if (!sSpellMgr.IsExistingSpellId(spellid))
                    sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Spell entry %u from `spell_effect_mod` doesn't exist, ignoring.", spellid);
                continue;
            }
            if (effect_idx >= MAX_EFFECT_INDEX)
            {
                sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "Spell %u has a modification for effect %u, but the maximum effect id is %u.", spellid, effect_idx, (MAX_EFFECT_INDEX - 1));
                continue;
            }
            // 0   1            2       3                    4               5                      6
            // Id, EffectIndex, Effect, EffectApplyAuraName, EffectMechanic, EffectImplicitTargetA, EffectImplicitTargetB,
            ModUInt32ValueIfExplicit(fields[2], spell->Effect[effect_idx]);
            ModUInt32ValueIfExplicit(fields[3], spell->EffectApplyAuraName[effect_idx]);
            ModUInt32ValueIfExplicit(fields[4], spell->EffectMechanic[effect_idx]);
            ModUInt32ValueIfExplicit(fields[5], spell->EffectImplicitTargetA[effect_idx]);
            ModUInt32ValueIfExplicit(fields[6], spell->EffectImplicitTargetB[effect_idx]);

            // 7                  8               9                10
            // EffectRadiusIndex, EffectItemType, EffectMiscValue, EffectTriggerSpell
            ModUInt32ValueIfExplicit(fields[7], spell->EffectRadiusIndex[effect_idx]);
            ModUInt64ValueIfExplicit(fields[8], spell->EffectItemType[effect_idx]);
            ModInt32ValueIfExplicit(fields[9], spell->EffectMiscValue[effect_idx]);
            ModUInt32ValueIfExplicit(fields[10], spell->EffectTriggerSpell[effect_idx]);

            // 11              12              13                14               15
            // EffectDieSides, EffectBaseDice, EffectBasePoints, EffectAmplitude, EffectChainTarget
            ModInt32ValueIfExplicit(fields[11], spell->EffectDieSides[effect_idx]);
            ModUInt32ValueIfExplicit(fields[12], spell->EffectBaseDice[effect_idx]);
            ModInt32ValueIfExplicit(fields[13], spell->EffectBasePoints[effect_idx]);
            ModUInt32ValueIfExplicit(fields[14], spell->EffectAmplitude[effect_idx]);
            ModUInt32ValueIfExplicit(fields[15], spell->EffectChainTarget[effect_idx]);

            // 16                  17                        18                         19
            // EffectDicePerLevel, EffectRealPointsPerLevel, EffectPointsPerComboPoint, EffectMultipleValue
            ModFloatValueIfExplicit(fields[16], spell->EffectDicePerLevel[effect_idx]);
            ModFloatValueIfExplicit(fields[17], spell->EffectRealPointsPerLevel[effect_idx]);
            ModFloatValueIfExplicit(fields[18], spell->EffectPointsPerComboPoint[effect_idx]);
            ModFloatValueIfExplicit(fields[19], spell->EffectMultipleValue[effect_idx]);

            ++total_count;
        }
        while (result->NextRow());

        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, "");
        sLog.Out(LOG_BASIC, LOG_LVL_MINIMAL, ">> Loaded %u spell effect modifications.", total_count);
    }

    // Other modifications (no 'speed' field in spell_mod)

    // Flare
    if (SpellEntry* fuseeEcl = const_cast<SpellEntry*>(sSpellMgr.GetSpellEntry(1543)))
        fuseeEcl->speed = 0.0f;

    // Seal of Command Trigger minor delay (melee radius 5.0 / 10.0 * 1000 = 0.5sec delay)
    if (SpellEntry* spellInfo = const_cast<SpellEntry*>(sSpellMgr.GetSpellEntry(20424)))
        spellInfo->speed = 10.0f;

    // Divine Favor EffectItemMask for Holy Light base spell
    // (HACK) need to modify EffectItemType column in spell_effect_mod to support bigint flags
    if (SpellEntry* pDivine = const_cast<SpellEntry*>(sSpellMgr.GetSpellEntry(20216)))
        pDivine->EffectItemType[0] = 0x80202000;
}

SpellModifier::IsAffectedOnSpell.body:
bool SpellModifier::IsAffectedOnSpell(SpellEntry const* spell) const
{
    SpellEntry const* affect_spell = sSpellMgr.GetSpellEntry(spellId);
    // False if affect_spell == nullptr or spellFamily not equal
    if (!affect_spell || affect_spell->SpellFamilyName != spell->SpellFamilyName)
        return false;
    return spell->IsFitToFamilyMask(mask);
}

Player::UpdateStats.body:
bool Player::UpdateStats(Stats stat)
{
    if (stat > STAT_SPIRIT)
        return false;

    // value = ((base_value * base_pct) + total_value) * total_pct
    float value  = GetTotalStatValue(stat);

    SetStat(stat, int32(value));

    switch (stat)
    {
        case STAT_STRENGTH:
            break;
        case STAT_AGILITY:
            UpdateArmor();
            UpdateAllCritPercentages();
            UpdateDodgePercentage();
            break;
        case STAT_STAMINA:
            UpdateMaxHealth();
            break;
        case STAT_INTELLECT:
            UpdateMaxPower(POWER_MANA);
            UpdateAllSpellCritChances();
            UpdateArmor();                                  //SPELL_AURA_MOD_RESISTANCE_OF_INTELLECT_PERCENT, only armor currently
            break;

        case STAT_SPIRIT:
            break;

        default:
            break;
    }
    // Need update (exist AP from stat auras)
    UpdateAttackPowerAndDamage();
    UpdateAttackPowerAndDamage(true);

    UpdateSpellDamageAndHealingBonus();
    UpdateManaRegen();

    return true;
}

Player::UpdateSpellDamageAndHealingBonus.body:
void Player::UpdateSpellDamageAndHealingBonus()
{
    // Magic damage modifiers implemented in Unit::SpellDamageBonusDone
    // This information for client side use only
    // Get healing bonus for all schools
    // Get damage bonus for all schools
    for (int i = SPELL_SCHOOL_HOLY; i < MAX_SPELL_SCHOOL; ++i)
        SetStatInt32Value(PLAYER_FIELD_MOD_DAMAGE_DONE_POS + i, SpellBaseDamageBonusDone(GetSchoolMask(i)));
}

Player::UpdateAllStats.body:
bool Player::UpdateAllStats()
{
    for (int i = STAT_STRENGTH; i < MAX_STATS; ++i)
    {
        float value = GetTotalStatValue(Stats(i));
        SetStat(Stats(i), (int32)value);
    }

    UpdateAttackPowerAndDamage();
    UpdateAttackPowerAndDamage(true);
    UpdateMaxHealth();

    for (int i = POWER_MANA; i < MAX_POWERS; ++i)
        UpdateMaxPower(Powers(i));

    UpdateAllCritPercentages();
    UpdateAllSpellCritChances();
    UpdateDefenseBonusesMod();
    UpdateSpellDamageAndHealingBonus();
    UpdateManaRegen();

    for (int i = SPELL_SCHOOL_NORMAL; i < MAX_SPELL_SCHOOL; ++i)
        UpdateResistances(i);

    return true;
}

Player::UpdateResistances.body:
void Player::UpdateResistances(uint32 school)
{
    if (school > SPELL_SCHOOL_NORMAL)
    {
        int32 value = school == SPELL_SCHOOL_HOLY ? 0 : GetTotalResistanceValue(SpellSchools(school));
        SetResistance(SpellSchools(school), value);
    }
    else
        UpdateArmor();
}

Player::UpdateArmor.body:
void Player::UpdateArmor()
{
    float dynamic = (GetStat(STAT_AGILITY) * 2.0f);

    // Add dynamic flat mods
    for (auto& i : GetAurasByType(SPELL_AURA_MOD_RESISTANCE_OF_STAT_PERCENT))
    {
        if (Modifier* mod = i->GetModifier())
        {
            if (mod->m_miscvalue & SPELL_SCHOOL_MASK_NORMAL)
                dynamic += (GetStat(STAT_INTELLECT) * (mod->m_amount * 0.01f));
        }
    }

    m_auraModifiersGroup[UNIT_MOD_ARMOR][TOTAL_VALUE] += dynamic;
    int32 value = GetTotalResistanceValue(SPELL_SCHOOL_NORMAL);

    SetArmor(value);
    m_auraModifiersGroup[UNIT_MOD_ARMOR][TOTAL_VALUE] -= dynamic;
}

Player::GetHealthBonusFromStamina.body:
float Player::GetHealthBonusFromStamina(float stamina)
{
    float baseStam = stamina < 20 ? stamina : 20;
    float moreStam = stamina - baseStam;

    return baseStam + (moreStam * 10.0f);
}

Player::GetManaBonusFromIntellect.body:
float Player::GetManaBonusFromIntellect(float intellect)
{
    float baseInt = intellect < 20 ? intellect : 20;
    float moreInt = intellect - baseInt;

    return baseInt + (moreInt * 15.0f);
}

Player::UpdateMaxHealth.body:
void Player::UpdateMaxHealth()
{
    UnitMods unitMod = UNIT_MOD_HEALTH;

    float value = GetModifierValue(unitMod, BASE_VALUE) + GetCreateHealth();
    value *= GetModifierValue(unitMod, BASE_PCT);
    value += GetModifierValue(unitMod, TOTAL_VALUE) + GetHealthBonusFromStamina(GetStat(STAT_STAMINA));
    value *= GetModifierValue(unitMod, TOTAL_PCT);

    SetMaxHealth(std::max(1, int(value)));
}

Player::UpdateMaxPower.body:
void Player::UpdateMaxPower(Powers power)
{
    UnitMods unitMod = UnitMods(UNIT_MOD_POWER_START + power);

    uint32 create_power = GetCreatePowers(power);

    // ignore classes without mana
    float bonusPower = (power == POWER_MANA && create_power > 0) ? GetManaBonusFromIntellect(GetStat(STAT_INTELLECT)) : 0;

    float value = GetModifierValue(unitMod, BASE_VALUE) + create_power;
    value *= GetModifierValue(unitMod, BASE_PCT);
    value += GetModifierValue(unitMod, TOTAL_VALUE) +  bonusPower;
    value *= GetModifierValue(unitMod, TOTAL_PCT);

    SetMaxPower(power, uint32(value));
}

Unit::GetAttackPowerFromStrengthAndAgili.body:
float Unit::GetAttackPowerFromStrengthAndAgility(bool ranged, float strength, float agility) const
{
    float val2 = 0.0f;
    float level = float(GetLevel());
    if (ranged)
    {
        switch (GetClass())
        {
            case CLASS_HUNTER:
                val2 = level * 2.0f + agility * 2.0f - 10.0f;
                break;
            case CLASS_ROGUE:
                val2 = level        + agility - 10.0f;
                break;
            case CLASS_WARRIOR:
                val2 = level        + agility - 10.0f;
                break;
            case CLASS_DRUID:
                switch (GetShapeshiftForm())
                {
                    case FORM_CAT:
                    case FORM_BEAR:
                    case FORM_DIREBEAR:
                        val2 = 0.0f;
                        break;
                    default:
                        val2 = agility - 10.0f;
                        break;
                }
                break;
            default:
                val2 = agility - 10.0f;
                break;
        }
    }
    else
    {
        switch (GetClass())
        {
            case CLASS_WARRIOR:
                val2 = level * 3.0f + strength * 2.0f    - 20.0f;
                break;
            case CLASS_PALADIN:
                val2 = level * 3.0f + strength * 2.0f    - 20.0f;
                break;
            case CLASS_ROGUE:
                val2 = level * 2.0f + strength + agility - 20.0f;
                break;
            case CLASS_HUNTER:
                val2 = level * 2.0f + strength + agility - 20.0f;
                break;
            case CLASS_SHAMAN:
                val2 = level * 2.0f + strength * 2.0f    - 20.0f;
                break;
            case CLASS_DRUID:
            {
                ShapeshiftForm form = GetShapeshiftForm();

                //Check if Predatory Strikes is skilled
                float mLevelMult = 0.0;
                switch (form)
                {
                    case FORM_CAT:
                    case FORM_BEAR:
                    case FORM_DIREBEAR:
                    {
                        Unit::AuraList const& mDummy = GetAurasByType(SPELL_AURA_DUMMY);
                        for (const auto itr : mDummy)
                        {
                            // Predatory Strikes
                            if (itr->GetSpellProto()->SpellIconID == 1563)
                            {
                                mLevelMult = itr->GetModifier()->m_amount / 100.0f;
                                break;
                            }
                        }
                        break;
                    }
                    default:
                        break;
                }

                switch (form)
                {
                    case FORM_CAT:
                       // World of Warcraft Client Patch 1.7.0 (2005-09-13)
                       // - Cat Form - Each point of agility now adds 1 attack power.
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_6_1
                        val2 = GetLevel() * mLevelMult + strength * 2.0f + agility - 20.0f;
                        break;
#endif
                    case FORM_BEAR:
                    case FORM_DIREBEAR:
                        val2 = GetLevel() * mLevelMult + strength * 2.0f - 20.0f;
                        break;
                    default:
                        val2 = strength * 2.0f - 20.0f;
                        break;
                }
                break;
            }
            case CLASS_MAGE:
                val2 = strength - 10.0f;
                break;
            case CLASS_PRIEST:
                val2 = strength - 10.0f;
                break;
            case CLASS_WARLOCK:
                val2 = strength - 10.0f;
                break;
        }
    }
    return val2;
}

Player::UpdateAttackPowerAndDamage.body:
void Player::UpdateAttackPowerAndDamage(bool ranged)
{
    AttackPowerModIndex unitMod = ranged ? RANGED_AP_MODS : MELEE_AP_MODS;

    uint16 index = UNIT_FIELD_ATTACK_POWER;
    uint16 index_mod = UNIT_FIELD_ATTACK_POWER_MODS;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
    uint16 index_mult = UNIT_FIELD_ATTACK_POWER_MULTIPLIER;
#endif

    if (ranged)
    {
        index = UNIT_FIELD_RANGED_ATTACK_POWER;
        index_mod = UNIT_FIELD_RANGED_ATTACK_POWER_MODS;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
        index_mult = UNIT_FIELD_RANGED_ATTACK_POWER_MULTIPLIER;
#endif  
    }

    float baseAttackPower = GetAttackPowerFromStrengthAndAgility(ranged, GetStat(STAT_STRENGTH), GetStat(STAT_AGILITY));

    // attack power mods are split into positive and negative field
    float attackPowerModPositive = GetAttackPowerModifierValue(unitMod, AP_MOD_POSITIVE_FLAT);
    float attackPowerModNegative = GetAttackPowerModifierValue(unitMod, AP_MOD_NEGATIVE_FLAT);

    SetInt32Value(index, (int32)baseAttackPower);               //UNIT_FIELD_(RANGED)_ATTACK_POWER field
    SetInt16Value(index_mod, 0, (int16)attackPowerModPositive); //UNIT_FIELD_(RANGED)_ATTACK_POWER_MODS field (positive)
    SetInt16Value(index_mod, 1, (int16)attackPowerModNegative); //UNIT_FIELD_(RANGED)_ATTACK_POWER_MODS field (negative)

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
    float attackPowerMultiplier = GetAttackPowerModifierValue(unitMod, AP_MOD_PCT) - 1.0f;
    SetFloatValue(index_mult, attackPowerMultiplier);           //UNIT_FIELD_(RANGED)_ATTACK_POWER_MULTIPLIER field
#endif

    //automatically update weapon damage after attack power modification
    if (ranged)
        UpdateDamagePhysical(RANGED_ATTACK);
    else
    {
        UpdateDamagePhysical(BASE_ATTACK);
        if (CanDualWield() && HaveOffhandWeapon())          //allow update offhand damage only if player knows DualWield Spec and has equipped offhand weapon
            UpdateDamagePhysical(OFF_ATTACK);
    }
}

Player::CalculateMinMaxDamage.body:
void Player::CalculateMinMaxDamage(WeaponAttackType attType, bool normalized, float& min_damage, float& max_damage, uint8 index) const
{
    UnitMods unitMod;

    switch (attType)
    {
        case BASE_ATTACK:
        default:
            unitMod = UNIT_MOD_DAMAGE_MAINHAND;
            break;
        case OFF_ATTACK:
            unitMod = UNIT_MOD_DAMAGE_OFFHAND;
            break;
        case RANGED_ATTACK:
            unitMod = UNIT_MOD_DAMAGE_RANGED;
            break;
    }

    float att_speed = GetAPMultiplier(attType, normalized) * m_modRecalcDamagePct[attType];

    float base_value  = GetModifierValue(unitMod, BASE_VALUE) + GetTotalAttackPowerValue(attType) / 14.0f * att_speed;
    float base_pct    = GetModifierValue(unitMod, BASE_PCT);
    float total_value = GetModifierValue(unitMod, TOTAL_VALUE);
    float total_pct   = GetModifierValue(unitMod, TOTAL_PCT);
    float total_phys  = GetTotalAuraModValue(UNIT_MOD_DAMAGE_PHYSICAL);

    float weapon_mindamage = GetWeaponDamageRange(attType, MINDAMAGE, index);
    float weapon_maxdamage = GetWeaponDamageRange(attType, MAXDAMAGE, index);

    if (IsAttackSpeedOverridenShapeShift()) // check if player is in shapeshift which doesnt use weapon
    {
        /* Druids don't use weapons so a weapon damage index > 0 
           should not affect their damage. Fixes crazy druid scaling
           when using melee weapons with two or more damage types on it */
        if (index > 0)
        {
            // Note that CalculateDamage will pull max_damage up to 5.0f, 
            // so they'll still get some extra damage...
            weapon_mindamage = 0.0f;
            weapon_maxdamage = 0.0f;
        }
        else 
        {
            uint32 lvl = GetLevel();
            if (lvl > 60)
                lvl = 60;

#pragma warning( push )
#pragma warning( disable : 4065)

            switch (GetShapeshiftForm())
            {
                // World of Warcraft Client Patch 1.7.0 (2005-09-13)
                // - Cat Form - The base weapon damage of the form has been increased.
#if SUPPORTED_CLIENT_BUILD <= CLIENT_BUILD_1_6_1
                case FORM_CAT:
                    // guessed
                    weapon_mindamage = lvl * 0.60f * att_speed;
                    weapon_maxdamage = lvl * 1.00f * att_speed;
                    break;
#endif
                default:
                    weapon_mindamage = lvl * 0.85f * att_speed;
                    weapon_maxdamage = lvl * 1.25f * att_speed;
                    break;
            }

#pragma warning( pop ) 

            total_value = 0.0f;                             // remove benefit from weapon enchants
        }
    }
    else if (!CanUseEquippedWeapon(attType))                // check if player not in form but still can't use weapon (broken/etc)
    {
        weapon_mindamage = BASE_MINDAMAGE;
        weapon_maxdamage = BASE_MAXDAMAGE;
        total_value = 0.0f;
    }
    else if (attType == RANGED_ATTACK && index == 0)        // add ammo DPS to ranged damage
    {
        weapon_mindamage += GetAmmoDPS() * att_speed;
        weapon_maxdamage += GetAmmoDPS() * att_speed;
    }

    if (index != 0)
    {
        base_value = 0.0f;
        total_value = 0.0f;
        total_phys = 0.0f;
    }

    min_damage = ((base_value + weapon_mindamage) * base_pct + total_value + total_phys) * total_pct;
    max_damage = ((base_value + weapon_maxdamage) * base_pct + total_value + total_phys) * total_pct;
}

Player::UpdateDamagePhysical.body:
void Player::UpdateDamagePhysical(WeaponAttackType attType)
{
    float mindamage;
    float maxdamage;

    CalculateMinMaxDamage(attType, false, mindamage, maxdamage);

    switch (attType)
    {
        case BASE_ATTACK:
        default:
            SetStatFloatValue(UNIT_FIELD_MINDAMAGE, mindamage);
            SetStatFloatValue(UNIT_FIELD_MAXDAMAGE, maxdamage);
            break;
        case OFF_ATTACK:
            SetStatFloatValue(UNIT_FIELD_MINOFFHANDDAMAGE, mindamage);
            SetStatFloatValue(UNIT_FIELD_MAXOFFHANDDAMAGE, maxdamage);
            break;
        case RANGED_ATTACK:
            SetStatFloatValue(UNIT_FIELD_MINRANGEDDAMAGE, mindamage);
            SetStatFloatValue(UNIT_FIELD_MAXRANGEDDAMAGE, maxdamage);
            break;
    }
}

Player::GetWeaponBasedAuraModifier.body:
float Player::GetWeaponBasedAuraModifier(WeaponAttackType attType, AuraType auraType) const
{
    float amount = 0.0f;
    AuraList const& auras = GetAurasByType(auraType);
    if (auras.empty())
        return amount;

    Item* pWeapon = GetWeaponForAttack(attType);
    for (auto const& i : auras)
    {
        SpellEntry const* pSpellEntry = i->GetSpellProto();
        if (pSpellEntry->EquippedItemClass >= 0)
        {
            if (!pWeapon)
                continue;

            if (!pWeapon->IsFitToSpellRequirements(pSpellEntry))
                continue;
        }

        amount += i->GetModifier()->m_amount;
    }
    return amount;
}

Player::UpdateBlockPercentage.body:
void Player::UpdateBlockPercentage()
{
    // No block
    float value = 0.0f;
    if (CanBlock())
    {
        // Base value
        value = 5.0f;
        // Modify value from defense skill
        value += (int32(GetDefenseSkillValue()) - int32(GetSkillMaxForLevel())) * 0.04f;
        // Increase from SPELL_AURA_MOD_BLOCK_PERCENT aura
        value += GetTotalAuraModifier(SPELL_AURA_MOD_BLOCK_PERCENT);
        value = value < 0.0f ? 0.0f : value;
    }
    SetStatFloatValue(PLAYER_BLOCK_PERCENTAGE, value);
}

Player::UpdateCritPercentage.body:
void Player::UpdateCritPercentage(WeaponAttackType attType)
{
    BaseModGroup modGroup;
    uint16 index;

    switch (attType)
    {
        case RANGED_ATTACK:
            modGroup = RANGED_CRIT_PERCENTAGE;
            index = PLAYER_RANGED_CRIT_PERCENTAGE;
            break;
        case BASE_ATTACK:
            modGroup = CRIT_PERCENTAGE;
            index = PLAYER_CRIT_PERCENTAGE;
            break;
        case OFF_ATTACK:                                    // client have only main hand crit
        default:
            return;
    }

    float value = GetTotalPercentageModValue(modGroup);
    switch (GetClass())
    {
        case CLASS_DRUID:
            value += 0.9f;
            break;
        case CLASS_MAGE:
            value += 3.2f;
            break;
        case CLASS_PALADIN:
            value += 0.7f;
            break;
        case CLASS_PRIEST:
            value += 3.0f;
            break;
        case CLASS_SHAMAN:
            value += 1.7f;
            break;
        case CLASS_WARLOCK:
            value += 2.0f;
            break;
    }
    // Modify crit from weapon skill and maximized defense skill of same level victim difference
    value += (int32(GetWeaponSkillValue(attType)) - int32(GetSkillMaxForLevel())) * 0.04f;
    value = value < 0.0f ? 0.0f : value;
    SetStatFloatValue(index, value);
}

Player::UpdateAllCritPercentages.body:
void Player::UpdateAllCritPercentages()
{
    float value = GetMeleeCritFromAgility();

    SetBaseModValue(CRIT_PERCENTAGE, PCT_MOD, value);
    SetBaseModValue(RANGED_CRIT_PERCENTAGE, PCT_MOD, value);

    UpdateCritPercentage(BASE_ATTACK);
    UpdateCritPercentage(RANGED_ATTACK);
}

Player::UpdateParryPercentage.body:
void Player::UpdateParryPercentage()
{
    // No parry
    float value = 0.0f;
    if (CanParry())
    {
        // Base parry
        value  = 5.0f;
        // Modify value from defense skill
        value += (int32(GetDefenseSkillValue()) - int32(GetSkillMaxForLevel())) * 0.04f;
        // Parry from SPELL_AURA_MOD_PARRY_PERCENT aura
        value += GetWeaponBasedAuraModifier(BASE_ATTACK, SPELL_AURA_MOD_PARRY_PERCENT);
        value = value < 0.0f ? 0.0f : value;
    }
    SetStatFloatValue(PLAYER_PARRY_PERCENTAGE, value);
}

Player::UpdateDodgePercentage.body:
void Player::UpdateDodgePercentage()
{
    // Nostalrius : base dodge per class
    float value = 0.0f;
    switch (GetClass())
    {
        case CLASS_DRUID:
            value += 0.9f;
            break;
        case CLASS_MAGE:
            value += 3.2f;
            break;
        case CLASS_PALADIN:
            value += 0.7f;
            break;
        case CLASS_PRIEST:
            value += 3.0f;
            break;
        case CLASS_SHAMAN:
            value += 1.7f;
            break;
        case CLASS_WARLOCK:
            value += 2.0f;
            break;
    }
    // Dodge from agility
    value += GetDodgeFromAgility();
    // Modify value from defense skill
    value += (int32(GetDefenseSkillValue()) - int32(GetSkillMaxForLevel())) * 0.04f;
    // Dodge from SPELL_AURA_MOD_DODGE_PERCENT aura
    value += GetTotalAuraModifier(SPELL_AURA_MOD_DODGE_PERCENT);
    value = value < 0.0f ? 0.0f : value;
    SetStatFloatValue(PLAYER_DODGE_PERCENTAGE, value);
}

Player::UpdateManaRegen.body:
void Player::UpdateManaRegen()
{
    // Mana regen from spirit
    float power_regen = GetRegenMPPerSpirit();

    // Apply PCT bonus from SPELL_AURA_MOD_POWER_REGEN_PERCENT aura on spirit base regen
    power_regen *= GetTotalAuraMultiplierByMiscValue(SPELL_AURA_MOD_POWER_REGEN_PERCENT, POWER_MANA);

    // Mana regen from SPELL_AURA_MOD_POWER_REGEN aura
    float power_regen_mp5 = GetTotalAuraModifierByMiscValue(SPELL_AURA_MOD_POWER_REGEN, POWER_MANA) / 5.0f;

    // Set regen rate in cast state apply only on spirit based regen
    int32 modManaRegenInterrupt = GetTotalAuraModifier(SPELL_AURA_MOD_MANA_REGEN_INTERRUPT);
    if (modManaRegenInterrupt > 100)
        modManaRegenInterrupt = 100;

    m_modManaRegenInterrupt = power_regen_mp5 + power_regen * modManaRegenInterrupt / 100.0f;

    m_modManaRegen = power_regen_mp5 + power_regen;
}

Creature::UpdateStats.body:
bool Creature::UpdateStats(Stats stat)
{
    if (stat > STAT_SPIRIT)
        return false;

    // value = ((base_value * base_pct) + total_value) * total_pct
    float value  = GetTotalStatValue(stat);

    SetStat(stat, int32(value));

    switch (stat)
    {
        case STAT_STRENGTH:
            UpdateAttackPowerAndDamage();
            break;
        case STAT_AGILITY:
            UpdateArmor();
            break;
        case STAT_STAMINA:
            UpdateMaxHealth();
            break;
        case STAT_INTELLECT:
            UpdateMaxPower(POWER_MANA);
            break;
        case STAT_SPIRIT:
        default:
            break;
    }

    if (GetMaxPower(POWER_MANA))
        UpdateManaRegen();

    return true;
}

Creature::UpdateAllStats.body:
bool Creature::UpdateAllStats()
{
    for (int i = STAT_STRENGTH; i < MAX_STATS; ++i)
    {
        float value = GetTotalStatValue(Stats(i));
        SetStat(Stats(i), (int32)value);
    }

    UpdateMaxHealth();
    UpdateAttackPowerAndDamage();
    UpdateAttackPowerAndDamage(true);
    UpdateAllSpellCritChances();

    for (int i = POWER_MANA; i < MAX_POWERS; ++i)
        UpdateMaxPower(Powers(i));

    for (int i = SPELL_SCHOOL_NORMAL; i < MAX_SPELL_SCHOOL; ++i)
        UpdateResistances(i);

    if (GetMaxPower(POWER_MANA))
        UpdateManaRegen();

    return true;
}

Creature::UpdateResistances.body:
void Creature::UpdateResistances(uint32 school)
{
    if (school > SPELL_SCHOOL_NORMAL)
    {
        int32 value = school == SPELL_SCHOOL_HOLY ? 0 : GetTotalResistanceValue(SpellSchools(school));
        SetResistance(SpellSchools(school), value);
    }
    else
        UpdateArmor();
}

Creature::UpdateArmor.body:
void Creature::UpdateArmor()
{
    float dynamic = GetStat(STAT_AGILITY); // 1 agility = 1 armor for creatures

    m_auraModifiersGroup[UNIT_MOD_ARMOR][TOTAL_VALUE] += dynamic;
    int32 value = GetTotalResistanceValue(SPELL_SCHOOL_NORMAL);

    SetArmor(value);
    m_auraModifiersGroup[UNIT_MOD_ARMOR][TOTAL_VALUE] -= dynamic;
}

Creature::UpdateMaxHealth.body:
void Creature::UpdateMaxHealth()
{
    UnitMods unitMod = UNIT_MOD_HEALTH;
    float stamina = GetStat(STAT_STAMINA) - GetCreateStat(STAT_STAMINA);

    float value = GetModifierValue(unitMod, BASE_VALUE);
    if (IsPet())
        value += GetCreateHealth();
    value *= GetModifierValue(unitMod, BASE_PCT);
    value += GetModifierValue(unitMod, TOTAL_VALUE) + stamina * 10.0f;
    value *= GetModifierValue(unitMod, TOTAL_PCT);

    SetMaxHealth(std::max(1, int(value)));
}

Creature::UpdateMaxPower.body:
void Creature::UpdateMaxPower(Powers power)
{
    UnitMods unitMod = UnitMods(UNIT_MOD_POWER_START + power);
    float intellect = (power == POWER_MANA) ? GetStat(STAT_INTELLECT) - GetCreateStat(STAT_INTELLECT) : 0.0f;

    float value  = GetModifierValue(unitMod, BASE_VALUE);
    if (IsPet())
        value += GetCreatePowers(power);
    value *= GetModifierValue(unitMod, BASE_PCT);
    value += GetModifierValue(unitMod, TOTAL_VALUE) + intellect * 15.0f;
    value *= GetModifierValue(unitMod, TOTAL_PCT);

    if (value < 0.0f)
        value = 0.0f;

    SetMaxPower(power, uint32(value));
}

Creature::UpdateManaRegen.body:
void Creature::UpdateManaRegen()
{
    float ManaIncreaseRate = sWorld.getConfig(CONFIG_FLOAT_RATE_POWER_MANA);
    float intellect = std::max(1.0f, GetStat(STAT_INTELLECT));
    // Apply PCT bonus from SPELL_AURA_MOD_POWER_REGEN_PERCENT aura on spirit base regen
    float power_regen = GetTotalAuraMultiplierByMiscValue(SPELL_AURA_MOD_POWER_REGEN_PERCENT, POWER_MANA);
    // Mana regen from SPELL_AURA_MOD_POWER_REGEN aura
    float power_regen_mp5 = GetTotalAuraModifierByMiscValue(SPELL_AURA_MOD_POWER_REGEN, POWER_MANA) / 5.0f;

    m_manaRegen = (GetRegenMPPerSpirit() * power_regen + power_regen_mp5 + (0.6f * sqrt(intellect) / 5.0f)) * ManaIncreaseRate * 5.0f;
}

Creature::UpdateAttackPowerAndDamage.body:
void Creature::UpdateAttackPowerAndDamage(bool ranged)
{
    AttackPowerModIndex unitMod = ranged ? RANGED_AP_MODS : MELEE_AP_MODS;

    uint16 index = UNIT_FIELD_ATTACK_POWER;
    uint16 index_mod = UNIT_FIELD_ATTACK_POWER_MODS;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
    uint16 index_mult = UNIT_FIELD_ATTACK_POWER_MULTIPLIER;
#endif

    if (ranged)
    {
        index = UNIT_FIELD_RANGED_ATTACK_POWER;
        index_mod = UNIT_FIELD_RANGED_ATTACK_POWER_MODS;
#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
        index_mult = UNIT_FIELD_RANGED_ATTACK_POWER_MULTIPLIER;
#endif
    }

    CreatureClassLevelStats const* pCLS = GetClassLevelStats();
    float baseAttackPower = ranged ? pCLS->ranged_attack_power : pCLS->attack_power;

    // attack power mods are split into positive and negative field
    float attackPowerModPositive = GetAttackPowerModifierValue(unitMod, AP_MOD_POSITIVE_FLAT);
    float attackPowerModNegative = GetAttackPowerModifierValue(unitMod, AP_MOD_NEGATIVE_FLAT);

    // Only apply AP bonus from stats when different than default value,
    // as the stats are already taken into account in the base AP values.
    if (GetCreateStat(STAT_STRENGTH) != GetStat(STAT_STRENGTH) ||
        GetCreateStat(STAT_AGILITY) != GetStat(STAT_AGILITY))
    {
        float defaultAPBonus = GetAttackPowerFromStrengthAndAgility(ranged, GetCreateStat(STAT_STRENGTH), GetCreateStat(STAT_AGILITY));
        float currentAPBonus = GetAttackPowerFromStrengthAndAgility(ranged, GetStat(STAT_STRENGTH), GetStat(STAT_AGILITY));

        float modFromStats = (currentAPBonus - defaultAPBonus);
        if (modFromStats > 0.0f)
            attackPowerModPositive += modFromStats;
        else
            attackPowerModNegative += modFromStats;
    }

    SetInt32Value(index, (int32)baseAttackPower);               //UNIT_FIELD_(RANGED)_ATTACK_POWER field
    SetInt16Value(index_mod, 0, (int16)attackPowerModPositive); //UNIT_FIELD_(RANGED)_ATTACK_POWER_MODS field (positive)
    SetInt16Value(index_mod, 1, (int16)attackPowerModNegative); //UNIT_FIELD_(RANGED)_ATTACK_POWER_MODS field (negative)

#if SUPPORTED_CLIENT_BUILD > CLIENT_BUILD_1_8_4
    float attackPowerMultiplier = GetAttackPowerModifierValue(unitMod, AP_MOD_PCT) - 1.0f;
    SetFloatValue(index_mult, attackPowerMultiplier);           //UNIT_FIELD_(RANGED)_ATTACK_POWER_MULTIPLIER field
#endif

    //automatically update weapon damage after attack power modification
    if (ranged)
    {
        UpdateDamagePhysical(RANGED_ATTACK);
    }
    else
    {
        UpdateDamagePhysical(BASE_ATTACK);
        UpdateDamagePhysical(OFF_ATTACK);
    }
}

Creature::UpdateDamagePhysical.body:
void Creature::UpdateDamagePhysical(WeaponAttackType attType)
{
    UnitMods unitMod;
    float databaseAttackPower;
    CreatureClassLevelStats const* pCLS = GetClassLevelStats();

    switch (attType)
    {
        case BASE_ATTACK:
        default:
            unitMod = UNIT_MOD_DAMAGE_MAINHAND;
            databaseAttackPower = pCLS->attack_power;
            break;
        case OFF_ATTACK:
            unitMod = UNIT_MOD_DAMAGE_OFFHAND;
            databaseAttackPower = pCLS->attack_power;
            break;
        case RANGED_ATTACK:
            unitMod = UNIT_MOD_DAMAGE_RANGED;
            databaseAttackPower = pCLS->ranged_attack_power;
            break;
    }

    float base_value  = GetModifierValue(unitMod, BASE_VALUE);
    float base_pct    = GetModifierValue(unitMod, BASE_PCT);
    float total_value = GetModifierValue(unitMod, TOTAL_VALUE);
    float total_pct   = GetModifierValue(unitMod, TOTAL_PCT);
    float total_phys  = GetTotalAuraModValue(UNIT_MOD_DAMAGE_PHYSICAL);

    float weapon_mindamage = GetWeaponDamageRange(attType, MINDAMAGE);
    float weapon_maxdamage = GetWeaponDamageRange(attType, MAXDAMAGE);

    // Disarm effects. Only applies to mobs with a weapon equipped. Sources suggest a 
    // ~60% damage reduction on mobs which can be disarmed and have a weapon
    // http://wowwiki.wikia.com/wiki/Attumen_the_Huntsman?oldid=1377353
    // http://wowwiki.wikia.com/wiki/Disarm?direction=prev&oldid=200198
    if (HasWeapon() && !CanUseEquippedWeapon(attType))
        total_pct *= 0.4f;

    /* AP for units is 30% of base damage.
     * ie if AP is reduced to 0, attack will be reduced of 30%
     * We have to ignore creatures that don't have AP set in database (we would divide by 0)
     */
    if (databaseAttackPower)
    {
        float attackPowerNow = GetTotalAttackPowerValue(attType);
        weapon_mindamage = weapon_mindamage * (0.7f + 0.3f * attackPowerNow / databaseAttackPower);
        weapon_maxdamage = weapon_maxdamage * (0.7f + 0.3f * attackPowerNow / databaseAttackPower);
    }

    float mindamage = ((base_value + weapon_mindamage) * base_pct + total_value + total_phys) * total_pct;
    float maxdamage = ((base_value + weapon_maxdamage) * base_pct + total_value + total_phys) * total_pct;

    uint16 fieldmin, fieldmax;

    switch (attType)
    {
        case RANGED_ATTACK:
            fieldmin = UNIT_FIELD_MINRANGEDDAMAGE;
            fieldmax = UNIT_FIELD_MAXRANGEDDAMAGE;
            break;
        case BASE_ATTACK:
            fieldmin = UNIT_FIELD_MINDAMAGE;
            fieldmax = UNIT_FIELD_MAXDAMAGE;
            break;
        case OFF_ATTACK:
            fieldmin = UNIT_FIELD_MINOFFHANDDAMAGE;
            fieldmax = UNIT_FIELD_MAXOFFHANDDAMAGE;
            break;
        default:
            return;
    }

    SetStatFloatValue(fieldmin, mindamage);
    SetStatFloatValue(fieldmax, maxdamage);
}

Creature::GetWeaponBasedAuraModifier.body:
float Creature::GetWeaponBasedAuraModifier(WeaponAttackType attType, AuraType auraType) const
{
    float amount = 0.0f;
    AuraList const& auras = GetAurasByType(auraType);
    for (auto const& i : auras)
    {
        SpellEntry const* pSpellEntry = i->GetSpellProto();
        if (pSpellEntry->EquippedItemClass >= 0)
        {
            if (!GetVirtualItemDisplayId(attType))
                continue;

            if (!Item::IsFitToSpellRequirements(pSpellEntry, GetVirtualItemClass(attType), GetVirtualItemSubclass(attType), GetVirtualItemInventoryType(attType)))
                continue;
        }

        amount += i->GetModifier()->m_amount;
    }
    return amount;
}

