TransportAnimationEntry const* TransportAnimation::GetPrevAnimNode(uint32 time) const
{
    auto itr = Path.lower_bound(time);
    if (itr != Path.end() && itr != Path.begin())
    {
        --itr;
        return itr->second;
    }

    return nullptr;
}

