            pCorpse->GetMapId() == MAP_BLACKWING_LAIR)
        {
            pPlayer->ResurrectPlayer(0.5f);
            pPlayer->SpawnCorpseBones();
            pPlayer->TeleportTo(MAP_BLACKWING_LAIR, -7672.32f, -1107.05f, 396.651f, 0.785398f);
        }
    }

    return false;
}

