npc_reginald_windsorAI::ResetCreature.body:
void npc_reginald_windsorAI::ResetCreature()
{
    m_bRoweKnows = false;
    m_squireRoweGuid.Clear();

    m_uiDespawnTimer = 5 * MINUTE * IN_MILLISECONDS;
    Timer = 3000;
    Tick = 0;
    playerGUID = 0;
    GreetPlayer = false;
    QuestAccepted = false;
    BeginQuest = false;
    Begin = true;
    NeedCheck = false;
    PhaseFinale = false;
    TheEnd = false;
    CombatJustEnded = false;

    for (uint8 i = 0; i < 6; i++)
    {
        GuardTimer[i] = 0;
        GuardNeed[i] = false;
    }
    for (uint64 & guid : GuardsGUIDs)
        guid = 0;

    for (uint64 & guid : DragsGUIDs)
        guid = 0;

    m_creature->EnableMoveInLosEvent();
}

