        if (npc_Krug_SkullSplitAI* pKrugSkullSplitAI = dynamic_cast<npc_Krug_SkullSplitAI*>(pCreature->AI()))
            pKrugSkullSplitAI->StartEvent();
        pPlayer->CLOSE_GOSSIP_MENU();
