void Database::Ping()
{
    std::string const sql = "SELECT 1";

    {
        SqlConnection::Lock guard(m_pAsyncConn);
        /* ignore result */ guard->Query(sql);
    }

    for (int i = 0; i < m_nQueryConnPoolSize; ++i)
