SendgridMail::Result SendgridMail::send()
{
    if (_recipients.empty())
    {
        return Result::RECIPIENT_MISSING;
    }

    if (_from.empty())
    {
        return Result::FROM_MISSING;
    }

    CURL* curl = curl_easy_init();

    if (!curl)
    {
        return Result::INTERNAL_ERROR;
    }

    //curl_easy_setopt(curl, CURLOPT_URL, uri.data());
    curl_easy_setopt(curl, CURLOPT_URL, uri);

    // add header data
    curl_slist* list = nullptr;
    const std::string auth = std::string("authorization: Bearer ") + _api_key;
    list = curl_slist_append(list, auth.c_str());
    list = curl_slist_append(list, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, list);

    if (sConfig.GetBoolDefault("MailCertChecks", true))
    {
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0);
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0);
    }

    json data
    {
        { "template_id", _template_name },
        { "from", {{ "email", _from }}},
        { "personalizations",
            {
            {{ "to", {{
                { "email", _recipients.front() } // only dealing with a single recipient for now
            }}},
            { "substitutions",
                _substitutions
             } },
           },
        }
    };

    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data.dump().c_str());

    _extended_error = curl_easy_perform(curl); // shouldn't really use int here

    curl_slist_free_all(list);
    curl_easy_cleanup(curl);
    return _extended_error == CURLE_OK? Result::OK : Result::EXTENDED_ERROR;
}

WinServiceInstall.body:
bool WinServiceInstall()
{
    CSD_T ChangeService_Config2;
    HMODULE advapi32;
    SC_HANDLE serviceControlManager = OpenSCManager(0, 0, SC_MANAGER_CREATE_SERVICE);

    if (!serviceControlManager)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "SERVICE: No access to service control manager.");
        return false;
    }

    char path[_MAX_PATH + 10];
    if (!GetModuleFileName(0, path, sizeof(path)/sizeof(path[0])))
    {
        CloseServiceHandle(serviceControlManager);
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "SERVICE: Can't get service binary filename.");
        return false;
    }

    std::strcat(path, " -s run");

    SC_HANDLE service = CreateService(serviceControlManager,
        serviceName,                                // name of service
        serviceLongName,                            // service name to display
        SERVICE_ALL_ACCESS,                         // desired access
                                                    // service type
        SERVICE_WIN32_OWN_PROCESS | SERVICE_INTERACTIVE_PROCESS,
        SERVICE_AUTO_START,                         // start type
        SERVICE_ERROR_IGNORE,                       // error control type
        path,                                       // service's binary
        0,                                          // no load ordering group
        0,                                          // no tag identifier
        0,                                          // no dependencies
        0,                                          // LocalSystem account
        0);                                         // no password

    if (!service)
    {
        CloseServiceHandle(serviceControlManager);
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "SERVICE: Can't register service for: %s", path);
        return false;
    }

    advapi32 = GetModuleHandle("ADVAPI32.DLL");
    if(!advapi32)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "SERVICE: Can't access ADVAPI32.DLL");
        CloseServiceHandle(service);
        CloseServiceHandle(serviceControlManager);
        return false;
    }

    ChangeService_Config2 = (CSD_T) GetProcAddress(advapi32, "ChangeServiceConfig2A");
    if (!ChangeService_Config2)
    {
        sLog.Out(LOG_BASIC, LOG_LVL_ERROR, "SERVICE: Can't access ChangeServiceConfig2A from ADVAPI32.DLL");
        CloseServiceHandle(service);
        CloseServiceHandle(serviceControlManager);
        return false;
    }

    SERVICE_DESCRIPTION sdBuf;
    sdBuf.lpDescription = serviceDescription;
    ChangeService_Config2(
        service,                                // handle to service
        SERVICE_CONFIG_DESCRIPTION,             // change: description
        &sdBuf);                                // new data

    SC_ACTION _action[1];
    _action[0].Type = SC_ACTION_RESTART;
    _action[0].Delay = 10000;
    SERVICE_FAILURE_ACTIONS sfa;
    ZeroMemory(&sfa, sizeof(SERVICE_FAILURE_ACTIONS));
    sfa.lpsaActions = _action;
    sfa.cActions = 1;
    sfa.dwResetPeriod =INFINITE;
    ChangeService_Config2(
        service,                                // handle to service
        SERVICE_CONFIG_FAILURE_ACTIONS,         // information level
        &sfa);                                  // new data

    CloseServiceHandle(service);
    CloseServiceHandle(serviceControlManager);
    return true;
}

