void stripLineInvisibleChars(char* str)
{
    static std::string invChars = " \t\7\n";

    size_t wpos = 0;

    bool space = false;
    size_t pos = 0;
    for (; str[pos] != '\0'; ++pos)
    {
        if (invChars.find(str[pos]) != std::string::npos)
        {
            if (!space)
            {
                str[wpos++] = ' ';
                space = true;
            }
        }
        else
        {
            if (wpos != pos)
                str[wpos++] = str[pos];
            else
                ++wpos;
            space = false;
        }
    }

    for (; wpos < pos; wpos++)
        str[wpos] = '\0';
}

secsToTimeString.body:
std::string secsToTimeString(time_t timeInSecs, bool shortText, bool hoursOnly)
{
    time_t secs    = timeInSecs % MINUTE;
    time_t minutes = timeInSecs % HOUR / MINUTE;
    time_t hours   = timeInSecs % DAY  / HOUR;
    time_t days    = timeInSecs / DAY;

    std::ostringstream ss;
    if(days)
    {
        ss << days;
        if (shortText)
            ss << "d";
        else if (days == 1)
            ss << " Day ";
        else
            ss << " Days ";
    }
    if(hours || hoursOnly)
    {
        ss << hours;
        if (shortText)
            ss << "h";
        else if (hours <= 1)
            ss << " Hour ";
        else
            ss << " Hours ";
    }
    if(!hoursOnly)
    {
        if(minutes)
        {
            ss << minutes;
            if (shortText)
                ss << "m";
            else if (minutes == 1)
                ss << " Minute ";
            else
                ss << " Minutes ";
        }
        if (secs || (!days && !hours && !minutes))
        {
            ss << secs;
            if (shortText)
                ss << "s";
            else if (secs <= 1)
                ss << " Second.";
            else
                ss << " Seconds.";
        }
    }

    return ss.str();
}

TimeStringToSecs.body:
uint32 TimeStringToSecs(std::string const& timestring)
{
    uint32 secs       = 0;
    uint32 buffer     = 0;
    uint32 multiplier = 0;

    for(std::string::const_iterator itr = timestring.begin(); itr != timestring.end(); itr++)
    {
        if(isdigit(*itr))
        {
            buffer*=10;
            buffer+= (*itr)-'0';
        }
        else
        {
            switch(*itr)
            {
                case 'd': multiplier = DAY;     break;
                case 'h': multiplier = HOUR;    break;
                case 'm': multiplier = MINUTE;  break;
                case 's': multiplier = 1;       break;
                default : return 0;                         //bad format
            }
            buffer*=multiplier;
            secs+=buffer;
            buffer=0;
        }
    }

    return secs;
}

